window.HARDTRP.receive("191019",[[191020,"2026-09-05T15:44:07",9,"Начало темы.\n\n@STR_V_Alekseev — Дм этой темы.",191019,null],[191046,"2026-09-05T15:48:05",37,"Книга Прошлого\n\nОднажды ваших героев пригласили на необычное мероприятие, а именно на закрытую выставку в архиве, где вы не увидели ничего интересного, так как выставка была бесплатной вы не переживали об этом.\n\nВот только уснув...\nУчастники:\n— Конрад https://t.me/c/3239766844/4646 @QURTZZ \n— Стэт https://t.me/c/3239766844/2387 @tochhkatochka \n— Аури https://t.me/c/3239766844/6859 @Ashenchampion \n— Летиция https://t.me/c/3239766844/6878 @sweetkittywitch",191019,null],[191049,"2026-09-05T15:48:19",37,"// Щас прочитаю ваших персонажей и мы начнем",191019,null],[192458,"2026-09-05T20:06:32",37,"// Так, я прочитал все ваши предыстории и готов начать завтра хоть с 9 по мск.",191019,null],[192490,"2026-09-05T20:15:31",0,"Я готов",191019,null],[192792,"2026-09-05T22:06:49",41,"( чето не начали пока",191019,null],[192794,"2026-09-05T22:07:03",41,"( надо было лайк?",191019,null],[192797,"2026-09-05T22:10:40",41,"@QURTZZ уже спит наверное",191019,null],[192813,"2026-09-05T22:23:35",11,"// я так поняла утречком начнем",191019,null],[192814,"2026-09-05T22:24:39",37,"// Да",191019,null],[193041,"2026-09-06T04:06:54",31,"Я обычно после 20-00 по Москве уже сплю, да. Зато и начать могу куда раньше других/",192797,null],[193079,"2026-09-06T10:05:04",0,"@STR_V_Alekseev хм //",191019,null],[193080,"2026-09-06T10:05:17",37,"// Скоро начнем, я пишу вступление",193079,null],[193082,"2026-09-06T10:26:30",37,"Буквально вчера каждый из вас побывал на бесплатной выставке в одной галерее. Вы не нашли там ничего интересного и просто скучали, а может и нет.\n\nКогда все закончилось вам дали листовку с приглашением на будущее посещение.\n\nВы попрощались и пошли по своим делам. Вот только уснув вы поняли, что что-то не так...\n\nКнига Первая: Крылья.\n\nВы обнаруживаете себя прямо перед небольшим обшарпанным домом, похоже публичный. \n\nВместе с этим вы заметили у себя в голове фразу: \"Слышали о «гении, который стал чучелом»? Я рад.\"\n\n// Вы все стоите прямо перед этим домом.",191019,null],[193085,"2026-09-06T10:35:26",37,"// @tochhkatochka @QURTZZ @Ashenchampion @sweetkittywitch",191019,null],[193086,"2026-09-06T10:35:39",0,"//тут",191019,null],[193088,"2026-09-06T10:39:43",11,"Поняв где находится Аури посильнее укуталась в плащ, так что бы только синие острые ушки и носик выглядывали\n\n«Кто со мной говорит?» — так же, в своей голове, ответила она\n\n— И где я? — это уже Аури произнесла вслух",191019,null],[193090,"2026-09-06T10:41:20",0,"—кто где что?",191019,null],[193097,"2026-09-06T10:47:43",37,"Из публичного дома выходят пару девушек и идут к выходу проходя мимо вас. Они мило болтали, но вы не могли разобрать их слов, словно они говорили на неизвестном вам языке.",191019,null],[193100,"2026-09-06T10:48:37",11,"— Тебя я понимаю, а их нет.. Не подскажешь что это за место..?",193090,null],[193102,"2026-09-06T10:49:17",0,"—это место рядом с домом \n—а может нет\n—а так не знаю",193100,null],[193103,"2026-09-06T10:49:45",41,"На выставку явилась единственная — мертвец. К тому моменту мало кто знал о её смерти, потому не ожидали увидеть мертвую девушку. От нелестных комментариев в свою сторону Летиция в конце концов расплакалась, так как не могла вынести чужих слов. Однако там же она встретила Аури — единственную подругу, что ценила её не смотря на смерть. Они вместе походили по галерее, в поисках любой картины с драконами. \n\nПоскольку галерея была скучной, естественно нарисовать драконов там никто не додумался, ведь там не публиковалась какая-нибудь Эля Сенина например. \n\nИ вот она очнулась в неизвестном месте перед публичным домом. Не было ни крика, ни страха. Лишь не стандартный интерес. \n\nВыглянув из под одеяла, она пошла искать кого-либо вокруг дома",191019,null],[193104,"2026-09-06T10:51:15",41,"— Привет! Эгей, есть тут кто???",191019,null],[193106,"2026-09-06T10:52:16",31,"- ну я есть. Правда понятия не имею где именно",191019,null],[193107,"2026-09-06T10:52:16",37,"Осмотревшись по сторонам ты поняла, что... Вы в странном городе. Он весь сделан из камня, а публичный дом имеет 18 дверей, похоже жилища каждого жителя.\n На твои крики никто из дома не отреагировал, будто там никого не было.",193103,null],[193108,"2026-09-06T10:52:25",11,"— Ой, знакомый голос! — девушка крикнула в ответ — Летиция, я здесь!",191019,null],[193110,"2026-09-06T10:53:42",41,"— Аури! Дорогая! Я бегу! \n\nОна побежала обниматься с подружкой\n\n— Пожалуйста, скажи что это часть выступления, я может о чем-то забыла ?",191019,null],[193112,"2026-09-06T10:54:54",0,"—кого есть\n—зачем есть",193106,null],[193115,"2026-09-06T10:56:22",37,"Вы замечаете, что сейчас около полудня и похоже все жители ушли на работу, но похоже кто-то есть в доме.",191019,null],[193117,"2026-09-06T10:56:33",11,"обнимает в ответ\n\n— Увы, но я и сама не знаю где мы. А ещё судя по всему язык местный мне не знаком, я понимаю только вот этого парня — показывает на Стэта — но судя по его удивлённому виду он тут оказался так же как и мы",193110,null],[193118,"2026-09-06T10:57:26",11,"— Ой, там ещё кто-то — Аури замечает мужчину за спиной подруги",193106,null],[193120,"2026-09-06T10:58:16",41,"— Правда…? Привет, незнакомые мужчины…",191019,null],[193122,"2026-09-06T10:59:33",11,"— Вы знаете как вы здесь оказались..? — дженази обращается к Конраду",191019,null],[193129,"2026-09-06T11:02:46",0,"—привет",193120,null],[193134,"2026-09-06T11:07:07",0,"Осматриваю дом *",191019,null],[193137,"2026-09-06T11:07:26",37,"// Прокинь внимание",193134,null],[193139,"2026-09-06T11:08:37",0,"/r d20+4",191019,null],[193142,"2026-09-06T11:09:29",37,"Ты понимаешь, что дом и вправду является публичным, ведь на табличке около забора записаны, похоже, имена и цифры, похоже, цены.",193139,null],[193143,"2026-09-06T11:10:07",11,"— Кстати, Лети, мне кажется нам тут не место.. — накрывает подругу своим плащом",191019,null],[193145,"2026-09-06T11:12:15",0,"*иду внутрь*\n—может зайдем спросим где мы?",191019,null],[193146,"2026-09-06T11:15:24",11,"— Не особо горю желанием, но полагаю стоит..",191019,null],[193147,"2026-09-06T11:16:41",31,"- просто уснул. Это уже становится какой то дурной шуткой. Я засыпаю и оказываюсь черт знает где",193122,null],[193149,"2026-09-06T11:17:10",31,"Иду следом за девушками, негоже их одних оставлять в таком месте",191019,null],[193150,"2026-09-06T11:17:46",41,"— Спасибо, Рассветная заря) Думаю, здесь нам как раз таки место, раз судьба завела нас сюда",193143,null],[193151,"2026-09-06T11:17:53",37,"Пройдя через забор можно было понять в каких дверях есть люди, а в каких нету. И похоже только на 3ем этаже кто-то есть, точнее слышно какую-то деятельность.",191019,null],[193157,"2026-09-06T11:20:11",11,"— Странная у тебя шутка.. Несущая Счастье.. Бенжамин бы не оценил",193150,null],[193158,"2026-09-06T11:20:36",41,"— Ох, и правда...он очень испугается (",193157,null],[193161,"2026-09-06T11:20:46",11,"— Может дождаться людей здесь..",191019,null],[193162,"2026-09-06T11:21:07",41,"— Вы ведь...тоже слышали тот голос?",191019,null],[193165,"2026-09-06T11:21:34",31,"- а это был голос? Я думал что то вроде телепатии",191019,null],[193167,"2026-09-06T11:21:43",31,"Во всяком случае, я его не ушами слышал",191019,null],[193168,"2026-09-06T11:21:48",11,"кивает и моргает\n\n— Ваааа, кажется мы попали в сказку! — с восхищением говорит она",191019,null],[193170,"2026-09-06T11:22:02",11,"— Голос в голове агамс",193167,null],[193171,"2026-09-06T11:22:18",31,"- ну, если с такой стороны посмотреть...",193170,null],[193176,"2026-09-06T11:23:20",31,"- да, простите, забыл представиться, Конрад фон Шаттенхаус, к вашим услугам\n\nПредставился молодой парень, чье имя не очень вязалось с простой одеждой и общей неухоженостью",191019,null],[193177,"2026-09-06T11:23:27",11,"Впрочем сказка начинающаяся с публичного двора несколько смутила и девушка как-то неловко стояла выжидая что решат другие",191019,null],[193183,"2026-09-06T11:24:54",0,"—а я стэт приятно познакомиться",193176,null],[193184,"2026-09-06T11:24:55",11,"— Аури Диан — имя на драконике для дженази воды тоже звучало странно — рада знакомству! \n\nДевушка показала на возрождённую\n\n— А это моя подруга!",193176,null],[193187,"2026-09-06T11:26:38",31,"- кстати, заметили двух девушек, что выходили отсюда? Они болтали, но языс мне решительно непонятен был. Есть ощущение, что это сон, но как проверить?",191019,null],[193189,"2026-09-06T11:27:35",31,"Щипаю себя с силой",191019,null],[193193,"2026-09-06T11:29:25",37,"Ты чувствуешь боль и понимаешь, что не просыпаешься, хотя ты не можешь сказать, что спишь",193189,null],[193194,"2026-09-06T11:29:51",0,"—Кто нибудь\n*кричу",191019,null],[193195,"2026-09-06T11:30:16",11,"— Просто Стэт?",193183,null],[193197,"2026-09-06T11:30:31",11,"— Ауч, выглядит больно, вы в порядке?",193189,null],[193198,"2026-09-06T11:30:43",0,"-да а что ещё",193195,null],[193201,"2026-09-06T11:31:22",31,"- терпимо, спасибо",193197,null],[193204,"2026-09-06T11:32:20",37,"Вы слышите, как от крика часть людей за дверью что-то бубнит, но ничего не происходит, похоже все спят днем.",193194,null],[193206,"2026-09-06T11:33:06",11,"— Тихий час у них что ли? Эм.. и будить как-то неприлично",191019,null],[193209,"2026-09-06T11:33:28",11,"— А, была не была — Аури делает пару шагов к двери и открывает её",191019,null],[193212,"2026-09-06T11:36:42",41,"— может погуляем здесь? Распросим Кого поблизости...",191019,null],[193213,"2026-09-06T11:37:35",11,"// представься кстати и жду реакцию мастера",191019,null],[193217,"2026-09-06T11:38:47",41,"— Кстати, где мои манеры. Я Летиция Даск...вы наверное слышали",191019,null],[193220,"2026-09-06T11:40:19",37,"Открыв дверь ты поняла, что на ней довольно слабый замок, что она открылась от простого толчка.\n Внутри была комната с туалетным столиком, кроватью, и столом, довольно низки столом. Похоже это все на восточный стиль, даже маты есть.\n И посмотрев на туалетный столик ты заметила кого-то.\n Это был не опрятный мужчина с грязными, лохматыми волосами черного цвета, бледной кожей и грязной одеждой.\n Он что-то делал и заметив, как вы открыли дверь сразу же попытался пройти к другой двери в комнату рядом с вами. Он очень быстро пробежал и спрятался за дверью, закрыв её.",193209,null],[193223,"2026-09-06T11:41:41",11,"— Эм.. вы это видели? — спросила Аури и отошла от двери не закрывая ее — слушайте.. если большинство жителей прячется днём по домах.. может ли быть?",191019,null],[193225,"2026-09-06T11:42:29",41,"— так странно. Они вампиры?",191019,null],[193226,"2026-09-06T11:42:34",31,"Извините, пропаду на полчасика/",191019,null],[193227,"2026-09-06T11:42:34",37,"Затем ты услышала вопрос на понятном вам языке, общем.\n— Гостей мы не принимаем, прошу... Покинуть вас мою квартиру.",193223,null],[193229,"2026-09-06T11:43:28",41,"— Нам очень жаль, господин. Можете пожалуйста помочь нам? Мы очутились здесь случайно..",193227,null],[193230,"2026-09-06T11:43:44",11,"кивает\n\n— Те же мысли..\n\nА затем слышит голос\n\n— Ой.. простите. Я не хотела беспокоить — она начинает закрывать дверь — но не подскажете у кого мы могли бы попросить помощи..?",193225,null],[193232,"2026-09-06T11:45:04",37,"— Если вам нужна помощь, то обращайтесь в полицейский участок... Там вам помогут...\n У мужчины был довольно ломанный голос, да и похоже он мало питался.\n\n// Вы не поняли слово под спойлером",191019,null],[193233,"2026-09-06T11:46:05",0,"—куда обращаться?",191019,null],[193236,"2026-09-06T11:48:58",11,"— В какой-то участок.. — Аури закрыла дверь ещё раз извинившись — такс, ну.. предлагаю выйти в город и осмотреться, может мы найдем тот самый.. участок",191019,null],[193238,"2026-09-06T11:49:10",37,"— В участок... Я не знаю где ближайший... Я... Не выходил отсюда довольно долго...",193233,null],[193239,"2026-09-06T11:49:34",37,"Из под двери выходит пара серебряных монет.\n— Прошу...",191019,null],[193241,"2026-09-06T11:52:09",0,"—может тебе еды дать или чем-то помочь?",193238,null],[193243,"2026-09-06T11:56:04",37,"— ... Только выйдите, пожалуйста... Моя жена еще не вернулась домой, можете поговорить с ней, когда она вернется...",193241,null],[193245,"2026-09-06T11:56:59",11,"— Если наша теория верна то боюсь обычная еда ему не поможет, сэр, вы едите обычную еду?",191019,null],[193246,"2026-09-06T11:57:25",37,"— А какая есть, кроме обычной? Я в основном куриные ножки ем...",193245,null],[193247,"2026-09-06T11:58:16",41,"— у меня есть домашний пирог с мясом и грибами, курица как раз...",191019,null],[193248,"2026-09-06T11:58:53",0,"Выхожу с комнаты * \n—хорошо дай ему еды",191019,null],[193249,"2026-09-06T12:01:35",11,"Аури протягивает паёк\n\n— Вот, тут есть мясо. Сушеное конечно, но так же много чего ещё вкусного! Только скажите пожалуйста ещё раз, в какой участок нам нужно",193246,null],[193251,"2026-09-06T12:02:44",37,"Мужчина открывает дверь из своей комнаты и рукой быстро хватает паек и закрывает дверь.\n— ... Я не знаю где ближайший... Пройдите дальше по главной улице...",193249,null],[193252,"2026-09-06T12:03:12",41,"— Бенжамин готовит так хорошо, что его еду я чувствую, но вам нужнее. Просттте еще раз за вторжение \n\nОставляет кусочек пирога",191019,null],[193253,"2026-09-06T12:04:56",11,"— Что-ж, похоже искать всё таки придётся самим..",193251,null],[193254,"2026-09-06T12:05:27",11,"— Я теперь тоже попробовать хочу~",193252,null],[193255,"2026-09-06T12:07:08",41,"— у меня два кусочка всего. Давай лучше отдадим их ему, а потом я обязательно походу тебя в гости)",193254,null],[193256,"2026-09-06T12:08:56",0,"—ладно пошли \n*выходит из здания",191019,null],[193257,"2026-09-06T12:10:04",11,"— Я это запомню! Хочу побывать у вас в гостях!",193255,null],[193258,"2026-09-06T12:10:42",11,"Аури берет Летицию за руку и следует за лысым:D\n\n— Конрад, догоняйте!",193256,null],[193259,"2026-09-06T12:12:40",37,"Когда вы закрыли дверь в \"квартиру\", как её назвал мужчина вы вышли обратно ко входу.\n Вместе с этим вы заметили, что прямо от выхода из-за идет дорога по прямой, похоже улица.",191019,null],[193261,"2026-09-06T12:14:07",0,"Осматриваю улицу *",191019,null],[193263,"2026-09-06T12:17:34",41,"— Хахаха!",193258,null],[193264,"2026-09-06T12:17:52",37,"Это была улица, вымощенная в камне, похоже как и в обычных городах. Вдоль дорог были здания из чистого камня, а именно кирпичей.",193261,null],[193265,"2026-09-06T12:18:00",37,"Похоже дорога ведет только прямо",191019,null],[193266,"2026-09-06T12:18:37",0,"—вперед вперед и только вперед",191019,null],[193269,"2026-09-06T12:21:22",11,"Идёт с Летицией за руку и оглядывается с любопытством и намерением найти что-то похожее на «участок»",191019,null],[193279,"2026-09-06T12:32:40",0,"//что мы видим когда доходим до конца?",191019,null],[193291,"2026-09-06T12:40:10",37,"Проходя по улице вы понимаете, что в зданиях и на прилавках никого нету, будто все довольно размыто.\n Через время вы понимаете, что дошли до небольшого заведения с надписью \"Кафе\".\n Вы замечаете что в нем почти никого нету никого, кроме одного мужчины... Похоже это тот же мужчина из комнаты...\n Он был в потрепанной, но одежде в виде рубашки и брюк. Он пил что-то в чашке и похоже о чем-то думал.\n Вы видели его через стекло в стене.",191019,null],[193299,"2026-09-06T12:41:43",41,"— так странно...",191019,null],[193302,"2026-09-06T12:42:14",0,"—э-э-э это же тот мужчина что мы видели до этого? \n—может зайдем?",191019,null],[193303,"2026-09-06T12:42:19",11,"— ..? Вы тоже видите того же мужчину?",191019,null],[193308,"2026-09-06T12:43:34",41,"— Давайте спросим...может близнец?",191019,null],[193311,"2026-09-06T12:44:03",0,"*подхожу к нему \n—привет",191019,null],[193337,"2026-09-06T12:49:43",31,"Вернулся/",191019,null],[193341,"2026-09-06T12:50:50",37,"Мужчина немного вздрагивает от обращения Стэта, но успокоившись ответил.\n— Ох, это вы... Вам, что-то нужно?...",191019,null],[193346,"2026-09-06T12:51:39",0,"—как ты попал из квартиры сюда раньше нас?",191019,null],[193349,"2026-09-06T12:52:50",37,"Мужчина задумался и спросил.\n— Разве вы не приходили ко мне?... Пару недель назад?... Я не хочу сейчас говорить много...",193346,null],[193353,"2026-09-06T12:53:59",31,"- а вот мы бы пообщались. И да, мы не приходили пару недель назад, мы тут бродим не более часа",191019,null],[193357,"2026-09-06T12:54:23",0,"—Хм.... \n—а кто твоя жена?",191019,null],[193359,"2026-09-06T12:54:54",11,"кивает\n\nЕй тоже интересно",193357,null],[193363,"2026-09-06T12:56:55",37,"— Ох... Моя жена очень умная и занятая девушка... Она всегда обо мне заботиться, подкладывает деньги, пока я сплю и общается со мной, когда я делаю вид, что сплю... К ней ночью приходит много гостей и они о чем-то разговаривают... Поэтому я ей не мешаю...",191019,null],[193381,"2026-09-06T12:58:30",0,"-а кем ты работаешь?",193363,null],[193385,"2026-09-06T12:58:50",0,"—ты работаешь в этом кафе?",191019,null],[193389,"2026-09-06T12:59:34",37,"— ...\nМужчина замолчал и немного подумав ответил.\n— Жена запрещает мне выходить из дому... Сегодня я ослушался её... Поэтому я не работаю нигде...",191019,null],[193396,"2026-09-06T13:00:31",0,"—а кем ты был до того как встретил свою возлюбленную?",193389,null],[193403,"2026-09-06T13:01:11",41,"— Мы говорили с вами правда недавно. Вы знаете, что происходит?",191019,null],[193428,"2026-09-06T13:04:07",37,"— Никем я не работал... Жена сказала, что мне она была и не нужна...",193396,null],[193433,"2026-09-06T13:04:23",37,"— Ну да... Около двух недель назад, а что?",193403,null],[193440,"2026-09-06T13:05:25",0,"—что ты помнишь до того как встретил жену",193428,null],[193443,"2026-09-06T13:06:00",37,"— Ничего, ведь это мне не нужно, ведь у меня есть жена...",193440,null],[193444,"2026-09-06T13:06:28",0,"—а как ты встретил свою жену?",191019,null],[193467,"2026-09-06T13:11:40",11,"Аури с любопытством выглядывает из-за спины Стэта ведь её интересует тоже самое, а затем добавляет ещё от себя:\n\n— А почему вы вышли если жена запрещает и вы слушаетесь ее?",191019,null],[193527,"2026-09-06T13:28:49",37,"— Ох... Она самый красивый цветок и источник света!... Только мне немного больно в горле от того, что я узнал... Но она точно простит меня, увидев, что я потратил деньги, что она дает мне...\n Мужчина немного улыбнулся.",191019,null],[193532,"2026-09-06T13:30:18",11,"— А что вы узнали?",191019,null],[193536,"2026-09-06T13:31:01",37,"— ... Я не хочу говорить об этом...",193532,null],[193538,"2026-09-06T13:31:23",0,"—так как вы встретили жену",193527,null],[193541,"2026-09-06T13:31:45",37,"— А зачем мне это помнить, ведь главное, что она у меня есть...",193538,null],[193542,"2026-09-06T13:31:49",11,"— Ох.. простите",193536,null],[193546,"2026-09-06T13:32:26",0,"—а где она сейчас",193541,null],[193550,"2026-09-06T13:33:11",37,"— Я не знаю...",193546,null],[193555,"2026-09-06T13:33:31",0,"—модем ли как-то с ней встретиться",193550,null],[193556,"2026-09-06T13:33:51",37,"Мужчина помотал головой.\n— Я не знаю...",193555,null],[193561,"2026-09-06T13:34:52",0,"—а пошли с нами вместе поищем\n—вручишь ей подарок",193556,null],[193562,"2026-09-06T13:35:21",37,"— Какой подарок?",191019,null],[193563,"2026-09-06T13:35:31",11,"от однообразного ответа девушка быстро начала скучать. Она села на стул рядом и начала дрыгать ногами как ребенок",191019,null],[193564,"2026-09-06T13:35:42",0,"—так ты говорил что купил что-то\n—я думал это подарок",193562,null],[193566,"2026-09-06T13:36:43",37,"— Ох...\n Мужчина поднял чашку и вы поняли, что внутри кофе.\n— Это одна из вещей, что я купил на деньги от жены...",193564,null],[193573,"2026-09-06T13:38:52",0,"—а куда дальше отправлятесь?",193566,null],[193575,"2026-09-06T13:39:18",37,"— ... Думаю посидеть немного и пойти домой, а что?",193573,null],[193585,"2026-09-06T13:41:12",0,"—пошли вместе",193575,null],[193591,"2026-09-06T13:41:45",11,"— Хехе, Стэт, зачем нам идти обратно? Мы же этот.. «участок» ищем",191019,null],[193596,"2026-09-06T13:42:34",0,"—пошлите отойдем обсудим",191019,null],[193599,"2026-09-06T13:42:59",0,"*выходит из кафе и зовет всех с собой",191019,null],[193604,"2026-09-06T13:44:51",11,"Аури спрыгивает со стула и идёт следом подманивая пальцем остальных",191019,null],[193614,"2026-09-06T13:48:00",31,"- мне кажется, он не в себе и мы ничего от него не добьемся",191019,null],[193618,"2026-09-06T13:49:26",11,"— Кроме тех девушек в самом начале - это буквально единственный человек здесь которого мы нашли. — задумчиво протянула Аури",191019,null],[193626,"2026-09-06T13:52:04",0,"—помните то что сказал нам голос в начале\n*шепотом*",191019,null],[193630,"2026-09-06T13:52:34",0,"—он говорил про гения ставшим пугалам \n*шепотом",191019,null],[193638,"2026-09-06T13:53:14",0,"—мне кажется гений это он \n—а в пуголо превратила его жена \n*шепотом",191019,null],[193642,"2026-09-06T13:53:53",11,"Дженази задумалась\n\n— В этом есть смысл, ну по крайней мере в том что этот парень может быть этим гением",191019,null],[193651,"2026-09-06T13:57:04",0,"—так что я думаю надо поговорить с его женой \n—а она должна прийти к нему",191019,null],[193656,"2026-09-06T13:58:15",11,"— Значит хочешь вернуться? Давай попробуем. Или ребятам есть ещё что сказать?",191019,null],[193658,"2026-09-06T13:58:38",37,"// @QURTZZ @sweetkittywitch",191019,null],[193662,"2026-09-06T13:59:35",41,"( сори, кушала",191019,null],[193678,"2026-09-06T14:04:13",31,"- а как же участок? Вам не кажется что мы как резко меняем планы?",191019,null],[193681,"2026-09-06T14:04:59",11,"— Мы можем поискать его позже, а этот парень может исчезнуть снова?",191019,null],[193684,"2026-09-06T14:05:23",31,"Может кому то остаться с ним?",191019,null],[193694,"2026-09-06T14:07:43",11,"— Разделиться..? Вы уверены что это хорошая идея. Мы ведь не знаем тут ничего, можем потеряться..",191019,null],[193696,"2026-09-06T14:08:20",11,"// извините, я занята буду пока",191019,null],[193698,"2026-09-06T14:10:00",0,"—так что делаем?",191019,null],[193703,"2026-09-06T14:14:13",41,"— кто-то может отследить магические колебания чтоб мы вновь не потерялись во времени?",193681,null],[193704,"2026-09-06T14:14:27",31,"- а мы точно сможем общаться с его женой? Пока только его мы тут поняли",191019,null],[193705,"2026-09-06T14:15:34",0,"—ну если он понимает нас может быть переводчикам",193704,null],[193712,"2026-09-06T14:17:50",31,"- боюсь весь кго перевод это будет панегирик жене",193705,null],[193716,"2026-09-06T14:18:56",0,"—ну не попробуем не узнаем",193712,null],[193719,"2026-09-06T14:21:34",0,"—предлагаю проголосовать",191019,null],[193722,"2026-09-06T14:22:36",0,"—я за то чтобы ходить за ним",191019,null],[193728,"2026-09-06T14:24:27",41,"— мне кажется, нам нужно разобраться самим...",191019,null],[193732,"2026-09-06T14:25:38",0,"—то есть идти в участок? \n—или что?",193728,null],[193743,"2026-09-06T14:33:03",31,"- я за поиск участка",191019,null],[193745,"2026-09-06T14:40:48",41,"— я за поиск этого участка",193732,null],[193746,"2026-09-06T14:41:34",0,"— ну тогда пошлите искать участок",191019,null],[193905,"2026-09-06T16:27:19",41,"Ищем?",191019,null],[193906,"2026-09-06T16:27:34",41,"/r d20-1 анализ, что за участок мы ищем?",191019,null],[193909,"2026-09-06T16:28:36",37,"// Ждём решения @Ashenchampion, просто она отошла",191019,null],[193910,"2026-09-06T16:28:51",41,"( а ок",191019,null],[193955,"2026-09-06T16:49:13",11,"// Спасибо что подождал",193909,null],[193970,"2026-09-06T16:51:38",11,"— Может действительно стоит разделиться? — Аури вновь оценивает улицу и разводит руками в обе стороны показательно — пока что здесь только путь вперёд и назад, потеряться тяжело. Если одна группа останется с этим парнем здесь или пойдёт обратно вторая легка найдет их? Те слова вначале что-то значили, я уверена, если это правда он возможно наша задача как-то помочь ему? \n\nДальше поток ее мыслей уходит в сказочную фантазию\n\n— А вдруг его жена злая ведьма которая заколдовала весь город и нам нужно его спасти?",193732,null],[193971,"2026-09-06T16:52:01",37,"По твоим подсчётам вы ищете какой-то участок, что поможет вам разобраться, где вы.",193906,null],[193972,"2026-09-06T16:52:21",31,"- или он злой колдун-извращенец, что нас использует как игрушку и тихонько смеётся",191019,null],[193973,"2026-09-06T16:52:48",0,"—ну улица то не большая \n—но если снова произойдет что-то со временем",193970,null],[193975,"2026-09-06T16:52:59",37,"// Прошу всех проверку внимания",191019,null],[193977,"2026-09-06T16:53:29",0,"/r d20+4",191019,null],[193988,"2026-09-06T16:55:10",31,"/roll d20-1",191019,null],[193992,"2026-09-06T16:56:13",41,"— а если мы разделимся и попадем в разное время?(",193970,null],[193997,"2026-09-06T16:57:43",37,"@sweetkittywitch @Ashenchampion",193975,null],[193998,"2026-09-06T16:58:09",41,"/r d20",191019,null],[194020,"2026-09-06T17:04:41",11,"— Ты права.. — девушка испуганно обняла Летицию — ладно давайте искать «участок» вместе! А того парня мы сможем найти ведь знаем где его дом!",193992,null],[194024,"2026-09-06T17:06:11",41,"— Да! Может еще встретимся с ним через...пару недель! Главное чтоб в нашем мире время шло не так быстро...мой дорогой Бенжамин с ума сойдет. А нам еще ведьму искать!",191019,null],[194027,"2026-09-06T17:06:33",11,"кивает",191019,null],[194028,"2026-09-06T17:10:33",37,"Как только вы заговорили про время вы заметили, что резко стемнело, а из-за двери показался мужчине.\n— Ох, ещё раз здравствуйте... Можно я пройду?\n  Мужчина проходит мимо вас. Теперь вы смогли понять, что на нем поисковый костюм черного цвета.",191019,null],[194029,"2026-09-06T17:10:53",11,"// это другой мужчина или тот же?",191019,null],[194030,"2026-09-06T17:11:21",41,"( мне кажется тот же",191019,null],[194031,"2026-09-06T17:12:30",37,"// Тот же",194029,null],[194032,"2026-09-06T17:12:59",31,"- последим?",191019,null],[194033,"2026-09-06T17:13:53",11,"— Да, конечно, простите — растерянно протараторила девушка и отодвинулась от двери",194028,null],[194034,"2026-09-06T17:14:11",11,"— Что за странная одежда..? И был ли он в ней в прошлый раз? — шепотом",191019,null],[194039,"2026-09-06T17:16:26",41,"— точно нет \n\nШепчет Летиция",191019,null],[194040,"2026-09-06T17:16:59",0,"—стой \n—сколько времени прошло с нашей  прошлой встречи",194028,null],[194041,"2026-09-06T17:17:08",11,"— Мы ведь стояли все время здесь он не выходил.. и стемнело резко",191019,null],[194042,"2026-09-06T17:17:31",41,"— будто мы не заметили, как он вышел...",191019,null],[194043,"2026-09-06T17:17:37",37,"Мужчина остановился и немного подумав сказал.\n— 6 часов и 12 минут, а что?",194040,null],[194044,"2026-09-06T17:17:50",0,"—а как мы ушли?",194043,null],[194045,"2026-09-06T17:18:02",11,"— Ох.. мы ведь решили идти к участку, но учитывая поворот событий давайте попробуем посмотреть что будет если пойти с ним..?",194032,null],[194046,"2026-09-06T17:18:14",0,"—и зачем ты считал?",194043,null],[194048,"2026-09-06T17:18:50",41,"— почему время не ускоряется, когда мы с кем-то здесь говорим?",191019,null],[194049,"2026-09-06T17:19:17",37,"— А что ещё делать? Я просто делал это, чтобы отвлечься от раздумий...",194046,null],[194050,"2026-09-06T17:19:37",0,"—так как мы ушли?",194049,null],[194052,"2026-09-06T17:19:47",31,"- возможно это только кажется, иликачки времени не линейные",194048,null],[194055,"2026-09-06T17:21:03",37,"— Вы сказали, что хотели отойти и все покинули кафейню",194050,null],[194057,"2026-09-06T17:22:11",11,"— Есть у меня догадка..",194048,null],[194058,"2026-09-06T17:22:14",0,"—ты снова забежал?",194055,null],[194059,"2026-09-06T17:22:45",41,"— Какая?",194057,null],[194061,"2026-09-06T17:24:08",11,"Остроухая наклоняется к подруге что бы прошептать на ухо\n\n— А что если этот человек - главный герой? А время течет только так как нужно в его истории?",194059,null],[194063,"2026-09-06T17:25:05",37,"— Что значит забежал? Я все время сидел в кафейне и пил свой кофе, а сейчас пойду домой...",194058,null],[194065,"2026-09-06T17:25:44",41,"От удивления, Летиция прикрыла рот рукой.\n\n— А ты слышала тот страшный голос в начале всего этого? Что он там говорил?...",194061,null],[194066,"2026-09-06T17:25:56",41,"/r d20-1 вспомнить",191019,null],[194068,"2026-09-06T17:26:03",0,"—ты 6 часов пил одно кофе?",194063,null],[194069,"2026-09-06T17:27:02",37,"Ты вспоминаешь что-то о гении, что то стал пугалом.",194066,null],[194072,"2026-09-06T17:27:19",37,"— Да, а что-то не так? Я не умею тратить деньги.",194068,null],[194074,"2026-09-06T17:27:50",11,"— «Слышали о гении который стал чучелом?» — повторила девушка",194065,null],[194077,"2026-09-06T17:28:31",0,"—да не все нормально\n—как жена как дети",194072,null],[194079,"2026-09-06T17:29:37",11,"— А вам нужно потратить деньги? Хотите мы поможем с этим — Аури решила влезть в разговор \n\n«Может так у нас получится пойти вместе с ним не преследуя его?» — подумала она",194072,null],[194094,"2026-09-06T17:31:15",37,"— Ну я не знаю сколько у меня...\n Мужчина полез в карманы и наскреб около 5 или 6 серебряных монет. Похоже он был очень беден.",194079,null],[194095,"2026-09-06T17:31:29",37,"— Ох... Детей у меня нету...",194077,null],[194098,"2026-09-06T17:32:21",41,"— Вот!",194074,null],[194099,"2026-09-06T17:32:34",0,"—а кто ещё живёт рядом с тобой",194095,null],[194102,"2026-09-06T17:32:59",11,"Аури смотрела на него уже с искренним сочувствием\n\n— Послушайте, а как ваше самочувствие? Может вам к жрецу нужно?\n\n«Или нам?»",194094,null],[194106,"2026-09-06T17:33:55",37,"— Дом 33... Имеет планировку публичного дома...",194099,null],[194107,"2026-09-06T17:34:09",37,"— Кто такие жрецы?",194102,null],[194108,"2026-09-06T17:34:24",0,"—а кто-то живёт рядом?",194106,null],[194109,"2026-09-06T17:34:41",11,"— Очень сильные лекари!",194107,null],[194112,"2026-09-06T17:34:43",37,"— Ну 18 квартир, я живу в 3ей...",194108,null],[194115,"2026-09-06T17:35:05",11,"своим\n\n— Он правда какой-то странный, не знает даже кто такие жрецы.. впрочем город тоже странный..\n\n// Современный я полагаю?",191019,null],[194127,"2026-09-06T17:36:24",0,"—ты кого-то из людей видел?",194112,null],[194128,"2026-09-06T17:36:28",37,"— Понятно... Нужно тогда спросить у жены...\n Мужчина поклонился немного и пошел в дальше по дороге, вместе с этим вы заметили, что здание, в котором был мужчина начало растворяться в виде странных бабочек...",194109,null],[194131,"2026-09-06T17:37:12",37,"— Я не выхожу так часто на улицу... Только жена и силуэты её гостей...",194127,null],[194136,"2026-09-06T17:37:49",11,"Девушка показывает пальцем на это\n\n— Я вам говорю! Мир будто.. создаётся вокруг него?",194128,null],[194161,"2026-09-06T17:41:13",0,"—что делаем?",191019,null],[194165,"2026-09-06T17:41:50",31,"- если мир и правда вокруг него крутится, то надо бы за ним идти. Хотя, может он просто будет нам везде попадаться, если он главный герой?",191019,null],[194166,"2026-09-06T17:42:26",11,"— Последнее предложение интересно проверить, мы уже встретили его дважды.. трижды, если это произойдет снова я точно поверю в это",194165,null],[194169,"2026-09-06T17:43:09",0,"—да но тогда надо чтобы он пришёл туда где мы \n—а может он придет через год или два\n—а может быть и никогда",194165,null],[194170,"2026-09-06T17:43:27",11,"— ..Вот! Ты прав!",194169,null],[194171,"2026-09-06T17:44:02",31,"- или этот год пройдёт для нас незаметно",191019,null],[194174,"2026-09-06T17:44:31",11,"— Может дело не в том что время для нас течет иначе, а он просто появляется перед нами оживляя вокруг себя мир только тогда когда действительно попадает в то место где мы?",191019,null],[194176,"2026-09-06T17:44:42",11,"— А для нас время течёт.. обычно?",194171,null],[194179,"2026-09-06T17:45:04",31,"- очевидно нет, мы тут по своему ощущению сколько, час? А для него две недели прошло",194176,null],[194181,"2026-09-06T17:45:10",11,"— Как и для него, но наши «обычно» разные, а когда мы рядом с ним то время начинает течь одинаково для всех?",191019,null],[194183,"2026-09-06T17:45:24",31,"- похоже на то",194181,null],[194187,"2026-09-06T17:45:45",11,"— Если бы наше время текло не обычно, то мы бы уже проголодались за это время",191019,null],[194188,"2026-09-06T17:45:46",31,"- То есть если мы будет рядом постоянно, то как то синхронизируемся?",191019,null],[194189,"2026-09-06T17:45:48",0,"—но почему тогда наступа ночь за секунду",191019,null],[194191,"2026-09-06T17:46:08",31,"- так мы вышли из кофейни, и для него наступила другая сцена",194189,null],[194192,"2026-09-06T17:46:13",31,"- мы словно в книге",191019,null],[194194,"2026-09-06T17:46:26",11,"— Он был не рядом с нами, а в этом исчезнувшем здании, а когда вышел то его «сцена» была другой?",194189,null],[194195,"2026-09-06T17:46:40",11,"Кив-кив",194192,null],[194197,"2026-09-06T17:47:20",31,"- а никто не помнит, что было на тех картинах, на выставку которых мы ходили? Может там что было, что может прояснить ситуацию?",191019,null],[194204,"2026-09-06T17:52:15",37,"// Прошу прокинуть историю",194197,null],[194207,"2026-09-06T17:55:21",41,"( так тут",191019,null],[194209,"2026-09-06T17:55:48",11,"/roll d20+6",194204,null],[194211,"2026-09-06T17:56:00",41,"— мне нравится твоя теория о главном герое...только жаль у нас нет жрецов",194187,null],[194220,"2026-09-06T17:58:54",37,"Ты вспоминаешь, что выставка была посвящена изучению истории прошлой эры, а именно до Рагнорека, хотя ты и не могла вспомнить про что там было.",194209,null],[194228,"2026-09-06T18:01:04",31,"/roll d20+1",194204,null],[194238,"2026-09-06T18:04:49",41,"/r d20-1 Мало ли",191019,null],[194242,"2026-09-06T18:05:39",0,"/r d20+1",191019,null],[194245,"2026-09-06T18:05:54",11,"— Что-то о событиях прошлого, но сами изображения вспомнить не могу",194197,null],[194247,"2026-09-06T18:06:17",41,"— Хм... Там точно не было драконов...",191019,null],[194259,"2026-09-06T18:11:44",37,"Ты припоминает странною страницу текста, в которой упоминался странный дракон, который не дракон.",191019,null],[194261,"2026-09-06T18:13:58",37,"Для @sweetkittywitch @QURTZZ",194259,null],[194263,"2026-09-06T18:14:26",31,"Ага, я прочитал/",191019,null],[194268,"2026-09-06T18:14:54",31,"- дракон, что не дракон...",191019,null],[194276,"2026-09-06T18:17:51",31,"- ладно, надо решать что делать. Идем за ним и отслеживаем историю?",191019,null],[194277,"2026-09-06T18:19:24",11,"— Или подождем следующей встречи что бы проверить теорию?",191019,null],[194281,"2026-09-06T18:19:46",31,"Предлагаешь просто стоять на месте?",194277,null],[194282,"2026-09-06T18:20:04",41,"— Псевдо - дракон...?",194259,null],[194283,"2026-09-06T18:21:03",0,"—Хм\n—только почему кофейня превратилась в бабочек?",191019,null],[194284,"2026-09-06T18:21:33",31,"- ну знаешь, он так говлрил о жене, может это бабочки из его живота?)",194283,null],[194289,"2026-09-06T18:23:37",41,"— Ой, и правда)",191019,null],[194290,"2026-09-06T18:24:37",11,"— Романтичная теория, но может просто этой кофейни больше не будет в его истории?",191019,null],[194293,"2026-09-06T18:25:06",31,"- главное чтобы мы бабочками не стали",191019,null],[194295,"2026-09-06T18:25:26",11,"— Можем пойти поискать других обитателей этого места, мы ведь видели двоих девушек в начале.. вдруг мы сможем узнать что-то у них. Теория либо подтвердиться либо опровергнеться",194281,null],[194301,"2026-09-06T18:26:13",0,"—в доме должны быть ещё жители",191019,null],[194302,"2026-09-06T18:26:15",11,"— Мы зачем-то сюда попали так что не думаю что такое случится, не переживай — она кладет руку на плече Конраду — но если хотите можем пойти за ним, я не против",194293,null],[194309,"2026-09-06T18:27:11",41,"— Ребята, может мы злодеи в этой истории?",191019,null],[194310,"2026-09-06T18:27:42",11,"— Почему ты так думаешь?",194309,null],[194314,"2026-09-06T18:27:56",37,"Пара бабочек пролетает мимо вас и затем прилетают ещё, что они полностью закрывают вам обзор.",191019,null],[194315,"2026-09-06T18:28:00",0,"—ну тогда стоит завершить её сейчас",194309,null],[194317,"2026-09-06T18:28:18",41,"— мы... Слишком навязчивые к парню. Но у нас есть мотивация,",194310,null],[194319,"2026-09-06T18:28:34",41,"— Ой...",194314,null],[194320,"2026-09-06T18:28:48",37,"После этого вы обнаруживаете себя снова перед домом, а мужчина только подошёл к своему дому под номером 33. Он стоял на первом этаже и только собирался открыть дверь.",191019,null],[194323,"2026-09-06T18:29:24",37,"Он без стука открывает дверь и на пару секунд стоит неподвижно.",191019,null],[194325,"2026-09-06T18:29:39",31,"- похоже, радиус его способностей ограничен и нас таскает за ним как хвост",191019,null],[194326,"2026-09-06T18:29:52",31,"Заглядываю в открытую дверь",194323,null],[194328,"2026-09-06T18:30:09",11,"— Ха-ха, похоже за нас решили",191019,null],[194329,"2026-09-06T18:30:16",37,"Из его рук упали монеты, а также послышался странный голос мужчины, что говорил на странном языке.",191019,null],[194332,"2026-09-06T18:30:32",0,"Бегу туда *",191019,null],[194337,"2026-09-06T18:31:23",37,"Ты замечаешь довольно красивую даму с чисто белыми волосами и голубыми, как небо глазами. Она имела хорошую фигуру и стройное тело. Она был на половину нагая. А рядом стоял мужчина тоже на половину нагой, но вы не могли его рассмотреть.",194326,null],[194343,"2026-09-06T18:32:19",37,"Мужчина стоит пару секунд в молчании и когда он начал реагировать, то просто развернулся и пошел из дома довольно быстрым шагом.",191019,null],[194345,"2026-09-06T18:32:30",11,"// наполовину ногой, извини забавная опечатка 😅",191019,null],[194346,"2026-09-06T18:32:42",37,"Его, похоже, жена немного встала и посмотрела вслед уходящему мужчине.",191019,null],[194349,"2026-09-06T18:33:53",11,"— Что увидел, Конрад?",191019,null],[194352,"2026-09-06T18:34:52",37,"Ты видишь тоже самое, что и Конрад.",194332,null],[194354,"2026-09-06T18:35:46",31,"- Там его полуголая жена с таким же полуголым мужиком. Видимо, клиент, не зря этот дом похож на бордель",194349,null],[194356,"2026-09-06T18:36:07",37,"Мужчина перестал обращать внимания и идти дальше по дороге, которая появлялась прямо перед ним из бабочек.",191019,null],[194357,"2026-09-06T18:36:12",41,"Летиция отворачивает взгляд смущенная",194337,null],[194358,"2026-09-06T18:37:00",11,"Девушка была рада что не заглядывала туда вместе с товарищем\n\n— ..Я надеялась что мы ошиблись..",194354,null],[194360,"2026-09-06T18:37:32",31,"Конрад, цинично:\n\n- это жизнь, она бывает и такой",194358,null],[194361,"2026-09-06T18:37:35",41,"— а почему нас перенесли? Мы что-то сделали не так?",191019,null],[194364,"2026-09-06T18:37:46",0,"кричу женщина\n—здравсте",191019,null],[194365,"2026-09-06T18:37:47",31,"- думаю, нач таскает за парнем",194361,null],[194370,"2026-09-06T18:41:13",11,"Аури предпочла не отвечать и подождать пока Стэт вернётся",194360,null],[194373,"2026-09-06T18:42:36",0,"@STR_V_Alekseev женщина отвечает? //",191019,null],[194387,"2026-09-06T18:51:21",37,"// постов немного не будет",191019,null],[194388,"2026-09-06T18:51:21",37,"Я получил тут в лицо",191019,null],[194395,"2026-09-06T18:53:46",31,"Все в порядке?/",194388,null],[194398,"2026-09-06T18:54:52",37,"Не очень",194395,null],[194408,"2026-09-06T18:57:12",11,"// не знаю с чем, но удачи тебе там, продолжим как у тебя будет возможность",194398,null],[194409,"2026-09-06T18:57:36",41,"( ага, держись",194398,null],[194774,"2026-09-06T20:40:32",37,"// Так",191019,null],[194775,"2026-09-06T20:40:37",37,"// Я отошел",191019,null],[194777,"2026-09-06T20:40:40",37,"// Продолжаем",191019,null],[194781,"2026-09-06T20:41:18",37,"\"Жена\" похоже даже не замечала тебя в своем сознании, будто она даже не могла воспринять тебя.",194364,null],[194794,"2026-09-06T20:42:48",37,"Когда Мужчина начал отходить вы начали слышать у себя нашептывания его же ломанного голоса.\n\n— Жена осыпала меня бранью, что же мне не спится по ночам, граблю кого-нибудь или шляюсь по притонам? Как несправедливо. Я был так изумлен, что не мог рта раскрыть.\n Я хотел выкрикнуть: «Разве не пыталась ты убить меня!» — но знал, какая брань обрушится на меня, если эти необоснованные обвинения слетят с моих губ.\n\nНо сам мужчина ничего не говорил своим ртом и медленно шел от двери.",191019,null],[194818,"2026-09-06T20:46:55",37,"// @tochhkatochka @sweetkittywitch @Ashenchampion @QURTZZ",191019,null],[194819,"2026-09-06T20:47:10",41,"( тебе лучше ?",191019,null],[194821,"2026-09-06T20:47:18",37,"// Да",194819,null],[194826,"2026-09-06T20:48:10",37,"// Давайте немного ускоримся и закончим первую часть, тут финишная прямая.",191019,null],[194829,"2026-09-06T20:49:15",0,"—вы тоже слышите голос?",191019,null],[194840,"2026-09-06T20:52:39",11,"— Да",191019,null],[194853,"2026-09-06T20:55:42",0,"*кричу ему \n—Эй стой",191019,null],[194858,"2026-09-06T20:57:32",37,"Он начал идти довольно медленно и не слышал ваших слов. Локация вокруг вас немного менялась за тем, как человек шел по улицам, что строились перед ним, как в какой-нибудь сцене и за ширмой меняют декорации.",191019,null],[194860,"2026-09-06T20:57:43",11,"Девушка пытается догнать его и схватить за запястье",191019,null],[194863,"2026-09-06T20:58:53",37,"Мужчина резко останавливается и посмотрев на него ты увидела странные эмоции, что тебе не были понятны.\n// Спас интеллекта. СЛ 20",194860,null],[194864,"2026-09-06T20:59:39",0,"Тоже пытаюсь его схватить \n—стой мы можем выпить пиво обсудить все",191019,null],[194871,"2026-09-06T21:01:06",37,"// Спас интеллекта",194864,null],[194872,"2026-09-06T21:01:10",11,"// было близко, но увынск",191019,null],[194875,"2026-09-06T21:01:49",37,"/r 2d6\nТвой разум ненадолго хватает мысли очень странную. Мы в реальном месте... И на этом твой разум начал немного тресктаься",194869,null],[194876,"2026-09-06T21:01:55",37,"/r 2d6",191019,null],[194880,"2026-09-06T21:02:20",11,"Из-за резкой боли в голове, расходящейся по телу девушка отпускает руку",191019,null],[194887,"2026-09-06T21:04:15",0,"/r d20+1",191019,null],[194892,"2026-09-06T21:05:13",37,"/r 2d6 псих урона и та же мысль, что у Ани.",194887,null],[194903,"2026-09-06T21:09:06",37,"Мужчина продолжил идти после того, как вырвался и вы начали слышать продолжение его ломанным голосом.\n\n— Сначала я подумал, что, как бы все это ни было несправедливо, пожалуй, лучшая тактика — лежать молча, но, сам не знаю почему, встал, отряхнулся, вытащил из кармана оставшиеся деньги — несколько вон с мелочью, — тихонько приоткрыл дверь и украдкой положил их под порог, а затем выскочил на улицу.\n Несколько раз чуть не попав под карету, я все-таки добрался до центральной гильдии. Сел за столик. Хотелось хоть чем-нибудь заесть горький привкус во рту.\n Кофе. Хорошо бы. Но только я шагнул в зал ожидания, я вспомнил, что у меня в кармане нет ни одной монетки. Голова опять закружилась. Я совсем пал духом и не знал, как поступить. Бродил по городу, как полоумный…",191019,null],[194916,"2026-09-06T21:13:34",11,"— Ты тоже это ощутил, Стэт? Есть идеи как его остановить, не касаясь.. может сеть там..?",191019,null],[194918,"2026-09-06T21:14:37",37,"Вы начали замечать, как из его спины, а именно из области лопаток начинает образовываться странный силуэт крыльев из стекла и солнечных зайчиков.",194903,null],[194919,"2026-09-06T21:14:58",0,"—не знаю он нас не слышит и коснуться мы его не можем",191019,null],[194921,"2026-09-06T21:16:59",11,"— Я боюсь ещё одного такого касания я не выдержу..",191019,null],[194922,"2026-09-06T21:17:16",11,"— Последуем за ним..?",191019,null],[194923,"2026-09-06T21:18:38",0,"—да",191019,null],[194925,"2026-09-06T21:19:32",37,"Мужчина продолжает идти. Из его спины продолжает образовываться пара крыльев, а локации меняться.\n Голос же очень душевно и филигранно говорил вам.\n\n— Не помню, где я слонялся. Когда я обнаружил, что стою на крыше лавки «Мицукоши», был уже почти полдень.\n Я опустился на какую-то скамейку и попытался припомнить двадцать шесть лет своей жизни. Но из смутных воспоминаний не вырисовывалось ничего конкретного.\n Я спрашивал себя. Хоть к чему-нибудь ты стремишься в жизни? Да или нет — я не хотел отвечать на этот вопрос. Я уже не верил даже в собственное существование.\n \n Вы заметили, что стоите прямо под зданием в высоту пять этажей, а мужчина поднялся на крышу. Похоже вам туда не добраться, ведь бабочки преграждали путь.",191019,null],[194929,"2026-09-06T21:20:49",0,"*пытаюсь пробиться сквозь них",191019,null],[194930,"2026-09-06T21:21:08",37,"// Проверка атлетики/акробатики",194929,null],[194931,"2026-09-06T21:21:29",0,"/r d20+3",191019,null],[194933,"2026-09-06T21:21:34",11,"— Стой, если он хочет прыгнуть с высоты мы можем просто поймать его здесь",191019,null],[194934,"2026-09-06T21:21:55",41,"— Давайте тогда так...",194933,null],[194935,"2026-09-06T21:22:31",37,"Ты с лёгкостью проходишь через толпу бабочек, но из-за их количества ты мог двигаться очень медленно.\n// Труднопроходимая местность.",194931,null],[194936,"2026-09-06T21:23:28",0,"//сколько футов до него",194935,null],[194937,"2026-09-06T21:23:47",37,"// около 300-350.",194936,null],[194938,"2026-09-06T21:24:19",0,"//не мало",194937,null],[194941,"2026-09-06T21:25:04",0,"*пытаюсь прийти к нему как можно быстрее",191019,null],[194943,"2026-09-06T21:25:34",37,"Голос продолжил.\n\n— Перегнувшись через перила, я смотрел на золотых рыбок. Какие они красивые. Маленькие нравились мне маленькими, а большие - большими, и все они были такими шустрыми, приятно посмотреть. В лучах майского солнца рыбки отбрасывали на дно аквариума тени. Их плавники были похожи на платочки. Я стоял, не разгибаясь, и пытался сосчитать рыбок. Спину грело солнце.\n\nВы заметили, что прямо к краю крыши вышел мужчина и смотрел на облака в небе.",191019,null],[194945,"2026-09-06T21:27:50",37,"Ты прошел только первый этаж из пяти. Ещё черты и по крыше бежать, если попытаться, то можно успеть... Эти бабочки очень сильно мешают.\n\n У мужчины же начали образовываться довольно средние крылья, что были из обломком стекла и создавали солнечных зайчиков.",194941,null],[194946,"2026-09-06T21:27:53",11,"— Лети, Конрад, помогите! — Аури достает холстину из сумки, сворачивает 5кв. м. ткани в пару слоев и даёт края товарищам",191019,null],[194947,"2026-09-06T21:28:03",41,"летиция побежала к нему",194943,null],[194948,"2026-09-06T21:28:13",41,"— НЕТ НЕТ НЕТ",191019,null],[194949,"2026-09-06T21:28:19",37,"Проверку акробатики/атлетики",194947,null],[194950,"2026-09-06T21:28:33",0,"*бегу быстрее",194945,null],[194951,"2026-09-06T21:28:42",41,"/r d20+2",194949,null],[194955,"2026-09-06T21:29:41",11,"// пользуюсь тем что Леша сейчас спит и надеюсь что хоть Конрад мне поможет снизу расправить ткань",191019,null],[194956,"2026-09-06T21:30:04",41,"— НЕ ПРЫГАЙ! \n\nЛети будто не соображает",191019,null],[194957,"2026-09-06T21:30:32",37,"Ты тоже бежишь через бабочек, но очень медленно.\n// Труднопроходимая местность.",191019,null],[194959,"2026-09-06T21:31:32",37,"Голос же продолжал.\n\n— Я посмотрел вниз на оживленные улицы. Там осторожно шевелилась надоевшая жизнь, раскачивалась, словно плавники золотых рыбок. Люди, крепко связанные невидимыми путами, не могли освободиться. Я подтащил вперед свое тело, разламывавшееся от усталости и голода, и подумал, что мне тоже нужно смешаться с оживленной толпой.\nЯ сделал еще шаг вперед и задумался. Куда ведет этот путь…\n\nВы видели, что рядом с вами начали ходить люди, что ходили по площади и разным лавкам. Это были разные личности и расы.",191019,null],[194960,"2026-09-06T21:31:34",41,"Она приказывает Фамильяру пролететь над бабочками",191019,null],[194962,"2026-09-06T21:31:55",37,"// какая скорость у фамильяра?",194960,null],[194963,"2026-09-06T21:32:02",41,"( ща",191019,null],[194966,"2026-09-06T21:32:39",41,"(60 летая",191019,null],[194972,"2026-09-06T21:33:48",37,"Твой фамильяр догоняет Стэта и вы оба добрались до второго этажа. Бабочек было все также много и они не давали четко видеть.",191019,null],[194973,"2026-09-06T21:33:55",37,"Ты же добралась только до 1го",191019,null],[194974,"2026-09-06T21:34:37",41,"/r d20+2 иду дальше",191019,null],[194976,"2026-09-06T21:34:44",41,"( не иду",191019,null],[194977,"2026-09-06T21:35:08",41,"Внутриидома издается не человеческий крик",191019,null],[194978,"2026-09-06T21:35:30",11,"Аури примерно выцеливает место куда может упасть мужчина и просит Конрада помочь ей расправить ткань",191019,null],[194979,"2026-09-06T21:36:06",41,"/r d20+2 Фамильяр летит",191019,null],[194981,"2026-09-06T21:36:13",41,"( не летит",191019,null],[194983,"2026-09-06T21:36:42",37,"Голос начал давить на ваши души и вы начинали чувствовать сильное сочувствие к мужчине.\n\n— Перед глазами молнией промелькнула злость жены. Аспирин и адалин.\n Мы с женой просто не поняли друг друга. Неужели жена вместо аспирина давала мне адалин. Не могу поверить. У нее не было на это причин, разве по ночам я воровал или шлялся по притонам? Определенно нет.\n Так уж сложилось, что мы с женой ковыляли не в ногу. Нечего искать логику в моем поведении или поведении жены. И объяснять тут нечего. Ведь могут же факты идти по миру своей дорогой, а непонимание - своей. Разве не так?\n Только вот трудно было определить, должен ли этот путь привести меня обратно к жене? Должен? А если не к жене, то куда?\n\n Вы заметили, как мужчина начал смотреть туда куда упадет, а за его спиной крвль стали очень большими, как у настоящих летающих рас.\n Стэт и фамильяр продвинулись до третьего этажа, осталось пройти только два этажа...",191019,null],[194988,"2026-09-06T21:39:22",41,"/r d20+2 ыыыть",191019,null],[194990,"2026-09-06T21:39:33",41,"/r d20+2 фамильяр",191019,null],[194992,"2026-09-06T21:40:06",37,"Вы смогли добраться до 4го этажа. (Фамильяр и Стэт)\n Летиция же поднялась только на третий и то с трудом.\n Осталось совсем немного...",191019,null],[194996,"2026-09-06T21:41:55",41,"/r d20+2 последний заход фамильяра",191019,null],[194998,"2026-09-06T21:42:05",41,"/r d20+2 летиция",191019,null],[195002,"2026-09-06T21:43:27",37,"Вы заметили изменение времени до полудня. Казалось, что время и ускорилось и замедлялось не давая так быстро пройти к мужчине.\nЛоманный голос мужчина продолжил говорть вам на ухо.\n\n— И тут пробило полдень. Люди замахали руками, словно курицы крыльями, стекло, сталь, мрамор, монеты, чернила все закипело в изумительной суете полудня.\n\n Люди и вправду стояли рядом с вами и пытались остановить мужчину.\n Вот Стэт и фамильяр добрались до пятого этажа, осталось пройти через дверь на крышу и остановить его.\n Летиция же добралась до четвертого.",191019,null],[195006,"2026-09-06T21:44:59",41,"/r d20+2 Фамильяр забирается",191019,null],[195008,"2026-09-06T21:45:04",11,"Аури с Конрадом стоят внизу с натянутой холстиной аки спасатели, четко там куда должен упасть мужчина",191019,null],[195009,"2026-09-06T21:45:16",41,"/r d20+2 Летиция тоже",191019,null],[195011,"2026-09-06T21:45:21",41,"( неа",191019,null],[195012,"2026-09-06T21:45:24",0,"—стоооооооой \n*играю на гармошке что бы защитить разум себе и фамильяру\n//бардовское вдохновение себе и фамильяру\n*пытаюсь его схватить",191019,null],[195014,"2026-09-06T21:45:59",0,"//кидать д20?",191019,null],[195015,"2026-09-06T21:46:01",37,"// Проверку атлетики для захвата",195012,null],[195016,"2026-09-06T21:46:45",0,"/r d20-1+d6",191019,null],[195018,"2026-09-06T21:46:59",37,"/r d20+7 Против захвата",191019,null],[195020,"2026-09-06T21:47:31",0,"//пусть фамильяр попробует захватить",195011,null],[195021,"2026-09-06T21:48:06",11,"// помощь даст разве что",195020,null],[195023,"2026-09-06T21:50:02",37,"// @sweetkittywitch фамильяр даёт помощь?",191019,null],[195025,"2026-09-06T21:50:38",41,"( помощь",191019,null],[195028,"2026-09-06T21:51:11",37,"// @tochhkatochka перекинь захват ещё раз, без бардовского вдохновения",191019,null],[195030,"2026-09-06T21:51:27",0,"/r d20-1",191019,null],[195033,"2026-09-06T21:52:21",37,"Вы попытались схватить мужчину, но он резко прыгает, а крылья взмазивают над ним.\n Голос продолжил.\n\n— Внезапно я почувствовал легкость в подмышках. Ах, раньше тут были крылья. Теперь уж нет этих крыльев, в голове, словно странички словаря, мелькают обрывки стремлений и надежд.\nЯ замедлил шаги. Захотелось кричать:\n«О, если б мои крылья выросли снова!\nВзлететь, взлететь, взлететь… Взлететь еще раз!\nВот бы взлететь еще раз!»\n\nКрылья мужчина раскрылись и он даже пролетел пару метров, но редко его крылья исчезли и он начал падать вниз своими крыльями вперёд.",191019,null],[195035,"2026-09-06T21:53:59",41,"/r d20+2 Летиция",191019,null],[195038,"2026-09-06T21:54:38",11,"Аури старается скорректировать траекторию как надо следя за \"полетом\"",191019,null],[195041,"2026-09-06T21:55:12",37,"Прикинь самую высокую проверку",195038,null],[195042,"2026-09-06T21:55:27",37,"Именно с высоким модификатором",191019,null],[195046,"2026-09-06T21:57:01",11,"/roll d20+6 магия",191019,null],[195049,"2026-09-06T21:57:07",11,"// мням",191019,null],[195050,"2026-09-06T21:57:17",11,"// я хз можно помощь от Конрада..?",191019,null],[195053,"2026-09-06T21:58:07",41,"( могу прыгнуть за ним?",191019,null],[195055,"2026-09-06T21:58:14",41,"( хочу прикол",191019,null],[195057,"2026-09-06T21:58:40",41,"( именно поймать в полёте",191019,null],[195059,"2026-09-06T21:59:42",37,"Можно",195050,null],[195060,"2026-09-06T21:59:56",37,"Проверка самой высокой характеристики",195057,null],[195062,"2026-09-06T22:00:10",41,"/r d20+3",191019,null],[195065,"2026-09-06T22:00:41",41,"( У меня они не высокие)))",191019,null],[195072,"2026-09-06T22:02:54",11,"«Двоих ловить будет труднее» — подумала Аури",191019,null],[195077,"2026-09-06T22:04:10",37,"Перебрось кубик",195072,null],[195078,"2026-09-06T22:04:44",41,"( видимо, не поймался летун(",191019,null],[195081,"2026-09-06T22:06:15",0,"//20",191019,null],[195084,"2026-09-06T22:06:36",41,"( не",191019,null],[195092,"2026-09-06T22:08:43",41,"( уРА 5 д 6 урона",191019,null],[195096,"2026-09-06T22:09:59",37,"Летиция успевает в полете поймать мужчину. Он смотрит на неё своим мертвым взглядом и говорит.\n— Пусть мои крылья перейдут вам, в знак этого...\n Мужчина падает прямо об землю обняв нежить сверху и не дав ей принять урон на себя.\n Как ни странно Летиция никакого урона не получила, но вот мужчина...\n Он истекал весь в крови и его жизнь уходила из глаз.\n— Слышали о «гении, который стал чучелом»? Я рад. В такие моменты и любовь приносит радость...\n На этом мужчина остался с пустыми глазами, его крылья начали трескаться и расстворяться в солнечном свете.",191019,null],[195100,"2026-09-06T22:11:26",41,"— нет...нет...нет...",191019,null],[195101,"2026-09-06T22:11:37",0,"—черт черт черт",191019,null],[195102,"2026-09-06T22:11:45",41,"— НЕТ НЕТ НЕТ НЕТ НЕТ НЕТ НЕТ НЕТ НЕТ НЕТ НЕТ НЕТ!!!!",191019,null],[195103,"2026-09-06T22:11:47",0,"*иду в низ",191019,null],[195105,"2026-09-06T22:12:07",41,"вопль заполонил улицу",191019,null],[195107,"2026-09-06T22:12:24",0,"*пытаюсь вылечить лечащим словом \n//чисто отыгрышь",191019,null],[195109,"2026-09-06T22:13:11",41,"— ты должен был...взлететь... Ты хоть знал, как это больно \n\nКрик перешел в тихий шепот невесты, что однажды тоже стала чучелом",191019,null],[195110,"2026-09-06T22:13:17",11,"Аури обречённо опускается на землю",191019,null],[195113,"2026-09-06T22:15:12",37,"Бабочки начинаю растворять все вокруг вас оставляя только труп мужчины и он тоже начал исчезать в странных лучах света.\n На его месте осталась странная книга, похоже она была у него в кармане или нет... Это уже не имело значения.\n Вместе с этим часть осколков начала присоединяться к спине Летиции, имитируя крылья.",191019,null],[195114,"2026-09-06T22:16:07",41,"— Аури... Помоги мне\n\nГолос исказился до безобразия.. \n\nШея хрустнула, лица не было видно. \n\nОсколки крыльев закреплялись на спинеи",191019,null],[195116,"2026-09-06T22:19:29",11,"Аури бежит к подруге стараясь не глядеть на труп мужчины, она касается тела девушки и использует лечение ран",191019,null],[195117,"2026-09-06T22:19:39",11,"/roll d8+4 чисто нарративно",191019,null],[195120,"2026-09-06T22:20:29",41,"Летиция кладет голову ей на плечо, отползая от трупа\n\n— Почему...почему таааак?(((",191019,null],[195125,"2026-09-06T22:21:27",37,"Вы замечаете, что книга открылась сама собой и вы все услышали тот же голос, что и сказал самую первую фразу в начале...\n\n// На этом мы закончим нашу первую сессию",191019,null],[195126,"2026-09-06T22:22:08",41,"( офигеть",191019,null],[195127,"2026-09-06T22:25:45",37,"// Вы все получаете: 200 опыта за отыгрыш, 300 за завершение первого акта квеста (считается как завершение квеста). Итого 500.\n\nТакже Эля получает предмет Крылья полёта.\nЧудесный предмет, неопределенный (настройка на Летицию)\nСтоимость: ??? зм\nПока вы носите эти крылья, вы можете действием произнести командное слово. Это превратит сжатые крылья в пару крыльев из осколков стекла на неограниченное время или пока вы не повторите командное слово действием. Крылья дают вам скорость полёта 120 футов. Перезарядка между призывом крыльев 1 час.",191019,null],[195128,"2026-09-06T22:26:51",37,"// Также напомню, что все персонажи обыватели получают *3 в продвижении своих изучений класса. И ваши персонажи попадают на этот квест после квестов ивентов, а не до.",191019,null],[195129,"2026-09-06T22:26:55",41,"( когда предмет не оговорили с Хардом:",195127,null],[195130,"2026-09-06T22:27:01",41,"( беру)))",191019,null],[195131,"2026-09-06T22:27:09",37,"// Все обговаривалось",195129,null],[195132,"2026-09-06T22:27:17",41,"( офигеть",191019,null],[195133,"2026-09-06T22:27:34",37,"// И ваши персонажи не могу покинуть квест до его завершения",191019,null],[195134,"2026-09-06T22:27:48",0,"//он проколят?",191019,null],[195135,"2026-09-06T22:28:39",41,"( символически",195134,null],[195136,"2026-09-06T22:38:12",37,"🔊 Нажми чтобы найти песню",191019,null],[195137,"2026-09-06T22:38:40",37,"// Музыка которую я забыл добавить в моменте так как получил удар в лицо...",191019,null],[195138,"2026-09-06T22:41:08",11,"// 120 ф? Много прям, а хард не против? В целом хорошая штука, но скорость как-то большевата",195127,null],[195139,"2026-09-06T22:42:28",41,"( я б сделала 30 или 60",191019,null],[195140,"2026-09-06T22:42:30",37,"// Эти предметы являются таковыми при действии квеста, когда он закончится, то предметы станут своими оригиналами или будут задебаффаны.",195138,null],[195141,"2026-09-06T22:42:31",11,"// ладно если хард не против, но я удивлена прям😳 впрочем мастерам виднее и Летиции подходит",191019,null],[195142,"2026-09-06T22:42:45",11,"// поняла, спасибо за ответ",195140,null],[195143,"2026-09-06T22:44:52",37,"// Когда все собираемся? Я за 12 по мск или около того.\n@Ashenchampion @sweetkittywitch @tochhkatochka @QURTZZ",191019,null],[195145,"2026-09-06T22:54:21",0,"//возраст задержусь а так за",195143,null],[195149,"2026-09-06T23:06:57",41,"Обновила скинчик Летиции",191019,null],[195422,"2026-09-07T12:17:29",41,"( время писать свою историю?)",191019,null],[195423,"2026-09-07T12:18:11",37,"// Щас, я допишу пост, просто когда идёшь не удобно писать",195422,null],[195428,"2026-09-07T12:18:36",41,"Оке",195423,null],[195440,"2026-09-07T12:42:22",37,"— Книга Вторая: Посторонний.\n\n// Только @sweetkittywitch и её персонаж могу прочитать спойлер.\n\n Голос говорит следующее:\n\n— Сегодня умерла мама. Или, может, вчера, не знаю...\n\nВокруг вас начала образовываться новая местность.\n\nЭта были поля. Над холмами, которые отгораживают от моря, небо закраснелось. И ветер доносил из-за холмов соленый запах. Начиналось утро.\nВокруг были окрестные поля. Сквозь ряды кипарисов, тянувшиеся к холмам у самого горизонта, на этой рыжеватой и зеленой земле, среди редко разбросанных, но четких домов можно было заметить прямо перед собой дом. Точнее не дом, а большой участок. Вы могли догадаться, что это был Дом Презрения/Престарелых.",195125,null],[195441,"2026-09-07T12:42:42",37,"// @sweetkittywitch @QURTZZ @Ashenchampion @tochhkatochka если все готовы, то начинаем.",191019,null],[195442,"2026-09-07T12:43:31",41,"( Ого, триггер варнинг мне",191019,null],[195445,"2026-09-07T12:50:51",31,"Я тут/",191019,null],[195449,"2026-09-07T13:00:11",37,"// А, там ошибка просто",191019,null],[195450,"2026-09-07T13:00:22",37,"// Т9 еб***й",191019,null],[195452,"2026-09-07T13:07:05",41,"Солнечный свет обогрел Летицию, сделав её нежнее и прозрачнее в руках Аури. Девушка утерла слезы, но не отходила от подруги. \n\n— Заря… Спасибо, что ты есть … \n\nСейчас ей было невероятно одиноко. Среди историй плохих концовок , она нуждалась именно в подруге, а не просто друге. Её прохладность, свежесть и нежность идеально чувствовалась призраком. \n\n— Спасибо…\n\nДженази могла заметить небольшие шрамы, похожие на трещины по телу Летиции. Глаза поймали солнечный свет, новое место заинтересовало её не меньше произнесенной фразы, несущей горечь утраты",191019,null],[195500,"2026-09-07T14:25:15",41,"— я не знаю... Но мне кажется, что явно не от крыльев...я просто...вспомнила кое-что. \n\nСлегка отпрянув от подруги, она осмотрелась внимательнее.\n\n— Его больше нет...",191019,null],[195521,"2026-09-07T14:34:41",41,"— Ты не виновата...я думала он взлетит, но он спас меня...",191019,null],[195526,"2026-09-07T14:38:15",31,"- никто не виноват в его смерти, не нужно на себя лишнего брать. Очевидно, у него была цель, и он бы к ней пришел в любом случае. Серьезно, как ты можешь посещать тому, кто буквально управляет этим миром?",191019,null],[195532,"2026-09-07T14:40:31",31,"- я бы предложил подумать, а где мы вообще? И если и правда тот парень управлял сюжетом, то кто перехватил управление сейчас?",191019,null],[195535,"2026-09-07T14:42:22",41,"— я не знаю точно... Здесь единственный дом, зайдем туда?",191019,null],[195552,"2026-09-07T14:47:33",31,"- не вижу причины этого не сделать",195535,null],[195553,"2026-09-07T14:47:35",41,"— В каком-то смысле... Это не плохо. Наши помыслы чисты...хоть злодеи мы для героев и...автора.",191019,null],[195555,"2026-09-07T14:48:33",31,"- хмм, если ты думаешь что ты злодей, то как минимум сомневаешься в себе. Настоящий злодей не сомневался бы",195553,null],[195578,"2026-09-07T14:56:49",41,"— можно ли вмешаться в смерть?",191019,null],[196270,"2026-09-07T17:17:44",37,"// @Ashenchampion @sweetkittywitch @tochhkatochka @QURTZZ",191019,null],[196298,"2026-09-07T17:21:02",41,"— не знаю...будем надеяться, чтотдальше сможем...",191019,null],[196314,"2026-09-07T17:24:07",37,"// Че делаете?",191019,null],[196335,"2026-09-07T17:26:14",31,"Вроде очевидно высказались за проход в дом/",191019,null],[196377,"2026-09-07T17:31:53",37,"Подойдя к забору перед домом презрения, вы замечаете, что к вам на встречу идет старый человек.\n Ему на вид было около 60 лет. Имел белые усы, голубые глаза и немного красноватый цвет кожи, похоже от загара.\n\n— Здравствуйте, дорогие гости, зачем пожаловали в дом презрения?",191019,null],[196426,"2026-09-07T17:39:17",41,"— мы как раз из общества… поддержки… хотели поболтать со стариками, на которых уже многим всё равно…",191019,null],[196452,"2026-09-07T17:42:39",37,"— Чтож... Рад, что кто-то из молодежи проявляет интерес к нам старикам... Но я не смогу вас так хорошо провести по нашему дому призрения так как у нас умерла Госпожа Мерсо...\n Привратник открывает ворота и пропускает вас внутрь",191019,null],[196463,"2026-09-07T17:44:36",41,"— Госпожа Мерсо… это хозяйка ?",191019,null],[196466,"2026-09-07T17:44:58",37,"— Нет, что вы... Просто одна из наших жителей...",196463,null],[196508,"2026-09-07T17:50:37",41,"На словах о сыне, девушка задумалась… а он ли туда прийдет?",191019,null],[196513,"2026-09-07T17:50:48",41,"— Спасибо большое…",191019,null],[196553,"2026-09-07T17:56:35",37,"Ты услышала совершенно другой голос. Более четкий и твердый. Будто говорил мужчина крепкого телосложения.\n\n— Получил телеграмму из дома призрения: \"Мать Скончалась. Похороны завтра. Соболезнуем\". Не поймешь. Возможно, вчера...\n... Выеду двухчасовым рейсом на карете и еще засветло буду на месте. Так что успею побыть ночью у гроба и завтра вечером вернусь.",196508,null],[196559,"2026-09-07T17:57:57",41,"Она закономерно огляделась в поисках источника голоса. Но теперь, кажется, на руках у неё была некая информация",196553,null],[196583,"2026-09-07T18:02:01",31,"- расскажите нас подробнее об усопшей? Раз уж мы очевидно попадем на ее похороны , то хотелось бы знать о ней. Да и о ее сыне тоже",191019,null],[196788,"2026-09-07T18:31:02",37,"— Ох, господин Мерсо очень строгий мужчина, не многословен и даже довольно холоден, но он привел свою мать сюда по её инициативе... \n Вас провели через главную дверь здания из дерева.\n Интерьер был довольно красив и спокоен. Было немного картин и пару статуй миниатюрного размера. Хороший серый ковер и хорошая люстра из железа.\n— Пройдемте в столовую...",196583,null],[196831,"2026-09-07T18:36:58",37,"// Я сам нашел ошибку пару минут назад",191019,null],[196833,"2026-09-07T18:37:28",41,"( я думала презренное потому что молодняк стариков не любит",191019,null],[196835,"2026-09-07T18:37:37",31,"Слава Богу, а то башку сломал как тут людей презирают/",191019,null],[196847,"2026-09-07T18:38:23",31,"Групповое занятие по осуждающим взглядам, мастер-класс по поджатым губам и так далее/",191019,null],[196853,"2026-09-07T18:39:07",37,"// Я сам думал что что-то не так, ведь я вроде все пишу правильно, а потом нашел опечатку, когда открыл текст книги.",191019,null],[196987,"2026-09-07T18:57:21",37,"Вас провели дальше по коридору и вы зашли в довольно просторный зал с растениями в горшках у окон и углов, а по центру был стол покрытый белой скатертью, где сидели и общались старики и старухи. Им было еще больше, чем привратнику.\n Он провел вас за ближайший стол и отошел набрать вам кофе.",191019,null],[197005,"2026-09-07T19:04:09",41,"— Здравствуйте, да… приятного",191019,null],[197018,"2026-09-07T19:06:09",37,"Часть пожилых жителей посмотрели на вас и на их лицах появились небольшие улыбки.\n— И вам ребята... Что же такого произошло, что вы решили посетить такое богом забытое место?",191019,null],[197023,"2026-09-07T19:06:49",31,"- можно сказать, нас привела сюда судьба",191019,null],[197031,"2026-09-07T19:07:33",37,"— Это очень мило с вашей стороны, молодой человек...\n Ответила одна старушка улыбнувшись и повернулась обратно, продолжая пить кофе.",197023,null],[198667,"2026-09-08T08:34:34",37,"// @QURTZZ @sweetkittywitch @tochhkatochka @Ashenchampion начнем с 13 по мск, хорошо?",191019,null],[198668,"2026-09-08T08:34:46",37,"// И стоп... А где слова Аури?",191019,null],[198669,"2026-09-08T08:34:55",37,"// У меня же не шиза?",191019,null],[198670,"2026-09-08T08:35:31",37,"// Просто что это?",191019,null],[198671,"2026-09-08T08:35:58",41,"( я тоже не вижу",191019,null],[198672,"2026-09-08T08:36:24",41,"( Они пропали и из моего квеста._.",191019,null],[198685,"2026-09-08T09:09:21",31,"Ну их может удалить только автор/",191019,null],[198686,"2026-09-08T09:09:39",31,"Или может заблокировали аккаунт?/",191019,null],[198687,"2026-09-08T09:09:55",41,"Неа, это телега я уверена",198686,null],[198884,"2026-09-08T11:08:14",11,"// я не удаляла😢",198685,null],[198886,"2026-09-08T11:10:18",11,"// видать меня телега забуллила, пишет ограничений нет, хотя вы видите что произошло 😕",191019,null],[198887,"2026-09-08T11:10:41",41,"Трешак",198886,null],[198889,"2026-09-08T11:10:59",41,"Хоть эпичный момент сохранился",191019,null],[198891,"2026-09-08T11:11:21",11,"// я перепишу ласт пост тогда",191019,null],[199636,"2026-09-08T16:10:01",37,"// Я вышел из запоя",191019,null],[199639,"2026-09-08T16:10:11",37,"// Скачивал и настраивал спотифай",191019,null],[199763,"2026-09-08T16:43:13",0,"—а где здесь можно выпить пиво",191019,null],[199765,"2026-09-08T16:43:41",41,"— тут же дедушки и бабушки, вредно это 😤",199763,null],[199769,"2026-09-08T16:43:49",0,"—мне все равно",191019,null],[199770,"2026-09-08T16:43:52",37,"— Мы не пьем это, внучок...",199763,null],[199772,"2026-09-08T16:44:14",0,"—а где его пьют?",199770,null],[199777,"2026-09-08T16:44:57",37,"— В табаках, забегаловках, ресторанах и тавернах... У нас до ближайшей 60 километров в сторону города...\n Ответил второй старик.",199772,null],[199778,"2026-09-08T16:45:16",0,"—далековато",199777,null],[199780,"2026-09-08T16:45:58",37,"— А что еще делать? Мы как у черта на куличиках...",199778,null],[199783,"2026-09-08T16:46:15",0,"—вы тут одни?",191019,null],[199784,"2026-09-08T16:46:50",37,"— А кто еще кроме директора и стариков хочет жить со стариками и старухами?\n Спросила одна старушка.",199783,null],[199786,"2026-09-08T16:47:06",0,"—а где директор?",191019,null],[199796,"2026-09-08T16:49:24",41,"— Аури. Могу попросить тебя выйти поговорить?",191019,null],[199797,"2026-09-08T16:49:42",37,"— Ох... Он ждет мистера Мерсо, да и нам бы сходить к гробу Госпожи Мерсо...\n Пару стариков и старушек начали подниматься со свих мест и взяв пару вещей пошли к выходу.",199786,null],[199813,"2026-09-08T16:51:40",41,"— раз так, останьтесь все \n\nГоворит друзьям",191019,null],[199834,"2026-09-08T16:56:49",37,"// @QURTZZ ты тут?",191019,null],[199845,"2026-09-08T16:58:58",11,"— Да.. мы тоже хотели бы попрощаться — ответила Аури, а затем поднялась ожидая Летицию",199797,null],[199855,"2026-09-08T17:01:08",41,"( Никто не остался :с",191019,null],[199858,"2026-09-08T17:02:04",37,"Аури и Летиция услышали четкий и хороший голос мужчины молодых лет у себя около уха.\n— Чуть не пропустил общественную повозку, пришлось бежать бегом. Торопился, бежал, да потом еще в повозке трясло и воняло чем-то не приятным, дорога и небо слепили глаза, и от этого меня сморил сон. Проспал почти до Маренго. А когда проснулся, оказалось — привалился к какому-то солдату, он мне улыбнулся и спросил, издалека я. Я сказал \"да\", разговаривать не хотелось.\n От деревни до дома призрения два километра. Пошел пешком. Хотел сейчас же увидеть маму.",191019,null],[199859,"2026-09-08T17:02:10",37,"// Только вам",191019,null],[199862,"2026-09-08T17:03:50",41,"летиция прикрыла рот рукой и пошла за остальными",191019,null],[199863,"2026-09-08T17:03:52",31,"Да, просто я не знаю что писать)/",199834,null],[199866,"2026-09-08T17:05:37",37,"// Пенсионерами или?",199862,null],[199868,"2026-09-08T17:06:25",41,"( Полагаю да, сын же скоро будет. А остальные Куда?",191019,null],[199877,"2026-09-08T17:08:40",41,"( персы точно не останутся?",191019,null],[199883,"2026-09-08T17:09:55",37,"// @QURTZZ @Ashenchampion @tochhkatochka идете за возрожденной?",191019,null],[199884,"2026-09-08T17:10:24",41,"( я хочу остаться в комнате, если все согласны",191019,null],[199885,"2026-09-08T17:10:35",41,".",199813,null],[199886,"2026-09-08T17:10:36",31,"Я нихрена не понимаю что происходит, так что да, следую/",199883,null],[199891,"2026-09-08T17:11:18",41,"— я слышу голос её сына как...рассказчика, но...так же я слышала название этой главы, которое ввело меня в ступор",191019,null],[199894,"2026-09-08T17:11:51",41,"— Она называется \"Посторонний\"...",191019,null],[199902,"2026-09-08T17:14:10",37,"Никто не смог расслышать слово Посторонний, кроме тебя.",199894,null],[199904,"2026-09-08T17:15:03",41,"По лицам друзей, Она это поняла, и добавила: \n\n— я думаю... Приедет не её сын",191019,null],[199916,"2026-09-08T17:16:44",37,"// Это уже без спойлера",199904,null],[199964,"2026-09-08T17:28:59",31,"- и местные не определят подмену?",199904,null],[199972,"2026-09-08T17:33:05",41,"— я не уверена...",191019,null],[200064,"2026-09-08T18:40:17",41,"( догадка ниже",191019,null],[200065,"2026-09-08T18:40:32",11,"// да я тоже уже запуталась с этим слышим не слышим",191019,null],[200069,"2026-09-08T18:43:13",31,"Я вообще третий день не понимаю что мы делаем/",191019,null],[200072,"2026-09-08T18:43:29",31,"Ну, в смысле, в о чем квест то?/",191019,null],[200082,"2026-09-08T18:47:31",11,"— Летиция, ты слышишь то чего не слышим мы?",191019,null],[200084,"2026-09-08T18:48:34",11,"// ну нас таскает по сюжетам книг на которые мы можем(?) влиять. По логике вещей тебе как персонажу должно быть интересно как выбраться отсюда думаю на этом можно сосредоточиться",200069,null],[200090,"2026-09-08T18:53:36",31,"Ммм, пока не вставляет. Сама идея неплохая, хотя и не новая, даже комиксы подобные читал, но пока я не вижу у нас реальных возможностей влияния. Пока больше похоже что мы бродим без цели и смысла, качаемся на волнах сюжета, созерцаем и строим теории, которые один хрен никуда не ведут. Это даже социалкой назвать трудно, так как у нас нет общения полноценного с миром, только между собой, так как нпс это не живой персонаж мастера, в персонаж другого произведения, и если мастер попытается что то в нём изменить, то может не туда пойти сюжет изначальной книги и это может сломать рельсы сюжета квеста. Нагромождение такое я ощущаю. Пока мне очень тяжело даётся этот квест, прям через силу, не могу я вовлечься/",200084,null],[200099,"2026-09-08T18:58:44",37,"// Просто это самое начало второй части, а изменить вы можете что угодно... Я могу вам сказать, что вы мне ничего не будете ломать",191019,null],[200100,"2026-09-08T18:59:03",37,"// Даже если и сломаете, то я скажу спасибо",191019,null],[200101,"2026-09-08T18:59:59",31,"Дай нам больше динамики, пожалуйста/",200100,null],[200102,"2026-09-08T19:00:21",11,"// У меня пока есть только один вопрос к мастеру, но я надеюсь что этому будет логичное объяснение так что пока озвучивать не буду.\n\nДругое дело что один игрок два дня уже не пишет ничего, а ты сам, Лёша, не особо пытаешься вникнуть. Тяжело когда только мы с Элей что-то говорим, но при этом и вас ждать надо",191019,null],[200104,"2026-09-08T19:01:32",37,"// Действуйте активнее, кидайте заявки, спрашивайте даже у меня",200101,null],[200105,"2026-09-08T19:01:39",37,"// Я на все отвечу",191019,null],[200107,"2026-09-08T19:02:05",31,"/да, я торможу, и прошу за это прощения. Но я не могу и не умею выдавливать из себя посты просто ради постов. Это топтание на месте получается, и идей для развития у меня нету, увы/",200102,null],[200108,"2026-09-08T19:02:06",41,"— я не знала , что вы не слышите. Но кажется это правда",200082,null],[200109,"2026-09-08T19:02:34",41,"Летиция в волнении закручивает волосы на палец",191019,null],[200110,"2026-09-08T19:03:39",11,"— Видимо ты - особенная! — с восхищением сказала Аури — может быть ты - главная героиня?",191019,null],[200112,"2026-09-08T19:05:12",31,"- не, вряд ли. Где это видано, чтобы главный герой слышал подсказки. Это прерогатива читателя, который знает больше чем герой, потому что автор ему больше рассказал",200110,null],[200114,"2026-09-08T19:06:20",11,"— Тогда почему подсказки слышит только Лети? Ведь она не одна здесь? — эмоции на лице дженази быстро сменялись и теперь она серьезно задумалась",191019,null],[200115,"2026-09-08T19:06:40",31,"- ну или более циницный вариант. Мы все психи, а Летиция еще и голоса слышит",191019,null],[200116,"2026-09-08T19:06:58",41,"— я главный злодей ? :0",200110,null],[200117,"2026-09-08T19:07:14",11,"— а вы шутник, Конрад!",200115,null],[200118,"2026-09-08T19:07:28",31,"- гляжу, тебе все хочется буть злодейкой",191019,null],[200119,"2026-09-08T19:07:34",11,"— Ты меня обижаешь, я не вожу дружбы с злодеями, это не может быть правдой!",200116,null],[200120,"2026-09-08T19:07:54",41,"— только если ты не лучшая подружка злодейка !",200119,null],[200121,"2026-09-08T19:08:02",31,"- на самом деле, если Летиция это чиатель, а мы ничего не слышим, то мы вероятно персонажи о которых она читает",191019,null],[200123,"2026-09-08T19:08:07",11,"Аури искренне расстроилась от этих слов",200120,null],[200124,"2026-09-08T19:08:11",41,"— а мальчики наши помощники , они ничего не слышат",191019,null],[200125,"2026-09-08T19:08:19",41,"— ну эй, я же шучу(",200123,null],[200126,"2026-09-08T19:08:27",41,"Гладит подругу",191019,null],[200127,"2026-09-08T19:08:43",41,"— ты самая добрая, кого я знаю! Ну… на равне с Бенжамином",191019,null],[200128,"2026-09-08T19:08:48",11,"— Ох, прости, я не поняла шутки. Просто Ксин бы не гордился мной если бы я была злодеем",191019,null],[200130,"2026-09-08T19:08:55",11,"— Большая честь!",200127,null],[200131,"2026-09-08T19:09:28",41,"— Уверена, ты заслуживаешь много много гордости за себя) Но все равно идешь со смирением)",200128,null],[200132,"2026-09-08T19:09:34",11,"— хм.. Лети, а ты не читала ли чего подобного прежде чем попасть сюда?",200121,null],[200133,"2026-09-08T19:10:21",11,"— Но почему тогда мы попали сюда вместе с ней? Я как её подруга, но что на счёт вас со Стэтом? Мы ведь даже не были знакомы перед этим",191019,null],[200134,"2026-09-08T19:10:24",41,"— нет… я люблю хорроры, но такой не читала",200132,null],[200135,"2026-09-08T19:11:06",11,"— Что-ж.. это немного затрудняет поиск ответов, не могла бы ты поделиться тем что слышала?",191019,null],[200136,"2026-09-08T19:11:31",31,"- мы живём в таком мире, где причиной перехода куда либо может стать вообще что угодно. Проклятие, шутка, зелье или погода, буквально что угодно",191019,null],[200139,"2026-09-08T19:12:26",41,"— кажется, книга мне не даст. Но если дословно , то рассказчик читает мысли сына, который едет к нам. Он уже в двух километрах …",200135,null],[200140,"2026-09-08T19:12:30",11,"Аури подняла взгляд в потолок. Смотрела она будто бы сквозь него\n\n— Участвовать в историях других людей интересно, но я бы хотела писать и собственные. Надеюсь мы здесь застряли не навсегда..",191019,null],[200141,"2026-09-08T19:12:58",41,"— может своя история — это наша награда ?)",200140,null],[200142,"2026-09-08T19:13:25",11,"— Да, но ведь попали сюда только мы - незнакомые друг другу люди — она обернулась к Лети — ну почти. Я имею ввиду, что-то должно было нас объединить..",200136,null],[200144,"2026-09-08T19:14:12",31,"- как я понял, нас объединяет приглашение на выставку",191019,null],[200145,"2026-09-08T19:14:20",41,"— ну… мы вчера собрались, вернулись из странной галереи и легли спать… а ещё мы с Бенжамином готовили другой пирог… нет, дело не в этом",191019,null],[200146,"2026-09-08T19:14:33",11,"— Ох, тогда мы ждём его полагаю.. какого, эм, окраса его мысли? Позитивные или негативные?",200139,null],[200150,"2026-09-08T19:15:32",11,"— Хорошо, тогда давайте поделимся тем что мы видели или получили с выставки что бы определить что нас объединяет? Мы всё равно ждём пока приедет сын ушедшей..",200144,null],[200151,"2026-09-08T19:15:52",41,"— нейтральные, но он чувствует долг",200146,null],[200155,"2026-09-08T19:18:48",31,"/roll d20+1 на историю. Что было на выставке",191019,null],[200157,"2026-09-08T19:18:56",31,"/пусть мастер расскажет/",191019,null],[200158,"2026-09-08T19:19:00",11,"— Наверное он огорчён потерей матери, бедняга",191019,null],[200159,"2026-09-08T19:19:08",11,"// угум, сюжетный вопрос полагаю, нам тоже",191019,null],[200167,"2026-09-08T19:20:47",37,"Конрад вспомнил, что выставка была посвящена прошлой эре и кто были до рагнорека. Там вам показывали многое, но в основном это были отрывки бумаги и скульптур.\n\nВы слышали как голос привратника что-то активно говорит и как он с кем-то поднимается на второй этаж.\n\nЛетиция же услышала продолжение.\n\n— Привратник сказал — надо сперва зайти к директору. А он был занят, и я немного подождал. Пока ждал, привратник так и сыпал словами.",191019,null],[200177,"2026-09-08T19:23:25",11,"// мы пытаемся понять что нас объединяет. Анализируем что стало катализатором, ищем логику. Думаю тут стоит назвать конкретные предметы на которые могут упасть наши подозрения",200167,null],[200178,"2026-09-08T19:23:28",31,"- на выставке была всякая старая мура. Не удивлюсь, если еще и волшебная или проклятая",191019,null],[200180,"2026-09-08T19:24:00",11,"— Я тоже много видела, но не могу толком даже вспомнить что.. вряд ли дело только в ней, на выставке ведь были и другие люди кроме нас..",191019,null],[200183,"2026-09-08T19:24:56",37,"// Использую пассивный стат\n\nТы вспоминаешь, что на выставке были и другие, но вам, как случайной группе показали еще один зал с более старыми вещами.",200180,null],[200185,"2026-09-08T19:26:26",41,"— он здесь… надо его найти …",200167,null],[200188,"2026-09-08T19:30:02",11,"— Я припоминаю что мы с Лети были в каком-то особом зале.. там не было других посетителей кроме нас, не водили ли вас в такой же? — спрашивает она Конрада",200183,null],[200189,"2026-09-08T19:30:07",11,"— Кто он?",200185,null],[200192,"2026-09-08T19:30:43",41,"— Сын погибшей",200189,null],[200193,"2026-09-08T19:30:57",31,"- вроде припоминаю что то такое. Если честно, мне было скучновато и я особо не вникал",200188,null],[200220,"2026-09-08T19:37:12",37,"Вы замечаете что кто-то спускается с привратником и он проходит дальше по коридору. Вы заметили, что это был мужчина молодых лет в хорошей одежде, черных прибранных волосах, такие же черные глаза и немного бледная кожа. Он был немного высок по сравнению с привратником (Мужчина 185 см, а привратник 165 см).\n\nОни проходят по коридору и похоже идут куда-то.",191019,null],[200221,"2026-09-08T19:38:24",11,"— Возможно дело в ней.. но я тоже плохо помню что там было — говорит девушка прежде чем замечает двух мужчин — ох, кажется это сын, Лети права, он здесь!",200193,null],[200224,"2026-09-08T19:39:14",31,"/вы извините, но я спать ухожу/",191019,null],[200228,"2026-09-08T19:39:59",11,"// спокойной ночи",191019,null],[200232,"2026-09-08T19:40:05",37,"// Тогда завтра продолжим?",191019,null],[200235,"2026-09-08T19:40:25",37,"// Предлагаю собраться в 13-14 по мск",191019,null],[200238,"2026-09-08T19:42:05",11,"// Надеюсь получится",191019,null],[200802,"2026-09-09T02:45:30",31,"В 13-14 я скорее всего буду за рулем. После 14-30 смогу думаю/",191019,null],[201113,"2026-09-09T13:30:54",37,"// Через час начнем, отмечаю заранее. @QURTZZ @Ashenchampion @sweetkittywitch @tochhkatochka",191019,null],[201233,"2026-09-09T14:56:04",37,"// Так, я вернулся! @sweetkittywitch @QURTZZ @Ashenchampion @tochhkatochka подъем!",191019,null],[201234,"2026-09-09T14:56:20",41,"Пока чуточку занята",191019,null],[201244,"2026-09-09T15:00:11",31,"Я тоже еще пока занят/",191019,null],[201245,"2026-09-09T15:00:29",11,"// жду котят^^",191019,null],[201376,"2026-09-09T16:26:21",31,"Я освободился. Ну и денек)",191019,null],[201513,"2026-09-09T17:05:53",37,"// Последнее сообщение! Начали!",200221,null],[201524,"2026-09-09T17:08:35",11,"// они шли молча?",191019,null],[201527,"2026-09-09T17:10:01",41,"— Кажется, он у директора. Идем туда",200221,null],[201538,"2026-09-09T17:12:22",11,"— А ты уверена что мы можем просто так вмешиваться в их разговор.. я имею ввиду неприлично как-то",191019,null],[201542,"2026-09-09T17:13:06",37,"// Привратник очень много говорил что-то, пока вел его.",201524,null],[201546,"2026-09-09T17:14:51",11,"Аури пытается вслушаться в разговор прежде чем вклиниваться, возможно она найдет за что зацепиться",191019,null],[201549,"2026-09-09T17:16:08",41,"— Ой...и правда. Но, чего мы хотим добиться?",201538,null],[201550,"2026-09-09T17:17:14",37,"— У Госпожи Мерсо все было очень хорошо, мы можем уверить вас, если вы хотите чего-нибудь, то я могу принести...\nГоворил привратник.\nБыло слышно из конца коридора и звуки подъема по ступеням.\nИ голос начал затихать.",201546,null],[201555,"2026-09-09T17:20:01",11,"— Честно говоря мне просто жаль его, терять близких всегда тяжело.. можем ли мы подождать их здесь что бы выказать ему свои соболезнования?",201549,null],[201556,"2026-09-09T17:20:57",41,"— Наверное, так будет лучше ...",201555,null],[201574,"2026-09-09T17:25:43",11,"Аури прислоняется к стене\n\n— Пока мы ждём их.. как думаете, сын покойной - главный герой этой истории?",191019,null],[201585,"2026-09-09T17:28:07",41,"— Раз мы сдвшим рассказ от его лица...выходит что он, Но На нем ли все кончится?",191019,null],[201590,"2026-09-09T17:28:57",31,"- а может быть так, что историй несколько? Что если нас бросает по библиотеке, и истории не связаны?",191019,null],[201596,"2026-09-09T17:29:53",11,"— Может и так, но раз мы сюда попали у нас должна быть какая-то цель",191019,null],[201600,"2026-09-09T17:30:35",41,"— может истории  связанны с нашими переживаниями?",191019,null],[201602,"2026-09-09T17:30:47",31,"- предлагаю просто и нагло идти следом за этим \"сыном\". Чего мы таимся? Пойдем и найдём все ответы",191019,null],[201603,"2026-09-09T17:31:13",31,"- я бы сказал, даже потребуем",191019,null],[201606,"2026-09-09T17:31:24",11,"— Ох ну, я переживала потерю близкого, но не уверена — отвечает девушка",201600,null],[201608,"2026-09-09T17:32:09",11,"— Вряд ли они что-то понимают.. ответы даёт только голос «рассказчика» который говорит почему-то только с Летицией и то односторонне..",201603,null],[201613,"2026-09-09T17:33:16",37,"И вдруг вы все услышали, как дверь сверху открылась и закрылась.\nПривратник начал спускаться. Вы же услышали все голос спокойного и четкого характера:\n\n\"Пока ждал, привратник так и сыпал словами, а потом я увидел директора, он принял меня в кабинете. Это старичок с орденом Почетного легиона. Он посмотрел на меня ясными глазами. Потом пожал мне руку и долго не выпускал, я уж и не знал, как ее отнять. Он заглянул в какую-то папку и сказал:\n– Госпожа Мерсо пробыла у нас три года. Вы были ее единственной опорой.\nМне показалось, он меня в чем-то упрекает, и я начал было объясняться. Но он перебил:\n– Не надо оправданий, дружок. Я перечитал бумаги вашей матушки. Вы были не в силах ее содержать. Она нуждалась в уходе, в сиделке. Заработки у вас скромные. Если все принять во внимание, у нас ей было лучше.\nЯ сказал:\n– Да, господин директор.\nОн прибавил:\n– Понимаете ли, здесь ее окружали друзья, люди ее лет. У нее нашлись с ними общие интересы, которых нынешнее поколение не разделяет. А вы молоды, с вами она бы скучала.\nЭто верно. Когда мама жила со мной, она все время молчала и только неотступно провожала меня глазами. В доме призрения она первые дни часто плакала. Но это просто с непривычки. Через несколько месяцев она стала бы плакать, если бы ее оттуда взяли. Все дело в привычке. Отчасти из-за этого в последний год я там почти не бывал...\"",191019,null],[201626,"2026-09-09T17:35:30",41,"( перепишу",191019,null],[201635,"2026-09-09T17:37:58",11,"— Привратник очень милый и доброжелательный человек, он пригласил нас незнакомцев и угостил кофе, я бы не хотела требовать с него что либо.. а что касается сына почившей.. ему сейчас наверняка и так тяжело",191019,null],[201638,"2026-09-09T17:38:58",11,"— ..? — девушка оглядывается в попытках понять это опять в голове или говорят так громко что слышно досюда",201613,null],[201640,"2026-09-09T17:39:10",41,"— я...думаю ты права. Только...\n\nОна попыталась уловить разницу между сыном до встречи и после",191019,null],[201643,"2026-09-09T17:39:53",37,"Ты понимаешь, что голос похож по донесению как в конце с мужчиной, который упал с крыши.",201638,null],[201647,"2026-09-09T17:40:52",11,"— Вы тоже это слышали? Похоже нам не нужно прослушивать то что.. — она предположила — является сюжетом",191019,null],[201651,"2026-09-09T17:41:06",11,"— Оно само нас настигает.. хм",191019,null],[201654,"2026-09-09T17:41:56",41,"— Это страшно...",191019,null],[201661,"2026-09-09T17:43:23",31,"- я устал быть зрителем. Раз мы можем и должны влиять на сюжет, то давайте это делать. Что толку от наших разговоров?",191019,null],[201662,"2026-09-09T17:43:30",11,"— Мы можем попытаться его изменить, но нам надо понять что к чему сперва..",191019,null],[201663,"2026-09-09T17:43:46",31,"Встаю и иду в комнату к рассказчику",191019,null],[201664,"2026-09-09T17:43:52",11,"— Наверное ты прав..",201661,null],[201666,"2026-09-09T17:44:01",31,"- разведка боем",201662,null],[201674,"2026-09-09T17:45:46",37,"Поднявшись по лестнице вы оказались прямо перед дверью с табличкой \"Директор Дома Призрения\"",191019,null],[201675,"2026-09-09T17:46:33",41,"( отойду поесть",191019,null],[201682,"2026-09-09T17:49:21",11,"// ну Конрад у нас прямо в кабинет решил ворваться судя по заявке",191019,null],[201684,"2026-09-09T17:50:34",31,"Открываю дверь. Если заперта - выбиваю",191019,null],[201686,"2026-09-09T17:51:05",37,"Вы услышали голос директора, тоже довольно старый.\n— Вы, наверно, хотите видеть вашу матушку...\nИ прямо перед попыткой парня дверь открылась.\n— Ох... Здравствуйте, гости...",191019,null],[201687,"2026-09-09T17:52:03",37,"За ним вы увидели того же мужчину высокого роста и с немного серьезным лицом и не читаемыми эмоциями.\n Похоже это и есть Господин Мерсо.",191019,null],[201688,"2026-09-09T17:52:17",31,"- и вам не хворать, хозяин. Я бы хотел поговорить с господином Мерсо, это возможно?",191019,null],[201689,"2026-09-09T17:53:14",11,"Аури с любопытством и немного виновато выглядывала из-за спины Конрада",191019,null],[201690,"2026-09-09T17:53:27",37,"— Ох... Вот как... Я хотел провести его к гробу его матери, чтобы он провел ночь перед ней... Вы можете пройти с нами.",201688,null],[201695,"2026-09-09T17:54:06",31,"- госпожа Мерсо уже никуда не убежит, я бы хотел поговорить тут, в не на бегу",191019,null],[201697,"2026-09-09T17:55:13",37,"Господин Мерсо вышел из двери тоже и закрыв дверь сказал кратко.\n— Можно.",191019,null],[201699,"2026-09-09T17:57:01",31,"- забыл представиться, Конрад фон Шаттенхаус, и ц меня у вас странный вопрос. Вы в чудеса верите? Я вот не очень верил, но что вы скажете, если одна из моих спутниц может процитировать вам ваши же мысли? И я бы очень хотел знать, как это работает, и какого хрена это значит?",191019,null],[201708,"2026-09-09T18:00:16",37,"На лице Мерсо и Директора появилось удивление и второй спросил.\n— Что вы такое говорите? Это же невозможно!\nМерсо же ничего не ответил.",191019,null],[201712,"2026-09-09T18:02:15",11,"Аури дословно цитирует мысли Мерсо которые услышала недавно пользуясь чертой отличная память",191019,null],[201713,"2026-09-09T18:02:22",11,"— Он прав",191019,null],[201715,"2026-09-09T18:03:31",37,"Мерсо все еще не проронил слова и спросил.\n— Что... Да, я говорил эти слова, но... Возможно это что-то иное?\n// Бросок убеждения",201712,null],[201717,"2026-09-09T18:04:32",11,"/roll +d20+2 према так как мы вдвоём убеждаем",191019,null],[201720,"2026-09-09T18:04:35",31,"Наводим суету//",191019,null],[201721,"2026-09-09T18:04:56",11,"// у меня перс скромнее, но я одобряю",191019,null],[201724,"2026-09-09T18:06:51",37,"Директор начинает смотрит на Мерсо, а второй спрашивает.\n— Возможно... Вы... Хм... Я, вас вижу впервые, поэтому могу вас не узнать...",201717,null],[201728,"2026-09-09T18:07:21",31,"- мы тоже не уверены, что виделись с вами ранее",191019,null],[201738,"2026-09-09T18:09:55",31,"- поэтому я и спрашиваю, что за хрень тут творится. Вы колдун, или еще какой-то маг? Почему ваши мысли транслируются в пространстве? Почему ваши мысли похожи на авторсую речь в книге? Что это вообще за страна, дв бог с ней со страной, что это за мир?",191019,null],[201739,"2026-09-09T18:10:14",31,"- какой сейчас год?",191019,null],[201741,"2026-09-09T18:10:35",31,"Меня отравят в психушку по квесту, 100%//",191019,null],[201745,"2026-09-09T18:12:05",11,"— Простите нашего товарища за резкость, но он прав, мы понятия не имеем как и зачем очутились здесь и что это за план..",191019,null],[201746,"2026-09-09T18:12:27",31,"Голос разума, спасибо/",201745,null],[201747,"2026-09-09T18:12:47",31,"Типа хороший и плохой копы/",191019,null],[201748,"2026-09-09T18:12:57",37,"— 1942 год Нового света, а что?\n\nТы не смог услышать слова, которые сказал Мерсо.\n\nДиректор же сказал.\n— Мужчина, прошу вас сходить к доктору и проверить свое самочувствие, может у вас какие-то проблемы?",201739,null],[201754,"2026-09-09T18:13:44",37,"Мерсо сделал небольшой кивок и ответил Аури.\n— Вот как.",201745,null],[201756,"2026-09-09T18:13:50",31,"- моя проблема, боюсь, не медицинская, а магическая",201748,null],[201762,"2026-09-09T18:15:58",31,"- как бы то ни было, вам есть что ответить?",191019,null],[201763,"2026-09-09T18:16:08",11,"— Простите, что вы сейчас сказали? — Аури переспрашивает Мерсо — не могли бы вы перефразировать.. я не разобрала",191019,null],[201810,"2026-09-09T18:34:39",37,"— 1942й год Нового Света, а именно лето.\nСнова ответил Мерсо. Вы снова не расслышали ответ.\n— И магия? Мистер Шаттенхаус, магии у нас нету с давних времен, сейчас эра технологий и прогресса.",191019,null],[201816,"2026-09-09T18:38:20",37,"— Давайте пойдем к гробу вашей матушки, Господин Мерсо... Там должны собраться и другие её друзья...\n Сказал Директор и начал идти в сторону лестницы. Мерсо немного посмотрел на вас и решил пойти следом.",191019,null],[201820,"2026-09-09T18:38:58",11,"— Я совсем не понимаю половину сказанного им.. мы так ничего и не добились — вздохнула Аури",191019,null],[201826,"2026-09-09T18:40:34",31,"- ну почему. Мы поняли что влиять на сюжет мы особо не можем. Он как шел к своей сюжетной цели, так и идет. И даже ухом не повел от наших слов. Словно у него нет даже вариантов что это возможно. Думаю, мы и правда в книге и наше влияние тут вряд ли будет заметно",201820,null],[201832,"2026-09-09T18:44:22",11,"— Хм.. ну реакция на нас была и правда слабой, но мы ведь не заставляли делать их что-то иное.. давай дадим ему попрощаться с матушкой сперва, а затем попробуем снова? Например разузнаем собирается ли он уезжать и если да попробуем заставить его остаться - таким образом мы повлияем на сюжет",191019,null],[201834,"2026-09-09T18:45:49",31,"- попробуем, что остается то...",191019,null],[201855,"2026-09-09T18:56:10",37,"Вы слышали голос директора, что немного извинился и продолжил.\n– У нас тут своя небольшая мертвецкая, мы перенесли покойницу туда. Чтобы не тревожить остальных. Каждый раз, как в нашем доме кто-нибудь умирает, остальные на два-три дня теряют душевное равновесие. И тогда затруднительно за ними ухаживать.\n\nГолос отдалялся и отдалялся. Так вы перестали их слышать.",191019,null],[201872,"2026-09-09T19:02:07",11,"Аури обменивается взглядами со спутниками и идет следом, но не вмешиваясь, а ждет пока сын закончит прощание с матерью",191019,null],[201900,"2026-09-09T19:09:57",37,"Вы пересекли двор, там было много стариков, они собрались кучками и толковали о чем-то. Когда вы проходили мимо, они смолкали. А за спиной у вас опять начиналась болтовня. Будто приглушенно трещали попугаи. У низенькой постройки вы заметили, что Мерсо слушал слова директора, и вы уловили часть разговора.\n— ... Погребение назначено на десять часов утра. Мы полагали, что вы захотите провести ночь подле усопшей. И еще одно: говорят, ваша матушка в беседах не раз высказывала желание, чтобы ее похоронили по церковному обряду. Я сам обо всем распорядился, но хочу вас предупредить.\n Мерсо кивнул головой и поблагодарил директора, когда тот пошел обратно в дом. Мерсо же вошел в небольшое здание.",191019,null],[201906,"2026-09-09T19:13:54",11,"// я если что пишу что иду сама ибо я не хочу решать за других игроков",191019,null],[201908,"2026-09-09T19:14:09",11,"Аури остаётся во дворе ожидая пока мужчина выйдет",191019,null],[201911,"2026-09-09T19:14:15",31,"Я хвостиком хожу/",191019,null],[201920,"2026-09-09T19:18:10",11,"// я не хочу за всех решать и играть одна🤷‍♂ у нас один персонаж ни фразы не сказал за два дня.. это прям неловко",191019,null],[201922,"2026-09-09T19:19:05",41,"( сори, я до этого отходила",191019,null],[201924,"2026-09-09T19:19:30",41,"( щас еще возможно отойду, кофе покупаю",191019,null],[201925,"2026-09-09T19:19:30",37,"Через пару минут в здание вошел привратник, а еще через минуту из здания вышла темнокожая девушка в белой одежде, похоже сиделка. Посмотрев на сиделку, лицо ее пересекала повязка. На том месте, где положено быть носу, повязка была плоская. На лице только и заметна белая повязка. Она ничего не сказала вам и прошла дальше по дороге.",191019,null],[202007,"2026-09-09T19:47:46",37,"// @tochhkatochka, я вывожу твоего персонажа по причине того, что ты не активничаешь на квесте, прости.\nВы замечаете, как прямо перед вами Стэт начал немного светиться светом, а пара бабочек из округи начали приземляться на него.\n Бабочек становилось все больше и больше и вы заметили, как от Стзта оставалось все меньше и меньше, пока бабочки не рассыпались и не разлетелись.\n На его месте же вы нашли книгу, что гласила: Посторонний.\n\n// Для @tochhkatochka \nСтэт же проснулся от сна и посмотрев по сторонам понял, что он проспал более пары дней на одном месте, да и он помнил все что произошло...",191019,null],[202026,"2026-09-09T19:54:27",31,"- твою мать, что это значит?",202007,null],[202028,"2026-09-09T19:54:40",31,"- тут книга, Посторонний",191019,null],[202029,"2026-09-09T19:54:55",31,"Хочу почитать книгу, может там какая информация будет полезная",191019,null],[202038,"2026-09-09T19:57:45",11,"Аури бросается к исчезающему спутнику пытаясь ухватить бабочки руками, но в итоге хватает лишь книгу и открывает её.",191019,null],[202041,"2026-09-09T19:59:27",37,"Открыв книгу ты замечаешь, что она показывает только пару страниц из всех по её толщине.\n Ты вспоминаешь такую же книгу, когда мужчина со стеклянными крыльями умер. От него тоже осталась книга и она открылась.\n\nСодержание книги было таким же, что вам рассказала Летиция, там даже были диалоги с вами! Но то, что вы не могли слышать была вырезано. Похоже это книга рассказывает, все что происходит в настоящем.",202029,null],[202047,"2026-09-09T20:01:59",11,"Девушка разочарованно вздохнула и протянула книгу Конраду\n\n— Похоже здесь я истории своей не напишу. Её уже кто-то пишет за нас. Надеюсь Стэт нашёл выход..\n\n// У моего перса отобрали его работу :(",191019,null],[202048,"2026-09-09T20:02:58",37,"// не на долго",202047,null],[202061,"2026-09-09T20:10:22",31,"- интересно, а эта книга только прошедшее описывает, или может спойлеры дает на будущее?",191019,null],[202064,"2026-09-09T20:11:50",41,"— это название… которое вы не могли расслышать",202038,null],[202066,"2026-09-09T20:12:15",11,"— Здесь написано только то что уже произошло с нами.",202061,null],[202067,"2026-09-09T20:12:51",31,"Ладно, девушки, я спать пошел, и так засиделся//",191019,null],[202068,"2026-09-09T20:13:07",41,"( споки (",191019,null],[202069,"2026-09-09T20:13:17",37,"// спокойной",191019,null],[202074,"2026-09-09T20:15:51",11,"// споки",191019,null],[202076,"2026-09-09T20:16:03",37,"// Так, продолжаем или в следующий раз? У меня просто завтра нет так как работать иду",191019,null],[202077,"2026-09-09T20:16:29",11,"// давай перенесем, я сегодня тоже не в настроении",191019,null],[202764,"2026-09-10T07:22:43",37,"// Ещё раз напишу, я сегодня буду весь день занят, поэтому игры не будет.",191019,null],[202765,"2026-09-10T07:24:16",31,"ок/",191019,null],[204583,"2026-09-11T13:19:01",37,"// @QURTZZ @Ashenchampion @sweetkittywitch Hard все смогут через пол часа - час?",191019,null],[204586,"2026-09-11T13:20:23",9,"//Кайф, можно",191019,null],[204588,"2026-09-11T13:21:03",31,"я смогу часа через 2 наверное/",191019,null],[204634,"2026-09-11T14:23:43",37,"// Для Hard \n\nТы побывал на очень скучной выставке... Ты мог сказать, что видел лучше и интереснее, да и те тоже не были достойны твоего внимания...\n В итоге ты зашел в отдельное крыло и увидел необычную страницу, в которой говорилось о странной дилемме прошлого \"Это я мечтаю, что я бабочка или бабочка мечтает о том, что она я?\". Это заставило тебя ненадолго задуматься, но не придав четкого значения ты покинул выставку. Через пару моментов ты почувствовал странное чувство в своем рассудке и очнулся прямо перед необычной местностью.\n Эта были поля. Над холмами, которые отгораживают от моря, небо закраснелось. И ветер доносил из-за холмов соленый запах. Начиналось утро, хотя ты точно помнил вечер.\nВокруг были окрестные поля. Сквозь ряды кипарисов, тянувшиеся к холмам у самого горизонта, на этой рыжеватой и зеленой земле, среди редко разбросанных, но четких домов можно было заметить прямо перед собой дом. Точнее не дом, а большой участок. Ты могли догадаться, что это был Дом Призрения(Престарелых).",191019,null],[204637,"2026-09-11T14:27:18",37,"// Для остальных. @sweetkittywitch @QURTZZ @Ashenchampion \n Вы заметили что в книге были именно моменты мужчины, пока он не встретил вас, затем говорилось только пока вы его видели.",202066,null],[204640,"2026-09-11T14:32:58",11,"// логично, так и поняла",191019,null],[204641,"2026-09-11T14:33:22",11,"— Что ты имеешь ввиду, то что ты слышала ранее?",202064,null],[204642,"2026-09-11T14:35:39",9,"— Ахахахах. Видения, марево, ужас. Как интересно. — *Он срезает немного колосьев из поля где точно никто не ходил, слегка промыв их оттягивает бинты около рта, прожевал их и выплюнул каку. Пытается оценить это ему превиделось или настоящее.*\n\n*Сейчас Вордо был весь в бинтах, скрывая свой изменённый необычный лик, даже с астрала откуда он вывалился его внешность была довольно необычной, не стоило прыгать в море сотворения звезд, но даже так, он прыгнул и выжил там, внешность? Внешность это всего лишь побочки.*\n\n//Ссылка на перса: https://t.me/c/3239766844/7247/7264",191019,null],[204643,"2026-09-11T14:39:52",37,"Ты полностью понял, что это все осязаемо и выглядит как настоящее.\n Вместе с этим ты заметил, что очень резко время повернулось к вечеру и начало смеркаться.\n\n// Прошу писать под спойлером до встречи с основной группой.",204642,null],[204644,"2026-09-11T14:40:02",41,"— Да, но у меня есть идея. Мы ведь можем написать вчера, Что слышали. Тогда эта симуляция кончится!",204641,null],[204645,"2026-09-11T14:41:27",11,"// хм.. не совсем поняла",204644,null],[204646,"2026-09-11T14:41:39",11,"— Имеешь ввиду записать пропущенные слова?",191019,null],[204647,"2026-09-11T14:42:16",41,"— Не просто, а доказать, Что Мы слышали сына..хотя может...это сделает все только хуже",191019,null],[204648,"2026-09-11T14:43:59",11,"— Кому доказать?",191019,null],[204649,"2026-09-11T14:47:10",9,"— Пару искаженных пространств или перемещений я переживу. — *Поправив повязки он неспешно идёт к дому пристарелых, его плащ мощно развевался за ним словно в любой момет готов поднять Вордо в воздух (бонусным развеваю плащ). Безумец? Прокажённый? Не верно! Но откуда остальным знать если он не будет выглядеть эпично и мегахорош.*",204643,null],[204650,"2026-09-11T14:48:33",41,"— видимо, ему же, Что если он узнает, Что он в книге?",204648,null],[204651,"2026-09-11T14:49:44",11,"— Ты права, мы можем попробовать.. но для начала нам нужно понять что он говорил",191019,null],[204652,"2026-09-11T14:50:12",11,"— А так я могу записать — девушка показывает на писчее перо за ухом",191019,null],[204653,"2026-09-11T14:51:51",37,"Ты заметил, что из здания вышла девушка черного цвета кожи в белой одежде. Лицо ее пересекала повязка. На том месте, где положено быть носу, повязка была плоская. На лице только и заметна белая повязка. Она заметила тебя и поклонившись пошла в сторону отдельного маленького здания, дальше через поле.",204649,null],[204654,"2026-09-11T14:52:25",41,"— я помню. Давай продикую, а ты запишешь!",191019,null],[204655,"2026-09-11T14:52:36",41,"— вернее я напишу, точно",191019,null],[204656,"2026-09-11T14:53:03",11,"Она протягивает тебе перо\n\n— Вот, оно не требует дополнительных чернил",191019,null],[204657,"2026-09-11T14:53:28",41,"/r d20-1 а насколько хорошо она помнит? Ух ты, перо, я чувствую себя таким писарем",191019,null],[204659,"2026-09-11T14:54:13",41,"— Оно такое легкое и мягкое, слова будто парят!",191019,null],[204660,"2026-09-11T14:55:25",11,"И пишет оно голубым как шариковая ручка",191019,null],[204661,"2026-09-11T14:55:39",41,"( увуву",191019,null],[204662,"2026-09-11T14:55:54",11,"// цвет могу менять, но мне нравится синий для Аури:3",191019,null],[204663,"2026-09-11T14:57:28",41,"— а цвет чернил такой... Ого",191019,null],[204664,"2026-09-11T14:57:45",9,"— Простите миледи, где я нахожусь? — *Спросил он у неё, внешность? Пффф, да, он лицемерен но видел краказябр и пострашнее, отсутствие носа или конечностей его не пугала.*",204653,null],[204665,"2026-09-11T14:57:48",41,"— никогда не замечала у тебя ...",191019,null],[204666,"2026-09-11T14:58:18",37,"Ты помнишь очень много моментов, кроме пары фраз, что он говорил в пути.",204658,null],[204667,"2026-09-11T14:59:25",11,"— Они волшебные, я обнаружила это когда вела дневник после того вечера для тебя. Чернила на пере совсем не заканчиваются, сколько бы я не писала, а цвет поменялся на вот этот — Аури приободрилась говоря о любимом пере с энтузиазмом — а ещё я могу стереть то что написано им по своему желанию!",191019,null],[204668,"2026-09-11T15:01:06",37,"Девушка перевела на тебя взгляд и оценив твой образ сказала.\n— В доме призрения, в Маренго.\nОна еще раз поклонилась и пошла дальше.\n\n// Ты не услышал текст, что зачеркнут.",204664,null],[204669,"2026-09-11T15:03:43",11,"// ну как я понимаю мы ждём пока сын закончит что бы попытаться его убедить что он в книге🤔",191019,null],[204670,"2026-09-11T15:04:09",11,"// а Эля записывает в книгу то что помнит на пустые места",191019,null],[204671,"2026-09-11T15:04:15",9,"*Слово, одно единственное слово что он услышал не смог разобрать, его будто зажевало пластинкой насамом хреновом проигрывателе.*\n\n— Чудесное место. — *Сказал он скорее уже самому себе.* — Что же, посмотрим.\n\n*Ищет дверь чтобы ворваться с ноги зайти и пообщаться с кем-то более сговорчивым.*",204668,null],[204672,"2026-09-11T15:04:24",37,"// Никто вам не мешает зайти внутрь.",204669,null],[204673,"2026-09-11T15:05:21",11,"// Ну там человек с матерью прощается.. не хочется что-то мешать",191019,null],[204674,"2026-09-11T15:07:38",37,"Зайдя в сам Дом Призрения ты понял, что он немного пуст, похоже все пенсионеры уже ушли спать или ужинают. Ты заметил только одного старичка, что был хорошо одет, но довольно стар. Он сидел на ближайшем стуле.",204671,null],[204675,"2026-09-11T15:10:18",9,"//Уже резко вечер!? День пятиминутка или был вечер с первого соо? Вродь ты писал утро.",204674,null],[204676,"2026-09-11T15:11:33",41,"( я потому думала, что идея не очень, но иначе тупо ждем что-ли?",204673,null],[204677,"2026-09-11T15:11:48",11,"// ну вот я и говорю что можно таймскип дать когда он выйдет",191019,null],[204678,"2026-09-11T15:11:57",41,"( была идея достучаться до рассказчика, но его тут нет",191019,null],[204679,"2026-09-11T15:12:27",11,"// ждём реакции от мастера на заявки твою с книгой мою с ожиданием",191019,null],[204680,"2026-09-11T15:12:33",37,"// Ты просил безумие, ты его получил. И я писал еще до этого, что с утра резко стал вечер.",204675,null],[204682,"2026-09-11T15:17:06",9,"*Смотрит в окно, понимает что уде вечер.*\n\n— Это какое-то колдовство, что-то тут не так. — *Взглянул на старика, спросил резко потеряв настроение фамильярничать.* — Как давно у вас вечер, дед.",204674,null],[204683,"2026-09-11T15:17:45",37,"В итоге Летиция смогла полностью написать весь текст, но Мерсо довольно долго не заходил.\n Рядом же прошла та же сиделка и открыв дверь спросила.\n— Не желаете ли зайти, возможно сын Госпожи Мерсо пробудет там всю ночь, как и часть её друзей.",191019,null],[204685,"2026-09-11T15:20:00",37,"Старик посмотрел на часы, что висели рядом и сказал.\n— Сейчас без пятнадцати минут восемь вечера, а что? Вам что-то нужно, молодой человек?",204682,null],[204686,"2026-09-11T15:23:10",11,"— Сын не будет против присутствия посторонних..?",204683,null],[204688,"2026-09-11T15:24:44",9,"— Я... — *И правда, что он здесь забыл. Здесь что-то не так, нужно выбираться, уйти, но как. Просто уйти в закат слишком просто, не просто же так он попал сюда.* — ...не знаю, посижу тут.\n\n*Вордо нашёл где присесть и смотрит на деда, думает.*",204685,null],[204693,"2026-09-11T15:30:51",37,"— Нет, что вы, там будут и друзья Госпожи Мерсо... Вот они и подходят.\n\nВы заметили как начали заходить старики и старушки.",204686,null],[204694,"2026-09-11T15:31:30",41,"— надеюсь, мы его не сильно побеспокоим",191019,null],[204695,"2026-09-11T15:32:10",31,"Конрад, цинично:\n\n- не думаю что он нас вообще заметит, чертов главный герой",191019,null],[204696,"2026-09-11T15:32:29",37,"— Ох, понятно... Тогда позвольте представиться, Мистер Рано, директор этого дома призрения.\n Ответил старик.\n\nТы же услышал себе на ухо слова.\n— Сегодня у меня умерла мама. Или, может, вчера, не знаю.\n\nСтарик похоже их вообще не слышал.",204688,null],[204697,"2026-09-11T15:34:46",11,"— Что-ж, мы пройдем.. — Говорит девушка и входит внутрь",191019,null],[204698,"2026-09-11T15:39:04",37,"Внутри очень светло, стены выбелены известкой, крыша стеклянная. Обстановка – стулья да деревянные козлы. Посередине, на таких же козлах, закрытый гроб. Доски выкрашены коричневой краской, на крышке выделяются блестящие винты, они еще до конца не ввинчены.\nГроб был закрыт, но не заколочен.\n Вы заметили, что сбоку от гроба сидит сам Мерсо, а остальные старики садились с другой стороны.\n Заметив вас Мерсо кивнул и продолжил смотреть на гроб.",204697,null],[204699,"2026-09-11T15:41:23",11,"Девушка садится недалеко от стариков\n\n// Если остальные следуют за мной то обращаюсь к Эле\n\n— Лети, а в подсказках что слышала ты не было ничего о том что он собирается делать дальше? — шепотом",191019,null],[204708,"2026-09-11T15:50:17",9,"— Меня зовут Уорлд. Можно просто Ворд (мистер Мир). — *Вордо смотрел в окно, словно время могло убежать от него.*",204696,null],[204709,"2026-09-11T15:51:13",37,"Усевшись старшие начали немного пускать слезы, стараясь их сдерживать. Стрики имели грустное выражение лица, а старушки не сдерживались.\n Мерсо же имел очень сложное выражение лица, а его веки казалось очень долго держались закрытыми. Его клонило в сон.",191019,null],[204710,"2026-09-11T15:52:59",37,"— Чтож, мистер Уорлд, тогда я пойду к себе в кабинет. Недавно к нам заходила группа человек и они пошли в здание слева от выхода, можете пойти туда.\nСказал директор и встав пошел по коридору.\n— До свидания, мистер Уорлд.",204708,null],[204720,"2026-09-11T16:05:42",9,"*Вордо сидел, смотрел на закат, а после тихо просипел через бинты. Что он себя накручивает, будь что будет. Встал взмахнув плащём и идёт в то здание слева от выхода, если здесь есть посетители, он уйдет вместе с ними в большой город, а там можно посмотреть.*",204710,null],[204727,"2026-09-11T16:10:47",37,"Пройдя через поле ты видишь как раз небольшую пристройку и похоже там сидит много людей.",204720,null],[204732,"2026-09-11T16:12:05",9,"*Немного сбавляет шаг, присматриыается. Тут все... люди? Ни одного эльфа, тролля или другого, хотя бы дварфа???*",204727,null],[204734,"2026-09-11T16:13:17",37,"Только люди. Ты видел по пути очень много людей стариков, но именно людей. Других здесь не было. А в здании ты не мог посмотреть так как окна были довольно высоко... Легче уже войти.",204732,null],[204773,"2026-09-11T16:26:45",9,"*Странно все это, одни люди. Поправил бинты убедившись что его кожу не видно и вошел внутрь, из-за чего такое столпотворение.*",204734,null],[204778,"2026-09-11T16:27:58",37,"// Это можешь уже без спойлера",204773,null],[204783,"2026-09-11T16:30:46",37,"Вдруг в здание заходит некий в бинтах и развивающемся плаще. Все, кроме Мерсо посмотрели на него и кивнув продолжили смотреть на гроб.\n\nВнутри очень светло, стены выбелены известкой, крыша стеклянная. Обстановка – стулья да деревянные козлы. Посередине, на таких же козлах, закрытый гроб. Доски выкрашены коричневой краской, на крышке выделяются блестящие винты, они еще до конца не ввинчены.\nГроб был закрыт, но не заколочен.\n Вордо заметил, что тут наконец то есть представитель другой расы! Даже два!",191019,null],[204791,"2026-09-11T16:39:16",9,"//Два, кого видит Вордо по расам они?",204783,null],[204793,"2026-09-11T16:39:48",37,"// Дженази воды и возрожденную, обе дамы",204791,null],[204794,"2026-09-11T16:40:51",31,"И человека Конрада, но он в глаза бросается разве что отличной от других людей одеждой/",191019,null],[204797,"2026-09-11T16:43:42",9,"*Плащ перестал развеваться и он подошёл к самой странной компашке, да и тем кто явно выделялся на фоне. Говорит не громко, чтобы не нарушать идилию.*\n\n— Вы так полагаю те самые гости. Что здесь происходит? — *Ваш собеседник чувствует себя уверенно при жтом, хотя выглядит как мумия или прокажённый, хотя бы бинты чистые на вид.*",191019,null],[204799,"2026-09-11T16:45:00",11,"— ..? — Обернувшись на голос Аури замечает явно нестандартного человека — да.. мы гости, а что на счёт вас?",191019,null],[204802,"2026-09-11T16:49:57",9,"— В некотором роде тоже гость. — *Садиться, если есть где присесть, лавки, стулья, или на крайняк облокотившись о стену.* — Тик так, часики часы, тик так. Раскажите мне историю, что здесь так а что не так. Что забыли, упустили, вы здесь были и не были, место странное внезапно оказалось пред глазами, очутился тут внезапно и руками и ногами. Вы же путкини, aimdoo, (эльфийским \"знаю/догадываюсь\") разделяем мы беду? \n\nМысли: \"Какой рифмоплет, какой красавец. Хахаха, прекрасно, пусть так.\"",191019,null],[204803,"2026-09-11T16:50:51",41,"( секунду",191019,null],[204805,"2026-09-11T16:52:20",11,"Аури хихикнула\n\n— А мне нравится ваша речь, сэр.. как к вам можно обращаться?",204802,null],[204806,"2026-09-11T16:54:37",9,"— Можете называть меня мистер Уорлд (мир), для друзей просто Ворд. — *Да, он кажется рад что его хорошо оценили, как и положенно, хотя за бинтами и ретушью этого не видно.*\n\n— Местных не смущает \"как вы выглядите\"? — *Спросил он у возрожденной и Дженази, все же они явно не люди среди этой толпы.*",204805,null],[204807,"2026-09-11T16:56:44",11,"Сидим мы поодаль от стариков и Аури старается говорить тише, что бы всхлипы пожилых дам заглушали ее голос\n\n— Вы ведь тоже не из сего места, верно, сэр Уорлд? — она хотела было по привычке спросить про значение имени, но посчитала что место и время не то, так что просто грустно улыбнулась — угу, они не обращают внимания на наш.. отличный внешний вид",191019,null],[204808,"2026-09-11T16:59:29",9,"*Видно что Вордо слегка удивлен этим фактом даже сквозь бинты. Он помял край ткани покрывающей тело, но снимать не стал, хотя раздражало.*\n\n— Верно, выставка, перенос. Ноги шли по помоске и камню а в другой момент уже по земле полевой тропы. — *Тоже говорит не слишком громко, но твердо.*",191019,null],[204809,"2026-09-11T17:02:56",11,"— Всё так же как у нас.. Сперва мы с Летицией — она помахала сидящей рядом подруге — посещали выставку, а затем очнулись здесь после сна.. Конрад тоже — теперь она кивнула парню — мы очутились здесь с ещё одним не местным человеком, но он исчез\n\nДевушка показала пальцем на книгу с названием «Посторонний» в руках подруги\n\n— Это всё что от него осталось. Он исчез так же как и всё остальное исчезает в.. как мы полагаем повествование здесь, растворился бабочками",191019,null],[204810,"2026-09-11T17:03:50",11,"— Мы пришли к выводу что попали сюда потому что посещали один из необычных залов на выставке где как раз кроме нас никого не было, у вас так же? Зал с выставкой о прошлом",191019,null],[204811,"2026-09-11T17:05:54",9,"*Кивнул, прикинул в уме.*\n\n— Да, сходится. — *Он махнул рукой, прошлое сошлось, но беспокоило будещее.* — Что значит \"повествование здесь\"?",204810,null],[204812,"2026-09-11T17:09:32",11,"— Судя по всему мы оказались в рассказе, вы случаем не слышали странного голоса в голове? Мы - да и не раз, особенно Летиция. А так же мы слышим голоса тех кого предполагаемо считаем главным героем даже если находимся там где не должны слышать..",191019,null],[204813,"2026-09-11T17:09:55",31,"- я тут подумал, что исчезновение нашего товарища было похоже на то что он очнулся ото сна",191019,null],[204814,"2026-09-11T17:11:33",11,"// Денис, большая просьба дать какую-то реакцию на заявку Эли.",191019,null],[204815,"2026-09-11T17:12:06",37,"// Она все же показала книгу Мерсо?",191019,null],[204816,"2026-09-11T17:12:08",11,"— Думаешь мы спим? — Аури щипает себя",204813,null],[204817,"2026-09-11T17:12:23",37,"Ты ощущаешь боль и ничего не происходит.",204816,null],[204818,"2026-09-11T17:12:39",11,"// она дописала недостающие части в книге, если это не даёт никакой реакции то тоже стоит озвучить",204815,null],[204820,"2026-09-11T17:13:23",11,"— Я не думаю что это сон.. боль ощущается — ответила девушка",204817,null],[204821,"2026-09-11T17:15:54",37,"@sweetkittywitch \n\nДописав все пробелы, что ты помнишь ты увидела, что... Ничего не произошло. Или произошло, ты не можешь понять. Книга вообще никак не изменилась или чего то такого. Но уже наступала ночь. Старики начали издавать странные звуки щелчков втягивая воздух через щели в зубах. Старушки же всхлипывали и лили слезы.\n Мерсо же похоже клонило в сон.\n Как же душно. Тут уже очень душно, хоть и прохладно.",191019,null],[204822,"2026-09-11T17:17:03",9,"//Вордо тоже душно?",191019,null],[204823,"2026-09-11T17:17:10",37,"Да",204822,null],[204824,"2026-09-11T17:17:34",11,"// ну в курс дела я ввела вввордо хд)",191019,null],[204825,"2026-09-11T17:17:51",31,"- я уже себя щипал, не помогло. Просто задумался еще раз. Может нас можно разбудить только снаружи сна, может его кто то разбудил",204816,null],[204826,"2026-09-11T17:18:28",11,"— Ох.. может быть, но вдруг здесь время идёт совсем иначе чем в реальном мире..? Вдруг мы только уснули пока тогда?",204825,null],[204827,"2026-09-11T17:20:09",11,"— И так сэр Уорлд, мы сейчас плывём по сюжету повествования рассказа, но очень хотим его изменить и посмотреть как это повлияет. Я предложила заставить главного героя — она указала на мужчину возле гроба — господина Мерсо заставить не уезжать отсюда когда закончатся похороны, таким образом повлияв на сюжет.. а моя подруга предложила попытаться убедить его что он персонаж книги",191019,null],[204828,"2026-09-11T17:20:14",11,"— Что скажете вы?",191019,null],[204830,"2026-09-11T17:20:45",9,"— Что то здесь не так, что вы не чувствуете духоты (духоты мастера надеюсь, было бы клёво)? — *Здесь что то не так, Вордо собирается с мыслями чтобы попытаться понять почему так душно стало (указание на себя).* — Соберитесь, что-то происходит.\n\n*Вордо немного волновало что нечем дышать.*",191019,null],[204831,"2026-09-11T17:21:49",37,"// Получай вдохноение",204830,null],[204832,"2026-09-11T17:21:54",9,"/roll 1d20+3+1d4+1d8 Анализ плюс указание плюс прием тактическая оценка чё тут так душно мать его за ногу",191019,null],[204834,"2026-09-11T17:22:41",9,"//24 но есть проблема, если даже крит, то если не мог узнать то не смогу ~",191019,null],[204835,"2026-09-11T17:22:41",11,"— Здесь многолюдно и закрытое пространство полагаю",191019,null],[204836,"2026-09-11T17:23:18",37,"Ты понимаешь, что только сейчас заметил причину духоты. Вы около моря, вон за холмами, утром и днем должно было быть жарко, а сейчас в помещении, которое не проветривалось... Еще и тут куча людей",204832,null],[204837,"2026-09-11T17:24:15",11,"// банальная физика 😁",191019,null],[204838,"2026-09-11T17:27:02",9,"— И влияние побережья, если кружится у кого голова лучше выйти наружу. — *Он подумал немного и сказал уже по делу.* — Толкать историю к другому окончанию хорошая идея, но вы не пытались её не просто изменить, полностью разрушить? Чтобы история не просто сошла с пера, преобразилась на корню в нечто иное.",204835,null],[204839,"2026-09-11T17:27:11",11,"// это тебе, хард",204827,null],[204840,"2026-09-11T17:29:28",9,"//А это реакция на духоту и на то соо, кинь анализ если не понимаешь и я раскажу о намереньях в словах)",204838,null],[204842,"2026-09-11T17:29:43",11,"— В прошлый раз когда мы пытались что-то изменить ничего не вышло, вот мы и пытаемся проверить насколько мы способны влиять на мир — ответила Аури. \n\nДевушка была в удобном платье и от неё исходил запах морской соли, будто бы она совсем недавно вышла с воды. Мокрые на вид волосы показывали тоже самое \n\n— Мне не особо душно, может дело в ваших бинтах?",204838,null],[204854,"2026-09-11T17:40:01",9,"*Планы таинственного незнакомца слишком сложны для тебя, но может немного приоткроют тайну следующие слова:*\n\n— История должна просто закончится и нам нужно просто дожить до этого момента. Или же мы можем заставить закончится её раньше времени, если можем повлиять в принципе. — *Он поднимает руку, скорей всего думает что-бы сделать, или сколдовать...*\n\n//Как далеко гроб?)",204844,null],[204856,"2026-09-11T17:40:56",9,"//Прошу описание от мастера, побольше",191019,null],[204857,"2026-09-11T17:40:59",11,"// у меня перс слишком добрый для такой фигни так что я великий слепой и ничего не понимаю",191019,null],[204858,"2026-09-11T17:41:27",37,"// Гроб в парк метров от тебя. Он закрыт, но не привинчен",204854,null],[204859,"2026-09-11T17:41:28",9,"— Где тот парень, это его мать умерла? — *Спрашивает у Дженази же?*",191019,null],[204860,"2026-09-11T17:42:09",11,"— угу",191019,null],[204861,"2026-09-11T17:42:59",9,"//Мне показали где парень?)",191019,null],[204863,"2026-09-11T17:44:23",11,"Указывает на единственного молодого человека здесь, кроме Конрада. Сидит он прямо у гроба, заметить не трудно",191019,null],[204866,"2026-09-11T17:46:58",9,"*Тихие таинственные слова среди бормотания и плача, чтобы не потревожить людей. Из гроба словно встаёт едва различимая светящиеся фигура женщины и обнимает парня, несколько мгновений и рассеивается как и небыло, словно явление, словно свет, словно душа.*\n\n//Если так можно. Блуждаюшие огни! 4 в 1! Форма ЧЕЛОВЕЧЕСКАЯ ФИГУРА! Делаем сцену",191019,null],[204867,"2026-09-11T17:47:18",9,"//Надеемся что магия здесь работает.",191019,null],[204868,"2026-09-11T17:48:04",11,"// если работает то помогу безмолвным образом во",191019,null],[204869,"2026-09-11T17:48:18",9,"//Честно, я ничего не знаю что тут было до меня, только вот то что вы расказали",191019,null],[204870,"2026-09-11T17:48:39",11,"// да так и надо, я постаралась рассказать ключевое",191019,null],[204871,"2026-09-11T17:48:47",9,"//Да, го я тоже безмолвным",191019,null],[204872,"2026-09-11T17:49:00",9,"// 3/4 приемы 2/3 метамагия",191019,null],[204873,"2026-09-11T17:49:32",11,"// колдуй тогда, не буду вмешиваться пока) если и без помощи можешь",191019,null],[204874,"2026-09-11T17:49:35",37,"// Что ты делаешь?",204866,null],[204875,"2026-09-11T17:49:54",9,"//Метамагией безмолвное заклинание. Сцена!)",204866,null],[204876,"2026-09-11T17:50:32",9,"//4 блуждающие огни можно делать в гуманоидную фигура средних размеров 😏👌",191019,null],[204877,"2026-09-11T17:52:25",9,"//Меня смущает что тут только мы, остальных ждём?",191019,null],[204878,"2026-09-11T17:55:08",37,"Все стрики и старушки ненадолго удивились и молчали в удивлении.\n Мерсо же посмотрел на это, попытался обнять силуэт, но он уже исчез.\n Он замолк и сказал.\n— Вот и все...\n Все старики и старушки начали грустить еще сильнее, а Мерсо сел обратно на стул и со сложным выражением лица смотрел дальше на гроб.",204866,null],[204879,"2026-09-11T17:56:29",11,"// а знаете я хочу что бы мой перс думал что это реально🥰",191019,null],[204880,"2026-09-11T17:56:56",9,"//Можно, я безмолвным и ты моих намерений проверкой не разгадала)",191019,null],[204881,"2026-09-11T17:57:32",41,"( сори, я чето очень хорошо легла на час . Вернулась",191019,null],[204883,"2026-09-11T17:57:49",37,"// Давай включайся",191019,null],[204884,"2026-09-11T17:58:35",11,"// отреагируй на заявку харда и попробуем дать книгу ему? \n\nЧестно говоря ситуация не располагает лезть к человеку который прощается с мертвым родственником для доброго перса такое, я бы рил предпочла продождать пока он выйдет..\n\nПоследнее мастеру",204881,null],[204886,"2026-09-11T18:00:56",41,"Летиция попыталась разобрать его чувства, что таила в себе эта небольшая заминка? \n\nНо тут некий прокаженный подошел к гробу и появилась фигура похожая на призрака. Летиция точно могла их отличить , но не знала причину явления этой иллюзии",204878,null],[204887,"2026-09-11T18:01:09",41,"/r d20 проницательности",191019,null],[204892,"2026-09-11T18:01:58",41,"( я про лицо сына",191019,null],[204893,"2026-09-11T18:05:42",37,"Ты прочитала... Сложные эмоции, будто человеку перед тобой было чуждо испытывать какие-либо эмоции. Он хотел увидеть свою маму и услышать ответ на вопрос, но он также он, будто, хотел закончить это все побыстрее и пойти по делам. Но также ты прочитала, что он хочет спать.",204887,null],[204894,"2026-09-11T18:06:14",31,"Психопат детектед/",204893,null],[204896,"2026-09-11T18:06:51",31,"Может, он маму и мочканул?/",191019,null],[204897,"2026-09-11T18:07:43",37,"// ФУ, ВЫПЛЮНЬ КАКУ!",191019,null],[204898,"2026-09-11T18:07:49",31,"Я без шуток кстати, отсутствие эмоций это и есть психопатия/",191019,null],[204899,"2026-09-11T18:07:59",37,"// Нельзя так думать",191019,null],[204900,"2026-09-11T18:08:34",31,"Это мои мысли, а не персонажа, он то не смотрел в лицо психа с проницательностью/",204899,null],[204901,"2026-09-11T18:10:08",9,"*Ворд лишь хмыкнул, думал люди среагируют более активно на явление, но ладно, он то сделал все как надо, это люди маловпечетлительные.*",191019,null],[204902,"2026-09-11T18:11:00",37,"// Заставил весь зал рыдать еще сильнее, а тут такое...",204901,null],[204903,"2026-09-11T18:12:28",9,"//У меня заявки кончились, остальные?",191019,null],[204904,"2026-09-11T18:13:22",41,"( он просто показал силуэт?",191019,null],[204905,"2026-09-11T18:13:55",37,"//.",204866,null],[204906,"2026-09-11T18:14:10",41,"Летиция дернула Ворда за руку и затащила в их компашку",191019,null],[204907,"2026-09-11T18:14:16",41,"( а, Вижу",191019,null],[204908,"2026-09-11T18:14:32",41,"/r d20-1 хватка Летиции, Бойся",191019,null],[204910,"2026-09-11T18:14:41",41,"( целых 5",191019,null],[204911,"2026-09-11T18:15:44",11,"// вот именно, они не особо реагируют на наши действия)",204901,null],[204912,"2026-09-11T18:16:19",11,"Аури тоже впечатлена и не ищет подвоха",191019,null],[204913,"2026-09-11T18:16:30",9,"//Надо же было на себе ощутить",204911,null],[204916,"2026-09-11T18:23:01",31,"- опять убеждаюсь, что не делай - местным похер. Хоть вырезай из массово. Может, начать? Шутка",191019,null],[204917,"2026-09-11T18:23:22",31,"- словно мы призраки какие...",191019,null],[204923,"2026-09-11T18:27:39",11,"// ыыых ладно предложу идею которая персу не оч подходит..",191019,null],[204924,"2026-09-11T18:28:32",11,"— А что если мы выкрадем господина Мерсо..? Не смотрите на меня так.. мы ведь не будем ему вредить, только попробуем помешать сюжету происходить?",191019,null],[204925,"2026-09-11T18:29:03",31,"- хмм. Мне нравится. Шоковая терапия",204924,null],[204927,"2026-09-11T18:30:01",11,"Аури вопросительно смотрит на остальных в ожидании ответа\n\n// @sweetkittywitch Hard",191019,null],[204931,"2026-09-11T18:31:34",41,"( Сори отойду",191019,null],[204932,"2026-09-11T18:33:08",9,"— Вдруг если история не закончится, мы застрянем здесь навсегда... — *Шепчет он наганяя ужаса, явно забавляется, но не высказал и слова против идеи.*",204924,null],[204933,"2026-09-11T18:36:21",11,"— Не проверим не узнаем, но жить по течению судьбы чужих историй совсем не интересно — девушка надула губы недовольно",191019,null],[204934,"2026-09-11T18:38:30",9,"— Я не помню чтобы вы представлялись, имена спутников упоминали ранее. — *Он указал на недочет со стороны дженази.*\n\n//Будем всем указывать на их ошибки и недостатки, не зря указание взял же",204933,null],[204935,"2026-09-11T18:39:28",31,"- Конрад фон Шаттенхаус, к вашим услугам",204934,null],[204936,"2026-09-11T18:39:32",9,"//Можно артики ваших персов? Мне так легче воспринимать вас",191019,null],[204937,"2026-09-11T18:39:56",11,"— Ох, я не назвала свое имя? Прошу прощение, хотелось ввести вас в курс дела. Меня зовут Аури Диан — она протянула руку",191019,null],[204941,"2026-09-11T18:46:47",9,"*Заминка, протянутая рука? Он её должен взять и поцеловать? Дженази выглядила неплохо, пожалуй стоит исключения. Он все же сделал ритуал рукоприкладства (целование руки/галантное приветствие). Вместо поцелуя и поклона скорее подтянул её руку к себе коснувшись бинтами у подбородка прекрасных голубых костяшек.*\n\n— Как представлялся ранее, не побоюсь сделать это ещё раз, мистер Уорлд (мир), для вас просто Ворд. Премного воодешевлён нашим знакомством, даже если обстановка немного не располагает. — *Он напомнил что все мы еще в зале полном плачущих людей, на похоронах знакомимся и фамильярничаем как на светской беседе. Слегка пошутил ещё.* — Может попросить кого-то принести нам вино и закуски?",204937,null],[204942,"2026-09-11T18:51:09",11,"Аури опешила ибо ждала рукопожатия и даже немного смутилась\n\n— Вы человек этикета, господин Ворд, атмосферу здешнюю несколько разбавляете ибо как не тоска от похорон, так отчаяние от ситуации настроение немного подпортили. Но может вы правы, может стоит начать вести себя абсурдно и посмотреть что из этого выйдет.. шучу, мне не хватит смелости прерывать похороны, не та обстановка. К тому же душно здесь, может выйдем и подождем пока обитатели дома призрения пойдут спать и останется только сын? Или какие будут у вас предложения? \n\n*Последнее предложение касается всех",191019,null],[204943,"2026-09-11T18:52:10",9,"//Ну а чё, мне дама протягивае руку, вы ожидали другой реакции?)\n\n//Ждем всех, а то будто ток я с Джейд играем(((",191019,null],[204944,"2026-09-11T18:53:58",11,"// короче спрашиваю всех воровать сына будем?)",191019,null],[204946,"2026-09-11T18:59:55",31,"- так, и как мы это провернем? Прямо сейчас схватим и в окно?",191019,null],[204947,"2026-09-11T19:00:39",11,"— Подкараулим когда он будет один?",191019,null],[204948,"2026-09-11T19:01:39",31,"- будем таскаться за ним толпой?",191019,null],[204949,"2026-09-11T19:02:37",11,"— Просто подождём пока пожилые люди выйдут и он останется один? Хм..",191019,null],[204951,"2026-09-11T19:03:19",11,"Аури пытается создать малой иллюзией рядом с собой на лавочке копию своей книги",191019,null],[204952,"2026-09-11T19:03:26",11,"// персонаж просто проверяет работает ли магия",191019,null],[204953,"2026-09-11T19:04:00",41,"( тут",191019,null],[204954,"2026-09-11T19:11:51",31,"- план не идеальный, но рабочий",204949,null],[204955,"2026-09-11T19:12:33",11,"— Я могу просто попытаться усыпить всех здесь",191019,null],[204956,"2026-09-11T19:13:00",11,"— Они задремают, а мы выкрадем господина Марсо",191019,null],[204960,"2026-09-11T19:17:01",9,"— Простите, вы волшебница? Неогранённый алмаз полный талантов, хотелось бы с вами дорогая Аури обсудить магические основы. — *Он махнул рукой на толпу и похорогы, небрежно.* — Когда нас не обременят дела.\n\n//Хочу учиться накладыванию заклинаний волшебника у Аури пока мы вместе на квесте",204956,null],[204961,"2026-09-11T19:19:09",11,"— У меня? — девушка прям по сторонам посмотрела что бы убедиться что ты с ней говоришь — это будет честью для меня учить вас",191019,null],[204962,"2026-09-11T19:21:17",41,"— Меня зовут Летиция. Значит вас тоже забросили сюда, прискорбно...",204934,null],[204963,"2026-09-11T19:21:39",41,"— ты и правда как алмаз. Говорят их не видно в воде)",204961,null],[204964,"2026-09-11T19:21:49",9,"— Вы не правы дорогая Аури. — *Он взял руку и слегка присел, на одно колено и руку волшебницы прислонил к своему лбу.* — Это будет честью для меня учиться у вас, источник невообразимой мощи и волшебства, прекрасный как и вы сами.",204961,null],[204965,"2026-09-11T19:22:49",9,"*Единственные кого Вордо может признать, это волшебники сильнее чем он сам. И вот он встретил одного.*",191019,null],[204966,"2026-09-11T19:23:11",37,"Ты создаешь копию своей книги, и да, магия работает.",204952,null],[204967,"2026-09-11T19:23:26",37,"// Забыл сказать... У меня обыватели имеют x3 бонус",204965,null],[204968,"2026-09-11T19:24:22",9,"//Пусть, я буду учится у прекрасной волшебницы что напоминает небесные сапфиры!)",204967,null],[204970,"2026-09-11T19:24:51",37,"// 10 дней на полное изучение, если эти эффекты стакаются.",204968,null],[204971,"2026-09-11T19:25:01",11,"// что вы Аури тут смущаете жесть",191019,null],[204972,"2026-09-11T19:25:09",9,"//Не, с учителем втрое быстрее, всё",191019,null],[204973,"2026-09-11T19:25:20",41,"— А вы знали, что Аури у нас медалистка турнира магов?)",204965,null],[204974,"2026-09-11T19:25:26",37,"// Она самый умный персонаж на свете, смогла понять половину всех задумок",204971,null],[204976,"2026-09-11T19:27:03",11,"Второй рукой закроет лицо книгой что бы не стесняться, а затем как отпустишь руку спрячет лицо на плече Летиции обнимая ту",204964,null],[204977,"2026-09-11T19:30:22",9,"— Не знал, достаточно того что знаю и вижу чтобы сказать \"её кожа напоминает небесные сапфиры а в глазах таится мудрость словно глубина вечносинего неба утонувшего в океане несбыточных грёз\". — *Красиво плетёт, да не сильно держит, дал спрятаться за Летицией, достаточно проницательный чтобы не докучать смущающейся девушке — встал на ноги.* — План есть, будем его придерживаться.",204973,null],[204978,"2026-09-11T19:32:04",9,"//Простите, чёт несет не туда наверное 😂👍",191019,null],[204979,"2026-09-11T19:32:32",37,"// Сука",191019,null],[204980,"2026-09-11T19:32:34",11,"Немного отойдя отлипает от подруги\n\n— Я с радостью научу вас тому что умею, но пока вы согласны на мой план?",191019,null],[204981,"2026-09-11T19:32:42",37,"// Держи второе вдохновение",191019,null],[204982,"2026-09-11T19:32:53",9,"//Мне?)",191019,null],[204983,"2026-09-11T19:32:54",11,"// я не против, нет ничего лучше чем социалка💅",204978,null],[204984,"2026-09-11T19:32:54",37,"// И Аури тоже вдохновение",191019,null],[204986,"2026-09-11T19:34:21",9,"//Щас мы вытрясем всё дерьмо все вдохновения с мастера",191019,null],[204988,"2026-09-11T19:35:03",31,"Давайте уже похищать чувака, а то я усну скоро/",191019,null],[204991,"2026-09-11T19:35:37",37,"// @sweetkittywitch, тут план делают, ты помогаешь или нет?",191019,null],[204993,"2026-09-11T19:37:17",11,"*Аури оценивает взглядом размеры помещения в котором они находятся",191019,null],[204995,"2026-09-11T19:38:16",11,"// можно ли задеть кастом только пожилых людей?",191019,null],[204997,"2026-09-11T19:41:18",37,"// Здание около 8 метров на 12 метров, то есть 1033 футов в площади",204995,null],[204998,"2026-09-11T19:41:41",41,"( я пока читаю",204991,null],[204999,"2026-09-11T19:41:54",41,"( можно кратко в чем план?",191019,null],[205000,"2026-09-11T19:41:58",37,"// Ну да",204995,null],[205001,"2026-09-11T19:42:11",41,"( я еще в 20 на онлайн игру уйду",191019,null],[205002,"2026-09-11T19:42:25",37,"// Они хотят усыпить жителей, а Мерсо похитить.",204999,null],[205003,"2026-09-11T19:42:35",41,"( ок",191019,null],[205004,"2026-09-11T19:43:37",41,"( у меня вариантов лучше нет",191019,null],[205005,"2026-09-11T19:44:36",11,"Аури берет книгу и отходит куда-то в угол позади стариков что бы те не видели ее странных движений. Жестикулируя шепотом читает заклинание",191019,null],[205007,"2026-09-11T19:48:28",31,"Представляю сейчас урит единица выпадает и у нас полная комната стариков, что уже не проснутся☠",191019,null],[205008,"2026-09-11T19:49:32",37,"// Разве это не усыпление?",191019,null],[205010,"2026-09-11T19:49:44",41,"( ну да",191019,null],[205011,"2026-09-11T19:50:39",11,"// там только один бросок и то на хп существа с хп ниже выпавшего значения будут засыпать",191019,null],[205012,"2026-09-11T19:50:52",37,"Вся группа из 8 пенсионеров, в числе привратника засыпает, а Мерсо остается в сознании, но похоже он уже засыпает от усталости.",191019,null],[205013,"2026-09-11T19:51:45",11,"Девушка возвращается к группе\n\n— Ну.. у нас есть минута, мужчины помогут? — достает верёвку",191019,null],[205014,"2026-09-11T19:52:05",31,"- о, наконец то разомнусь",191019,null],[205015,"2026-09-11T19:52:17",9,"*К нему подходит Вордо и берет за плечо, он стоял в зоне заклинания и на него не действовали такие фокусы.*\n\n— Тебе пора идти.",205012,null],[205016,"2026-09-11T19:52:32",11,"// эльфы:D",191019,null],[205017,"2026-09-11T19:52:50",11,"Аури по этому сделает догадку о расе Вордо",191019,null],[205018,"2026-09-11T19:53:20",41,"— Я тоже могу помочь. Аури видела , как я поднимала чашку! :3",191019,null],[205019,"2026-09-11T19:54:13",37,"— Что?\nМерсо умел уставший вид и засыпал на ходу, но был в сознании.",205015,null],[205020,"2026-09-11T19:54:13",9,"//Надеюсь он сопротивляется ^^",191019,null],[205021,"2026-09-11T19:55:25",37,"// На плечо, нет",205020,null],[205022,"2026-09-11T19:56:16",9,"*Небольшая пауза, заминка, Вордо собирается с мыслями чтобы звучать убедительнее (указание на себя) и говорит:*\n\n— Просто пошли, иначе тябя потащат силой, сейчас. — *Старается звучать как можно более убедительнее.*",205019,null],[205023,"2026-09-11T19:56:21",41,"( мне кажется , в его состоянии мы можем просто поднять его и утащить",191019,null],[205024,"2026-09-11T19:56:35",9,"/roll 1d20+1d4 запугивание нах)",191019,null],[205026,"2026-09-11T19:56:58",9,"*Вордо звучал неубедительно для сонного человека.*",205025,null],[205027,"2026-09-11T19:57:02",41,"( мастер, хочу телекинетикой вызвать у него эффект как при укачивании",191019,null],[205030,"2026-09-11T19:57:18",41,"( что мне кинуть ?",191019,null],[205032,"2026-09-11T19:57:40",37,"— Куда? Мне нужно дождаться церемонии похоронения матери и пойти обратно в город...",205022,null],[205034,"2026-09-11T19:57:50",37,"// Магию",205030,null],[205035,"2026-09-11T19:57:55",11,"— У тебя есть идея? — Аури с любопытством смотрит на подругу",191019,null],[205036,"2026-09-11T19:58:00",41,"— лучше… поспи~",191019,null],[205037,"2026-09-11T19:58:07",41,"/r d20-1",191019,null],[205039,"2026-09-11T19:58:28",37,"Мерсо почувствовал укачивание и попытался встать на ноги.",191019,null],[205040,"2026-09-11T19:58:29",9,"— Помогай, он не слушает.",205014,null],[205041,"2026-09-11T19:58:32",37,"/r 1d20-1",191019,null],[205043,"2026-09-11T19:58:45",41,"( хер там плавал, спи давай",191019,null],[205044,"2026-09-11T19:58:57",37,"Он спотыкается и падает на пол оперевшись руками.",191019,null],[205046,"2026-09-11T19:59:05",37,"// У кого, кстати книга?",191019,null],[205047,"2026-09-11T19:59:07",9,"*Берет его под ручку и выводит, надеюсь Конрад щас под вторую подтянется.*",191019,null],[205048,"2026-09-11T19:59:36",41,"— Ой… я думала уснет",191019,null],[205049,"2026-09-11T19:59:51",41,"— у кого-то есть что-то тяжелое ?",191019,null],[205050,"2026-09-11T20:00:08",37,"// @Ashenchampion у тебя?",205046,null],[205051,"2026-09-11T20:00:15",9,"//У нас минута напомню на сон",191019,null],[205052,"2026-09-11T20:00:19",9,"//Вроде",191019,null],[205053,"2026-09-11T20:00:28",11,"// у Летиции",205046,null],[205054,"2026-09-11T20:00:30",31,"Подхожу и коротко бью по затылку, чтобы вырубить. \n\n/Конрад не болтает, Конрад бьет/",205040,null],[205055,"2026-09-11T20:00:49",41,"( я думала мемно стукнуть его книгой",191019,null],[205056,"2026-09-11T20:00:55",41,"( можна?",191019,null],[205057,"2026-09-11T20:01:38",37,"// почему нет?",205056,null],[205058,"2026-09-11T20:01:48",37,"// Попадание",205054,null],[205059,"2026-09-11T20:01:51",41,"/r d20-1",191019,null],[205061,"2026-09-11T20:01:56",41,"( ой",191019,null],[205062,"2026-09-11T20:02:02",9,"— Теперь нам тащить его, это сложнее. — *Немного не понравились методы но ладно, тащить так тащить, потом выест мозги молодому человеку, где-то за кадром.*",205054,null],[205064,"2026-09-11T20:02:31",31,"/roll d20+3",205058,null],[205066,"2026-09-11T20:02:33",11,"// с одной стороны Летиция, с другой Конрад)",191019,null],[205067,"2026-09-11T20:02:56",37,"Мерсо получает небольшой удар от парня и затем небольшой удар от возрожденной. В итоге он вырубается.",191019,null],[205068,"2026-09-11T20:02:58",11,"— Авв, полагаю это было больно.. давайте выведем его быстрее пока остальные не очнулись — идёт открывать дверь и смотреть нет ли там никого",191019,null],[205069,"2026-09-11T20:03:07",41,"( Летиция просто мимо книжкой махнула, а такой вид будто попала)))",191019,null],[205070,"2026-09-11T20:03:11",37,"Книга же резко растворяется в свете.",191019,null],[205071,"2026-09-11T20:03:33",41,"— ой! Нет подожди !",191019,null],[205072,"2026-09-11T20:03:39",9,"— Тащим, нет времени.",191019,null],[205073,"2026-09-11T20:03:42",41,"( ребят , сори, я на игру",191019,null],[205074,"2026-09-11T20:04:03",9,"//Ну тут и остановимся наверноес Алексею спать надо тоже",191019,null],[205075,"2026-09-11T20:04:05",37,"//Предлагаю тогда закончить",191019,null],[205076,"2026-09-11T20:04:17",31,"Ок, перерыв/",191019,null],[205077,"2026-09-11T20:05:23",31,"Я только сейчас понял что использовал мод ловкости для попадания, надо было наверное силу? Или у меня как обладателя черты посвященный в боевое искусство есть возможность заменять силу на ловкость?/",191019,null],[205078,"2026-09-11T20:05:51",11,"// ты от чего бьешь оружием? Можно основным статом думаю без проблем",191019,null],[205079,"2026-09-11T20:05:52",9,"//Так у тебя та черта недомонаха, для ударов безоружных ловкость можно.",205077,null],[205080,"2026-09-11T20:06:17",11,"// а так да спокойной ночи Лёше и спасибо за игру, пока момент интересный) интересно что дальше будет надеюсь тоже активно пойдем",191019,null],[205081,"2026-09-11T20:06:18",31,"Отлично/",191019,null],[205395,"2026-09-12T12:30:17",37,"// @QURTZZ @Ashenchampion @sweetkittywitch Hard все смогут сегодня через 15-30 минут?",191019,null],[205396,"2026-09-12T12:30:23",37,"// Или сразу сейчас?",191019,null],[205398,"2026-09-12T12:30:31",11,"// я тут",191019,null],[205399,"2026-09-12T12:30:53",41,"( я буду через 15",191019,null],[205400,"2026-09-12T12:31:15",9,"//Тут",191019,null],[205417,"2026-09-12T12:44:30",31,"Я картошку копаю) буду забегать и читать и если что, отписываться/",191019,null],[205420,"2026-09-12T12:58:53",37,"// Так продолжаем.\n\nВы смогли успешно вытащить Мерсо на улицу, уже было темно и видно луну.",191019,null],[205421,"2026-09-12T12:59:09",37,"Мерсо был без сознания и не стоял на ногах.",191019,null],[205424,"2026-09-12T13:01:37",11,"— Давайте отнесём его куда-то.. в безлюдное место? Что бы попытаться убедить в том что он персонаж книги или как минимум помешать сюжету идти так как он идёт? \n\nАури оглядывалась по сторонам что бы убедиться что их никто не видит и в попытках найти примечательное местечко куда они могли бы направиться",191019,null],[205425,"2026-09-12T13:02:10",41,"— Мне кажется тут одни степи в округе... Давайте отойдем подальше...",191019,null],[205426,"2026-09-12T13:02:18",37,"Уже никого не было снаружи и вас от основного здания разделяло около 100 футов",205424,null],[205429,"2026-09-12T13:02:45",9,"— Поля. — *Указал он в поле.* — Нас скроет ночь.",191019,null],[205432,"2026-09-12T13:03:21",41,"— Хорошо",205429,null],[205440,"2026-09-12T13:05:14",11,"— Давайте в поле — идёт последней и оглядывается — меня одну не покидает ощущение что то что мы делаем неправильно, но при этом адреналин ситуацию делает крайнее интересной..?",191019,null],[205445,"2026-09-12T13:08:37",41,"— со вторым я соглашусь...а вот первое. Наверное мы можем успокоить себя благой целью - выбраться",191019,null],[205447,"2026-09-12T13:08:39",9,"*Вордо расправился, нести кого-то было ему не очень приятно, жаль что нет при себе заклинаний и инсрументов делающих предметы невесомыми, хотя бы тензеров диск.*",191019,null],[205448,"2026-09-12T13:09:09",11,"// мы припахали для этого Конрада",191019,null],[205457,"2026-09-12T13:10:32",11,"*кивает \n\nКогда же группа выбралась подальше от чужих глаз, желательно ещё скрыться за какими-то кустарниками/деревьями. Аури стелит холстину что бы ребята усадили Мерсо на ткань, а не землю",205445,null],[205465,"2026-09-12T13:12:18",31,"- заботливая ты, Аури. Я вот бы просто так его бросил. Не очень я верю что персонаж книги обиделся бы",191019,null],[205467,"2026-09-12T13:12:30",11,"— Ну пока он приходит в себя.. давайте решим что будет спрашивать у него и что будем говорить..? — немного нервничаю",191019,null],[205468,"2026-09-12T13:12:37",11,"— Ну, проверим как проснётся..",205465,null],[205474,"2026-09-12T13:13:06",41,"— покажем ему страницу так точно",191019,null],[205475,"2026-09-12T13:13:38",31,"- с мы можем как то повлиять на его разум? Чтобы он легче шел на контакт",191019,null],[205476,"2026-09-12T13:13:47",11,"— Угу..",205474,null],[205477,"2026-09-12T13:13:51",31,"- ну там заклинанет какое или еще чего",191019,null],[205480,"2026-09-12T13:14:22",11,"— Ну, я хочу попытаться спросить что он планирует делать дальше и убедить его делать иначе.. как минимум что бы он не покинул это место если по сюжету должен?",205475,null],[205482,"2026-09-12T13:14:55",11,"она обиженно надула губы\n\n— Такой магии меня не учили.",205477,null],[205484,"2026-09-12T13:15:26",37,"// Напомню, что книги нету",191019,null],[205485,"2026-09-12T13:15:31",11,"А сама решила провести ритуал призыва невидимого слуги",191019,null],[205486,"2026-09-12T13:15:35",31,"- жаль\n\nКонрад искренне жалеет",205482,null],[205488,"2026-09-12T13:15:42",11,"— Лети, книга у тебя?",205484,null],[205507,"2026-09-12T13:18:44",41,"— да, еще у меня. Прости, забыла отдать",191019,null],[205510,"2026-09-12T13:19:01",41,"( а бля",191019,null],[205511,"2026-09-12T13:19:11",41,"( книга испарилась",191019,null],[205512,"2026-09-12T13:19:26",37,"Летиция понимает, что книги та и нету",191019,null],[205513,"2026-09-12T13:19:27",9,"— Будь увереннее дорогая Аури, у тебя все получится, главное не показывать слабостей. — *Подбадривает он волшебницу.*\n\n//Указание",191019,null],[205514,"2026-09-12T13:19:31",41,"— ой...",191019,null],[205516,"2026-09-12T13:19:44",41,"— что же делать...",191019,null],[205517,"2026-09-12T13:19:45",11,"— Спасибо",205513,null],[205519,"2026-09-12T13:20:03",11,"— ..? — Заметив растерянность подруги Аури забеспокоилась",205516,null],[205522,"2026-09-12T13:20:37",41,"— книга пропала!",191019,null],[205530,"2026-09-12T13:21:40",11,"*вздох\n\n— Погоди, я помню что ты писала, могу переписать это на бумаге.. \n\n// Черта отличная память или я не могла видеть те слова что она записала?",191019,null],[205532,"2026-09-12T13:22:02",37,"// Не видела",205530,null],[205533,"2026-09-12T13:22:15",41,"— я могу еще раз...",191019,null],[205535,"2026-09-12T13:22:39",41,"— может он хоть увидит, что лист пропадет",191019,null],[205536,"2026-09-12T13:22:51",11,"— Я запишу содержимое книги, а ты снова заполнишь пустые места?\n\nДевушка достает пергамент и пустые листы пергамента начиная записывать то что видела в книге, а затем передает листы и перо подруге",191019,null],[205541,"2026-09-12T13:23:26",41,"— да, Давай так",191019,null],[205543,"2026-09-12T13:23:51",11,"*поглядывает на бессознательного Мерсо пока Летиция пишет",191019,null],[205544,"2026-09-12T13:24:21",37,"Вы замечаете, что мерсо начал немного дергаться, похоже приходить в сознание.",191019,null],[205545,"2026-09-12T13:24:23",41,"летиция специально не заканчивает, ждет пока Мерсо очнетсч",191019,null],[205550,"2026-09-12T13:26:37",11,"— Он приходит в себя — комментирует девушка",191019,null],[205597,"2026-09-12T13:35:55",11,"— Как вы себя чувствуете? — девушка наклоняется над мужчиной приходящим в себя и смотрит прямо в глаза",205544,null],[205599,"2026-09-12T13:36:29",37,"— Не приятно...\n Отвечает Мерсо полностью придя в себя.",191019,null],[205600,"2026-09-12T13:36:30",41,"( Ариэль",191019,null],[205608,"2026-09-12T13:37:26",11,"— Мне жаль.. но.. кхм, мы оглушили вас и выкрали, что вы собираетесь делать с этим? — она пыталась звучать строгой в последнем предложении",191019,null],[205616,"2026-09-12T13:39:05",9,"//У меня не слишком хорошие ассоциации с \"не приятно\" ощущение что мы щас его выпотрошим или... ну хрен с ним короче.",205599,null],[205621,"2026-09-12T13:40:10",37,"— Выкрали?\n Мерсо посмотрел по сторонам и поняв, что он даже не связан сказал.\n— Вы пока что только оглушили меня",205608,null],[205625,"2026-09-12T13:40:45",11,"— Это поправимо — показывает на угрожающего вида Конрада с её веревкой в руках — так и какой ваш план дальше?",191019,null],[205629,"2026-09-12T13:41:42",37,"На лице Мерсо не было видно эмоций и он ответил.\n— За что же вы так со мной?",205625,null],[205633,"2026-09-12T13:42:58",11,"*разочарована отсутствием реакции \n\n— Потому что вы главный герой — говорит она — а теперь вы должны нам поведать что вы планировали делать дальше",191019,null],[205636,"2026-09-12T13:43:34",9,"— Если вы хотите изменить сюжет его всегда можно убить, или растворить в кислоте. — *Меж пальцами в бинтах перебирает склянку с кислотой, черной как ночь, обращается уже к парню.* — Просто за то что ты есть парень, тебе нужно донести правильную мысль для эксперимента, мы совсем не герои этой истории и не люди. Слушай госпожу Аури.\n\n//Помощь Аури",205629,null],[205637,"2026-09-12T13:43:38",37,"// минутку",191019,null],[205649,"2026-09-12T13:45:36",11,"*переводит взгляд с героя на Вордо и пытается понять серьезно ли это сказано или нет, а сама несколько опешила",205636,null],[205653,"2026-09-12T13:46:48",31,"- мне нравится ход ваших мыслей, господин Вордо",205636,null],[205654,"2026-09-12T13:47:13",9,"— Не переживайте дорогая Аури, он сам выбирает свою судьбу, постарайтесь донести ему суть происходящего. — *Подбадривает её действовать.*\n\n//Обновляем указание",205649,null],[205656,"2026-09-12T13:47:37",11,"// честно говоря не понимаю что вы от меня хотите, кастов очарования у меня нет)",191019,null],[205658,"2026-09-12T13:47:53",31,"Харизмой мочи/",205656,null],[205673,"2026-09-12T13:49:42",11,"// великая и ужасная Аури! Хд\n\nЖдём мастера",191019,null],[205674,"2026-09-12T13:49:51",9,"— Само собой разумеющийся. — *А как иначе, он даже не воспринял это как похвалу, скорее Аксиому, даже можно было не упоминать вслух.*",205653,null],[205675,"2026-09-12T13:50:10",9,"//Помогаем всей толпой ^^",205673,null],[205714,"2026-09-12T14:03:00",37,"Мерсо переводил взгляд по вам всем и посмотрев на Аури сказал.\n— Хорошо... Я хотел после похорон пойти обратно в город, но после вашей просьбы остаться после похорон повести следующий день здесь и пойти обратно на работу...",191019,null],[205718,"2026-09-12T14:05:47",11,"*оглядывается на остальных с немым вопросом: «будет ли этого достаточно?»",191019,null],[205720,"2026-09-12T14:06:10",37,"— К сожалению я не знаю что делать в таких ситуациях...",191019,null],[205722,"2026-09-12T14:06:45",11,"— Можете ли вы рассказать побольше о том что планировали в будущем?",191019,null],[205724,"2026-09-12T14:07:13",37,"— Только это, я же не планирую свое расписание на пару недель вперед",205722,null],[205733,"2026-09-12T14:09:24",11,"— Лети, продемонстрируй нашу работу господину Мерсо",191019,null],[205735,"2026-09-12T14:10:09",11,"*передаёт бумаги с оглавлением «Посторонний» \n\n— Прочитайте это и скажите что вы об этом думаете",191019,null],[205736,"2026-09-12T14:10:14",41,"Она показывает и при нем пишет последнее слово, читая вслух",191019,null],[205743,"2026-09-12T14:13:44",37,"Книга начала светиться и гореть, а из неё самой вылетать бабочки.\n— Что происходит?\n Говорит Мерсо.",191019,null],[205746,"2026-09-12T14:17:33",11,"— Твоя теория была верной, Лети.. Это сюжет вашей жизни, господин Мерсо, как видите показать его вам мы не можем, «мир» в котором мы находимся противится этому",191019,null],[205748,"2026-09-12T14:18:39",11,"— Но так как вы являетесь главным героем нам известно все что вы делаете по сюжету даже если вы находитесь не в радиусе нашего поля зрения. Так что мы поставили себе задачу заставить вас идти против сюжета и будем ее придерживаться. Боюсь на работу вы вернуться пока что не сможете",191019,null],[205750,"2026-09-12T14:19:09",31,"- да, пуститьечь в приключения. Мечатли же о них поди?",191019,null],[205753,"2026-09-12T14:20:07",11,"— О, отличная идея, Конрад, тут как раз чудесные места, может возьмёте отпуск и отдохнёте у моря? На работе должны понять, вы ведь недавно потеряли матушку, к тому же здесь такие чудесные края..",191019,null],[205756,"2026-09-12T14:22:12",9,"*Стоит, наблюдает как дело идёт. Пока не вмешивается. Правда методы слишком неэффективные, зато чужими руками, сделать иначе можно всегда.*",191019,null],[205757,"2026-09-12T14:22:16",41,"— кажется, мы свежем его с ума",205746,null],[205760,"2026-09-12T14:23:33",31,"- нет, это слишком логично. Надо собраться с цепи, я не знаю, выбрить половину головы и покрасить вторую в ярко зелёный цвет, уволится побнув начальнику в лицо, женится на нищенке с тремя детьми и так далее",205753,null],[205774,"2026-09-12T14:27:01",37,"— Хм... Я бы сходил в отпуск на море...",191019,null],[205780,"2026-09-12T14:29:49",11,"*послушав Конрада говорит \n\n— А ещё лучше выйти в море! Вы плавали на корабле когда-то? Мы вот с Летицией да, давайте уплывем куда-то далеко за горизонт, как вам идея? — обращается ко всем",205774,null],[205783,"2026-09-12T14:30:28",11,"— А ещё вы случаем не хотели бы сделать себе тату? — смотрит нет ли у него уже их",191019,null],[205804,"2026-09-12T14:33:38",37,"— Хм... Я бы просто поплавал от жары...",191019,null],[205820,"2026-09-12T14:36:35",11,"— Тогда точно в море! Решено и тату сделаем обязательно \n\n*Глядит на Конрада доволен ли тот",191019,null],[205828,"2026-09-12T14:38:44",31,"- никогда не видел моря...",191019,null],[205832,"2026-09-12T14:39:40",11,"— Правда? Исправим!",191019,null],[205836,"2026-09-12T14:40:00",11,"— Завтра после похорон отправляемся к морю и ищем корабль!",191019,null],[205839,"2026-09-12T14:40:09",11,"— Нет, не так, ОДОЛЖИМ его?",191019,null],[205840,"2026-09-12T14:40:25",31,"- пиратом я. Тоже не бывал",191019,null],[205848,"2026-09-12T14:41:10",11,"— Ура пиратам!",191019,null],[205855,"2026-09-12T14:43:36",11,"*смотрит на Мерсо\n\n— И никаких отказов! Не заставляйте меня применять к вам магию очарования!",191019,null],[205859,"2026-09-12T14:44:40",37,"— Какая магия?",191019,null],[205868,"2026-09-12T14:46:49",37,"Мерсо начал вставать и вы заметили, что он все также в 185 см ростом очень внушителен.\n— Так, что... Могу я продолжить сидеть у матери?",191019,null],[205876,"2026-09-12T14:48:19",11,"— Злая-злая магия которая подавляет вашу волю! Не верите в магию? — Аури даёт свою книгу заклинаний невидимому слуге — видели когда-то предметы сами по себе парящие?",205859,null],[205880,"2026-09-12T14:48:31",11,"*слуга просто носит книгу туда сюда и отдаёт обратно",191019,null],[205884,"2026-09-12T14:49:40",11,"*наклоняется к остальным пока слуга книгу носит \n\n— Так что отпустим его сейчас или как?",191019,null],[205885,"2026-09-12T14:49:51",11,"// давайте тоже что-то делайте",191019,null],[205886,"2026-09-12T14:50:07",41,"( сори читаю",191019,null],[205888,"2026-09-12T14:50:17",41,"( я немного путаюсь",191019,null],[205889,"2026-09-12T14:50:37",9,"//Мне делать нечего, смотрю на ваши попытки.",191019,null],[205890,"2026-09-12T14:51:10",41,"— кажется, магию они будто бы игнорируют...",205876,null],[205893,"2026-09-12T14:52:00",9,"*На этом слове реагирует Вордо.*\n\n— Магия, таинства, сверхспособности. Мы не отсюда, мы не люди.",205859,null],[205897,"2026-09-12T14:52:33",37,"— Как? Что?\n На лице Мерсо появилось удивление и резко вы заметили смену обстановки. Вы оказались на берегу моря. Вы видели хороший пейзаж.\n Мерсо же рядом не было.\n А что случилось с книгой? Вы заметили Мерсо, что был рядом с берегом и плавал в воде, а рядом с ним стояла миловидная девушка.\n\nВы видели их в 300 футах.",191019,null],[205909,"2026-09-12T14:54:12",11,"— Что чёрт возьми..",191019,null],[205912,"2026-09-12T14:54:48",37,"Мерсо спокойно плавал на волнах, а девушка стояла и что-то говорила Мерсо.",191019,null],[205913,"2026-09-12T14:54:53",9,"*Вордо тоже удивился, и его ноги снова орустились на, теперь уже песок.*",191019,null],[205914,"2026-09-12T14:55:11",11,"*очень разочарованный вздох \n\n— Видимо мы и правда не можем никак повлиять на мир, только главный герой может, а мы с переменным успехом на него..",191019,null],[205915,"2026-09-12T14:55:22",41,"— что...что случилось",191019,null],[205918,"2026-09-12T14:55:34",9,"— Возможно история меняется в зависимости от того что хочет сделать главный герой.",205909,null],[205920,"2026-09-12T14:55:46",9,"*Кивнул в согласии.*",205914,null],[205921,"2026-09-12T14:55:54",11,"— Возможно магия очарования и правда бы помогла — вздыхает",191019,null],[205923,"2026-09-12T14:56:18",41,"— Но...а какая тогда концовка?",205914,null],[205928,"2026-09-12T14:57:14",9,"— Пытаться показать ему магию. То что за гранью этого мира, чтобы герой вышел за рамки истории или своих желаний. — *Вордо подумал над токо вероятностью, а после кивнул.* — Или просто убить, это же лишь история.",191019,null],[205929,"2026-09-12T14:57:20",11,"— Именно, дорогая, я не знаю.. это не даёт ответа на вопрос как нам выбраться..\n\nАури села на песок у моря и начала рисовать на мокрой почве пальцем дракона по которому скучает",205923,null],[205932,"2026-09-12T14:58:23",41,"— Давайте тогда Отдохнем у моря, пока все самое не закончится. А в следующий раз уже подумаем... Вдруг мы не понравится книге и она нас выплюнет?",191019,null],[205935,"2026-09-12T14:58:47",11,"— Убить? Простите, но я не способна на это, а убедить.. \n\nОтсутствие результата явно не мотивировало девушку на новые действия и она просто молча уставилась на нарисованного на песке дракончика",205928,null],[205939,"2026-09-12T14:59:33",31,"- ну, я могу это сделать, если хотите. Шею этому мужику свернуть вроде не сложно будет, не воин он...",205935,null],[205940,"2026-09-12T14:59:48",11,"// хотя можно проверить способны ли мы вообще навредить персонажам книги, но чёт да тильт какой-то, долго играем, а выхлопа 0 как будто",191019,null],[205943,"2026-09-12T15:01:02",31,"- ну так что?",191019,null],[205944,"2026-09-12T15:01:16",31,"- вдруг это и правда выход?",191019,null],[205956,"2026-09-12T15:02:57",11,"— Убить кого-то не плохого что бы выбраться самим? Это.. жестоко",191019,null],[205959,"2026-09-12T15:03:15",11,"// хз мой перс не для таких действий..\nВ этом плане да доброе мировоззрение сильно ограничивает",191019,null],[205971,"2026-09-12T15:05:06",31,"- а человек ли он?",205956,null],[205975,"2026-09-12T15:05:32",37,"// небольшой",191019,null],[205976,"2026-09-12T15:05:35",37,"// перерыв",191019,null],[206002,"2026-09-12T15:14:12",9,"//Бля, сбилось сообщение что писал(((",191019,null],[206044,"2026-09-12T15:23:12",41,"( Прости, Денис, я покидаю квест",191019,null],[206049,"2026-09-12T15:24:05",31,"А кто будет тогда речь рассказчика слушать?/",191019,null],[206055,"2026-09-12T15:24:28",37,"// А...",191019,null],[206058,"2026-09-12T15:24:46",37,"// Я только закончил искать нужную сцену...",191019,null],[206060,"2026-09-12T15:24:59",41,"( ну невозможно, прости",191019,null],[206061,"2026-09-12T15:25:11",37,"// Понятно...",206060,null],[206064,"2026-09-12T15:25:37",41,"( напишу рецензию и всё",191019,null],[206091,"2026-09-12T15:37:51",38,"——————————\n\nКвест перезапускается\n\n——————————\n\nИгроки на квесте\n— Аури https://t.me/c/3239766844/6859 @Ashenchampion \n— Ноа Викстеди https://t.me/c/3239766844/6501 @Ko11lu \n— Вордо https://t.me/c/3239766844/7247 Hard \n— Изольда https://t.me/c/3239766844/2756 Fantomas \n\nПерезапуск будет через час.",191019,null],[206094,"2026-09-12T15:38:12",37,"// Все хотят на перезапуск?",191019,null],[206097,"2026-09-12T15:38:23",31,"Меня не включай лучше, тяжело мне такое играть",191019,null],[206100,"2026-09-12T15:39:08",9,"//Могу попробовать",206094,null],[206102,"2026-09-12T15:39:21",37,"// Если не хочешь, то можешь не идти",206100,null],[206103,"2026-09-12T15:40:04",9,"//Я за любой кипишь, ты и игроки скорее смотрите сами, хотьте ли видеть тут меня и Вордо?",191019,null],[206179,"2026-09-12T15:59:01",38,"Чтож... Вас всех собрало приглашение на \"Выставку прошлого\". Вам предложили сходит и посмотреть на необычное место и узнать об эре, до Рагнорека... То, что существовало более четырехсот лет назад. Именно поэтому вас встретил мужчина, что был одет в костюм и имел темно-русые волосы.\n— Рад вас всех видеть, дамы и господа! Меня очень радует, что увидеть прошлое пришло так много человек... Прошу проходите, у нас очень уютно и интересно!\n\n// Прошу ваших персонажей представиться.",191019,null],[206185,"2026-09-12T16:01:19",8,"/10 минут, ирл/",191019,null],[206218,"2026-09-12T16:09:44",8,"–Изольда, взаимно! Я давно была увлечена старыми балладами, но мисс Аури привила мне интерес к прозе *светится от счастья, трясёт ему руку*",191019,null],[206233,"2026-09-12T16:15:04",38,"— Очень-очень рад... У нас на выставке очень много, что заинтересует каждого!\n Говорит мужчина и сказал.\n— Забыл представиться, зовите меня Читатель...",206218,null],[206238,"2026-09-12T16:17:26",8,"– Хорошо, псевдонимы всегда приемлемы) *ожидающе смотрит на остальных*",191019,null],[206313,"2026-09-12T16:43:10",9,"//С маскировкой и без. Ссылка персонажа если берёте: https://t.me/c/3239766844/7247/7264\n\n*Приглашение, али нет, но место для вордо было новое, как и мир. Поля, деревья, грязь... не то что в родном астрале, приходилось стряхивать с себя пыль, какая морока.*\n\n*В это место он пришел посмотреть на устройство мира в который попал, конечно весь обмотанный бинтами как мумия или прокажённый, но бинты чистые, так что впечатления от образа могли быть двоякие.*\n\n*Проходя между экспанатами он внимательно осматривал каждый из них.*",191019,null],[206316,"2026-09-12T16:44:35",8,"*мимолётный взгляд и мысли: опять некромант? Чересчур похож на Табулу своей загадочностью*",191019,null],[206317,"2026-09-12T16:45:03",9,"/roll 1d20+3+1d4+1d8 анализ и метамагией безмолвное указание с приемом тактической оуенки, потрачу условно тут то что тратил ранее ищем чет интересно",191019,null],[206321,"2026-09-12T16:46:12",8,"/roll 1d20+3 прохаживаясь вдоль полок, обращает внимание на даты и картинки*",191019,null],[206349,"2026-09-12T16:50:13",38,"Вы оба видите очень много картин изношенных временем и разные приписки на обрывках. Читатель поясняет.\n— Чтож... Это все картины и пейзажи прошлой эры, которую я называю старым светом ... В прошлом же эту эру называли новым светом.\n\n Мужчина указал на небольшую картину похожую на карту.\n— География немного изменилась с момента Рагнорека, но мы нашли парадокс в истории... Желаете узнать?",191019,null],[206358,"2026-09-12T16:52:33",8,"И какой же? /активно отыгрывать буду, дождавшись\n@Ashenchampion @sweetkittywitch/",191019,null],[206365,"2026-09-12T16:53:34",41,"( сори, я была чуть чуть не готова",191019,null],[206427,"2026-09-12T17:19:25",8,"– Подозреваю, парадокс магический, ибо последовательность времени относительно стабильна...",191019,null],[206434,"2026-09-12T17:21:38",41,"— Привет, Изольда!\n\n Поприветствовала Летиция, помахав полупрозрачной рукой своей знакомой с турнира.\n\n— Я так скучала по вам с Аури, рада встретиться :3",206218,null],[206436,"2026-09-12T17:21:52",41,"( ждем Джейд",191019,null],[206437,"2026-09-12T17:21:56",38,"— Хех... Вы немного правы, но и совершенно не правильно мыслите... Все упирается в парадокс наличия магии. Почему-то некоторые источники о ней не упоминают, а другие говорят о ней, как о боготворителе... Это очень сил ная проблема для меня...",206427,null],[206440,"2026-09-12T17:22:51",8,"– Может, она спала, как вулкан? *растерянно смотрит на Аури*",191019,null],[206442,"2026-09-12T17:24:44",37,"// @Ashenchampion проснись пожалуйста...",191019,null],[206446,"2026-09-12T17:27:36",37,"// Проснулась!",191019,null],[206451,"2026-09-12T17:29:18",11,"// я писала что отойду..",191019,null],[206452,"2026-09-12T17:29:40",8,"/всё ок, мы тебя ждали/",191019,null],[206461,"2026-09-12T17:34:08",11,"— Привеееет! — кричит бегущая к вам дженази — фух.. я немного перепутала время и.. фух \n\nДелает пару вдохов и выдохов, а затем выравнивается\n\n— Опоздала. Прошу прощения. Мне сказали куда подойти и я немного поплутав нашла вас! Рада видеть вас, девочки! \n\nОбнимает обоих крепко\n\n— И вас, господа.. как я могу вас называть?",191019,null],[206464,"2026-09-12T17:37:38",41,"— Аури, дорогая! Ты всё же тут и это уже хорошо)",191019,null],[206465,"2026-09-12T17:38:11",11,"— И в какой компании!",191019,null],[206468,"2026-09-12T17:38:33",8,"– Ага, и с какой темой! Нам тут Читатель интересные факты рассказывает",191019,null],[206470,"2026-09-12T17:39:28",38,"— Мистер Читатель, к вашим услугам",191019,null],[206474,"2026-09-12T17:40:24",11,"— Рада знакомству, вы наш проводник полагаю? Простите ещё раз за опоздание — сокрушалась девушка пока ее внимание не привлек странный человек в бинтах  — а вы..?",191019,null],[206481,"2026-09-12T17:43:06",9,"*Махнув рукой на старые книжки \"владелец выставки и сам не знает достоверно ли то что у него в руках\" Вордо собирался уходить с зала как к нему обратилась девушка.*\n\n— Пришел взнлянуть на выставку.",191019,null],[206482,"2026-09-12T17:43:31",9,"— Кажется здесь нет ничего особенно интересного.",206318,null],[206484,"2026-09-12T17:43:58",11,"— Вижу вы не особо впечатлены, но может составите нашей группе дам компанию?",191019,null],[206485,"2026-09-12T17:44:13",41,"— Как искусство может быть не интересным?",206482,null],[206486,"2026-09-12T17:44:17",11,"// кстати, а Вьюгу сюда пустили?",191019,null],[206488,"2026-09-12T17:44:27",8,"/я надеюсь",191019,null],[206490,"2026-09-12T17:45:39",11,"Аури присаживается к Вьюге и чешет ее за ушком\n\n— Привет, хорошая девочка, скучала по мне?",191019,null],[206494,"2026-09-12T17:46:09",8,"*Вьюга радостно и гулко гогочет в ответ*",191019,null],[206496,"2026-09-12T17:47:01",8,"– Её и без слов понятно)",191019,null],[206498,"2026-09-12T17:47:44",38,"// Да",206486,null],[206501,"2026-09-12T17:48:26",41,"( хочу тогда меркота в сумке",191019,null],[206502,"2026-09-12T17:48:27",9,"— Хм, ладно. Мы лишь видели часть выставки. — *Он поправляет плащ и слегка наигранно представляется.* — Меня зовую Уорлд (мир), для вас можно просто, Ворд.\n\n*Раз он уже пришел то нужно осмотреть всю чертовую выставку до последней мышиной норы в стене, даже если она его разочаровала на первый взгляд.*",191019,null],[206503,"2026-09-12T17:48:57",41,"( Теперь я Ворд(слово)",191019,null],[206505,"2026-09-12T17:49:39",8,"– Ваш образ тоже искусство",191019,null],[206506,"2026-09-12T17:49:57",11,"— Приятно познакомиться — девушка поднялась и искренне улыбнулась — Я - Аури Диан\n\n*И протянет руку \n\n// 😁",206502,null],[206507,"2026-09-12T17:49:59",41,"— Очень приятно. Я Летиция. Смотрите, кого принесла. \n\n\nОна развернет сумку с персидским котом ( мертвым)",191019,null],[206509,"2026-09-12T17:50:21",11,"// а он мертвый как ты или прям совсем?",206507,null],[206512,"2026-09-12T17:50:49",41,"( зомби кот",191019,null],[206514,"2026-09-12T17:51:00",11,"— О, ты таки смогла его приобрести! Помню ты давно его хотела, поздравляю, как назвала пушистика?",191019,null],[206517,"2026-09-12T17:51:21",8,"– Он дождался своей героини *руки вместе от умиления*",191019,null],[206519,"2026-09-12T17:52:14",41,"— это подарок Бенжамину))) Он выбирал ему имя вместе со мной и мы назвали его Самсон)))",191019,null],[206521,"2026-09-12T17:52:38",38,"— Вижу вы давние подруги, верно?\n Спрашивает Читатель и проведя вас к одной квартире говорит.\n— Вижу среди вас есть писатели и те, кто любят рассказывать истории, сюда уже заходил один Рассказчик... Так... Я отошёл от темы",191019,null],[206523,"2026-09-12T17:53:04",8,"/он поборол смерть/",206519,null],[206524,"2026-09-12T17:53:08",9,"*Лёгкая заминка, руку? С чего бы он должен, но Аури выглядела неплохо, исключение могло того стоять. Он взял её руку и притулил с своему подберодку что обиотан бинтами.*\n\n— Приятно с вами познакомится леди Аури. — *Он отпустил руку выполнив привычный ритуал рукоприкладства.*\n\n//Повторять сложновато ~",206506,null],[206525,"2026-09-12T17:53:14",11,"— Это так мило\n*повторяет за Изольдой жест умиления",206519,null],[206526,"2026-09-12T17:53:53",41,"— Его имя переводится как Солнышко))",206525,null],[206527,"2026-09-12T17:54:08",11,"— Взаимно\n\n// Только рукоприкладство смутило 😁 сперва подумала о другом контексте",206524,null],[206528,"2026-09-12T17:54:21",11,"— Ты знала что я спрошу хехе!",206526,null],[206529,"2026-09-12T17:54:52",8,"– Так что за парадокс?",206521,null],[206530,"2026-09-12T17:55:23",11,"— Рассказчик? А мне любопытно послушать о коллеге, расскажите",206521,null],[206532,"2026-09-12T17:55:34",41,"— я люблю читать и познавать. Это тоже интересно :3",206521,null],[206533,"2026-09-12T17:56:08",38,"— Именно поэтому я и организовал эту выставку... Я уже отправлял одну группу разведать что в этих текстах, но все обернулось плохо...",206529,null],[206534,"2026-09-12T17:56:29",38,"— Вы слышали о человеке, которого судили не за его преступлении?",191019,null],[206536,"2026-09-12T17:56:53",38,"— Или мужчине что раскололся в своих выборах, совершив убийство?",191019,null],[206537,"2026-09-12T17:57:02",41,"— это рассказ?",206534,null],[206538,"2026-09-12T17:57:13",8,"– Старая баллада рассказывала *трёт виски* Ему же вырезали сердце?",206534,null],[206541,"2026-09-12T17:57:44",38,"— Записи из прошлой эры! Вот что это! Пара из них стала рассказами как поучительными, но это были реальные люди!",206537,null],[206544,"2026-09-12T17:59:14",38,"Читатель задумался и спросил.\n— Вы же слышали о человеке, что продал душу ради знаний? Это настоящий человек из прошлой эры...",191019,null],[206546,"2026-09-12T17:59:37",11,"— Изольда, ты так много знаешь, мне точно есть чему у тебя получиться! Обязательно расскажешь мне пару историй на досуге когда мы продолжим работу над твоим тату — восхищённо протараторила Аури",191019,null],[206547,"2026-09-12T18:00:10",41,"— мне тоже интересно! Вырезать сердце, так трагично!",206546,null],[206548,"2026-09-12T18:00:26",41,"— … простите, это тоже интересно )",206544,null],[206550,"2026-09-12T18:00:45",41,"Кот мявкнул в знак согласия",191019,null],[206552,"2026-09-12T18:01:04",8,"– Обязательно. Жаль, что мои знания обрывочны. Что же до продавца души, финал его варьируется в разных легендах",191019,null],[206555,"2026-09-12T18:02:48",8,"– А в чём, собственно, дело?",191019,null],[206556,"2026-09-12T18:02:54",38,"— Так вот... Если вы хотите помочь мне узнать тайны прошлой эры, то я могу отправить вам в 14 историй! За это вы сможете забрать все что найдете и получите вознаграждение в золотых!\n Сказал Читатель",191019,null],[206558,"2026-09-12T18:03:26",38,"— Мне нужно узнать истиную правду и первопричину падения прошлой эры! Думаю там в прошлом и есть ответ",206555,null],[206559,"2026-09-12T18:03:37",41,"— а как отправить ? :0",206556,null],[206560,"2026-09-12T18:04:03",8,"– Достойная цель, но как мы заберём вещи из нематериального плана?",206558,null],[206561,"2026-09-12T18:04:03",41,"( сори, отойду поужинать",191019,null],[206562,"2026-09-12T18:04:09",11,"*Летиция сорвала первый вопрос Аури с языка, поэтому девушка решила задать второй\n\n— И какое наше будет задание?",206559,null],[206563,"2026-09-12T18:04:27",11,"// приятного ❤️",206561,null],[206564,"2026-09-12T18:04:43",41,"( спасибо:3",206563,null],[206568,"2026-09-12T18:05:34",9,"— ... — *Вордо не нравится то что он слышит, слишком странно для этого места. Отправлять в истории? Но ладно, любопытство чуточку сильнее, однажды он прыгнул ради интереса в звездные облака где куются звезды и выжил, а это звучит как лёгкая прогулка.*",206556,null],[206570,"2026-09-12T18:07:23",38,"— Я отправлю вас туда необычной книгой, что расскажет повествование о разных 14 периодах эры... Ваша же задача узнать первопричину несастыклвок магии и падения богов. Согласны?",191019,null],[206574,"2026-09-12T18:09:18",38,"— Вы можете влиять на героев и участников истории, но ваша главная задача выжить, это главное!",191019,null],[206575,"2026-09-12T18:09:21",8,"– Снова другой мир. Да, согласна на все сто",191019,null],[206576,"2026-09-12T18:10:13",9,"//Все сложилось, нам нужно было просто прожить истории и выжить",191019,null],[206578,"2026-09-12T18:10:45",11,"— Попасть в истории и изучить их изнутри? Звучит очень интересно и загадочно! — Завороженно протараторила Аури, а затем подуспокоившись добавила — Но.. как местные будут реагировать на нас? Как пока мы будем находиться там будет течь время в реальном мире? И как мы сможем вернуться обратно? У меня так много вопросов.. нельзя так просто бросаться в омут с головой \n\n*Последнее звучало немного поучительно в сторону Изольды",191019,null],[206582,"2026-09-12T18:13:05",8,"*неловко покраснела от своей вспыльчивости*",191019,null],[206585,"2026-09-12T18:13:37",11,"// а какой рост у Изольды?",191019,null],[206587,"2026-09-12T18:14:08",8,"/175",191019,null],[206589,"2026-09-12T18:14:59",11,"*коротышка тянется к твоей голове что бы погладить\n\n— Прости, не хотела тебя ругать. Просто задание звучит серьезно, нужно узнать все его аспекты пока не поздно",191019,null],[206591,"2026-09-12T18:15:18",8,"– Ты совершенно права",191019,null],[206592,"2026-09-12T18:16:05",9,"//И тут вордо 186 такой (рядом обнаруженны гномы)",191019,null],[206593,"2026-09-12T18:16:07",41,"— агась. Может есть командное слово ?",191019,null],[206594,"2026-09-12T18:16:13",11,"— Лети, Ворд, что вы скажете? Вы в деле? Если да то какие у вас есть вопросы, господа?",191019,null],[206597,"2026-09-12T18:17:35",9,"— Дорогой читатель. На сколько опасно то что вы предлагаете. — *Просто для справки, только невежды не задают вопросов.*",191019,null],[206610,"2026-09-12T18:21:57",8,"– И как мы оттуда выйдем? Я не хочу дракона, если честно",191019,null],[206612,"2026-09-12T18:22:46",11,"— Дракона? — Аури с любопытством глянула на подругу — Ты видела дракона?",191019,null],[206615,"2026-09-12T18:23:12",41,"— а может дракон будет добрый )",191019,null],[206616,"2026-09-12T18:23:16",8,"– Очень странного, маленького и безумно сильного, в ином мире",191019,null],[206617,"2026-09-12T18:23:42",11,"— Псевдодракона? Но они обычно не очень сильные — задумалась девушка",206616,null],[206618,"2026-09-12T18:23:47",38,"— Давайте по порядку",191019,null],[206619,"2026-09-12T18:23:53",8,"– Летиция тоже его заметила. Он странный",191019,null],[206620,"2026-09-12T18:24:21",11,"— О я такого знаю! А он знает очень много историй из прошлого! Правда обычно истории ему рассказываю я..",206615,null],[206621,"2026-09-12T18:24:27",41,"— да, но это был просто сон",191019,null],[206622,"2026-09-12T18:24:59",41,"— это тоже здорово! Вдруг мы найдем историю о нём ?",206620,null],[206624,"2026-09-12T18:25:20",8,"(шёпотом, чтобы не перебивать читателя) – Был бы сон, у Табулы бы тень осталась...",206621,null],[206625,"2026-09-12T18:25:47",11,"Искренний восторг в глазах\n\n— О, я представляю как бы он удивился если бы я узнала о его прошлом!",206622,null],[206626,"2026-09-12T18:26:06",38,"— Реагировать будут по разному, некоторые будут бояться, а некоторые боготворить. Я не знаю когда какие.\n— Я не знаю как будет течь время, ведь прошлая группа так и не вернулась...\n— Обратно вы вернётесь после конца истории, в этом я вас уверяю.\n— Опасность этого места не однозначна, ведь я отправил туда только пару человек и они не вернулись.",206578,null],[206629,"2026-09-12T18:26:37",38,"— К сожалению я бы и сам отправился, но я не знаю какой поток времени и что происходит, если книга без присмотра...",191019,null],[206631,"2026-09-12T18:27:30",27,"// *Отражение",206624,null],[206633,"2026-09-12T18:27:38",8,"– Магию там заметят. А она тогда спала...",191019,null],[206635,"2026-09-12T18:28:18",38,"— Я точно могу сказать, что ваша работать будет, ведь я мог отслеживать прошлую группу, но в моменте связь прервалась и оборвалась...",191019,null],[206636,"2026-09-12T18:28:25",38,"Читатель выглядел виноватым.",191019,null],[206637,"2026-09-12T18:28:35",11,"— В конце историй или истории? — уточнила девушка — Звучит это не утешительно.. заботиться о собственном пропитании и проживании нам нужно будет самим? И сможем ли мы как-то связаться с вами будучи там?",206626,null],[206640,"2026-09-12T18:29:14",8,"*надела свою стеклянно-дымчатую маску*",191019,null],[206641,"2026-09-12T18:29:14",11,"— Работает ли на том ..плане? Наше золото?",191019,null],[206642,"2026-09-12T18:29:29",11,"— Ты такая загадочная!",206640,null],[206644,"2026-09-12T18:29:47",8,"– Понадобится для маскировки",191019,null],[206646,"2026-09-12T18:30:21",38,"— Чтож... В конце историй точно есть выход, ведь я проанализировал всю книгу, а про конец одной из историй я не уверен... Про пропитание я получил отчёт, что в некоторые моменты они вообще не чувствовали голода, а иногда он был как обычно. Золото работает всегда, это валюта прошлых поколений и всегда ей будет!",206637,null],[206647,"2026-09-12T18:30:36",11,"*оглядывается на Лети \n\n— Хм.. мне нравится твоя идея, нужно тоже что-то придумать",191019,null],[206648,"2026-09-12T18:30:58",38,"— Связаться вы точно со мной не сможете, но я смогу отслеживать вас и если что-то случиться я попытаюсь вам помочь...",191019,null],[206653,"2026-09-12T18:31:22",8,"– Нам можно спорить с книгой или лучше потакать её сюжету?",191019,null],[206654,"2026-09-12T18:31:38",38,"Читатель задумался и сказал.\n— Вы сможете оставить все секреты и ответы, кроме основной двойки себе! И забрать все что там достатнете!",191019,null],[206656,"2026-09-12T18:32:02",38,"— Как я и говорил каждая история реагирует по разному",206653,null],[206660,"2026-09-12T18:32:45",41,"— ух ты!",206640,null],[206661,"2026-09-12T18:33:08",11,"— Хорошо.. условия не самые простые, но я более менее поняла. Могу ли я просить вас о подсказках к сюжету и где именно или хотя бы как нам искать ответы на ваши вопросы?",191019,null],[206666,"2026-09-12T18:34:17",38,"— Хм... Я  могу сказать фразы, которые расскажет вам книга и также где примерно будет все происходить...",206661,null],[206668,"2026-09-12T18:34:41",38,"— Вы можете делать и искать информацию как умеете, мне нужны любые зацепки",191019,null],[206670,"2026-09-12T18:35:20",8,"– Хорошо, какая история начинает цепочку? *вдумчиво*",206666,null],[206671,"2026-09-12T18:35:56",11,"— Это слишком растяжимое понятие, нужны хоть какие-то зацепки. Например нужно ли искать ответы вокруг главных героев событий или нет?",206668,null],[206674,"2026-09-12T18:36:42",41,"— а прошлая группа выбралась ?",191019,null],[206675,"2026-09-12T18:36:44",11,"— А насчёт этого.. вы можете просто дать нам книгу с сюжетом? Ну или я могла бы переписать его сама",206666,null],[206698,"2026-09-12T18:47:16",9,"— Тоесть, необходимо наблюдать за происходящим и документировать. Преимущественно то что не упоминалось в самих книгах чтобы вытащить как можно больше информации которую вы сами не можете прочитать на страницах произведений копии или оригиналы которых у вас храняться. — *Коротко подытожил Вордо, он в таком еще не учавствовал.* — Это достаточно интересно. Я лишь попрошу, вы заинтересованны исключительно в информации?",206668,null],[206701,"2026-09-12T18:48:56",11,"— Вести запись я могу, возможно это пригодится! Скажите в каком формате вы бы хотели видеть отчёт? Я предпочитаю формат рассказов, но такой у вас и так есть на столе — девушка поправила воображаемые очки",191019,null],[206705,"2026-09-12T18:50:27",38,"// Подождите немного я тут ищу переписываю кое-что",191019,null],[206844,"2026-09-12T19:33:51",38,"Читатель отошёл к одной клетке под занавеской и достал от туда книгу, даже скорее гримуар, которая сочила из-за странное чувство знаний и веса на разум.\n Мужчина сказал.\n— Я заинтересован именно в причинах различий вопроса о магии и вопроса смерти богов... Также вот и сама книга...\n Книга имела странный белый отсвет и имела странную надпись на языке, который никто из вас не мог понять.\n— По поводу фраз... Книга будет говорить их каждый раз, но я все равно их назову... \"Взлететь, взлететь, взлететь… Взлететь еще раз! Вот бы взлететь еще раз!\", \"Сегодня умерла мама. Или, может, вчера, не знаю\", \"Лучше ошибаться по-своему, чем быть правым по-чужому\", \"Кэтрин Эрншо, не знай покоя, пока я жив! Будь со мной всегда, прими любой облик, сведи меня с ума!\", \"Я ведь всего только и хотел попытаться жить тем, что само рвалось из меня наружу. Почему же это было так трудно?\", \"Когда Грегор Замза однажды утром проснулся от беспокойных снов, он обнаружил, что превратился в своей постели в гигантское насекомое\", \"Правда становится вымыслом, когда вымысел правдив\", \"Этого нет ни на одной карте; настоящих мест на них никогда не бывает\", \"Алчные души людей, проклятая золота жажда!\", \"Только те, кто видел ад, могут нарисовать его по настоящему\", \"Презри разум и знание, высочайшие из всех людских способностей, — и ты окончательно в руках дьявола\", \"Когда сама жизнь кажется безумной, кто знает, где таится истинное безумие?\", \"Никто, это мое имя\", \"Оставь надежду, всяк сюда входящий\"... Пока что это все фразы...\n Читатель положил книгу на специальный стол.\n— Мне будет полезна информация и из самих книг, ведь тут все написано на языке который даже я не знаю... Если вам не затруднит, то за это я дополнительно заплачу.\n Читатель указал на другие книги на полке рядом.\n— Хоть это и оригиналы, но они очень сильно изменены и приукрашены... Поэтому прошу все же писать все что видите... И ищите ответы желательно вокруг героев.",191019,null],[206845,"2026-09-12T19:34:01",38,"// Текст под спойлером вы не услышали, но пропустили мимо ушей...",191019,null],[206848,"2026-09-12T19:34:19",38,"// Короче там простое лицо и обращение",191019,null],[206851,"2026-09-12T19:35:53",38,"// Это было долго",191019,null],[206852,"2026-09-12T19:36:05",38,"// У меня просто нету пары исходников прямо на руках и пришлось искать в интернете",191019,null],[206855,"2026-09-12T19:37:08",8,"/только три цитаты вспомнила/",206852,null],[206857,"2026-09-12T19:37:24",38,"// Это тоже хорошо",206855,null],[206863,"2026-09-12T19:39:12",8,"– Это занятно. Я думаю, что готова /ждём остальных, мб уточнения/",191019,null],[206864,"2026-09-12T19:40:26",38,"— Точно... Если вы будете видеть бабочек, то прошу попытаться узнать их настоящую природу, потому что последнее что мне сообщила прошлая группа было \"Бабочки\"...",191019,null],[206866,"2026-09-12T19:41:17",8,"– Символ греха, понятно. Или иной смысл",191019,null],[206867,"2026-09-12T19:42:01",11,"— Хорошо, я могу вести запись событий в любом удобном для вас формате, если документальном то тоже.. \n\n// Честно говоря не уверена что будет интересно просто пересказывать сюжет книги, так что надеюсь мы как-то сможем на него повлиять и изменить или узнаем больше чем в сюжете хотя бы",191019,null],[206868,"2026-09-12T19:42:17",9,"*Читатель будто слишком увлечен собой поэтому Вордо не стал задавать лишних вопросов из за этого. Вряд-ли ему скажут что-то полезное.*\n\n— Показывайте книги.",191019,null],[206870,"2026-09-12T19:43:57",38,"— Тут только одна книга и это она... Когда вы откроете её вас отправит в первый отрывок времени и вы можете услышать голос в голове, что начнет повествование.\n Сказал Читатель.",191019,null],[206872,"2026-09-12T19:43:59",11,"— Могу я у вас попросить кое-что? Я владею одним заклинанием что возможно пригодится на задании, но мне не хватает денег на материальный компонент для его исполнения.. Можете вычесть это из моего гонорара если получится его достать \n\n// Камушек для опознания",191019,null],[206877,"2026-09-12T19:45:09",38,"— Ох... Конечно, у меня тут такого полно...\n Читатель зашёл за одну полку и достал нужный камень.\n— Держите...",206872,null],[206879,"2026-09-12T19:46:05",11,"— Благодарю! Постараюсь быть полезной. — девушка осмотрела камушек и довольная спрятала его в сумку — у меня больше нет вопросов, что на счёт остальных?",191019,null],[206881,"2026-09-12T19:46:11",9,"//Я лишь надеюсь что произойдёт событие за коророе модно будет зацепиться и не отынрывать таинственного нещнакомца, прошлый раз почти вышло)",191019,null],[206882,"2026-09-12T19:46:26",9,"*Кивнул.*",206879,null],[206883,"2026-09-12T19:46:43",8,"– У матросов нет вопросов! *отдала честь* *наконец-то в путь, она явно заждалась*",191019,null],[206886,"2026-09-12T19:47:36",11,"*хихикнула и подумала о том что Изольда милашка",206883,null],[206887,"2026-09-12T19:48:10",11,"// повторю вопрос мастеру, на счёт прошлой экспы, ее откатить?",191019,null],[206890,"2026-09-12T19:49:40",41,"— она так веет волшебством... Я думаю, мы готовы",206870,null],[206893,"2026-09-12T19:49:54",41,"( а на вопрос про группу ответили?",191019,null],[206904,"2026-09-12T19:53:23",38,"// Какой вопрос, отметь пожалуйста",206893,null],[206906,"2026-09-12T19:53:42",38,"// Да, я же ответил",206887,null],[206909,"2026-09-12T19:54:03",41,".",206674,null],[206913,"2026-09-12T19:54:59",38,"Читатель мрачно покачал головой и ответил.\n— Никто... Либо они все ещё там и зашли очень глубоко, либо они и вправду не справились...",206674,null],[206921,"2026-09-12T19:55:53",41,"— как же так. Зачем вы тогда такое предлагаете как аттракцион?",206913,null],[206923,"2026-09-12T19:56:54",11,"— Это ведь работа, Лети.. я постараюсь позаботиться о вас — девушка приобнимет подругу одобряюще",191019,null],[206927,"2026-09-12T19:57:23",41,"Лети обнимает её в ответ",206923,null],[206930,"2026-09-12T19:57:47",41,"— хорошо. Я тебя туда сама не пущу, только со мной!",191019,null],[206931,"2026-09-12T19:57:55",38,"— Я пригласил много кого, наемников, рыцарей, приключенцев и много кого ещё, но все они отказались...",206921,null],[206932,"2026-09-12T19:58:07",11,"— Ты такая заботливая \u003c3",206930,null],[206936,"2026-09-12T19:58:47",41,"Обнимает \n\n— Как давно отправились прошлые? Может они застряли?",206932,null],[206938,"2026-09-12T19:59:25",38,"— Прошло уже больше недели с момента отправки прошлой группы...",206936,null],[206942,"2026-09-12T19:59:49",41,"— Значит не всё потеряно",206938,null],[206947,"2026-09-12T20:01:57",38,"— Чтож... Если это все, то в в готовы...\n Читатель начал расстёгивать ремни на книге и та начала дёргаться.",191019,null],[206949,"2026-09-12T20:03:02",11,"*Изольду тоже за руку возьмёт",191019,null],[206950,"2026-09-12T20:03:32",41,"Кот залезет вам на плечи",191019,null],[206951,"2026-09-12T20:03:42",8,"*берётся крепко в ответ, держа при этом Вьюгу за холку*",206949,null],[206967,"2026-09-12T20:06:58",9,"*Пока молча подходит ближе, бесстрашно откинув плащ, эта книга его достаточно сильно заинтересовала, прошлые не дёргались сами по себе.*",191019,null],[206968,"2026-09-12T20:07:08",38,"— Тогда... Желаю удачи...\nЧитатель раскрывает книгу и вас озаряет очень яркий свет. Отойдя от него вы обнаруживаете себя в городе... Только он весь был выполнен из камня, а вокруг было много людей, что ходили по каменным дорогам. Также были кареты без лошадей... В прошлом все было так технологично?\nВы же услышали голос, странный из многих интонаций и форм. Будто говорило много голосов в унисон.\n— Слышали, \"о гении, который стал чучелом\"? Я рад. Иногда даже любовь приносит радость...\n Вы также могли отметить высоту зданий вышел чем 4 этажа каждая.",191019,null],[206971,"2026-09-12T20:07:51",8,"– Как неуютно *поёжилась*",191019,null],[206976,"2026-09-12T20:08:32",41,"— Ой, ой! Невидимые лошади! \n\nПодумала Летиция",191019,null],[206978,"2026-09-12T20:08:43",11,"— Очень необычно, согласна! Непривычно, но у нас получится \n\n*Осматривается по сторонам в поисках чего либо примечательного и может тех самых бабочек",206971,null],[206981,"2026-09-12T20:09:19",11,"— Вдруг это что-то вроде моих невидимых слуг! Ты такая умная, Лети! Отличное использование магии стоит заметить!",206976,null],[206982,"2026-09-12T20:09:43",38,"// На этом предлагаю закончить, мне нужно будет подготовить материал теперь и вместе с этим мне надо идти. Пока что перезапуск идёт лучше, чем до него.",191019,null],[206983,"2026-09-12T20:09:46",11,"// а, подумала😅",191019,null],[206986,"2026-09-12T20:09:51",41,"Летиция направляет кота чтоб он искал\n\n— Смотри! Ты охотник на бабочек!",191019,null],[206987,"2026-09-12T20:10:04",41,"(?",206983,null],[206989,"2026-09-12T20:10:25",11,"// я об этом, это в голове или озвучила",206976,null],[206991,"2026-09-12T20:10:43",11,"// да, приятно получать ответы на вопросы, надеюсь дальше динамику не потеряем",206982,null],[206993,"2026-09-12T20:10:51",41,"( озвучила",206989,null],[206996,"2026-09-12T20:11:37",41,"— Спасибо, это так...догадка)",206981,null],[207001,"2026-09-12T20:12:39",11,"// Аури верит в это",191019,null],[207007,"2026-09-12T20:13:45",41,"( тебе кот помогает искать бабочек",191019,null],[207012,"2026-09-12T20:15:00",9,"*Магия движет этим местом или нет, Вордо не мог проверить (тупо обнарудения магии нет). Он видел подобные места, в видениях прошлого своего народа, в трансе, но никогда лично. Подошел к зданию и трогает стены.*",191019,null],[207044,"2026-09-12T20:24:57",41,"— Господин Ворд, что вы делаете ?",207012,null],[207714,"2026-09-12T23:50:13",8,"*Изольда пытается понять местные нравы и женские облики, манеру речи* /в общем, характер толпы, заявка такая/",191019,null],[207739,"2026-09-13T00:14:02",9,"— Габлюдать некоторые вещи лично совсем другие ощущения чем в видениях или представляя. — *Ну и эльфы не видят сны, немного тяжело выдумывать праобразы самому себе пока другие расы просто спят чуть дольше и чуть крепче при этом видят сны.*",207044,null],[207742,"2026-09-13T00:17:14",11,"// технически эльфы могут спать нормально, сон аль транс решать тебе",191019,null],[207743,"2026-09-13T00:19:34",9,"//Вроде нет? Хм",191019,null],[207905,"2026-09-13T10:04:10",8,"/я готова, напишите, как время будет/",191019,null],[207907,"2026-09-13T10:05:47",38,"// начнем, когда я закончу с картошкой. У меня тут сейчас будет её сбор",191019,null],[207908,"2026-09-13T10:06:07",38,"// хотя можно продолжить и сейчас, просто потом я отойду",191019,null],[207909,"2026-09-13T10:17:25",38,"// Fantomas Hard @Ashenchampion @sweetkittywitch все смогут через 15 минут?",191019,null],[207910,"2026-09-13T10:17:39",9,"// Постараюсь",191019,null],[207912,"2026-09-13T10:35:01",38,"Стены были очень гладкими и имели разделение, как кирпичи в некоторых замках и дворах.\n Девушки что проходили вокруг были разных нарядов, но в основном они имели очень мало элементов украшений. Только рубашку, брюки или юбку и поверх рубашки пиджак или что-то похожее.\n Поведение девушек же было очень разным. Дамы ходили со строгой элегантностью, а молодые девушки хихикали друг с другом.\n Вместе с этим вы услышали продолжение голоса в голове.\n— Пусть тело мое дрожит от усталости, зато душа сияет, как серебряная монета. Когда никотин проникает в мой полный паразитов желудок, в голове разворачивается чистый лист бумаги. И я размещаю на нем свои мысли и афоризмы, словно расставляю шашки для игры в падук. Ненавистная болезнь разума.\nЯ планирую свою жизнь с женщиной. Неумелой в любви, но постигшей высший смысл, - свихнувшейся, другими словами. В смысле, планирую жизнь, в которой владею хотя бы половиной такой женщины, - половиной всего. Заглянув хотя бы одним глазком в эту жизнь, улыбаться друг другу в лицо, словно два солнца. Должно быть, меня невыносимо утомило все человечество. Гуд бай!",191019,null],[207913,"2026-09-13T10:35:21",38,"// Сорян за удаление, просто что-то не то с сообщением",191019,null],[207914,"2026-09-13T10:36:17",8,"*Изольда пока не припоминает эту легенду, но атмосфера с весёлыми девушками ей даже начинает нравиться. Она маскировкой меняется: человеческие уши, рубашка со звёздной брошью, фиолетовая юбка*\n– Попробую немного обжиться здесь *жизнерадостно*",191019,null],[207915,"2026-09-13T10:38:42",8,"/метагеймить и лезть в интернет не буду, попробую вспомнить по ходу сюжета/",191019,null],[207916,"2026-09-13T10:39:22",9,"— Кто-то хочет покончить с собой. Вы тоже слышали этот голос? — *Вернувшись от созерцания стен Вордо осмотрелся по сторонам, а потом, на крышу?*\n\n//Я вообще не читал ничего и не буду пока что, какой метагейм 😂👍",191019,null],[207917,"2026-09-13T10:40:34",8,"– Его надо остановить, это же глупо!",207916,null],[207918,"2026-09-13T10:40:44",9,"*Голос в голове точно вещал не просто так, подсказка от читателя или \"приём обсуждения происходящего от лица расказчика\" в литературе.*",207916,null],[207919,"2026-09-13T10:41:04",38,"// скажу то, что эта одна из самых не популярных и известных книг в списке",207915,null],[207920,"2026-09-13T10:41:20",8,"/а я нишевый лох",207919,null],[207921,"2026-09-13T10:41:29",38,"// я тоже",191019,null],[207922,"2026-09-13T10:42:22",9,"//Я смотрю на верх в поисках не на крыше ли самоубийца + мы ждем элю и джейд, без них не хочу играть, пати так пати",191019,null],[207923,"2026-09-13T10:42:24",38,"На крышах никого не было, только птицы летали между них и ты заметил очень много разных ниток? Они были черными.",207916,null],[207926,"2026-09-13T10:45:57",8,"/Моя заявка: вглядываюсь в окона, ища людей, у которых тоскливый взгляд. /ждём остальных//",191019,null],[207930,"2026-09-13T10:51:24",38,"На удивление тут очень много стеклянных окон на каждом этаже и они ещё и широкие.\n Ты замечаешь, что атмосфера здесь скорее угнетающая, а не тоскливая. Мужчины со спокойным выражением что-то делали, а девушки также работали, но общались между собой.\n Сейчас был полдень и похоже час пик работы.",207926,null],[207932,"2026-09-13T10:53:48",8,"/окей, у меня есть наитие про су@ника, упавшего на забор, но могу ошибаться, троп частый. Ждём ещё двух/",191019,null],[207937,"2026-09-13T11:00:59",41,"Летиция остолбенела на секунду, будто вся атмосфера быта потеряла для неё смысл. \n\n— Вы правы… что же нам… делать?",207916,null],[207938,"2026-09-13T11:03:08",9,"— Он курит. А ещё. — *Вордо тянется рукой к нитям, далеко они или нет, сможет дотянутся ухватить или нет, суорее пытается показать другим.* — Черные нити.",191019,null],[207942,"2026-09-13T11:04:38",8,"*щёлкнуло в голове, и, проверяя своё наитие, Изольда бежит к ближайшей девушке*\n– Мисс, здравствуйте. Должно быть, у меня амнезия или что-то в этом роде. Один лишь вопрос: была ли сейчас большая война?",191019,null],[207947,"2026-09-13T11:06:28",38,"— Война? Их много в мире происходит. Последняя была около 20 лет назад, а что?\n Ответила девушка, что похоже уже работала.",207942,null],[207950,"2026-09-13T11:07:30",8,"– Не то, не то... *уходит* /до Аури заявок у меня не будет/",191019,null],[208231,"2026-09-13T13:10:39",11,"Дженази тоже с любопытством оглядывается по сторонам, оценивает насколько здесь отличается не только местность, но и обитатели: их внешность, их язык. Обратив внимание что Изольда разговаривает с ними на общем немного успокоилась\n\n— Так, господа зеваки — подзывая всех к себе говорит она — что высмотрели? Судя по всему.. вы ведь тоже слышали голос, верно? Так вот. Наша задача найти курящего парня который хочет совершить самоубийство.. а ещё я предлагаю найти ему ту самую любовь которую он ищет! Хехе.",191019,null],[208249,"2026-09-13T13:15:14",9,"— Вы решили побыть свахой леди Аури. — *Не спрашивал, не утверждал.*",208231,null],[208252,"2026-09-13T13:16:22",11,"— А почему бы и нет? Если это остановит его от самоубийства стоит попытаться!",191019,null],[208284,"2026-09-13T13:25:38",8,"*вернувшаяся от собеседницы Изольда кивает*\n– Впрочем, надо ещё предложить ему смысл жизни. Без глобального не будет частного, не так ли?",191019,null],[208291,"2026-09-13T13:26:54",11,"— Это слишком философский вопрос, дорогая, возможно тех кто ищет его это может только больше вогнать в апатию..",191019,null],[208294,"2026-09-13T13:27:46",8,"– Я просто боюсь, что любовь может оказаться временной. Иногда нужна подпорка вечная",191019,null],[208299,"2026-09-13T13:28:54",11,"— Бууу, какая ты пессимистичная, тогда какой у тебя план?",191019,null],[208300,"2026-09-13T13:28:57",9,"— Смысл жизни в том что его нет. Смысл в существовании равен существованию, жить необходимо для того чтобы жить. — *Вордо выуживал из памяти обрывки фраз прежде чем сказать.* — Нет цели, лишь путь, и ты не самурай.",191019,null],[208306,"2026-09-13T13:29:36",8,"– Никто не мешает тебе быть самураем в душе!)",191019,null],[208308,"2026-09-13T13:29:42",9,"*Ему этот мир абсолютно понятен, смысл в этом мгновении, сейчас, когда ты живёшь.*",191019,null],[208311,"2026-09-13T13:29:56",38,"Голос же продолжил говорить.\n— Гуд бай! Есть какая-то ирония в том, что порой жадно поглощаешь самые нелюбимые блюда. Мысли и афоризмы…",191019,null],[208317,"2026-09-13T13:30:47",11,"*скептически смотрит",208300,null],[208318,"2026-09-13T13:30:49",9,"— Это лишь один из способов. Но мы все еще ищем человека, разделимся?",208306,null],[208322,"2026-09-13T13:31:14",11,"— А что если мы потеряемся? Местность то неизвестная всем нам полагаю..",191019,null],[208324,"2026-09-13T13:31:38",8,"– Обычно это плохая затея *неловко*\nА его надо отучить есть нелюбимое. И брать только лучшее)",208318,null],[208325,"2026-09-13T13:31:49",9,"//Я очень долго над этим думал в реале, это мой ответ, так вижу ^^",208317,null],[208327,"2026-09-13T13:31:56",11,"— Может он ест сейчас раз думает о еде?",191019,null],[208330,"2026-09-13T13:31:58",41,"— может нам стоит спросить в кафе про какого-нибудь постоянника?",208311,null],[208334,"2026-09-13T13:32:16",11,"// это ответ персонажа, не мой",208325,null],[208336,"2026-09-13T13:32:37",41,"Кот забрался на плечи Летиции\n\n— Самсон тоже голоден)",191019,null],[208337,"2026-09-13T13:32:38",8,"– Твой разум поражает, дельная идея",208330,null],[208338,"2026-09-13T13:32:50",11,"— Думаю их там много, но не попробуем не узнаем, вдруг мы сразу поймём кто это как увидим.. есть здесь лавки с едой? \n\nОглядывается по сторонам в поисках",208330,null],[208339,"2026-09-13T13:33:04",38,"Голос все равно продолжал говорить. Выражая эмоции и все детали из своего странного голоса.\n— Попробуйте и вы подделать самого себя. Ваше творение окажется подобающе возвышенным, в соответствии с образцом, которого никто ни разу не видел.",191019,null],[208340,"2026-09-13T13:33:20",38,"Очень много разных заведений вдоль улиц",208338,null],[208342,"2026-09-13T13:33:27",41,"— Хехе, спасибо. Думаю искать стоит не дорогую лавку",208337,null],[208343,"2026-09-13T13:33:45",8,"– Где тихо и уютно, думаю",191019,null],[208345,"2026-09-13T13:34:06",41,"— у них тут больше таверн чем у нас, Ух ты...",191019,null],[208347,"2026-09-13T13:34:28",8,"/две на континент)",208345,null],[208348,"2026-09-13T13:34:38",11,"— Очень много.. и где же искать?\n\n*движется к ближайшей и заглядывает в окнах в поисках кого-то \"особенного\"",191019,null],[208351,"2026-09-13T13:34:48",41,"— да, Давайте проследим за его эстетикой... Серебрянная монета, паразиты, женщина...",208343,null],[208354,"2026-09-13T13:35:27",38,"Все в окнах выглядят похожими друг на друга. Черные волосы у всех людей, одинаковый цвет кожи и даже одинаковый вид.",208348,null],[208355,"2026-09-13T13:35:29",9,"//Можно заявку? Попытаться по поведению и голосу в голове сложить автопортрет того кто говорит проверкой анализа?",191019,null],[208356,"2026-09-13T13:35:31",11,"— Эм.. вам это что-то говорит?",208351,null],[208358,"2026-09-13T13:35:47",11,"— Ребят, а вас не смущает что все здесь.. одинаковые люди?",208354,null],[208360,"2026-09-13T13:36:09",9,"//Типа, скорей всего на что больше должен быть похож человек с такими мыслями",208355,null],[208361,"2026-09-13T13:36:12",38,"// Да, анализ",208355,null],[208362,"2026-09-13T13:36:13",11,"— При этом — показывает на тех кто ходит вокруг — мы их не смущаем",191019,null],[208363,"2026-09-13T13:36:17",8,"– Игра в чужого себя, которая стала портить настоящее",208351,null],[208365,"2026-09-13T13:36:28",41,"— Может это название дешевого кафе, очень похоже",191019,null],[208366,"2026-09-13T13:36:43",41,"— Погодите, что?",208358,null],[208367,"2026-09-13T13:36:52",41,"Она осмотрится",191019,null],[208372,"2026-09-13T13:38:08",9,"*Проходя меж кофеен, ища отличия в лицах, Вордо смотрит на иходежду, мелкие детали, чтобы составить отличия людей и подметить хотя бы пару деталей в уме что должны были бы принадлежать говорящему человеку, кроме следов курения на коже.*",208361,null],[208376,"2026-09-13T13:38:33",9,"/roll 1d20+3+1d8 тактическая оценкс без указания, некогда",191019,null],[208378,"2026-09-13T13:38:44",38,"Голос же продолжал свой рассказ, его интонация начала становится более человеческой и понятной. Вы смогли отличить, что говорит мужчина молодых лет.\n— Избавьтесь от пережитков девятнадцатого века, если сможете. Так называемый дух Достоевского почти утрачен. Похоже, прав был тот, кто бы это ни был, кто назвал Гюго «куском французской булки». Детали помогут вам отличить настоящую жизнь от подделки, ведь правда? Не сердитесь. Я вынужден предупредить…\n(Пусть пойдет кровь. Я верю, что рана вскоре затянется. Гуд бай!)\n\n// Скрытый текст вы слышали, но там простое лицо. В скобочках похоже на шепот.",191019,null],[208382,"2026-09-13T13:39:14",38,"Ты отмечаешь, что человек должен вести образ жизни не похожий на общественный.",208376,null],[208385,"2026-09-13T13:39:52",41,"( а люди все одинаковые?",191019,null],[208386,"2026-09-13T13:40:08",8,"/ищем замаскированного отшельника, получается/",191019,null],[208387,"2026-09-13T13:40:08",38,"// они просто похожи друг на друга. Как азиат на азиата",208385,null],[208389,"2026-09-13T13:40:14",9,"— Возможно нам нужно искать бездомного...",208382,null],[208393,"2026-09-13T13:40:36",41,"— вроде разница есть, но минимальная...",191019,null],[208395,"2026-09-13T13:40:59",11,"// я о том что раса одна",191019,null],[208401,"2026-09-13T13:41:41",9,"— Это история. Похоже она идет своим чередом.",208362,null],[208402,"2026-09-13T13:41:42",8,"*Изольда ищет кого-то с максимально неподвижным лицом. Должно быть, его маска крепко приросла к телу*",191019,null],[208403,"2026-09-13T13:41:55",11,"— ..? Ну, стоит попытаться.. — говорит Аури, а затем замирает — погодите.. есть у меня идея",208389,null],[208406,"2026-09-13T13:43:00",11,"— Людей здесь и правда много, тяжело будет найти нужного человека, но ведь мы можем заставить его найти нас? Что если попытаться привлечь внимание к нам? Тем что его беспокоит например? Произнести тираду о смысле жизни и предложить консультацию?",191019,null],[208407,"2026-09-13T13:43:02",9,"//У меня тоже, го сначала ты)",191019,null],[208410,"2026-09-13T13:43:47",11,"— У Изольды отлично получается привлекать публику своим выступлением хехе",191019,null],[208412,"2026-09-13T13:43:56",38,"Голос уже был похож на полноценный голос мужчины молодых лет и довольно открытой душой.\n— Чувства - лишь поза. (Я обращаю внимание только на некоторые детали.)\nЕсли поза не меняется, источник чувств иссякает. С высоты своего прогресса я по-другому смотрю на мир.\nПчеломатки и вдовы - кто среди многочисленных женщин мира не остался, по существу, вдовой? Нет таких. Я, наверное, оскорбил женщин своими соображениями. Я не хотел. Гуд бай!",191019,null],[208413,"2026-09-13T13:44:00",9,"— Говорить громко те же слова которые мы слышим от него. Посмотреть кто среагирует?",208406,null],[208414,"2026-09-13T13:44:21",38,"Таковых ты не находишь на улице и в зданиях пока вы идете.",208402,null],[208417,"2026-09-13T13:44:46",41,"( тогда для Летиции они просто все белые",208395,null],[208418,"2026-09-13T13:45:06",8,"– Привлечь любой необычностью. Он явно устал от однообразности",208406,null],[208419,"2026-09-13T13:45:08",11,"— Как вариант!",208413,null],[208423,"2026-09-13T13:45:57",11,"— Тогда он бы сам вышел на нас. Только посмотри на меня и ребят — пожимает плечами — боюсь не всё что есть в нашем репертуаре влияет на окружение так что идея господина Вордо мне по душе",208418,null],[208424,"2026-09-13T13:46:02",41,"— Если мы никого еще не напугаем. Наша неосторожность до добра не доведет",191019,null],[208429,"2026-09-13T13:46:10",11,"*Аури начинает выкрикивать услышанные в голове фразы",191019,null],[208432,"2026-09-13T13:46:26",8,"– Тогда повторим слова?",208423,null],[208436,"2026-09-13T13:46:42",41,"— Погоди, Аури!",191019,null],[208440,"2026-09-13T13:47:18",38,"Пару человек остановилась и один из них сказал.\n— Ох... Я уже слышал слова про гения - чучело",208429,null],[208442,"2026-09-13T13:47:20",41,"— А если мы тоже невидимки? Посмотрите, мы же совершенно на них не похожи. А Никто он подошел",191019,null],[208443,"2026-09-13T13:47:32",11,"// подошли",191019,null],[208445,"2026-09-13T13:47:34",41,"— Ладно, Может и неи",208440,null],[208446,"2026-09-13T13:47:48",8,"*подошла к нему*",191019,null],[208447,"2026-09-13T13:47:50",41,"— Погодите, что за гений?",191019,null],[208449,"2026-09-13T13:47:54",11,"— О, вам знакомы эти слова? Вы случаем не знаете кому они принадлежат?",208440,null],[208472,"2026-09-13T13:51:15",38,"— Хм... Если мне не изменяет память, то я услышал это от одной дамы в доме 33. Он дальше по главной улице и сверните в переулок номер 4. Так вы пойдете до девушки, что говор да это.",191019,null],[208475,"2026-09-13T13:52:11",8,"– Мило. Можете заодно сказать, как выглядит эта девушка *указываю на Аури*? Ужасно болит голова, знаете ли",191019,null],[208476,"2026-09-13T13:52:47",9,"— Это место немного крохотное, так? Все друг друга знают. Как вас зовут. — *Вопросы чтобы кое что проверить.*",208472,null],[208477,"2026-09-13T13:53:07",8,"/мб маскировка автоматом/",191019,null],[208478,"2026-09-13T13:53:44",38,"— Ох... У вас довольно необычная внешность, вы из Европы? Там вроде магия все ещё сохранилась...\n Мужчина посмотрел на часы и сказал.\n— Меня зовут #### #####.",191019,null],[208479,"2026-09-13T13:54:01",38,"— На этом прошу меня простить мне нужно идти...",191019,null],[208480,"2026-09-13T13:54:13",11,"— А что не так с магией здесь? Да-да, мы приезжие, именно оттуда",191019,null],[208481,"2026-09-13T13:54:20",11,"— ох..",208479,null],[208482,"2026-09-13T13:54:24",9,"— Хорошего дня. — *Отмахнклся от него.*",208479,null],[208484,"2026-09-13T13:54:51",11,"— Ребята, кто-то понял как называлось то место? Я не расслышала.. но кажется это именно то что мы ищем? Я имею ввиду по заданию",191019,null],[208491,"2026-09-13T13:55:54",38,"Голос Рассказчика продолжал.\n— Дом номер тридцать три по планировке напоминает публичный дом.\nВосемнадцать квартир дома выстроились плечом к плечу, с одинаковыми окнами и дверями, одинаковыми печками. Да и люди, живущие в этих квартирах, все как один молоды, словно бутоны цветов. Солнце не заглядывает сюда. Потому что люди делают вид, будто знать не знают о солнце. Натягивают перед дверями веревки и, притворяясь, что им нужно развесить и подсушить заляпанные постели, преграждают солнцу путь.",191019,null],[208492,"2026-09-13T13:56:01",8,"– Нам дальше по главной улице в переулок. Может, эта дама – его друг или возлюбленная",191019,null],[208495,"2026-09-13T13:56:23",9,"— Не слышал. Но мы можем спрашивать о нём через коственные признаки, как наличие магии.",191019,null],[208498,"2026-09-13T13:57:30",11,"*кивок\n\n— Может нам нужно будет отправиться туда..",208495,null],[208503,"2026-09-13T13:58:17",8,"– В случаях подобных настроений лучше поспешить...",191019,null],[208506,"2026-09-13T13:58:39",9,"— Мы всё ещё в книге. Возможно мир за пределами этого места существует лишь на словах.",208498,null],[208508,"2026-09-13T13:59:22",11,"— Ладно, вы правы, пойдём искать героя..",191019,null],[208511,"2026-09-13T14:00:13",9,"//Идем куда нибудь, по коственным признакам можно быть смелее...",191019,null],[208521,"2026-09-13T14:01:37",11,"// угу ищем нужный дом",191019,null],[208528,"2026-09-13T14:02:39",38,"Пока вы шли в сторону, которую указал мужчина вы слышали продолжение голоса.\n— Спят днем в темных комнатах. Ночью, что ли, не могут выспаться? Не знаю. Откуда мне знать, если я сам сплю день и ночь напролет. Днем в восемнадцати квартирах тридцать третьего совсем тихо.\nНо тихо только днем. На закате они снимают свои постели. Зажигается электрический свет, и в электрическом свете восемнадцать квартир смотрятся куда веселее, чем днем. Допоздна раздается шум то открываемых, то закрываемых дверей. Становится все оживленнее. Появляются разные запахи. Запах жареной селедки, запах косметики, воды из-под мытого риса, запах мыла…",191019,null],[208533,"2026-09-13T14:04:20",11,"— Судя по тому что мы слышим найти нужного человека мы сможем если дождёмся ночи и определим какая из квартир все ещё спит?",191019,null],[208536,"2026-09-13T14:05:00",41,"Самсон увидеть на одном из окон горсть сушащейся рыбы и стырил одну селедку. \n\nВпитывая её в себя и идея рядом с Летицией",191019,null],[208540,"2026-09-13T14:05:18",41,"— Ты молодец, хороший план!",208533,null],[208542,"2026-09-13T14:05:31",8,"– Тогда надо найти дом и караулить под окнами, как верные собаки *её рассмешила подобная ситуация*",191019,null],[208543,"2026-09-13T14:05:53",41,"— Вьюга нас научит)",191019,null],[208544,"2026-09-13T14:06:07",9,"//Точно, волк ржет?)",191019,null],[208546,"2026-09-13T14:06:46",8,"– Точно. *волк вторит хозяйке* Только бы он не свалил в мир иной раньше ночи",191019,null],[208554,"2026-09-13T14:08:01",11,"— Ну судя по повествованию он должен спать..?",191019,null],[208559,"2026-09-13T14:08:44",8,"– Проблема в том, что спящие не говорят...",191019,null],[208561,"2026-09-13T14:08:56",41,"— может это его сон?",208559,null],[208570,"2026-09-13T14:10:12",38,"Вот вы и увидели дом, о котором говорили и рассказчик и мужчина.\n Так же и имел тоже описание, которое вы и слышали.\nГолос Рассказчика продолжал.\n— Но вот видя таблички на дверях, остается только головой покачать. Створка ворот, где перечислены имена обитателей восемнадцати квартир, всегда распахнута. Не ворота - одно название. Через эти никогда не закрывающиеся ворота словно пролегает тракт. Целыми днями шатаются торговцы. Люди не выходят даже за соевым творогом, покупают его прямо в комнатах, приоткрыв дверь. Какой тогда смысл собирать и вешать на ворота таблички с именами обитателей квартир? И люди как-то незаметно завели обычай крепить картонки над дверями, где иероглифами было выведено: «Зал Величайшего Терпения» или «Зал Добрых Предзнаменований». И в полном соответствии с этим обычаем над дверью моей комнаты висела моя - а точнее, моей жены - визитная карточка размером с четвертушку игральной карты.",191019,null],[208573,"2026-09-13T14:10:48",38,"Как и говорил голос рядом была табличка с именами 18 жителей.",191019,null],[208588,"2026-09-13T14:12:04",38,"Через этот двор проходили люди и продавали некоторым жителям еду.",191019,null],[208593,"2026-09-13T14:12:21",8,"/имена одинаковые?/",208573,null],[208594,"2026-09-13T14:12:29",38,"// Нет",208593,null],[208596,"2026-09-13T14:12:37",11,"*читает табличку \n\n— Ждать не придётся, нужно найти комнату с визитной карточкой и картой на табличке..",191019,null],[208604,"2026-09-13T14:14:10",8,"– Идём смотреть комнаты?",191019,null],[208605,"2026-09-13T14:14:52",11,"*прочитав табличку с именами уже убежала искать нужную дверь",208604,null],[208606,"2026-09-13T14:14:56",41,"– идем",191019,null],[208607,"2026-09-13T14:15:01",38,"Ты нашла нужный вариант.\n\nСакура Тоука\n Открыты с 17.\n Час — 5 серебряных\n Ночь — 30 серебряных\n\nКвартира 7",208596,null],[208612,"2026-09-13T14:15:28",11,"— Ребята! Кажется нам сюда! — не стесняясь кричит Аури",191019,null],[208617,"2026-09-13T14:16:35",8,"– Господин Тоука, извините за невежливость, но мы хотим лишь помочь! *скинула маскировку, убрала маску*",191019,null],[208619,"2026-09-13T14:17:00",11,"*стучит в дверь",191019,null],[208621,"2026-09-13T14:17:51",38,"В дверь вам никто не открывает, но вы начинаете слышать звуки, как кто-то ворочается внутри.\n Вы снова увидели ту же визитку над дверью.",191019,null],[208630,"2026-09-13T14:18:49",8,"– Привлечь его гуманнее. Ломать дверь опасно",191019,null],[208631,"2026-09-13T14:18:50",9,"Мысли: \"Похоже публичный дом не был словесным оборотом\"\n\n*Если это он то Вордо брезливо старается ни к чему не касаться.*\n\n— Неприятное место...",208607,null],[208635,"2026-09-13T14:19:13",9,"//Надеюсь ничего не напутал",191019,null],[208636,"2026-09-13T14:19:26",41,"— подождем, кажется",191019,null],[208638,"2026-09-13T14:19:54",38,"Вы слышите небольшие стоны мужчины за дверью и за дверью вы слышите голос похожий на голос Рассказчика.\n— Кто там?... Моей жены нету дома...",191019,null],[208643,"2026-09-13T14:20:26",41,"— Это вы гений?",191019,null],[208649,"2026-09-13T14:21:25",38,"— Какой гений?\n Послышался вопрос за дверью. Вы услышали звук небольшого падения, похоже он упал на пол.",208643,null],[208651,"2026-09-13T14:21:38",11,"— Вы в порядке?",191019,null],[208652,"2026-09-13T14:21:50",11,"— Мы не к вашей жене, мы к вам",191019,null],[208653,"2026-09-13T14:21:50",41,"Она попробовала просто открыть дверь",191019,null],[208656,"2026-09-13T14:23:20",8,"– Что-то странное происходит, мы хотим разобраться и помочь по возможности *обеспокоенно*",191019,null],[208658,"2026-09-13T14:23:44",38,"— Моя жена сказала, у меня простуда...\n Дверь была закрыта, замок внутри.",191019,null],[208659,"2026-09-13T14:23:45",38,"— Как кто-то может быть ко мне? У меня есть только жена...",191019,null],[208664,"2026-09-13T14:27:33",9,"— Мы к вам. Нас привело предсказание из печенья. — *Вордо вышел вперед и взял роль переговорщика на себя, говорил уверенно.* — Мир нашептал ваши мысли, теперь ваша судьба... — *Он оглянулся на остальных.* — В некотором роде нам не безразлична.",191019,null],[208668,"2026-09-13T14:28:09",9,"//Я манал, будем брать чела мистикой",191019,null],[208672,"2026-09-13T14:28:41",8,"/привлечём магией, это лучше одинаковых лиц/",191019,null],[208674,"2026-09-13T14:29:20",38,"— Хах... Мне уже однажды предсказали судьбу...\n Ответил мужчина.\n\nВы же услышали голос Рассказчика похожий на голос мужчины.\n— Я ни с кем не общаюсь. Не только не общаюсь, но и не здороваюсь. Да я и не собирался здороваться ни с кем, кроме собственной жены. Думаю, если бы я здоровался или общался с другими людьми, это плохо сказалось бы на ее репутации. А я всегда дорожил своей женой.\nЯ так дорожил ею потому, что знал, она, как и ее визитная карточка, была самой миниатюрной и красивой из женщин, проживавших в восемнадцати квартирах дома тридцать три. Здесь, под оцинкованной крышей, не пропускавшей солнечных лучей, моя жена была источником света и самым красивым из цветков, распустившихся в восемнадцати квартирах. И жизнь такого существа, как я, ухаживающего за этим цветком,.. нет, просто прильнувшего к нему, разумеется, казалась невыразимо нелепой.",208664,null],[208679,"2026-09-13T14:31:45",8,"– Вы не хотите поговорить с нами? Мы не кусаемся и не ругаемся. Наоборот, составим приятную компанию, поболтаем как люди. О магии расскажем *доброжелательно*",191019,null],[208683,"2026-09-13T14:33:06",11,"*шепчу своим\n\n— А что если сказать что с его женой что-то случилось..?",191019,null],[208685,"2026-09-13T14:33:46",9,"— Врать? Это низко.",208683,null],[208686,"2026-09-13T14:34:08",8,"– Мы не знаем пока. Не спугнём, если спросим о ней? *шёпотом*",208683,null],[208687,"2026-09-13T14:34:16",38,"— ... Простите... Я не хочу с вами общаться...\n Сказал мужчина и вы услышали шаги, как он отходит.",191019,null],[208688,"2026-09-13T14:34:22",11,"*посмотрит на Вордо снизу вверх, со всей высоты своего 159 роста",208685,null],[208691,"2026-09-13T14:34:55",9,"*Смотрит сверху вниз в ответ.*",208688,null],[208692,"2026-09-13T14:34:58",11,"— Я просто думаю как его выманить оттуда, раз для него так важна жена..",208686,null],[208693,"2026-09-13T14:35:11",11,"*надулась и отвернулась",208691,null],[208696,"2026-09-13T14:35:18",9,"//Надо гиф где 2 чела смотрят друг на друга и меж ними молнии",208691,null],[208698,"2026-09-13T14:35:33",11,"— Видите? Он не хочет нас впускать.. есть другие идеи?",208692,null],[208700,"2026-09-13T14:35:50",8,"– Необязательно общаться, можно просто посмотреть на магию. Вам же интересно что-то необычное, а не этот скучный город? *с детской непосредственностью*",208687,null],[208717,"2026-09-13T14:37:44",9,"— Можно выжечь механизм замка или петли на дверях. — *Достает склянку с чертой как смола кислотой и перебирает её меж пальцами как монетку.*",191019,null],[208720,"2026-09-13T14:37:50",8,"/не хочу сейчас в манипуляции уходить/",191019,null],[208723,"2026-09-13T14:38:38",8,"– Могу заглушить шипение замка музыкой *задумчиво*",208717,null],[208724,"2026-09-13T14:38:47",9,"//\"Нам мешает дверь? Вы уверенны что дверь достаточно мощная преграда?\" Вот как сейчас выглядит Вордо, но сами решайте)",191019,null],[208725,"2026-09-13T14:38:49",11,"— То есть врать низко, а взламывать чужие замки - высоко? Поражена, то есть я.",208717,null],[208729,"2026-09-13T14:39:25",38,"// Так тут мы немного приостановился, я тут в дороге и инет может пропадать",191019,null],[208731,"2026-09-13T14:39:35",8,"/где туманный шаг, когда он так нужен/",208724,null],[208732,"2026-09-13T14:39:45",11,"// мы все таки решим что делать будем, а ты там отреагируешь как сможешь)",191019,null],[208733,"2026-09-13T14:39:49",9,"— Вы правы миледи. — *Он прячет склянку.* — Она не достойна траты ресурсов, можно выбить.",208725,null],[208734,"2026-09-13T14:40:15",11,"— Вандал. — смотрит на девушек в поисках поддержки",191019,null],[208735,"2026-09-13T14:40:30",8,"– И спугнуть его. Умно, не скажешь *шёпотом, крутит пальцем у виска*",208733,null],[208737,"2026-09-13T14:40:34",9,"//Не, могу и туманным шагом, я забыл о нем напрочь",191019,null],[208738,"2026-09-13T14:41:02",8,"/закрыть доступ к окну и колюще-режущим/",191019,null],[208739,"2026-09-13T14:42:17",9,"— Я могу проникнуть внутрь без грубой силы. Но вы при этом останетесь снаружи.",208735,null],[208743,"2026-09-13T14:43:15",8,"– Но ты можешь открыть дверь изнутри. Главное – заблокируй окно и убери с виду ножи, а то мало ли *шёпотом*",208739,null],[208746,"2026-09-13T14:44:09",9,"*Взглянул на остальных.*",208743,null],[208748,"2026-09-13T14:44:30",11,"— Это мне больше по душе..",208739,null],[208751,"2026-09-13T14:44:44",11,"— Договоритесь с ним или откройте нам дверь изнутри",191019,null],[208753,"2026-09-13T14:45:03",9,"//Так, что там, щель или замочная скважена? Окно искать?",191019,null],[208829,"2026-09-13T15:12:12",41,"Она постучит еще раз. \n\n— Прошу подождите!",191019,null],[209008,"2026-09-13T16:33:08",38,"Дверь открывается на вас и имеет систему замочной скважины.",208753,null],[209010,"2026-09-13T16:33:18",38,"Тебе уже никто не ответил.",208829,null],[209021,"2026-09-13T16:43:21",8,"– Он молчит. Вордо, иди к нему, пожалуйста. Мне страшно: человек явно не в здравом уме *шёпотом*",191019,null],[209025,"2026-09-13T16:46:18",9,"//Так, вопрос к д-му, можно туманный шаг внутрь, щели есть? А то я щас описание жахну а окажется нет",191019,null],[209040,"2026-09-13T16:52:48",38,"// Да можешь, но подожди чутка",209025,null],[209084,"2026-09-13T17:19:10",38,"Вы продолжили слышать голос рассказчика, что говорил очень эмоционально.\n— Моя комната - не дом, дома-то никакого не было - нравилась мне во всех отношениях. Температура воздуха соответствовала температуре моего тела, а тусклое освещение - моему зрению. Я не мечтал о комнате более прохладной или теплой. И не пожелал бы комнаты посветлее или поуютнее. Я благодарил комнату за то, что ради меня она оставалась такой, какой была, и радовался, будто появился на свет ради того, чтобы наслаждаться этой комнатой. Но я не знал, в этом ли счастье. На самом деле, мне не было никакой надобности думать о том, счастлив ли я. Все было в порядке, пока день за днем я вел праздное бесцельное существование.\nЯ находился в замечательном, можно сказать, положении, удобном и беззаботном, не утруждал себя вульгарными раз мышлениями, счастье это или нет - валяться, не выходя из комнаты, к которой, как к одежде, прикипел душой и телом. И это положение мне нравилось.\nЭта замечательная комната была седьмой от ворот. Не без намека на «счастливую семёрку». Я гордился этой цифрой, как орденом. И кто знает, может, эта комната, разделенная раздвижной дверью на две половинки, была символом моей судьбы. \n\nВместе с этим вы все заметили, что с вами на площадки, ровно справа от вас стоит некто. Он был в деловом костюме, как и все мужчины здесь. Имел белые перчатки на руках, точнее на передних двух... Он имел пять рук. Две длинных и выходящих из конца плеч держали что-то за спиной, а две более средних и нормальных были как обычные руки. А пятая выходила прямо из воротника костюма и в отличии от остальных имела белый рукав и была согнута к лицу. Лицо некто было закрыто кучей бабочек, что сидели в одном положении.",191019,null],[209087,"2026-09-13T17:20:17",38,"Некто",191019,null],[209090,"2026-09-13T17:21:30",38,"// От него до вас еще около 60 футов",191019,null],[209091,"2026-09-13T17:21:48",8,"– Здравствуйте, как мы Вас можем называть, с какой целью здесь? *робко помахала рукой*",191019,null],[209096,"2026-09-13T17:23:15",9,"*Вордо уде собирался влететь минуя дверь и мял бинт на руках как пришло нечто. Он не удивился, астрал странное место, с другой стороны, это была бабочка, а последнее что видели их предшественники были бабочки.*\n\n//Вордо на стороже",191019,null],[209101,"2026-09-13T17:23:56",38,"Ты услышала довольно спокойный голос. На его плечи село пара бабочек\n— Куда бабочка попадает после смерти?",209091,null],[209102,"2026-09-13T17:24:22",8,"– Может, ты посторожишь Тоука? Вдруг он его враг? *шёпотом*",209096,null],[209103,"2026-09-13T17:24:58",41,"— Вы меня пугаете…",191019,null],[209104,"2026-09-13T17:25:00",8,"– К другим мёртвым существам в мир иной?",209101,null],[209105,"2026-09-13T17:25:36",9,"//Напомните мне что/кто такий/такие Тоук",209102,null],[209106,"2026-09-13T17:25:48",8,"/@Ashenchampion, дм пришёл/",191019,null],[209107,"2026-09-13T17:26:01",8,"/мистер Депрессия/",209105,null],[209108,"2026-09-13T17:27:00",38,"Мужчина продолжил говорить, медленно идя к вам.\n\n— Давным-давно в каком-то мире люди верили, что после смерти они станут прекрасными существами с маленькими крылышками. Глупая история. И бессмысленная... Не правда?",209104,null],[209109,"2026-09-13T17:27:32",8,"/жду Джейд/",191019,null],[209110,"2026-09-13T17:27:40",38,"// @Ashenchampion",191019,null],[209111,"2026-09-13T17:27:47",41,"(+",191019,null],[209430,"2026-09-13T20:03:03",11,"— Почему же? — Вклинилась Аури — Человеческая вера может творить чудеса, особенно когда она соприкасается с магией. Так кто вы и чем мы можем вам помочь, сэр?",209108,null],[209435,"2026-09-13T20:06:23",38,"— Чтож... Ваш ответ не удовлетворил моего...\n Одна из нормальных рук зашла под одежду и достала странное орудие. Оно было похоже на арбалет, но имело вместо болта палочку, волшебную палочку.\n\n// От вас до него 30 футов\nИ бросок инициативы.",209430,null],[209437,"2026-09-13T20:12:15",41,"( говорю по телефону",191019,null],[209444,"2026-09-13T20:17:56",8,"/roll 1d20+2",191019,null],[209449,"2026-09-13T20:19:04",8,"– Нет ничего предрассудительного в мечте – после смерти отбросить земное тело и взлететь навстречу новому пути. А вы грубиян, каких поискать. *обиженно*",191019,null],[209451,"2026-09-13T20:19:31",8,"/нас расстреляют🥰/",191019,null],[209456,"2026-09-13T20:20:28",11,"// отбросить панику, мы уважающие себя персонажи 2 лвла(я) и обыватели!!",191019,null],[209457,"2026-09-13T20:21:01",8,"/3-го, с щитом. Надеюсь, у Вордо он есть",191019,null],[209458,"2026-09-13T20:21:01",9,"/roll 1d20+2+1d8 боевой приём ЗАСАДА от Вордо",191019,null],[209468,"2026-09-13T20:25:59",38,"Инициатива:\nАури 16\nВордо 14\nИзольда 5\nПМБ 5\nЛетиция 4",191019,null],[209470,"2026-09-13T20:26:12",38,"/r +2 ПМБ",191019,null],[209475,"2026-09-13T20:27:08",9,"//Я пока хреновый маг, учусь ток, у меня есть пару других фокусов...",191019,null],[209478,"2026-09-13T20:27:33",11,"// я великий маг 2 лвла💅\nЖдём Элю",191019,null],[209479,"2026-09-13T20:27:44",41,"/r d20+2 ини",191019,null],[209483,"2026-09-13T20:28:00",41,"Кот рыча прыгнул в сумку Летиции",191019,null],[209485,"2026-09-13T20:28:17",8,"/мне кидать за волчицу?/",191019,null],[209486,"2026-09-13T20:28:30",38,"// Она с тобой по инициативе",209485,null],[209492,"2026-09-13T20:30:33",11,"*магические доспехи окутывают Аури, девушка пока не спешит атаковать и ждёт действий противника\n// Ход",191019,null],[209495,"2026-09-13T20:32:53",8,"/Hard/",191019,null],[209505,"2026-09-13T20:37:15",8,"/кстати, какие есть укрытия поблизости?/",191019,null],[209509,"2026-09-13T20:38:41",8,"/2. Дальнобойные атаки по лежащим проходят с помехой?/",191019,null],[209520,"2026-09-13T20:44:06",9,"//Щас подумаю мгновение)",191019,null],[209521,"2026-09-13T20:44:48",8,"/а вообще приколы какие-то. То атлетику кидай, то против пистолета дерись🙄/",191019,null],[209527,"2026-09-13T20:47:04",9,"*Вордо очень не нравилась штука в руках этого существа. Очень! Он с разбегу бежит в него и бьет по предмету пытаясь выбить его из рук противника.*\n\n//30 футов пробежал из 40 доступных и атлетика да?",209435,null],[209530,"2026-09-13T20:47:22",9,"/roll 1d20-1 атлетика нах)",191019,null],[209536,"2026-09-13T20:49:21",9,"//Вроде там соревнование, не помню",191019,null],[209538,"2026-09-13T20:50:02",8,"/@STR_V_Alekseev/",191019,null],[209545,"2026-09-13T20:54:19",38,"/r +3+2 Акробатика против захвата",191019,null],[209548,"2026-09-13T20:54:31",38,"/r +5",191019,null],[209553,"2026-09-13T20:56:21",9,"— Ты не трогай меня. — *Слова странным образом пытаются повлиять на существо.*\n\n//Бонусным \"Убежище\" на себя, ход",191019,null],[209559,"2026-09-13T20:57:52",8,"*Изольда швыряет в него снаряд хаоса 2 ячейкой, ибо задолбал своей загадочностью*",191019,null],[209562,"2026-09-13T20:58:02",8,"/roll 1d20+5",191019,null],[209567,"2026-09-13T20:58:50",8,"/прошло али нет?/",191019,null],[209569,"2026-09-13T20:59:01",38,"// Промах",209567,null],[209570,"2026-09-13T20:59:24",8,"/2 единицы на ищущее",191019,null],[209571,"2026-09-13T20:59:34",8,"/roll 1d20+5",191019,null],[209576,"2026-09-13T20:59:46",9,"//Если по мне то попал, я может задолбал загадочностью. Но на мне убежище, так что спас мудрости сначала сл 12 😏👌",209563,null],[209578,"2026-09-13T20:59:53",8,"/а так?",191019,null],[209580,"2026-09-13T21:00:02",8,"/я по бабочке",209576,null],[209582,"2026-09-13T21:00:07",38,"// Попал",191019,null],[209585,"2026-09-13T21:00:43",8,"/roll 2d8+2d6",191019,null],[209590,"2026-09-13T21:01:48",8,"/давай холодом",191019,null],[209593,"2026-09-13T21:02:10",8,"/нет иммуна против холода у него?",191019,null],[209595,"2026-09-13T21:02:21",11,"// щас узнаешь:3",191019,null],[209602,"2026-09-13T21:03:42",8,"*движением ухожу на 30 футов назад. Есть укрытия?*",191019,null],[209606,"2026-09-13T21:04:19",38,"// Вы в коридоре, где справа от вас забор на траву, а слева стена с дверьми",209602,null],[209609,"2026-09-13T21:04:59",38,"// И вы на 2м этаже",191019,null],[209612,"2026-09-13T21:05:31",8,"/какие-то двери открыты?/",191019,null],[209614,"2026-09-13T21:05:54",38,"Мужчина уклонился от захвата Вордо и почти уклонился от атаки Изольды, но все же она попадает по нему и он получает удар, все еще продолжая джержаться на ногах.",191019,null],[209615,"2026-09-13T21:05:57",38,"// Нет",209612,null],[209620,"2026-09-13T21:06:28",8,"/тогда просто 30 футов назад и ход",191019,null],[209622,"2026-09-13T21:06:36",8,"/теперь собака",191019,null],[209625,"2026-09-13T21:07:29",9,"//Собака ржёт, черт, надо было дать псу злую насмешку",191019,null],[209629,"2026-09-13T21:08:46",8,"*волк создан для атак. Он подбегает к бабочке и пытается выбить оружие, кусая за руку*",191019,null],[209631,"2026-09-13T21:09:00",8,"*на что кидать?*",191019,null],[209634,"2026-09-13T21:09:44",38,"// Атлетика/акробатика",191019,null],[209635,"2026-09-13T21:10:04",8,"/roll 1d20+1",191019,null],[209638,"2026-09-13T21:10:26",8,"/лучше ловкость, тогда 4 в сумме.",191019,null],[209639,"2026-09-13T21:10:34",9,"//Щас ток если крит 1 у него, это хотя бы автопровал",191019,null],[209643,"2026-09-13T21:11:09",38,"/r 1d20+5",191019,null],[209646,"2026-09-13T21:11:24",8,"/можно искусную остроту?/",191019,null],[209649,"2026-09-13T21:11:44",9,"//Волк кстати с преимуществом если рядом союзник, не? Тактика стаи)",191019,null],[209650,"2026-09-13T21:11:57",8,"/Вордо рядом в 5 футах?/",191019,null],[209651,"2026-09-13T21:12:16",9,"//Я прям возле нашего врага стою, дышу",191019,null],[209652,"2026-09-13T21:12:35",8,"/roll 1d20+2 от преимущества",191019,null],[209654,"2026-09-13T21:12:53",8,"/тогда острота, пусть бабочка перекинет",191019,null],[209656,"2026-09-13T21:13:04",38,"/r 1d20+5",191019,null],[209658,"2026-09-13T21:13:50",11,"// у меня флэшбеки от двух острот таких на квесте Сереги сразу",191019,null],[209661,"2026-09-13T21:14:09",8,"/ход",191019,null],[209662,"2026-09-13T21:14:23",38,"// пару минут",191019,null],[209702,"2026-09-13T21:25:43",8,"/волк может делать отход действием, на будущее?/",191019,null],[209703,"2026-09-13T21:25:54",38,"// да",209702,null],[209706,"2026-09-13T21:29:38",8,"/а спасы от смерти он делает или сразу автопровал?/",209703,null],[209726,"2026-09-13T21:38:52",38,"Мужчина посмотрел на вас всех и вы заметили, что он он стал... Более холодным? От него веяло частью смерти, а рядом с вами, между Вордо с волком и остальной группой его копия из разных бабочек, что вылетали из-за спины мужчины.",191019,null],[209728,"2026-09-13T21:39:07",38,"/r 1d10+2",191019,null],[209731,"2026-09-13T21:39:43",38,"Мужчина поднял орудие странное для вас и из палочки вылетел снаряд из бабочки, что издал звук колокольчика.",191019,null],[209732,"2026-09-13T21:40:06",38,"/r +5 Выстрел по Аури",191019,null],[209735,"2026-09-13T21:40:35",38,"// Спас мудрости Сл: 14",191019,null],[209737,"2026-09-13T21:41:23",38,"/r 1d10+3 Урона силовым полем",191019,null],[209740,"2026-09-13T21:41:34",38,"// И состояние испуганный",209736,null],[209741,"2026-09-13T21:42:42",38,"// Ход закончен",191019,null],[209744,"2026-09-13T21:43:06",38,"// @sweetkittywitch твой ход",191019,null],[209746,"2026-09-13T21:44:12",41,"— не смей её трогать! \n\nВорвалась в битву Летиция, перебросив сумку с котом Аури. После дважды ударила кинжалами существо",191019,null],[209747,"2026-09-13T21:44:23",41,"/r d20+3 d20+3",191019,null],[209749,"2026-09-13T21:44:30",41,"( хуи",191019,null],[209750,"2026-09-13T21:45:09",41,"( преимущества нет ?",191019,null],[209752,"2026-09-13T21:45:40",38,"// Нету",191019,null],[209753,"2026-09-13T21:45:47",8,"/он же окружен волком и Вордо?/",191019,null],[209754,"2026-09-13T21:46:13",38,"// Ещё скажу, что вам преграждает путь его копия из кучи бабочек",191019,null],[209755,"2026-09-13T21:47:15",38,"// Весь ход?",191019,null],[209757,"2026-09-13T21:50:57",38,"Вы услышали, что рассказчик продолжает разговор.\n— На одну половинку иногда заглядывало солнце. Утром появлялось пятнышко света размером с платок для переноски книг, а после обеда оно становилось не больше носового платочка и затем исчезало. И без слов ясно, что я занимал половинку с трубой, куда солнце никогда не заглядывало. Я уже не помню, кто из нас двоих, я или жена, решил, что жена займет солнечную комнату, а я — нет. Но я не жалуюсь. Как только жена уходит, я спешу к ней в комнату, открываю выходящее на восток окно, и когда я его открываю, яркие солнечные лучи освещают туалетный столик жены, всевозможные скляночки начинают сиять и переливаться, и это зрелище доставляет мне ни с чем не сравнимое удовольствие.\nЯ достаю увеличительное стекло и развлекаюсь, поджигая салфетки, которыми пользуется только жена. До смерти интересно в напряжении наблюдать, как, преломившись, параллельные лучи фокусируются в одной точке, эта точка нагревается все сильнее, и вдруг раз! - бумага загорается, выпустив струйку дыма, а на бумаге остается дырочка.\n\nМужчина же сказал, его голос был холоден и абсолютно спокоен.\n— Не мешайте И Сану в его жизненном пути и пусть он сам поймет, куда делись его крылья...",191019,null],[209760,"2026-09-13T21:52:16",41,"Да",209755,null],[209762,"2026-09-13T21:53:26",38,"// Может вам карту сделать? Скажу, что она будет очень простая",191019,null],[209764,"2026-09-13T21:53:37",11,"/roll d20+2 пробуем скинуть испуг (напомните на это тратится что-то?)",191019,null],[209766,"2026-09-13T21:53:54",38,"// Ты сняла испуг и потратила действие",191019,null],[209767,"2026-09-13T21:54:28",11,"// если я не ошибаюсь это бесплатный спас, но в конце моего хода. Так что действую с помехой\nНо слово мастера закон так что ход полагаю",191019,null],[209772,"2026-09-13T21:58:38",38,"// Вот карта",191019,null],[209774,"2026-09-13T21:58:51",38,"// Сорян у меня просто сейчас уже все спят",191019,null],[209777,"2026-09-13T22:00:15",38,"// Да, ты права это я сейчас просто сонный",209767,null],[209780,"2026-09-13T22:03:23",11,"/roll d8+4 лечение ран на себя",191019,null],[209782,"2026-09-13T22:04:56",11,"— Вы, нет, Ты не будешь указывать что и как нам делать. Понятия не имею кто ты, но слушаться того кто атакует меня и моих друзей я не собираюсь — говорит девушка пока мягкое голубое свечение исходит от её руки что прикладывается к собственной груди \n\n// Ход",191019,null],[209783,"2026-09-13T22:05:19",38,"// Hard твой ход",191019,null],[209784,"2026-09-13T22:05:39",9,"//Что же, ух",191019,null],[209786,"2026-09-13T22:07:13",9,"*Вордо намтраивается на действие (указание себе быстрым) рука его разит как змея по оружию.*\n\n//Хорошо что выбивается проверкой, можно указанием бахнуть",191019,null],[209787,"2026-09-13T22:07:43",9,"/roll 1d20-1+1d4 Попутка номер два на какую хрень я трачу метамагию",191019,null],[209789,"2026-09-13T22:08:15",38,"// Это же захват?",191019,null],[209790,"2026-09-13T22:09:05",9,"//Атлетика на особый вид атаки \"выбить оружие\" но там все равно соревнование атлетики/акробатика",191019,null],[209791,"2026-09-13T22:09:12",38,"/r 1d20+5 Акробатика",191019,null],[209793,"2026-09-13T22:09:19",8,"/острота",191019,null],[209795,"2026-09-13T22:10:19",9,"*Вордо понимает что его противник очень ловок, и со всех ног (на 40 футов) удаляется от врага.*\n\n//Щас боевой приём что кд увеличит последней костью",191019,null],[209796,"2026-09-13T22:10:37",9,"/roll 12+1d8 кд в движении",191019,null],[209798,"2026-09-13T22:10:57",38,"/r 1d20+6 Провоцированная атака по Вордо",191019,null],[209800,"2026-09-13T22:11:40",38,"// Промах",191019,null],[209801,"2026-09-13T22:12:07",8,"/собака может сходить до меня?/",191019,null],[209802,"2026-09-13T22:12:19",9,"*Вордо слишком быстро отошёл, увернулся словно предсказав атаку.*",209799,null],[209803,"2026-09-13T22:12:24",38,"Вы делите одинаковую инициативу",209801,null],[209804,"2026-09-13T22:13:03",8,"/тогда волчара ходит сейчас до меня, ок?/",191019,null],[209805,"2026-09-13T22:13:57",8,"*волчица по команде Изольды делает отход на 40*",191019,null],[209806,"2026-09-13T22:14:27",8,"/я могу потом зайти к Летиции, чтобы копия не мешала?/",191019,null],[209807,"2026-09-13T22:15:03",38,"// Да и вордо тоже",209806,null],[209809,"2026-09-13T22:15:36",8,"*тогда волчица движением отходит к Летиции*",191019,null],[209810,"2026-09-13T22:16:10",8,"*Изольда становится ровно перед собакой и так, чтобы копия не мешала заклинанию*",191019,null],[209813,"2026-09-13T22:16:35",8,"/roll 1d20+5\nкинжал",191019,null],[209815,"2026-09-13T22:16:44",38,"// Попала",191019,null],[209816,"2026-09-13T22:17:04",8,"/сек",191019,null],[209817,"2026-09-13T22:17:58",8,"/roll 1d10 \nНужен спас ловкости сл.13 от бабочки",191019,null],[209820,"2026-09-13T22:22:15",38,"/r 1d20+3 Спас ловкости",191019,null],[209822,"2026-09-13T22:22:40",8,"/ход, урон на 1 мощно вышел",191019,null],[209823,"2026-09-13T22:24:26",38,"Мужчина вздыхает и взяв оружие покрепче говорит.\n— Я хоте сдерживаться, но не выйдет...",191019,null],[209824,"2026-09-13T22:25:13",11,"— Сдерживаться? Это говорит человек? Существо? Которое из меня чуть весь дух не выбило?",191019,null],[209825,"2026-09-13T22:25:19",38,"/r 1d20+6 По Собаке\n/r 1d20+6 По Вордо",191019,null],[209827,"2026-09-13T22:25:34",9,"//Попал кнчно",191019,null],[209828,"2026-09-13T22:25:38",8,"/собака за моей спиной. По мне",191019,null],[209829,"2026-09-13T22:25:42",41,"— может мы можем решить всё мирно?!",191019,null],[209830,"2026-09-13T22:26:21",8,"/попал",191019,null],[209831,"2026-09-13T22:27:00",38,"/r 1d10+3 Силового урона по Вордо\n/r 1d10+3 Силового урона по Изольде",191019,null],[209833,"2026-09-13T22:27:10",11,"— Он первый атаковал нас, Лети и он хочет что бы мы оставили господина Тоуку в таком состоянии!",191019,null],[209834,"2026-09-13T22:27:11",38,"// Вас также отталкивает на 10 футов назад",191019,null],[209835,"2026-09-13T22:27:22",38,"// И спас мудрости Изольда",191019,null],[209839,"2026-09-13T22:28:08",41,"— Но я боюсь за вас!",209833,null],[209840,"2026-09-13T22:28:26",8,"/roll 1d20+1",191019,null],[209842,"2026-09-13T22:28:38",38,"— Оставьте И Сана на его жизненном пути и я отпущу вас в этот раз...\n Отвечает Мужчина.",191019,null],[209843,"2026-09-13T22:28:45",38,"// Только урон",209841,null],[209845,"2026-09-13T22:28:59",11,"— Оставить человека который хочет покончить с собой?! Ещё чего!",191019,null],[209846,"2026-09-13T22:29:07",8,"*Изольда слишком бесстрашная, какие бабочки её напугают?*",191019,null],[209848,"2026-09-13T22:29:28",8,"– Слабым нужна помощь, а не добитие!",191019,null],[209850,"2026-09-13T22:29:54",41,"— Они правы! Почему вы так хотите его смерти?!",209842,null],[209852,"2026-09-13T22:30:12",11,"— Или просто он не желает вмешательства в сюжет..",191019,null],[209853,"2026-09-13T22:30:18",38,"/r 1d10+3",191019,null],[209855,"2026-09-13T22:30:25",9,"*Принял туловищем, вы могли бы заметить черное пятно вместо кожи и ран, из него вытекала такая же темная смолянистая жидкость что местами сияла как звёзды. Вордо придерживает сеья рукой, он не привык получать ранения...*\n\n— Кх, кх... — *Еще одного удара он не переживёт.*",209832,null],[209856,"2026-09-13T22:31:42",8,"/далеко стоит?/",209855,null],[209857,"2026-09-13T22:31:46",38,"— И Сана ждёт путь, который он сам выбрал... Если хотите узнать его причину, то дослушайте... \"Его\"...\n Мужчина указал своей рукой из воротника вверх.",191019,null],[209858,"2026-09-13T22:31:59",38,"// К тебе оттолкнуло",209856,null],[209861,"2026-09-13T22:32:50",9,"*Если к Вордо бегут с помощью он видом показывает \"не надо\".*",191019,null],[209862,"2026-09-13T22:32:56",11,"— Вот пускай о причинах нам расскажет сам «гений»",209857,null],[209863,"2026-09-13T22:32:59",8,"– Когда он закончит, он может закончить в этом мире. Подобного допустить нельзя хотя бы ради гуманизма *уязвлены её ценности*",209857,null],[209868,"2026-09-13T22:34:38",38,"// Ход мужчины закончен.\n— Куда человек попадает после смерти?\n Спрашивает он вздохнув.",191019,null],[209869,"2026-09-13T22:35:35",38,"// Ход @sweetkittywitch",191019,null],[209870,"2026-09-13T22:36:17",41,"— КАК Я ЗНАЮ — НИКУДА! \n\nсо злостью бьет копию Лети",209868,null],[209871,"2026-09-13T22:36:26",41,"/r d20+3 d20+3",191019,null],[209873,"2026-09-13T22:37:30",9,"//Хотя бы не крыса нас порешала ^^",191019,null],[209874,"2026-09-13T22:38:02",38,"Голос Рассказчика продолжил.\n— Когда мне надоедает это развлечение, я беру поиграть ручное зеркальце жены. Зеркало приносит пользу, только если смотришься в него. А иначе остается пустой игрушкой.\nЭто развлечение мне тоже надоедает. Моя страсть к развлечениям устремляется из физической в духовную сферу. Я отбрасываю зеркало, приближаюсь к туалетному столику жены и заглядываю в расставленные на нем всевозможные склянки с косметикой. Они для меня привлекательнее всего на свете. Я выбираю одну из них, осторожно открываю пробку, подношу горлышко склянки к носу и, затаив на секунду дыхание, делаю легкий вдох. Когда экзотический нежный аромат проникает в легкие, я чувствую, как глаза мои сами собой закрываются. Частичка запаха тела моей жены. Закрыв бутылочку, я размышляю. От какой части ее тела исходит этот запах?… Но не могу сообразить. Почему? Да потому, что запах тела жены складывается из всех имеющихся здесь ароматов.",191019,null],[209876,"2026-09-13T22:39:59",8,"– Если так важны причины, почему бы не обсудить их за чашкой чая, решив судьбу парня? Заодно убрав все возможности самоухода. Многие заслуживают второго шанса.",191019,null],[209880,"2026-09-13T22:41:52",38,"— Эта история прошлого и я не хочу видеть ещё больше бабочек, что хотят утешения...\n Сказал мужчина и вы заметили, что из-за его гроба как раз и выходят бабочки. Точнее вы догадались, что это гроб.",209876,null],[209881,"2026-09-13T22:42:07",8,"/преимущество от остроты себе и Аури/",191019,null],[209883,"2026-09-13T22:42:59",8,"/диалог во время боя нельзя полноценный, да?/",191019,null],[209884,"2026-09-13T22:43:35",38,"// Ход @Ashenchampion , если ход @sweetkittywitch все",191019,null],[209885,"2026-09-13T22:44:03",41,"( ага",191019,null],[209888,"2026-09-13T22:45:29",11,"*Аури читает заклинание, нащупав что-то в сумке",191019,null],[209890,"2026-09-13T22:45:42",11,"/roll d20+6 на попадание хроматик орбом",191019,null],[209892,"2026-09-13T22:45:50",11,"// услышал тебя родной",191019,null],[209894,"2026-09-13T22:45:58",38,"// У тебя же преимущество",191019,null],[209895,"2026-09-13T22:45:59",11,"// использую преимущество",191019,null],[209896,"2026-09-13T22:46:10",38,"// Попала",191019,null],[209900,"2026-09-13T22:46:55",11,"/roll 3d8 урон хм кислотой",191019,null],[209902,"2026-09-13T22:47:02",11,"// ход",191019,null],[209904,"2026-09-13T22:47:27",11,"— Мы в твоём гробу не окажемся.",191019,null],[209908,"2026-09-13T22:47:59",38,"Мужчина обливается кислотой и вы слышите его негодование по этому поводу.\n— Этот гроб не для вас...",191019,null],[209912,"2026-09-13T22:48:48",11,"— И не для него!",191019,null],[209916,"2026-09-13T22:49:38",38,"// Ещё что-то?",191019,null],[209919,"2026-09-13T22:50:13",11,".",209902,null],[209924,"2026-09-13T22:52:50",9,"*Вордо понимает что сам по себе он мало что может сделать.*\n\n— Ты зря меня ранил. — *Вордо нажимает на ноги, и встает за Изольдой обращаясь уже к нейс коснулся прикосновением словно электрическим разрядом заставив магию внутри её вскипеть.* — Ты сможешь сделать следующий шаг, не защищайся, атакуй.\n\n//Обыгрываем помошь, чё, надеюсь есть чет на попадание",191019,null],[209925,"2026-09-13T22:53:46",9,"//Ход",191019,null],[209926,"2026-09-13T22:54:25",8,"– Послушай, пока мне не пришлось атаковать. Можем к каждой бабочке относиться индивидуально? Здешние люди имеют отличия снаружи, и, вероятно, внутри. Вылечи свою рану, а не наноси их окружающим, пожалуйста.",191019,null],[209929,"2026-09-13T22:55:28",38,"// Прошу проверку выступления/убеждения, действия не тратит",209926,null],[209931,"2026-09-13T22:55:51",8,"/roll 1d20+5",191019,null],[209935,"2026-09-13T22:57:28",38,"Ты увидела небольшое движение у мужчины и его копия сразу же разок класть из бабочек.\n Он немного помолчал и сказал.\n— Даю вам один шанс... Только один...\n\nМужчина проходит сквозь стену и исчезает\n// Конец битвы",209926,null],[209939,"2026-09-13T22:58:10",8,"– Вордо, бежим помогать",191019,null],[209941,"2026-09-13T22:59:12",11,"*Аури виновато отводит глаза",191019,null],[209944,"2026-09-13T22:59:34",8,"/извините, что обломала опыт, но действую в рамках персонажа, беспокоящегося за таймер/",191019,null],[209945,"2026-09-13T23:00:06",9,"*Вордо перестает касаться плечь и осторожно садится у стены.*\n\n— Кх. Пока не поздно, успеем. — *Он не просит помощи, раны затянутся сами, словно по волшебству, если они не слишком сильны.*",191019,null],[209946,"2026-09-13T23:00:15",41,"— ого… какая вдохновляющая речь",209926,null],[209949,"2026-09-13T23:01:14",8,"– Вордо, открой дверь изнутри, будь добр, пока не поздно *зажала голову, мозги разрывает*",191019,null],[209951,"2026-09-13T23:02:09",11,"*Осторожно касается Изольды",209949,null],[209952,"2026-09-13T23:02:17",11,"/roll d8+4",191019,null],[209954,"2026-09-13T23:02:45",11,"— Лучше? — она говорит стараясь не смотреть в глаза никому",191019,null],[209955,"2026-09-13T23:02:47",8,"– Спасибо *сверлит мага глазами*",191019,null],[209957,"2026-09-13T23:04:23",11,"*молча отходит и сама сползает по стене напротив Вордо с грустным вздохом",191019,null],[209958,"2026-09-13T23:04:29",41,"— Аури, ты как, милая ?",209954,null],[209960,"2026-09-13T23:04:53",38,"Рассказчик продолжал повествование.\n— Комната жены всегда выглядит пестро. В отличие от моей простенькой комнаты, где нет ни единого гвоздя, по всей комнате жены под потолком вбиты гвоздики, на которых висят ее яркие кофточки и юбки. Приятно смотреть на пестрые узоры. В этих юбках мне чудится тело жены и различные позы, которые она принимает, и моя душа приходит в волнение.\nА у меня одежды не было. Жена не давала мне одежды. Плисовый костюм, что был на мне, служил и повседневным, и выходным нарядом, и пижамой. А свитер с высоким горлом был моим нижним бельем на все времена года. Вся одежда черного цвета. Как я догадываюсь, для того, чтобы не было противно смотреть, пока не представится возможность постирать. Я носил панталоны с тремя резинками - одной на талии и по одной на штанинах - и никогда не жаловался, развлекался как мог.",191019,null],[209961,"2026-09-13T23:04:56",8,"/Hard/",191019,null],[209962,"2026-09-13T23:05:17",9,"//Го завтра, я засыпаю. Не соображаю почти",191019,null],[209964,"2026-09-13T23:05:43",8,"/ок, тогда завтра разговоры/",191019,null],[209965,"2026-09-13T23:06:13",38,"// Завтра, до 14 я точно смогу иногда вам давать инфу.",191019,null],[209966,"2026-09-13T23:06:27",11,"— Простите.. из-за меня вы пострадали",209958,null],[209967,"2026-09-13T23:07:00",8,"– Ничего, он сам агрессивный, с  оружием лезет...",191019,null],[209968,"2026-09-13T23:07:22",41,"— Ты что… мы друг за друга горой, не вини себя … Самсон, обними её…\n\nСумка на руках Аури мурчит и ей на плечи лезет перс",209966,null],[209969,"2026-09-13T23:08:32",8,"*обняла Аури и волчицу холодными руками и сидит в напряжении* /мои заявки всё, жду завтрашнего туманного шага/",191019,null],[209970,"2026-09-13T23:08:54",11,"обнимает котика и гладит\n\n— Я его спровоцировала на конфликт, а оказалось с ним легко было договориться, мне жаль",209968,null],[209971,"2026-09-13T23:09:19",41,"— ну ну… он нас всех очень напугал(",209970,null],[209972,"2026-09-13T23:10:31",11,"— Из-за меня..",191019,null],[209973,"2026-09-13T23:11:07",41,"— ты не знала точно, насколько плохо всё кончится(",209972,null],[209974,"2026-09-13T23:11:17",41,"— и ведь не кончилось ведь !",191019,null],[209975,"2026-09-13T23:13:25",11,"— Не кончилось, благодаря Изольде.. мне есть чему у тебя получиться.. — голос звучит глухо ибо говорит она уткнувшись лицом в шерсть котика, а затем резко подымает голову чуть не стукнув Изольду — Ой.. прости! Но вы правы, кому сейчас действительно нужно утешение так это человеку за дверью",191019,null],[209977,"2026-09-13T23:13:41",11,"// до завтра, ждём действий Вордо",191019,null],[209979,"2026-09-13T23:14:56",41,"( Аури хочется цомнуть \n\nПерс облизал руку Аури",191019,null],[210010,"2026-09-14T07:52:07",9,"//Так, могу вклиниться в игру когда надо",191019,null],[210019,"2026-09-14T08:21:16",38,"// Сегодня возможно игры не будет, как и завтра",191019,null],[210178,"2026-09-14T11:47:11",8,"/если время будет, сообщите/",210019,null],[214474,"2026-09-15T23:19:34",38,"// Дамы и хард. Завтра я смогу продолжить, поэтому собираемся примерно к 13 по мск.\n\nFantomas @sweetkittywitch @Ashenchampion Hard",191019,null],[215564,"2026-09-16T13:02:19",8,"/тут",214474,null],[215565,"2026-09-16T13:02:46",38,"// Так... Игра задержится на 30 минут, меня тут задерживают в школе",191019,null],[215566,"2026-09-16T13:04:04",8,"/ок. Тогда вопрос перед игрой: два преимущества от остроты длятся по минуте. Скорее всего, они уже прошли?",215565,null],[215567,"2026-09-16T13:04:45",11,"// учитывая что 1 минута - это целых 10 ходов, нет не должно, мы только бой закончили",215566,null],[215569,"2026-09-16T13:09:20",38,"// Нет еще",215566,null],[215639,"2026-09-16T13:59:07",38,"// Так. Продолжаем! Hard Fantomas @Ashenchampion @sweetkittywitch.\n\n Вы все ещё находитесь в коридоре после битвы с мужчиной, где вместо головы у него были бабочки, а за собой он носил гроб.",191019,null],[215640,"2026-09-16T14:00:09",41,"— что же нам теперь делать?...\n\nОтчаянно говорит Лети под мурлыканье меркоти",191019,null],[215641,"2026-09-16T14:00:52",8,"/Hard, выпили дверь, пожалуйста/",191019,null],[215642,"2026-09-16T14:01:18",11,"// дверь мне запили",191019,null],[215643,"2026-09-16T14:02:25",8,"*Взяв себя в руки, девушка распрямляет плечи и надевает изящные перчатки со стразами, из белого шёлка. Лицо принимает собранное выражение. Она встаёт у двери и терпеливо ждёт, готовая броситься в комнату*",191019,null],[215645,"2026-09-16T14:03:03",8,"– Лети, не оставайся одна",191019,null],[215646,"2026-09-16T14:03:04",11,"*резво подымается вслед за Изольдой. Котика все ещё гладит",191019,null],[215649,"2026-09-16T14:03:30",41,"— я с вами",215645,null],[215650,"2026-09-16T14:03:30",38,"Дверь, как была закрыта, так и оставалась",191019,null],[215651,"2026-09-16T14:03:58",8,"/Харда ждём с туманным шагом/",191019,null],[215652,"2026-09-16T14:04:11",11,"// звездным шагом💅",215651,null],[215687,"2026-09-16T14:20:04",9,"//У меня и то и то есть)",191019,null],[215689,"2026-09-16T14:20:28",11,"// давай, только тебя и ждём",191019,null],[215701,"2026-09-16T14:23:49",9,"*Вордо встал и начал разматывать свои бинты, они больше не нужны. Здесь будто всем плевать как и кто выглядит, а маскировка только мешает...*\n\n— ...Так лучше. — *Он расправляется во весь рост и откидываея плащ предстает во всей красе.*\n\n*Он словно скопление звезд на небе, а глаза полыхают белым ослепляющим светом.*",191019,null],[215704,"2026-09-16T14:25:02",41,"( взламываем суесыдника",191019,null],[215705,"2026-09-16T14:25:50",9,"*Одной рукой запихав бинты в сумку — подошёл к двери.*\n\n— Я иду. — *Превратившись в туман, скопление звезд, его тело, вещи, он сам просачился на лругую сторону двери и оказался там.*\n\n//Туманный пока",191019,null],[215711,"2026-09-16T14:27:14",11,"— О, вы решили сменить стиль, господин Вордо, этот мне больше по душе — всё ещё поглаживая котика сказала девушка прежде чем парень исчез в дымке перед ними",191019,null],[215715,"2026-09-16T14:28:10",9,"//Остался ток один поинт метамагии и один звездный, бм всего +1. Только кости боевых приёмов на коротком, все исторатил, хех",191019,null],[215719,"2026-09-16T14:29:06",8,"*проводила восхищённым взглядом* /а так ячейка 1, ячейка 2, 1 единица чародейства, тьма и усё/",215705,null],[215728,"2026-09-16T14:31:37",41,"— Вы просто чудесный, Вордо...",191019,null],[215731,"2026-09-16T14:32:55",38,"Оказавшись за той стороной двери ты увидел, что она и вправду выглядит, как говорил голос.\n За дверью было жилище из двух комнат перекрытые раздвижными дверьми. Сейчас сюда падало солнце и было видно всю комнату. Тут был туалетный столик, кровать для двоих и довольно низкий стол, без стульев, похоже сидеть на коленях.\n По всей комнате под потолком вбиты гвоздики, на которых висят ее яркие кофточки и юбки.\nТы не обнаружил никого в этой комнате.\n\nРассказчик же продолжал повествование.\n— Пятнышко света размером с носовой платок незаметно исчезло, а жена все не возвращалась. Я устал от развлечений, к тому же до прихода жены мне все равно нужно вернуться к себе в комнату. В моей комнате полумрак. Я ложусь средь бела дня спать и накрываюсь одеялом с головой. Постель, которую я не убирал ни разу в жизни, уже стала частью моего тела. Иногда я хорошо засыпаю. А иногда никак не могу устроиться и заснуть. И тогда я выбираю какую-нибудь тему для исследования. Завернувшись в сырое одеяло, я сделал немало открытий и сочинил немало статей. Сложил множество стихов.\n Но как только я засыпаю, они исчезают, растворившись, словно мыльные пузыри, в колышущемся воздухе моей комнаты, и, проснувшись через некоторое время, я чувствую внутри только комок нервов, тугой, словно подушка, набитая гречневой шелухой или ватой. Больше всего я ненавидел клопов. Даже зимой они то и дело выползали по несколько штук. Если меня что и беспокоило, так это ненависть к клопам. Я до крови расчесывал зудящие места укусов. Ноет. И в этом можно найти удовольствие. Изможденный, я засыпаю. Но нельзя же исследовать что-нибудь позитивное, проводя жизнь в размышлениях перед сном. Мне по большей части не до того. Если бы я выдумал что-нибудь позитивное, мне пришлось бы посоветоваться с женой, а если бы я это сделал, пришлось бы слушать ее упреки... Не то чтобы я боялся этих упреков, просто они надоели мне. Чем строить из себя приличного члена общества и слушать ворчание жены, я предпочитал валяться, словно самое ленивое животное. Если бы я мог, я сорвал бы с себя бессмысленную маску человека.\n Человеческое общество надоело мне. И жизнь надоела. Все кажется чужим.",215705,null],[215732,"2026-09-16T14:34:27",11,"— Изольда, послушай",191019,null],[215733,"2026-09-16T14:34:47",11,"*Аури возвращает котика хозяйке\n\n— Спасибо, Лети, он лучший антистресс!",191019,null],[215734,"2026-09-16T14:35:18",8,"– Уже. Пустота в жизни, инфантилизм – печально *выглядит расстроенно*\n– Он там?",215732,null],[215735,"2026-09-16T14:35:25",11,"— Ты ведь владеешь искусством перевоплощения.. что если ты примеришь роль его жены?",215732,null],[215737,"2026-09-16T14:36:01",8,"– Я не знаю её облика, но могу попытаться воссоздать",191019,null],[215738,"2026-09-16T14:36:52",8,"– Она ворчлива, кокетлива, любит наряжаться. Но цвет глаз, рост...",191019,null],[215739,"2026-09-16T14:37:24",11,"— Это верное замечание, но вдруг внутри есть фотографии.. я просто подумала об этом и вот.. решила озвучить",191019,null],[215740,"2026-09-16T14:37:37",41,"— Всегда рада поделиться) На счет жены...Я даже не знаю...я вышла замуж совсем недавно и если б увидела копию настоящего мужа, то разозлилась бы...потерю надо прожить. Даже потерю самого себя",215733,null],[215741,"2026-09-16T14:38:01",41,"—... Извините, не по теме",191019,null],[215742,"2026-09-16T14:38:06",9,"*Вордо поворачивается. Смотрит не может ли он открыть замок изнутри?*",191019,null],[215743,"2026-09-16T14:38:10",38,"Рассказчик начал говорить уже монотонно передавая эмоции человека, которого Мужчина-Бабочка назвал И Саном, а вы Тоукой.\n\n— Моя жена выходит умываться дважды в день. А я ни разу. Только когда часа в три ночи иду в туалет, прежде чем вернуться, я, бывает, стою без дела во дворе, особенно если ночь лунная. Так что я почти не сталкиваюсь ни с кем из соседей. И все же помню лица всех молодых девушек из восемнадцати квартир. Все эти девушки моей жене и в подметки не годятся. В первый раз, часов в одиннадцать, моя жена умывается очень быстро. А во второй раз, часов в семь вечера, - гораздо тщательнее. И одежду она вечером надевает почище и получше, чем днем. Она выходит из дома и днем, и вечером.\n Есть ли у жены работа? Откуда мне знать, чем она занимается. Если бы она была безработной, ей, как и мне, не нужно было бы выходить из дома - а она выходит. Она не только выходит, но и принимает посетителей. Когда посетителей особенно много, мне приходится весь день лежать в постели у себя в комнате.\n Нельзя играть с огнем. Нельзя вдыхать запах косметики. И я нарочно впадаю в депрессию. Тогда жена дает мне денег. Серебряную монетку. Мне приятно. Не зная, на что бы потратиться, я кидал монетки в изголовье постели, и незаметно их собралось довольно много. Увидев их однажды, жена купила мне копилку в форме сейфа. Я по одной побросал туда монетки, а жена забрала ключ. Я, помнится, и потом время от времени бросал в копилку монетки. Но считать их было лень. Не свидетельствовала ли новая шпилька, вскочившая, как прыщ, на голове у жены, что моя копилка облегчилась? Я перестал, наконец, притрагиваться к копилке, стоявшей у изголовья. Лень не позволяла мне уделять внимание подобным мелочам.",191019,null],[215744,"2026-09-16T14:38:36",38,"Может, тут прямо рядом и стоит простой механизм защелки замка.",215742,null],[215745,"2026-09-16T14:38:45",8,"– Я всё равно взгляну на фотографии, но, Лети, ты права. Только на крайний случай",215740,null],[215746,"2026-09-16T14:38:53",11,"— Да, но вдруг мы сможем что-то с этим сделать, Изольда хороша в выступлении..",215740,null],[215747,"2026-09-16T14:39:18",41,"— Ладно. Злость - тоже ему нужна",215746,null],[215749,"2026-09-16T14:39:26",9,"*Двидением одной руки Вордо призывает магическую руку и та окрывает защёлку.*\n\n— Входите.",215744,null],[215750,"2026-09-16T14:40:02",38,"Дверь очень легко открывается и все остальные видят похожую картину жилья.",215749,null],[215751,"2026-09-16T14:40:29",8,"– Мы слышали его голос, но он пропал *ищет тщательно*",191019,null],[215756,"2026-09-16T14:40:56",9,"— Скорее в другой комнате.",191019,null],[215757,"2026-09-16T14:41:04",38,"Вы видите только закрытую раздвижную дверь.",215751,null],[215758,"2026-09-16T14:41:04",11,"*с любопытством заглядывает внутрь\n\n— Угу, как и говорит голос",191019,null],[215762,"2026-09-16T14:41:25",8,"*тихо крадётся туда*",191019,null],[215763,"2026-09-16T14:41:35",38,"// Проверку скрытности",215762,null],[215765,"2026-09-16T14:42:10",8,"/roll 1d20+2\n/roll 1d20+2\nот остроты",191019,null],[215768,"2026-09-16T14:42:32",9,"*Вордо перепризывает магическую руку у той двери и отодвигает её, медленно, очень медленно чтобы скрипела до ужаса а сам стоит за ней скрестив руки.*",215757,null],[215769,"2026-09-16T14:43:13",11,"*Аури тем временем озирается в поисках фотографий",191019,null],[215778,"2026-09-16T14:50:06",38,"Дверь очень тихо открывается не издавая ни звука и вы видите какой тут бардак. Куча мусора, жуков, клопов и никакого света внутрь. В углу был матрас, на котором лежал он... Заросший на голове волосами юноша с бледной кожей и в свитере. Он лежал под изношенным одеялом и голом матрасе.\n\nАури же видела как над потолком подвешены фотографии жены, но была только её часть тела в юбках.\n\nРассказчик же продолжил повествование.\n— В дождливые дни и в дни, когда у жены было много посетителей, я не мог уснуть, как ни зарывался в одеяло. В такие дни я занимался исследованием, почему у жены всегда водятся деньги и почему их так много.\nПосетители, похоже, и не подозревали о том, что я лежу за дверью. Они отпускали, особо не стесняясь, такие шуточки, которых даже я не позволял себе при ней. Среди тех, кто приходил к жене, трое-четверо выглядели приличнее прочих и, как это принято, к полуночи уходили. А были и некультурные, похоже, люди - но такие обычно приносили с собой еду. Так что все было в порядке.",191019,null],[215782,"2026-09-16T14:51:28",41,"Лети помогает",215769,null],[215784,"2026-09-16T14:51:38",41,"Кот тоже ищет",191019,null],[215786,"2026-09-16T14:52:03",8,"/окно есть?/",191019,null],[215787,"2026-09-16T14:52:14",8,"/колюще-режущие?/",191019,null],[215790,"2026-09-16T14:52:49",38,"// Окно есть, но оно сейчас закрыто и через него освящается основная комната. В комнату за дверью свет вообще не попадает",215786,null],[215793,"2026-09-16T14:53:40",8,"*аккуратно садится на матрас и крепко берёт парня за руку, чтобы не убёг*",191019,null],[215794,"2026-09-16T14:53:46",11,"— В таких условиях его состояние мне предельно понятно — шепнет на ухо Летиции — его бы вытянуть отсюда проветриться..",191019,null],[215795,"2026-09-16T14:53:58",9,"*Вордо тяжело вздохнул отгоняя желание просто сжечь этот клоповник.*",215778,null],[215798,"2026-09-16T14:54:26",8,"/можно, но после выхода отсюда. Не то чтобы я против/",215795,null],[215799,"2026-09-16T14:54:42",38,"Мужчина похоже и вправду был простужен, что даже не заметил твоего действия продолжая лежать с закрытыми глазами.",215793,null],[215800,"2026-09-16T14:55:24",8,"*тихо манит Аури и Летицию запахом сирени в комнату*",191019,null],[215801,"2026-09-16T14:56:44",9,"*Вордо магической рукой закрывает дверь наружу обратно на защёлку. Хорошо что он решил сразу воспользоваться заклинанием, иначе пришлось бы умывать руки кислотой.*",191019,null],[215802,"2026-09-16T14:56:48",8,"*волк рядом сидит*",191019,null],[215803,"2026-09-16T14:57:00",38,"// раком?",215802,null],[215805,"2026-09-16T14:57:19",8,"/рядом/",191019,null],[215807,"2026-09-16T14:58:00",11,"*«Неожиданный запах для этого злачного места» — подумает девушка и пойдёт в направлении его источника",215800,null],[215811,"2026-09-16T14:58:34",8,"*Изольда понимает ситуацию. \"Бордель есть, но парень туповат\"*",191019,null],[215813,"2026-09-16T14:58:57",38,"Пока вы подходили рассказчик начал говорить так, будто рассуждал о чем-то великом и строил теории, что решат судьбу мира.\n\n— Я занимался исследованием, что за профессия у моей жены, но из-за узости кругозора и недостатка знаний понять не мог. Похоже, я так никогда и не узнаю, что за профессия у моей жены.\nМоя жена носила только новые носки. И готовила еду. Хотя сам я ни разу не видел, чтобы она готовила, она всегда приносила мне что-нибудь поесть, когда наступало время завтрака или ужина. А в нашем доме никого не было, кроме меня и моей жены. Так что, без сомнения, еду жена готовила своими руками.\nЖена никогда не звала меня к себе в комнату. Я всегда ел один и спал один в дальней комнате. Еда была невкусная. И закуски никудышные. И хотя я быстро все проглатывал, как курица или щенок, порой я укорял жену за бездушие. Мое лицо высохло и стало совсем бледным. Силы убывали день ото дня. Из-за недостатка питательных веществ из меня тут и там стали торчать кости. Ночью я никак не мог улечься, переворачивался десятки раз - то тут, то там невыносимо давило.\nПоэтому в постели я обычно не размышлял об источнике денег, которыми так свободно распоряжалась жена, а представлял, как еда, ускользая через щелку в двери, появляется в другой комнате. Сон никак не шел.\nЯ понял. Я понял, что деньги, без сомнения, оставляли те странные посетители, которые раньше мне казались просто никчемными людишками. Но я никак не мог вникнуть, в чем суть обычая, который заставлял этих посетителей оставлять деньги, а жене позволял принимать их.\nБыл ли это просто обычай? Или это была плата? А может быть, награда? Может быть, моя жена казалась им несчастным существом, заслуживающим сострадания?\nКак подумаю об этом, мысли начинают путаться. Хотя все заключения, к которым я прихожу, прежде чем заснуть, неприятны, я ни разу ни о чем не спросил жену. И не только потому, что она наверняка была бы раздражена, но и потому, что, как все люди, выспавшись, к утру обо всем начисто забываю.\nКогда жена возвращается домой или выпроваживает посетителей, она переодевается в домашнюю одежду и заходит проведать меня. Приподняв одеяло, она наклоняется к моему уху и пытается подбодрить меня парой веселых слов. С улыбкой на лице - ни веселой, ни грустной, ни насмешливой - я смотрю на красивое лицо жены. Жена ласково улыбается. Но разве может от меня укрыться смутная печаль на ее лице…\nЖена сразу замечает, если я голоден. Но не приносит мне еду, что остается у нее в комнате. Конечно же потому, что не хочет унижать меня. Несмотря на голод, мне приятно чувствовать уверенность в этом. Все, что говорит мне жена, влетает в одно ухо и вылетает в другое. И только у изголовья постели остается блестящая в свете серебряная монетка, которую жена кладет, прежде чем уйти.\nСколько же этих серебряных монеток набралось в сейфе-копилке? Я никогда не взвешивал ее. Безо всякого интереса и желания я бросаю серебряные монетки в щелку размером с пуговичную петлю.\nЯ никак не мог понять, зачем жена дает мне деньги, так же, как я не мог понять, зачем посетители дают деньги ей. Мне не было неприятно получать от жены деньги, но единственная пустяковая радость от серебряных монеток - подержать их на ладони, а потом монетки бесследно исчезают в пасти копилки.\nВ один прекрасный день я выкинул эту копилку в помойную яму. К тому времени серебряных монеток в ней уже набралось немало, не знаю, правда, сколько именно.\nСтоило мне подумать о том, что Земля, на которой я живу, стремительно несется в бесконечном пространстве, все начинало казаться бессмысленным. Чувствуя головокружение на вертящейся Земле, я хотел побыстрее спрыгнуть с нее.",191019,null],[215814,"2026-09-16T14:58:57",38,"Когда я под одеялом размышлял об этом, монетки начинали вызывать у меня отвращение. Одно время я надеялся, что моя жена сама станет пользоваться копилкой. На самом деле, и копилка, и деньги нужны были только ей, а для меня никогда не представляли ценности, и я ждал, когда же жена наконец заберет копилку к себе в комнату. Но она все не забирала. Однажды мне даже пришло в голову самому отнести копилку в ее комнату, но именно тогда гостей было особенно много, и у меня не было никакой возможности попасть туда. Делать нечего, пришлось выбросить копилку в помойную яму.\nС тяжелым сердцем я ждал, что жена будет бранить меня. Но она не сказала ни слова. Мало того, она, похоже, продолжала оставлять мне деньги. Потому что у изголовья незаметно снова собралась целая куча монеток.",191019,null],[215825,"2026-09-16T15:01:43",8,"– Как думаешь, зачем ты нужен своей жене? *спрашивает парня серьёзно*",191019,null],[215835,"2026-09-16T15:03:55",38,"Мужчина открыл немного глаза и вздрогнув от чужого голоса сказал.\n— Разве она не любит меня?",215825,null],[215841,"2026-09-16T15:04:26",8,"– Она это говорила? *ждёт остальных для поддержки*",191019,null],[215848,"2026-09-16T15:05:44",38,"— Не знаю...\n\nГрустно ответил юноша.",215841,null],[215849,"2026-09-16T15:05:55",41,"— Понимаю..",215794,null],[215852,"2026-09-16T15:06:34",11,"*Аури встаёт в дверном проёме\n\n— У тебя есть мечты? Не связанные с женой, чего-то что хотелось бы тебе независимо от неё",191019,null],[215853,"2026-09-16T15:06:49",8,"– В чём заключается любовь, если ты её не слушаешь, а она тебя кормит бурмалдой? *улыбается*",215848,null],[215860,"2026-09-16T15:07:51",11,"— Мне кажется ты спешишь, Изольда",215853,null],[215862,"2026-09-16T15:08:00",41,"— что ты думаешь, когда вспоминает о ней?",191019,null],[215870,"2026-09-16T15:08:49",11,"вздох\n*Девушка решает просто наблюдать",191019,null],[215872,"2026-09-16T15:09:07",8,"*молчит, слушая диалог*",191019,null],[215885,"2026-09-16T15:12:01",38,"Мужчина задумался немного и вы начали слышать шипение рассказчика, что затем спокойно продолжил повествование.\n— Под одеялом я занимался исследованием, была ли какая-нибудь причина, кроме удовольствия, по которой посетители оставляли деньги моей жене, а она - мне. Я продолжал думать. Если дело было в удовольствии, то каком? Не было никакого способа выяснить это, не вылезая из-под одеяла. Удовольствие, удовольствие,… неожиданно я почувствовал интерес к этому вопросу.\nЖена фактически держала меня взаперти. Правда, мне не на что было жаловаться. И все-таки хотелось бы знать, существует ли это удовольствие на самом деле.\nОднажды вечером, когда жена ушла, я, воспользовавшись случаем, выбрался из дома. Я прихватил с собой серебряные монетки и на улице обменял их на бумажки. Получилось пять бумажек. Я положил их в карман и отправился слоняться по городу. Улицы, которых я так давно не видел, не могли не растревожить мои нервы, словно какое-то чудо. Я быстро устал. Но терпел. До поздней ночи, забыв, зачем вышел, я бесцельно шатался по улицам. Не потратил ни монетки. Даже желания ни разу не возникло. Я, похоже, напрочь утратил способность тратить деньги.\nЯ больше не мог выносить усталость. С трудом я отыскал свой дом. В мою комнату можно было попасть только через комнату жены, и я беспокоился, нет ли у жены гостей. Перед дверью я смущенно кашлянул, дверь как-то сама собой отворилась, и, к своему ужасу, я увидел обращенное ко мне лицо жены, а за ее спиной лицо незнакомого мужчины. Я замешкался, ослепленный внезапно хлынувшим светом.\nЯ, конечно, видел выражение глаз жены. Но мне ничего не оставалось, кроме как притвориться, что я ничего не замечаю. Почему? Да потому, что мне в любом случае пришлось бы пройти через ее комнату…\nЯ залез под одеяло. Ноги болели невыносимо. Под одеялом сердце мое бешено колотилось, еще немного, и я потерял бы сознание. Я задыхался так, как не задыхался по пути. На спине выступил холодный пот. Я уже жалел, что вышел из дома. Скорее бы заснуть и забыть об этой усталости. Я хотел забыться.\nСколько же я пролежал поперек постели лицом вниз, пока мое сердце не угомонилось? По крайней мере, остался жив. Я перевернулся, улегся, устремив взгляд в потолок, и вытянул ноги.\nНо новых волнений было не избежать. Из передней комнаты сквозь щель между раздвижными дверями доносились обрывки слов жены и того мужчины - они шептались так тихо, что я не мог ничего разобрать. Я открыл глаза. И задержал дыхание. И тут я услышал, как моя жена и мужчина, отряхиваясь, поднялись, а мужчина, вставая, надел пальто и шляпу, затем открылась входная дверь, донесся стук каблуков - это мужчина, а вслед за ним и моя жена спустились во двор, - а потом и тяжелые, и легкие шаги удалились по направлению к воротам. Я никогда не видел, чтобы жена себя так вела. Она ни с кем не шепталась. Лежа в дальней комнате под одеялом, я, бывало, не понимал, о чем болтали заплетающимися языками нетрезвые посетители, но я не упускал ни одного слова, ни громко, ни тихо произнесенного моей женой. Если она и говорила что-нибудь режущее слух, меня успокаивал ровный тон ее голоса. Я чувствовал себя неуютно, понимая, что у жены наверняка есть какая-то особая причина для подобного поведения, но я слишком устал и, твердо решив никакими исследованиями сегодня не заниматься, попытался заснуть. Но сон никак не шел. И жена, вышедшая за ворота, долго не возвращалась. Засыпая, я продолжал блуждать среди расплывчатых пейзажей улиц. \n\nЮноша же ответил на вопрос.\n— Я хочу быть свободен... Но... Я и так свободен именно настолько, сколько хочу... Когда-то у меня были крылья...",191019,null],[215888,"2026-09-16T15:12:36",9,"— Не те вопросы вы задаёте. — *Вордо вздыхает и его ноги отрываются на фут от земли, он влетает в грязную комнату похоже принадлежащую этому парню и левитируя в воздухе спрашивает его.* — Ты должен ответить на один единственный вопрос, слушай его внимательно, повторять его не буду.\n\n*Вордо звучал уверенно, четко, создавалось впечатление что он точно знал о чем говорил.*\n\n— Где твои крылья И Сан.",191019,null],[215894,"2026-09-16T15:14:06",8,"– Вордо, мне кажется, он спит *твёрдо* и его пора будить",191019,null],[215896,"2026-09-16T15:14:51",38,"Мужчина резко поворачивает тело к Вордо и на его лице появилась грусть. Он ответил.\n— Они куда-то делись... Я и не помню когда...",215888,null],[215912,"2026-09-16T15:20:03",9,"— Сидя в этом клоповнике, в грязном углу, не видя света, ты не найдёшь ответа. Крысой сгниёшь или птицей взлетишь, ты должен отыскать свои крылья сам, ты должен отыскать свои крытья сам. Тебе никто не сможет помочь, ни мы, ни твоя жена ни её посетители, только ты сам, найди свои крылья. — *Вордо закончил свой монолог и взмахнув плащом словно видение вынырнул из этой грязной комнаты в более чистую, его сапоги снова встали на пол.*\n\n// Щас песню скину",215896,null],[215914,"2026-09-16T15:21:14",9,"https://youtu.be/Hoa8_wqnZvo?si=rp5Fj_noqNrEEntz",191019,null],[215915,"2026-09-16T15:21:20",38,"// Кофе помогает от альцгеймера, кофе помогает от альцгеймера",215912,null],[215917,"2026-09-16T15:22:15",9,"//Я спецом тут повторил чтобы сделать акцент на важности слов и эти слова должны зацепиться в уме сильнее чем красивая рамка из слов)",215915,null],[215920,"2026-09-16T15:22:54",8,"– Ты молод, и всё впереди. Время – вот что главное. А здоровье восполнить куда легче. И мозги есть. Разве не хорошо?",191019,null],[215921,"2026-09-16T15:23:14",8,"*отошла, но контролирует окно*",191019,null],[215922,"2026-09-16T15:23:26",38,"Мужчина посмотрел на тебя еще некоторое время и повернувшись к углу сказал.\n— Прошу... Покиньте мою комнату...",215912,null],[215925,"2026-09-16T15:24:41",8,"/Аури, Лети, помогите, из нас психологи не очень/ *просительно смотрит на девушек*",191019,null],[215927,"2026-09-16T15:25:14",41,"( я еще перевариваю эти текста",191019,null],[215929,"2026-09-16T15:25:57",11,"// я оставлю комментарии об этом на конец сессии..",215927,null],[215934,"2026-09-16T15:26:32",11,"*вздыхает",215925,null],[215935,"2026-09-16T15:27:12",11,"— Нет не покинем — подходит и стягивает с него одеяло — давай подымайся, ты пойдешь с нами, это не обсуждается",215922,null],[215936,"2026-09-16T15:27:34",11,"*откидывает одеяло и протягивает руку",191019,null],[215937,"2026-09-16T15:27:54",8,"*\"Грязь, грязь\" *чистит всё, что можно, фокусами*",191019,null],[215939,"2026-09-16T15:28:11",41,"— Может вам лучше сбежать в неизвестность? Меня Это привело к любви...а вас...может быть и к крыльям",191019,null],[215940,"2026-09-16T15:28:36",11,"— На улице прекрасная погода, солнце светит. Готова поспорить ты давно солнечного света не видал. Пора выйти и насладиться им, а затем пойти в какую-то лавку и поесть чего-то вкусненького, я заплачу, за мой счёт",191019,null],[215983,"2026-09-16T15:38:17",38,"Голос рассказчика начал говорить снова очень ломано и будто, кто-то ломал связь и мешал ему говорить.\n— Кто-то яростно тряс меня. Это жена, проводив гостя, вернулась и принялась меня будить. Я открыл глаза и взглянул ей в лицо. Улыбки на лице не было. Я потер глаза и вгляделся пристальнее. Глаза жены гневно сверкали, тонкие губы подрагивали. Было похоже, что гнев ее пройдет нескоро. Я закрыл глаза. Ждал, когда грянет гром. Но раздался только вздох, шелест подола и шум закрываемой двери - жена ушла к себе в комнату. Я повернулся, опять натянул на голову одеяло, распластался на животе, как лягушка, и, забыв о голоде, всей душой ощутил раскаяние по поводу вечерней прогулки.\nПод одеялом я извинялся перед женой. Я был не прав…\nЯ в самом деле думал, что уже глубокая ночь. Я и представить себе не мог, что, как ты сказала, еще не было полуночи. Я слишком устал. Зря я так долго гулял, ведь я так давно не выходил на улицу. Если в чем и есть моя вина, то только в этом. Спрашиваешь, зачем я вышел?\nЯ хотел кому-нибудь отдать пять купюр, которые сами собой накопились у изголовья моей постели. И только-то. Если скажешь, что я виноват, я пойму. Разве я не раскаиваюсь?\nЕсли бы я знал, на что можно потратить эти пять бумажек, я не вернулся бы домой до полуночи. Но улицы были слишком оживленными, людей слишком много. Я не мог сообразить, кого из них выхватить, чтобы отдать деньги. Я невыносимо устал, пока думал об этом.\nБольше всего на свете я хотел отдохнуть. Хотел лечь. Делать нечего, пришлось вернуться домой. По моим подсчетам получалось, что было довольно поздно, а на самом деле еще не было полуночи. Я сожалею. Готов просить прощения сколько угодно. Но какой смысл в этих извинениях, если они все равно не помогут мне наладить отношения с женой? Печально.\nЯ метался в тревоге целый час. Отшвырнув одеяло, я встал, отодвинул дверь и влетел в комнату жены. Я едва соображал. Помню только, что бросился на постель жены, достал из кармана и вложил жене в руку пять бумажек.\nКогда я проснулся на следующее утро, то увидел, что лежу в постели жены в ее комнате. Впервые с тех пор, как мы стали жить в доме тридцать три.\nСолнце заглядывало в форточку, и жена уже ушла - рядом со мной ее не было. А может быть, она ушла вчера ночью, пока я был без сознания. Но у меня не было желания заниматься исследованием. Все тело ломило, не было сил даже пальцем пошевельнуть. Глаза слепили лучи, освещавшие квадратик пола размером с платок для книг. В лучах кружились бесчисленные пылинки, похожие на микробов. Норовили забиться мне в нос. Я снова закрыл глаза, накрылся одеялом и попытался заснуть. Но забравшийся в нос запах тела жены взволновал меня. Как ни пытался, я не мог заснуть, ворочаясь и вызывая в памяти запахи всевозможных скляночек с косметикой, выстроенных на туалетном столике жены, и запахи крышечек, которые я из этих скляночек вытаскивал.\nНе в силах сдержаться, я отпихнул одеяло, встал и ушел в свою комнату. Там уже стояла еда. Прежде чем уйти, жена позаботилась о моем пропитании. Вроде бы я хотел есть. Но когда поднес ложку ко рту, еда оказалась холодной, как остывшая зола. Моя постель, пустовавшая всю ночь, была рада снова принять меня. Натянув на голову одеяло, измотанный, я погрузился в глубокий сон. Сразу же…\nЯ проснулся, когда пора уже было зажигать свет. Но жена еще, похоже, не вернулась. А может быть, она возвращалась опять вышла? Но зачем было размышлять об этом.\nЯ пришел в себя. И попытался вспомнить события прошлой ночи. Я не мог даже объяснить, что за чувство испытал, когда рухнул, протянув жене пять бумажек. Я очень обрадовался, раскрыв, как мне показалось, тайную психологию посетителей, оставлявших деньги моей жене, и психологию жены, оставлявшей деньги мне. Я улыбнулся сам себе. Как же смешон я был, как жил до сегодняшнего дня, не понимая этого? Мои плечи затряслись.",191019,null],[215984,"2026-09-16T15:38:17",38,"Я, конечно, тут же захотел сегодня вечером снова выйти на улицу. Но денег не было. Я жалел, что вчера вечером отдал жене все деньги сразу. Раскаивался в том, что выкинул в помойную яму копилку. В разочаровании я по привычке пошарил рукой в кармане, где лежали когда-то пять вон. Неожиданно рука что-то нащупала. Всего две бумажки. А мне больше и не надо. Сгодится. Я обрадовался и тому, что было.\nЯ обрел силу. Натянул свой единственный изношенный плисовый костюм и, забыв и думать о голоде и своем неприглядном виде, вышел на улицу, размахивая руками. Выходя, я горел желанием, чтобы время - «Умоляю!» - пролетело стрелой, и скорее бы настала полночь. Как хорошо было бы, отдав деньги жене, снова провести ночь в ее комнате, но очень уж я боялся по ошибке вернуться домой до полуночи и разгневать ее. До темноты я бесцельно блуждал по улицам, снова, снова и снова поглядывая на часы. На этот раз я совсем не устал. Жалко только, что время тянулось слишком медленно.\nТолько убедившись, что часы на центральном вокзале показывают полночь, я направился к дому. В тот день я встретил жену и ее друга в воротах - они стояли и разговаривали. Я сделал вид, что не заметил их, и прошел в свою комнату. Следом вошла жена. Принялась на ночь глядя убираться, чего никогда раньше не делала. Услышав, что жена легла, я отодвинул дверь, вошел к ней в комнату и быстро протянул ей две бумажки. Жена несколько раз украдкой взглянула мне в лицо, будто удивляясь, что я и сегодня не потратил деньги, а принес их обратно, - в конце концов она, не сказав ни слова, уложила меня в своей комнате. Я не променял бы эту радость ни на что на свете. Я спал отлично. \n\nЮноша повернулся к вам и подумав ответил.\n— Я уже выходил на улицу... Да, там свежо, но дома у меня есть жена и то, что она рядом уже приносит мне счастье...\n Живот юноши резко проурчал и он все же подумав сказал.\n— Хорошо... Только сегодня...",191019,null],[215988,"2026-09-16T15:39:56",11,"— Вот и отлично — Аури все ещё держит руку ожидая что мужчина за нее возьмётся — что бы ты хотел поесть?",191019,null],[215989,"2026-09-16T15:41:06",8,"*закончила чистку комнаты и шлифанула фокусами одежду И Сана. Замагичила запах свежей тайги*",191019,null],[215992,"2026-09-16T15:42:38",8,"– И, неба ради, давай купим тебе нормальную одежду для прогулок. *волчица засмеялась по-собачьи, словно прочтя мысли*",191019,null],[216003,"2026-09-16T15:46:16",38,"Юноша встает с матраса сам и посмотрев по сторонам вытащил из-за матраса плисовый костюм и надев его поверх свитера сказал.\n— Можно и просто кофе...\n Заметив, что комната резко стала чистой, а приятной.\n— Магия?",191019,null],[216006,"2026-09-16T15:47:02",8,"– Есть немного. Вот видишь, что творит хорошее настроение)",191019,null],[216011,"2026-09-16T15:47:17",11,"— Угу, тебе нравится магия?",191019,null],[216013,"2026-09-16T15:47:35",38,"— Ну... Я все еще болею простудой...\n— Не знаю...",191019,null],[216024,"2026-09-16T15:51:34",8,"– Звучит как повод зайти к местному травнику... Сразу так много пунктиков *радостно*",191019,null],[216025,"2026-09-16T15:51:40",11,"— Тогда давай зайдём к травнику и возьмём тебе какую-то хорошую настойку или.. хм.. я не видела здесь полей в окрестностях, но мы могли бы поискать и собрать там трав самостоятельно! А затем заварить из них теплый лечебный чай, а ещё бы не мешало купить тёплого меда, ты любишь мед?",216013,null],[216028,"2026-09-16T15:52:10",38,"— У меня нету денег...\n Ответил И Сан.",191019,null],[216029,"2026-09-16T15:52:16",11,"*последнее Аури начинает тараторить с энтузиазмом. Ей самой нравится идея отправится гулять на природу",191019,null],[216030,"2026-09-16T15:52:25",41,"— мы угостим сегодня",191019,null],[216031,"2026-09-16T15:52:51",11,"*кивает\n\n— И травы на поле бесплатные, хехе! Знаешь тут фермеров каких которые медом торгуют?",191019,null],[216032,"2026-09-16T15:53:13",8,"– А дальше найдёшь себе применение. У тебя отлично варит голова",216030,null],[216033,"2026-09-16T15:53:29",38,"— Тут нету хороших полей или садов в округе...",191019,null],[216034,"2026-09-16T15:54:04",8,"– Городской садик, может быть?",191019,null],[216035,"2026-09-16T15:54:06",11,"— Бууу — она надула щеки как лягушка и сразу же сдулась — а как далеко ближайшие? Я бы сказала что это не проблема, так даже лучше! Нужно выбраться и развеяться",216033,null],[216040,"2026-09-16T15:55:02",41,"На колени И сел кот!",191019,null],[216042,"2026-09-16T15:55:41",41,"Мрррр мрррр мрррр",191019,null],[216043,"2026-09-16T15:55:45",11,"— Так, ладно, хватит стоять без дела, пошли сперва перекусим чего!\n\n*Заметив движения пушистого друга Летиции \n\n— Он отлично помогает поднять настроение, советую его погладить!",191019,null],[216044,"2026-09-16T15:56:52",38,"— Хм... Не знаю...\n Ответил юноша и продолжил смотреть на свою уже чистую комнату.\n\n// Мне придется остановиться на этом до 19 помск, мне к репетитору надо.",191019,null],[216051,"2026-09-16T15:58:34",11,"*Направилась к выходу зовя за собой \n\n— Просто пошли за нами, а там втянешься",216044,null],[216052,"2026-09-16T15:58:35",8,"*отошла к окну в основной комнате, ищет взглядом прикольные места и немного блокирует доступ* /на этом заявка всё/",191019,null],[216053,"2026-09-16T15:58:51",8,"/roll 1d20+3",191019,null],[216056,"2026-09-16T16:00:01",41,"— любое место может стать прекрасным в хорошей комнапии\n\nПока они собираются, Летиция заштопает его одежду",191019,null],[216112,"2026-09-16T16:22:51",11,"*пока остальные собираются девушка быстренько чирканет что-то на пергаменте и передаст записку Изольде\n\n[ Кажется Повествователь (голос рассказывающий нам сюжет) не хочет что бы мы ломали историю, а я хочу. Предлагаю проверить что будет если мы действительно сильно отдалимся от места действия событий вместе с героем. Заодно попробуем ему показать прелести жизни и не торопитесь с давлением на него!\n\nP.s. Передай остальным]",191019,null],[216129,"2026-09-16T16:27:59",8,"*передала записку Летиции с еле заметным кивком* /школьники за партой/ *держа руку за спиной, естественно*",191019,null],[216141,"2026-09-16T16:30:47",8,"*вернулась к окну* /до 19/",191019,null],[216207,"2026-09-16T16:51:03",41,"Летиция передает записку Ворду и кивает Изольде",216129,null],[216223,"2026-09-16T16:54:31",9,"*Вордо читает и долго не думая передает записку волчице.*",191019,null],[216231,"2026-09-16T16:59:14",8,"*Волчица сжевала записку, как заправский шпион*",191019,null],[216233,"2026-09-16T16:59:30",11,"*Аури смотрит грустно на ее бедный пергамент",191019,null],[216234,"2026-09-16T16:59:54",9,"//Простите, это того стояло",191019,null],[216235,"2026-09-16T17:00:04",11,"*но волчицу погладит",191019,null],[216290,"2026-09-16T17:11:34",8,"/ещё: Изольда, Аури, Вордо, Летиция, кот и волчица получают по 6 вхп/",191019,null],[216538,"2026-09-16T18:30:36",38,"И Сан ещё немного посмотрел на комнату и всё же пошел за вами на улицу.\n\nИзольда видела только здания в окне и очень далеко было видно парк, с холмом.",191019,null],[216555,"2026-09-16T18:33:09",8,"– Вдалеке живописный парк с холмом, пойдём в том направлении \"мысли: похож на курган, мило; но парень сейчас и так расстроен\" *указала туда*",191019,null],[216570,"2026-09-16T18:34:30",9,"*Вордо идет и смотрит по сторонам, чтобы их угроза, тот человек с бабочкой, не стал внезапностью.*",191019,null],[216586,"2026-09-16T18:36:22",11,"*А Аури идёт впереди и вынюхивает может где пахнет чем вкусным \n\n— Тебе что больше нравится? Мясо? Сладости? Рыба может? — Спрашивает героя",191019,null],[216590,"2026-09-16T18:36:42",38,"— Кофе...",216586,null],[216599,"2026-09-16T18:38:15",11,"— Кофе не еда, но его тоже закажем, впрочем при простуде лучше чай!",191019,null],[216607,"2026-09-16T18:38:44",11,"— Ладно, а какой кофе? Простой или с добавками какими?",191019,null],[216613,"2026-09-16T18:40:03",8,"/roll 1d20+3\n*Изольда пока слушает и ищет лекарьскую лавку*",191019,null],[216663,"2026-09-16T18:46:52",38,"— Капучино...\n Ответил И Сан.\n\nВы вышли к одной из площадей. Юноша заметил небольшое заведение и надпись рядом, Центральный вокзал.\n— О... Давайте пойдем поедим там...",216607,null],[216672,"2026-09-16T18:47:50",8,"– Как хочешь. А там с животными пускают?",191019,null],[216675,"2026-09-16T18:48:02",11,"*читает надпись и уже думает что удачное местечко, подмигивает остальным \n\n— Конечно, почему бы и нет?",191019,null],[216678,"2026-09-16T18:48:23",11,"— Мне кажется раз они на нас внимания не обращают то и на Вьюгу не должны",216672,null],[216680,"2026-09-16T18:48:34",38,"— Не знаю... Давайте посмотрим...\n И Сан подошел к двери и там не было знака о запрете.\n— Нету...",216672,null],[216683,"2026-09-16T18:48:48",11,"*Открывает дверь \n\n— Прошу, дамы и господа",191019,null],[216686,"2026-09-16T18:49:04",8,"/@sweetkittywitch/",191019,null],[216688,"2026-09-16T18:49:25",11,"*заходит следом за остальными и осматривается\n\n// Это реально вокзал или просто странное название кафе?",191019,null],[216691,"2026-09-16T18:50:18",9,"/roll 1d20+1 восприятие прокину и будем пить капучино",216570,null],[216704,"2026-09-16T18:52:22",9,"*Вордо очень внимательно осматривался, нет ли их противника где то рядом, только после зашёл вместе с девушками и их грузом (И Саном) в заведение или место куда они собирались. Он ьы и сам попробовал Капучино или Латте с Американо, конечно если предложат, то хоть все три, названий пока не знал заморских.*",191019,null],[216706,"2026-09-16T18:53:14",38,"Это было заведение в крыле вокзала. Тут были отведены лишние столы и даже ходили официанты и бариста.\n И Сан сел за стол у окна и начал перебирать карманы своего костюма.",216688,null],[216708,"2026-09-16T18:54:00",8,"*девушка, удивлённая новой обстановкой, смотрела во все глаза, но держала Вьюгу крепко на поводке*\n/как выглядит кафе?/",191019,null],[216709,"2026-09-16T18:54:33",41,"( Сори ем",216686,null],[216710,"2026-09-16T18:54:37",11,"— Займите тогда столик, я пойду закажу, чего вам, ребята?",216706,null],[216712,"2026-09-16T18:56:14",8,"– Суп, мясо, овощи, по старинке *впечатлённо оглядывает кафе*",191019,null],[216713,"2026-09-16T18:56:21",9,"— Монеты здесь принимают? — *Вордо показывает пару золотых меж пальцами тому кто похожна официанта или продавца.*",191019,null],[216718,"2026-09-16T18:56:53",38,"Как таверна, но столы были не большими, а круглыми и не больше 6 человек вкруг. Имело стол, как и у Трактирщиков, где готовили напитки, а за баром была дверь, похоже на кухню.",216708,null],[216720,"2026-09-16T18:57:36",38,"— Ох... Вам бы обменять золотые на серебряные, а их на купюры...\n Отвечает ближайшая официантка.",216713,null],[216721,"2026-09-16T18:57:41",11,"*подойдёт туда посмотрит за другими людьми как тут принято заказы делать нет ли очереди",216718,null],[216722,"2026-09-16T18:58:00",11,"— Обменять? А где?",216720,null],[216723,"2026-09-16T18:58:21",8,"– Милая девушка, а как выглядят купюры?)",216720,null],[216724,"2026-09-16T18:58:28",9,"— Золотой много стоит? Нам сообразить прекрасный обед на пятерых.",216720,null],[216731,"2026-09-16T18:59:25",41,"— тут всё так по особенному...",191019,null],[216732,"2026-09-16T19:00:00",8,"– Такие столики изящные, прямо кукольные",191019,null],[216733,"2026-09-16T19:00:21",38,"Ты заметила, что официанты подходят к каждому столику и делают заказы на месте. Похоже здесь система обслуживания.\n\n— Ох... Купюры вы можете обменять в банке, он через пару кварталов около сквера Бабочек. По поводу их соотношения, то одна серебряная это одна купюра номиналом вон.",216721,null],[216737,"2026-09-16T19:01:01",11,"// обычно на вокзале есть уже обменники👉👈",191019,null],[216741,"2026-09-16T19:01:36",8,"/это 1937 или 1965, так что хз",191019,null],[216743,"2026-09-16T19:01:48",38,"// На корейском полуострове начала 20 века их еще не было",216737,null],[216744,"2026-09-16T19:01:59",38,"// 37",216741,null],[216748,"2026-09-16T19:02:43",11,"— Хм.. спасибо, а вы не принимаете серебряные?",216733,null],[216750,"2026-09-16T19:03:14",38,"— Давайте я уточню у заведующего...\n Девушка поклонилась и ушла в сторону стойки бара.",216748,null],[216754,"2026-09-16T19:04:00",11,"*пока ожидает немного подтанцовывает от нетерпения. Отойдет к окну посмотреть на сам «вокзал»",191019,null],[216756,"2026-09-16T19:04:24",8,"*когда девушка ушла*\n– Если не получится, я сбегаю до банка, мне несложно",191019,null],[216757,"2026-09-16T19:05:03",9,"*Вордо слегка недовольный заминкой садится за столик.*\n\n— Излишние трудности.",191019,null],[216760,"2026-09-16T19:05:51",8,"– Не вини чужой мир за наличие своих правил *ободряюще, ждёт*",191019,null],[216761,"2026-09-16T19:05:54",41,"Лети слегка трясет Аури от восторга при виде вокзала :D",216754,null],[216762,"2026-09-16T19:06:06",38,"В окне ты увидела небольшую каменную платформу и странные железные или стальные линии. Похоже по ним что-то двигается.\n Вместе с этим тут было много этих карет на невидимых лошадях.",216754,null],[216765,"2026-09-16T19:06:25",8,"/фестралы 100 проц./",216762,null],[216768,"2026-09-16T19:06:44",11,"— Тебе тоже интересно там погулять?",216761,null],[216771,"2026-09-16T19:07:19",11,"— Смотри, там двигаются большие железные штуки! Хочу посмотреть на них поближе",216762,null],[216775,"2026-09-16T19:08:14",38,"— Лучше не подходить дальше чем за желтую линию на станции... Поезда могут и не вовремя остановиться...",216771,null],[216777,"2026-09-16T19:08:31",11,"— Поезда? Так называются эти железные штуки?",191019,null],[216778,"2026-09-16T19:08:36",38,"Ответил И Сан и поймав официантку заказал крепкий кофе.",191019,null],[216779,"2026-09-16T19:08:42",38,"— Все верно...",216777,null],[216781,"2026-09-16T19:09:02",11,"— Ооо, спасибо, а зачем они нужны? — она тут же вернулась обратно и села рядом с И саном",191019,null],[216783,"2026-09-16T19:09:38",41,"— Да! Да! Да!",216768,null],[216784,"2026-09-16T19:09:55",38,"Юноша подумал и сказал.\n— Чтобы перевозить грузы более надежным, быстрым и спокойным способом. Они способны вести 24/7 товар из точки а в точку б...",191019,null],[216785,"2026-09-16T19:10:21",8,"– Быть того не может *глаза сияют*",191019,null],[216789,"2026-09-16T19:10:52",8,"– Лошади классные, но это впечатляет",191019,null],[216791,"2026-09-16T19:11:20",11,"— Ого! Это как повозки, только намного больше и без коней, звучит и удобно и неудобно одновременно — она задумалась — а людей они возят?",216784,null],[216795,"2026-09-16T19:12:25",11,"*оглянется где та официантка с которой они говорили, не вышла ли ещё",191019,null],[216800,"2026-09-16T19:15:31",38,"— Да...\n Ответил И Сан и как раз к этому моменту подошла официантка и рядом с ней мужчина.\n— Здравствуйте, мне сказали вы хотите оплатить золотыми, это так?",191019,null],[216802,"2026-09-16T19:15:55",8,"*показала монету*",191019,null],[216805,"2026-09-16T19:17:08",38,"— Хорошо... Мы можем принять у вас оплату в монетах, что вы собираетесь заказать?\n Спросил мужчина.",216802,null],[216806,"2026-09-16T19:17:36",11,"*мырг-мырг\n\n— ..А что можно? — глупо улыбается",191019,null],[216807,"2026-09-16T19:18:11",11,"— Простите, мы тут не местные, поможете разобраться? — неловко хихикнет",191019,null],[216809,"2026-09-16T19:18:40",8,"– Какие супы есть, например? *ей тоже неловко за незнание*",191019,null],[216810,"2026-09-16T19:18:51",38,"— У нас есть простые блюда, закуски, напитки и еще салаты с ланчами.",216806,null],[216813,"2026-09-16T19:19:33",9,"— Сколько стоит нам сообразить отличный обед на пятерых с кофем и десертами на ваш вкус?",216810,null],[216815,"2026-09-16T19:19:56",8,"– Прекрасный И Сан, что будете? Напитки не еда ведь",191019,null],[216818,"2026-09-16T19:20:38",11,"*пытается взглядом найти меню только сейчас о нем вспомнив",191019,null],[216819,"2026-09-16T19:20:39",8,"– Что в вашем мире вкуснее всего?",191019,null],[216820,"2026-09-16T19:20:52",11,"— Она хотела сказать в вашей стране да\n*Кхм",216819,null],[216821,"2026-09-16T19:20:58",9,"— Как вы поняли мы не местные. Большинство блюд и их названия нам ни о чем не говорят. — *Показывает на меню, и спроашивает девушек.* — У вас есть предпочтения в еде?",191019,null],[216823,"2026-09-16T19:21:37",11,"— Я люблю водоросли, но не люблю морепродукты",191019,null],[216824,"2026-09-16T19:21:45",8,"*ждёт ответа И Сана про самое вкусное*",191019,null],[216826,"2026-09-16T19:22:24",11,"// а там случаем нет десертов с кофе?",191019,null],[216828,"2026-09-16T19:22:51",9,"//Все учёл ^^",216813,null],[216833,"2026-09-16T19:24:18",38,"— Хм... Если соотносить одну золотую к десяти серебряным, то у вас это выйдет в 10 золотых.\n Ответил мужчина.\n\nИ Сан же ответил.\n— Тогда еще мне Пибимпап...\n\nМужчина же продолжил.\n— Могу предложить вам кимчи, пибимпап, бульгоги, самгёпсаль, кимпаб...",191019,null],[216834,"2026-09-16T19:24:26",8,"/Вордо в звёздном виде?/",191019,null],[216841,"2026-09-16T19:25:09",8,"– Пибимпап? Надо попробовать. И водорослей немного",191019,null],[216843,"2026-09-16T19:25:48",11,"*пытается повторить названия запоминая, но совершенно не понимая значения \n\n— Мне что-то что бы без морепродуктов пожалуйста, а остальным то что они просят\n*Протянет 10 монет",191019,null],[216849,"2026-09-16T19:27:15",9,"*Вордо достаёт 10 золотых и собирался отдать их, как его уже опередили.*\n\n— Хорошая цена для такого места, надеюсь бы нас не разочаруете. — *Спрятал обратно, чего уж там. Но выглядит очень важно.*",216833,null],[216852,"2026-09-16T19:28:10",38,"— Так... Вам всем 5 блюд и напитки, верно?",191019,null],[216855,"2026-09-16T19:28:22",11,"*кивает важно",191019,null],[216857,"2026-09-16T19:28:35",8,"– Кофе, да",191019,null],[216859,"2026-09-16T19:29:03",38,"— Хорошо... Прошу, ожидайте...\n Отвечает мужчина и официант уходят.",191019,null],[216862,"2026-09-16T19:29:39",41,"— Мне много не надо)",191019,null],[216865,"2026-09-16T19:30:27",8,"– К слову, тебе по душе \"поезда\", как и кофе? *у И Сана*",191019,null],[216866,"2026-09-16T19:31:02",38,"— Мне по душе мой дом... И наверное улица...",191019,null],[216868,"2026-09-16T19:32:36",8,"– А люди?",191019,null],[216869,"2026-09-16T19:32:49",38,"— У меня есть жена...",191019,null],[216870,"2026-09-16T19:32:51",11,"— А что думаешь про природу и животных?",216866,null],[216875,"2026-09-16T19:37:17",38,"— Думаю я бы завел себе Ворона, такого же свободного...",216870,null],[216878,"2026-09-16T19:39:26",8,"– И правда, вороны верные и умные создания. А чем заниматься хочется?",191019,null],[216880,"2026-09-16T19:40:02",38,"И Сан задумался.\n— А зачем? Я живу и мне не нужно ходить на работу... Это ли не свобода?",216878,null],[216881,"2026-09-16T19:40:14",11,"— Хм... Ворон интересно где они тут у вас водятся — думает Аури вслух",191019,null],[216882,"2026-09-16T19:40:31",11,"— Нет. — непривычно холодно ответила девушка",216880,null],[216883,"2026-09-16T19:40:55",8,"– Неужели свобода должна приносить печаль?",216880,null],[216884,"2026-09-16T19:41:28",11,"— Вы азартный человек, господин И-сан?",191019,null],[216897,"2026-09-16T19:50:09",38,"— Вроде нет... Я думал над тем, что делать, когда выздоровею...",191019,null],[216899,"2026-09-16T19:50:37",41,"— Вы хотели бы завести кота?",191019,null],[216900,"2026-09-16T19:50:42",11,"— И что надумали?",216897,null],[216901,"2026-09-16T19:51:30",38,"— Как раз хотел погулять и прийти в полночь к жене...\n\nНа вопрос Летиции юноша ответил.\n\n— Не знаю...",191019,null],[216902,"2026-09-16T19:51:33",8,"/10 минут, телефон садится",191019,null],[216904,"2026-09-16T19:52:40",8,"/даже 20",191019,null],[216905,"2026-09-16T19:53:23",11,"— Хм.. а ворону?",216901,null],[216910,"2026-09-16T19:55:08",11,"*Аури достанет ещё один лист пергамента и перо из-за уха и напишет новую записку \n\n[ Так что? Попробуем его убедить не возвращаться обратно к жене пока что? Если да то как? Я бы хотела вытянуть его покататься на этих дивных повозках.. поездах вроде так, уехать куда-то.. ]",191019,null],[216918,"2026-09-16T19:57:16",11,"//передаю пока Лети или Вордо, кто первый ответит",191019,null],[216919,"2026-09-16T19:57:28",41,"Лети дописывает\n\n\"Они кажется громкие, может найдем лошадок напрокат? Даже невидимых \u003c3\"",191019,null],[216921,"2026-09-16T19:58:01",11,"«Хочу покататься на этой штуке.. ':)»",191019,null],[216922,"2026-09-16T19:58:33",41,"\"Ну лааааадно\" \n\nИменно много а",216921,null],[216924,"2026-09-16T19:58:57",11,"*записка переходит в руки Вордо вместе с пером",191019,null],[216926,"2026-09-16T20:00:55",9,"*Смотрит на неё и хмыкает, появилась мысль передать эту записку И Сану? Было бы забавну наблюдать реакцию этого незрелого юнца который не понимает основ своего существования в мире... сминает записку отдав её собаке.*",191019,null],[216929,"2026-09-16T20:01:49",11,"*перехватывает руку",191019,null],[216931,"2026-09-16T20:02:01",11,"*больно",191019,null],[216934,"2026-09-16T20:02:19",9,"//Мою? Я не даю её И Сану",191019,null],[216936,"2026-09-16T20:02:34",41,"( зачем собаке???((((",191019,null],[216937,"2026-09-16T20:02:42",11,"— Прекрати переводить мою бумагу и мысли твои у тебя на лице написаны, эльф",191019,null],[216938,"2026-09-16T20:02:54",11,"*она взмахнет пером и записи исчезнут",191019,null],[216941,"2026-09-16T20:03:25",11,"*скажет это совершенно не стандартным для нее тоном и с хмурым лицом",216937,null],[216944,"2026-09-16T20:03:57",9,"*Отдает записку Аури.*\n\n— Это всё интересно, но он не изменит своё мировозрение если не захочет сам. Все кончится его смертью.",191019,null],[216947,"2026-09-16T20:05:08",11,"— Говорить не дела делать, а?",191019,null],[216951,"2026-09-16T20:05:55",11,"*заберёт записку и быстро успокоится вновь улыбаясь как прежде",191019,null],[216954,"2026-09-16T20:06:41",11,"*будет рисовать ворону пока ждёт заказа",191019,null],[216957,"2026-09-16T20:07:48",9,"— Он не похож на того кто сделает что-то под давлением. — *Вордо и не собирался делать ничего, сейчас ему интереснее попробовать местную еду и кофе.*\n\n*Всё ещё убеждён что И Сан должен найти свои крылья сам.*",191019,null],[216960,"2026-09-16T20:09:05",8,"/тут",191019,null],[216962,"2026-09-16T20:09:49",11,"*хмыкнет и продолжит рисовать",216957,null],[216967,"2026-09-16T20:10:46",11,"— Скажите, господин И-сан, что бы убедило вас решиться на перемены?",191019,null],[216968,"2026-09-16T20:11:30",38,"— На перемены в чем?",216967,null],[216971,"2026-09-16T20:11:47",11,"— В жизни, к лучшему конечно же",191019,null],[216972,"2026-09-16T20:11:59",38,"// И Сан (Yi San в оригинале, может быть переведено Ли Сан, но И Сан более правильно)",216967,null],[216973,"2026-09-16T20:12:04",11,"*говорит продолжая рисовать и не отвлекаясь взглядом от бумаги",191019,null],[216975,"2026-09-16T20:12:15",63,"// Ты всех сюда запихать решил?",216972,null],[216976,"2026-09-16T20:12:22",38,"// ДА!",216975,null],[216977,"2026-09-16T20:12:26",63,"// когда айди игрокам за квесты выдавать будешь?",191019,null],[216978,"2026-09-16T20:12:41",38,"// Хуй там плавал",216977,null],[216981,"2026-09-16T20:12:48",63,"// (",191019,null],[216982,"2026-09-16T20:12:50",63,"// а чо",191019,null],[216984,"2026-09-16T20:13:27",38,"// Только основные 14 книг",216982,null],[216991,"2026-09-16T20:15:47",38,"— Не знаю... Может мои мысли? Не хочется думать об этом...",216971,null],[216993,"2026-09-16T20:16:16",11,"— Что бы вы делали если бы в один из дней ваша жена не вернулась?",191019,null],[216994,"2026-09-16T20:16:55",38,"На лице Юноши появилось испуганное выражение.\n— Как... Не вернулась?...",216993,null],[216997,"2026-09-16T20:18:23",8,"– Ушла бы гулять слишком надолго, например",191019,null],[217009,"2026-09-16T20:20:46",8,"/как ему аккуратно намекнуть-то/",191019,null],[217014,"2026-09-16T20:21:44",11,"— Просто гипотетически представьте. И скажите мне что бы вы делали?",216994,null],[217015,"2026-09-16T20:22:05",38,"— Думаю она бы вернулась к полуночи... Ей же не где спать, кроме её дома...\n Ответил И Сан.\n— Хм... Пошел бы искать её...",191019,null],[217017,"2026-09-16T20:22:21",38,"// Так сейчас будет таймскип, пару заявок/вопросов и он уже будет",191019,null],[217019,"2026-09-16T20:22:30",11,"— А что если с ней что-то случится? — Аури все ещё рисует, но быстро тараторит вопросы — если она пострадает где-то или если ей перестанут давать деньги, вам нужно будет о ней заботиться, ведь так?",191019,null],[217022,"2026-09-16T20:23:27",38,"— Как же так! Если с ней что-то случится, то я попытаюсь помочь ей!",217019,null],[217024,"2026-09-16T20:24:09",8,"– Как именно?",191019,null],[217026,"2026-09-16T20:24:29",11,"*девушка заканчивает рисунок и передает его мужчине.\n\nЧерный ворон на изображении расправляет крылья и улетает постепенно уменьшаясь, а затем совсем исчезая с бумаги прямо в руках мужчины\n\n— Вам нужно поискать своё призвание, найти работу, тогда вы сможете позаботиться и о себе и о ней",191019,null],[217028,"2026-09-16T20:24:42",11,"// попытка в убеждение, моя заявка все полагаю",191019,null],[217034,"2026-09-16T20:25:58",38,"— Хм... Я если бы такое и вправду случилось, то я бы и вправду пошел искать работу...",191019,null],[217035,"2026-09-16T20:27:03",8,"– Кем бы вы работали с удовольствием? /заявка всё/",191019,null],[217036,"2026-09-16T20:27:36",38,"— Хм... думаю архитектором...",217035,null],[217038,"2026-09-16T20:28:18",11,"— Вы умеете рисовать чертежи? Может мы поможем найти вам работу",191019,null],[217042,"2026-09-16T20:31:26",38,"— Немного...",217038,null],[217043,"2026-09-16T20:31:31",38,"Вместе с этим вам подали 5 блюд и 5 напитков, где было два одинаковых блюда и крепкий кофе для И Сана.\n\nВы хорошо пообедали и И Сан похоже немного повеселился. Он был уже не так мрачен и грустен, а немного мягок.\n Вместе с этим вы не заметили, что уже наступил вечер и близилось к полночи.\n И Сан заметив время сказал.\n— Спасибо за ужин... Могу ли я теперь пойти к жене? Думаю она беспокоиться...",191019,null],[217045,"2026-09-16T20:32:14",8,"/он же увидит прикол. Или видение было раньше?/",191019,null],[217046,"2026-09-16T20:32:58",9,"— Мы тебя проводим. — *Вордо не хочет оставлять цель их исследования, он не забыл зачем они здесь.*",191019,null],[217047,"2026-09-16T20:33:25",11,"*оглянется на остальных",217043,null],[217048,"2026-09-16T20:34:11",8,"*беспокойный косой взгляд в сторону И Сана*",191019,null],[217050,"2026-09-16T20:34:51",38,"// Какое видение? Я забыл.",217045,null],[217051,"2026-09-16T20:35:16",8,"/чужой с ней там. Это было раньше?/",191019,null],[217054,"2026-09-16T20:36:07",38,"// Это до встречи с вами.",217051,null],[217056,"2026-09-16T20:37:47",8,"/у меня план идти за ним даже втихую, если не разрешит в открытую/",191019,null],[217057,"2026-09-16T20:38:17",11,"— Угу, мы вас проводим если вы не против, а ещё не хотели бы вы завтра встретиться снова? Поискать работу вместе? Я бы тоже не отказалась.. деньги то не бесконечные хехе",191019,null],[217060,"2026-09-16T20:38:44",38,"Пока вы шли по дороге к дому 33 вы услышали голос рассказчика, где на заднем плане было слышно странные звуки колокольчика...\n— Жена снова зашла в мою комнату. Испугавшись, что вот теперь-то и грянет гром, я, затаив дыхание, лежал, распластавшись, как жаба. Но слова, слетевшие с ее губ, были ласковыми. И дружелюбными. Она сказала, что знает, почему я плачу. Из-за денег ведь? Я по-настоящему удивился. Она видела меня насквозь. С одной стороны, я испугался, но, судя по всему, жена собиралась дать мне денег, а это было бы очень кстати. Я лежал, закутавшись в одеяло, и даже не поднял головы - ждал, что же предпримет жена дальше, - а она со словами «На, возьми!» бросила что-то в изголовье постели - судя по легкому шороху, купюру. И, нагнувшись к моему уху, тихо попросила, чтобы сегодня я вернулся позже, чем вчера. Это нетрудно. Я был рад деньгам и благодарен жене.\nВсе-таки я вышел на улицу. У меня куриная слепота. Поэтому я старался выбирать освещенные улицы. А на центральном вокзале заглянул в кафе рядом с залом ожидания для пассажиров первого и второго класса. Это кафе стало для меня открытием.\nГлавное, никто из знакомых не заходил сюда. А если и заходил, то тут же выходил. Я подумал, что мог бы проводить здесь время каждый день.\nА лучше всего было то, что часы здесь шли точнее, чем где бы то ни было. Не хотелось бы мне, доверившись каким-нибудь неуклюжим, неисправным часам, вернуться домой раньше положенного и получить по шее. Сев за свободный столик, я пил крепкий кофе. А пассажиры в спешке наверняка не успевали насладиться хорошим напитком. Свой кофе они выпивали быстро, уставившись в стену, будто задумавшись о чем-то, и сразу уходили. Печально. Но мне эта печальная атмосфера была больше по душе, чем беспокойная атмосфера уличных кафе. Доносящиеся время от времени резкие и гулкие свистки паровозов заглушали Моцарта.\nЯ несколько раз снизу вверх и сверху вниз пробежал меню, в котором блюд было раз два и обчелся. Мелькавшие перед глазами названия были родными, как имена друзей детства.\nНе знаю, как долго я просидел там, размышляя о всякой всячине, когда, судя по тому, что посетители стали оставлять свои места и расходиться, наступило время закрытия. Едва миновало одиннадцать часов. И здесь не найти мне покоя. В тревоге, где же мне дожидаться полуночи, я вышел на улицу. Шел дождь. Крупные капли грозились доставить мне немало неприятностей, ведь у меня не было ни плаща, ни зонта. А в таком чудаковатом виде я не мог болтаться в зале ожидания, эх, подумал я, не умру же, если попаду под дождь, и вышел на улицу.\nБыло невыносимо холодно. Мой плисовый костюм вскоре промок насквозь и стал прилипать к ногам и рукам. Я собирался кружить по улицам, пока смог бы терпеть этот дождь, но из-за холода терпеть было очень трудно. Дрожь пробирала меня, зубы клацали.\nУскорив шаги, я задумался. Неужели и в такой ненастный день, как сегодня, у жены гости? Навряд ли, подумал я. Пойду-ка домой. Если вдруг, к несчастью, у жены окажется посетитель, объясню все как есть. Если объясню, она своими глазами посмотрит, какой дождь идет, и поймет меня.\nКогда я прибежал домой, у жены был гость. Я так замерз и промок, что в рассеянности забыл постучаться. Я увидел нечто, что моя жена вряд ли хотела бы, чтобы я видел. Оставляя мокрые следы, будто от портянок, я быстро прошагал через комнату жены в свою комнату, сорвал с себя промокшую одежду и закутался в одеяло. Дрожь только усилилась. Как бывало и раньше, земля ушла из-под меня. Я потерял сознание.\nКогда на следующий день я открыл глаза, жена сидела у изголовья моей постели и была явно обеспокоена. Я простудился. По-прежнему дрожал от озноба, голова гудела, слюна во рту отдавала горечью, а руки и ноги отяжелели.\n\nИ Сан же на вопросы ответил.\n— Хм... Почему бы и нет?",191019,null],[217071,"2026-09-16T20:41:12",11,"*приободрившись \n\n— Чудесно! Вы могли бы заработать на подарок жене, представьте как она была бы рада! Купить ей новую юбку например, вам ведь нравятся ее юбки? Или духи!",191019,null],[217073,"2026-09-16T20:41:33",8,"– Но сначала почему бы по пути не купить хорошую одежду и лекарств?",191019,null],[217075,"2026-09-16T20:42:04",11,"— Да, где у вас тут травники? Что бы прикупить вам чего от.. простуды? Чем вы болеете?",191019,null],[217087,"2026-09-16T20:44:23",9,"— Работа, бывает разной. — *Если это книга то её кто-то написал. Если она есть то её читали. В голове парня достаточно много мыслей для романов средней руки.* — Попробуй заняться писательством, тебе не нцжно выходить из дома, при этом мысли на бумаге могут стать бесцеллером. Твоей жене больше не прийдется работать, она будет сидеть дома вместе с тобой. Главное попытаться.",191019,null],[217088,"2026-09-16T20:44:31",38,"— Аптека? Вот вдоль улиц есть...\n Ответил юноша продолжая идти в сторону дома.\n\nРассказчик продолжил говорить.\n— Жена легко коснулась моего лба и велела принять лекарство. Не успел я подумать, что, судя по тому, насколько холодной мне показалась рука жены, у меня был жар, а выпить предстояло жаропонижающее, как жена протянула мне стакан теплой воды и четыре белых таблетки. Сказала, что мне следует выпить их и хорошенько выспаться. Я выпил залпом. Горьковатые таблетки, как я и предполагал, были похожи на аспирин. Я снова укрылся одеялом и сразу же заснул как убитый.\nНесколько дней я хлюпал носом. И пока болел, постоянно пил эти таблетки. От них во рту стоял горький привкус коры.\nЗахотелось снова выйти на улицу. Но жена не велела. Сказала пить лекарства и лежать. Разве не достаточно, мол, доставил ты мне неприятностей, слоняясь без дела и подхватив простуду. И то верно. Так что я поклялся не выходить из дома, собрался заботиться о своем здоровье и принимать таблетки.\nЯ спал дни напролет, натянув на себя одеяло. Невероятно, но меня невыносимо клонило в сон и днем, и ночью. Сонливость, я был уверен, означала, что я шел на поправку.\nТак я провел, пожалуй, с месяц. Мои волосы и усы отросли, стали мешать мне, захотелось взглянуть на себя в зеркало, и я, улучив момент, когда жены не было дома, забрался в ее комнату и уселся перед туалетным столиком. Отлично. Волосы изрядно спутались. Думая о том, что не мешало бы постричься, я вытаскивал пробки из склянок с косметикой и нюхал то одну, то другую. Среди позабытых запахов я различил запах ее тела, от которого меня аж скрутило. Я хотел назвать ее по имени. Но произнес лишь «Ëнсим»*…\n\n// * Торговая марка косметической компании.",191019,null],[217107,"2026-09-16T20:50:17",38,"// @sweetkittywitch @Ashenchampion Fantomas Hard ?",191019,null],[217108,"2026-09-16T20:50:52",11,"// ты тоже на все вопросы отвечай пожалуйста",191019,null],[217109,"2026-09-16T20:50:58",11,".",217075,null],[217111,"2026-09-16T20:51:33",11,"// я же все таки с персом говорю, а не с рассказчиком",191019,null],[217112,"2026-09-16T20:51:33",38,"— Простуда... А так... Аспирин простой подойдет...",217075,null],[217114,"2026-09-16T20:52:01",38,"— Ох... Ей бы понравилось, вы правы...",217071,null],[217115,"2026-09-16T20:52:03",9,"//Я сказал о писалтельстве",191019,null],[217116,"2026-09-16T20:52:09",41,"( опять читать гору(((",191019,null],[217117,"2026-09-16T20:52:18",11,"— Аспи..рин.. впервые слышу, но вроде запомнила, подождите! Сейчас буду \n\n*Аури забежала в указанное местечко легонько хлопнув дверью",217112,null],[217118,"2026-09-16T20:52:40",41,"— звучит как жуткое заклинание",217117,null],[217120,"2026-09-16T20:54:06",38,"— Хм... Я бы подумал над этим... Но давайте завтра, хорошо?",217087,null],[217122,"2026-09-16T20:54:42",11,"// сколько там ещё на твой аспирин",191019,null],[217124,"2026-09-16T20:54:56",38,"// 1 серебрянная",217122,null],[217126,"2026-09-16T20:55:33",8,"/roll 1d20+3 ищем лавки с одеждой",191019,null],[217131,"2026-09-16T20:56:15",38,"Ты находишь еще одну буквально в паре магазинов спустя, но он уже готовился к закрытию.",217126,null],[217133,"2026-09-16T20:56:36",38,"И Сан же немного медленно шел, похоже у него реально проблемы со зрением.",191019,null],[217137,"2026-09-16T20:57:20",8,"*пока Аури пошла за лекарствами, Изольда показала ему на магазин*",191019,null],[217139,"2026-09-16T20:58:12",8,"– Вам бы купить что-то более плотное, вроде дорожной одежды",191019,null],[217140,"2026-09-16T20:58:17",38,"— И вправду магазин... Но зачем мне одежда, кроме моего костюма?",191019,null],[217143,"2026-09-16T20:59:12",11,"*Аури возвращается с аспирином \n\n— Старинные у вас лекарства.. и пахнет там совсем не травами в лавке этой, но вот, то что вы просили",191019,null],[217147,"2026-09-16T21:00:13",38,"— Спасибо...\n И Сан немного поклонился и продолжил идти по дороге.",217143,null],[217148,"2026-09-16T21:00:14",8,"– Для дома он подходит, но одежда как язык. Для каждого случая особая",217140,null],[217149,"2026-09-16T21:00:28",38,"— Мне и одного случая достаточно...",217148,null],[217152,"2026-09-16T21:00:42",11,"— Мне кажется ему очки нужнее чем одежда, у вас случаем нет очков?",191019,null],[217156,"2026-09-16T21:01:30",11,"— Но она права, если будете устраиваться на работу, то нужно быть одетым прилично",191019,null],[217159,"2026-09-16T21:02:02",38,"— Хм... Так мистер же предложил попробовать писательство...",191019,null],[217162,"2026-09-16T21:02:33",8,"– Но и в кафе нужен приличный костюм",191019,null],[217163,"2026-09-16T21:02:59",38,"— А мой плохой?\n И Сан посмотрел на свой костюм.",191019,null],[217166,"2026-09-16T21:03:38",11,"— Что бы издаваться все равно нужно обращаться в издательство",217159,null],[217167,"2026-09-16T21:04:41",41,"— А я плохо заштопала? Подождите...",217163,null],[217168,"2026-09-16T21:05:35",8,"– Он хороший, но полезно иметь второй на то время, пока стираешь первый",217163,null],[217169,"2026-09-16T21:06:16",9,"— Попробовать можно всё. Писательсво не помешает простой подработки, оно не обязательно принесёт плоды,если принесет то подрабатывать не прийдётся. Я бы рекомендовал посещать библиотеку. — *Если Вордо согласился играть в эту игру, что же, идём до конца. Но при этом он разговаривал с И Саном наставнически и слегка отчуждённо, как с чужим ребёнком.*",217159,null],[217176,"2026-09-16T21:09:47",38,"— Хм... Но магазин уже закрывается, будет не очень вежливо делать это так поздно... Давайте завтра, хорошо?\n Ответил И Сан.",191019,null],[217179,"2026-09-16T21:11:37",8,"– В Ваших словах есть логика, но давайте условимся о месте встречи",191019,null],[217181,"2026-09-16T21:12:27",8,"/мы хотели выгнать его за пределы карты/",191019,null],[217185,"2026-09-16T21:13:35",8,"/@Ashenchampion, @sweetkittywitch, что делать/",191019,null],[217186,"2026-09-16T21:13:57",41,"( мммм блин",191019,null],[217187,"2026-09-16T21:14:08",41,"( ну завтра попробуем",191019,null],[217198,"2026-09-16T21:17:58",11,"// ты видела парк вроде",217181,null],[217199,"2026-09-16T21:18:09",8,"/да, и указала вам",191019,null],[217201,"2026-09-16T21:18:40",38,"Вы заметили, что вместо рассказчика говорил уже... Бабочка?\n— Я хотел было в злости пойти на улицу, но вот в дверь постучал кто-то... Это была группа личностей, что зашла внутрь, похоже гости жены... Но они полезли ко мне и начали задавать странные вопросы и выглядели так, будто впервые видят обыкновенные вещи...\n Они вытащили меня на улицу, где накормили меня и дали мне подумать над всем, что происходило.\n Я стал размышлять об адалине и аспирине. Но в голове был полный хаос, и мысли никак не выстраивались. И пяти минут не прошло, как в голову полезли сомнения, и во мне закипела злость. Я хотел было достать адалин, но я забыл его прихватить. Все вокруг отливало желтизной. Словно молния, мелькнула мысль об аспирине и адалине.\nАспирин, адалин, аспирин, адалин, Маркс, Мальтус, Мадрас, аспирин, адалин…\nМоя жена месяц обманывала меня - давала адалин вместо аспирина. Упаковка адалина, которую я нашел в ее комнате, была тому очевидным доказательством.\nЗачем ей нужно, чтобы я спал и днем, и ночью?\nУсыпляя меня и днем, и ночью, что она делает, пока я сплю?\nА если она собиралась потихоньку убить меня?\nС другой стороны, возможно, я весь этот месяц пил аспирин. Может быть, на самом деле жена, о чем-то тревожась, не могла спать по ночам и сама принимала адалин - тогда мне очень жаль. Не дело, что у меня возникли такие ужасные подозрения.\nЯ решил побыстрее придти к ней. Голова кружилась, с трудом переставляя ноги, я еле дошел до дома. Было около восьми.\n\nВы дошли до дома и И Сан попросил вас остаться у калитки и сам пошел наверх, к себе.",191019,null],[217202,"2026-09-16T21:18:44",8,"/главное, чтобы ночью всё ок было. Но, вроде, гг в ± порядке/",191019,null],[217208,"2026-09-16T21:20:27",8,"*отбой, идём сторожить у двери, хз*",191019,null],[217209,"2026-09-16T21:20:47",11,"— До завтра..",191019,null],[217210,"2026-09-16T21:21:07",11,"*проводя его взглядом обернулась к остальным\n\n— Вы не представляете сколько у меня вопросов..",191019,null],[217212,"2026-09-16T21:21:29",11,"— Первым делом хочу спросить знает ли кто из вас что такое ада..Лин?",191019,null],[217213,"2026-09-16T21:21:36",41,"— у меня голова закипает…",191019,null],[217214,"2026-09-16T21:21:57",41,"— этот мир не перестает удивлять. А с голосом в голове я просто теряюсь…",191019,null],[217215,"2026-09-16T21:22:07",8,"– Не знаю. Усыпляющее заклинание?",217212,null],[217217,"2026-09-16T21:22:44",11,"— Судя по сказанному что-то не хорошее \n*Вздох",191019,null],[217218,"2026-09-16T21:23:06",11,"— И так, что мы имеем.. мы попытались его вытянуть, но вышел он в то же место куда и должен был идти по сюжету",191019,null],[217219,"2026-09-16T21:23:11",9,"— Похоже на то как люди называют что-то в свою честь. По контексту снотворное снадобье при этом что может быть ядом.",191019,null],[217221,"2026-09-16T21:23:25",8,"– Как бы то ни было, наверху будет сцена, и я боюсь, она закончится плачевно",191019,null],[217222,"2026-09-16T21:23:28",38,"И Сан начал подниматься и вы заметили, что начало летать подозрительное количество бабочек.\n Вы снова увидели его, мужчину с 5 руками и бабочкой вместо головы.\n В этот раз он сидел на своем гробу прямо на углу дороги.\n— Здравствуйте... Похоже... Скоро будет то, о чем я и говорил... Давайте поговорим, вы не против?",191019,null],[217223,"2026-09-16T21:23:29",11,"— Звучит похоже на то..",217219,null],[217226,"2026-09-16T21:24:09",41,"— о нет… нет нет нет…(",217222,null],[217230,"2026-09-16T21:25:04",9,"— Думаю мы не изменили ничего. Будем смотреть. Всё же я разделяю вашу точку зрения, он должен сам найти свои крылья. — *Указал на оружие собеседника.* — В этот раз никаких ранений и сражений.",217222,null],[217231,"2026-09-16T21:25:20",8,"– Но кажется, пришел в себя. Даже решил выяснить отношения, найти правду. Почему финал такой же?",217222,null],[217232,"2026-09-16T21:26:14",11,"— Потому что мы глобально ничего не изменили — Аури отвечает Изольде игнорируя рассказчика",191019,null],[217234,"2026-09-16T21:26:49",38,"На этот раз уже продолжил Рассказчик.\n— Я собирался рассказать жене о своих недостойных мыслях и извиниться перед ней. Так торопился, что все слова вылетели у меня из головы.\nНо случилась катастрофа. Я своими глазами увидел то, чего не должен был видеть ни в коем случае. В замешательстве я захлопнул дверь и, пытаясь унять головокружение, склонил голову, закрыл глаза и прислонился к косяку, но не прошло и секунды, как дверь снова отворилась, моя жена, вся расхристанная, выскочила и схватила меня за шиворот. Меня повело, и я шлепнулся на пол. Жена навалилась на меня и принялась рвать на части. «Ой, как больно!» У меня не было ни сил, ни желания сопротивляться, я лег и стал ждать, что произойдет, но тут вышел мужчина, быстро схватил жену в охапку и увлек в комнату. Противно было видеть, как жена послушно позволила себя схватить. Противно.\nЖена осыпала меня бранью, что же мне не спится по ночам, граблю кого-нибудь или шляюсь по притонам? Как несправедливо. Я был так изумлен, что не мог рта раскрыть.\nЯ хотел выкрикнуть: «Разве не пыталась ты убить меня!»- но знал, какая брань обрушится на меня, если эти необоснованные обвинения слетят с моих губ.\nСначала я подумал, что, как бы все это ни было несправедливо, пожалуй, лучшая тактика - лежать молча, но, сам не знаю почему, встал, отряхнулся, вытащил из кармана одну бумажку, что оставила официантка, - тихонько приоткрыл дверь и украдкой положил ее под порог, а затем ...\n\nБабочка посмотрел на вас всех и ответил.\n— Финал всегда один... Но его финал это найти крылья... И вы как рад помогли ему их найти. Разве это не лучше?",191019,null],[217237,"2026-09-16T21:27:56",8,"– Где он? *со страхом*",191019,null],[217238,"2026-09-16T21:28:51",38,"— Прямо сейчас перед дверью своей квартиры и ложит свои последние деньги жене... Думаю он не будет на нас уже обращать внимания...\n Ответил Бабочка.",217237,null],[217243,"2026-09-16T21:30:04",11,"*Аури молча направляется к двери квартиры",191019,null],[217244,"2026-09-16T21:30:30",8,"*аналогично. Пусть ничего не изменить, но надо попытаться*",191019,null],[217245,"2026-09-16T21:30:31",11,"*пытается открыть, если закрыто стучит, не открывают — стучит громче",191019,null],[217246,"2026-09-16T21:30:34",41,"Лети бежит за ней",191019,null],[217248,"2026-09-16T21:32:01",38,"Поднявшись на 2й этаж к 7й квартире вы заметили, что И Сан немного побитый как раз собирался спускаться, похоже он не заметил вас.\n Бабочка поднялся с гроба и приблизившись спросил у И Сана.\n— Так как ты хотел бы взлететь?",191019,null],[217253,"2026-09-16T21:33:33",11,"— Не слушай его — Аури пытается схватить мужчину за руку",191019,null],[217256,"2026-09-16T21:33:57",8,"– Лети духовно, найди себя в жизни",191019,null],[217257,"2026-09-16T21:34:05",38,"// И Сана или бабочку?",217253,null],[217259,"2026-09-16T21:34:22",41,"— Только не это…",191019,null],[217261,"2026-09-16T21:34:57",8,"– Мы договорились зайти завтра в магазин, не забыл? *подмигнула*",191019,null],[217263,"2026-09-16T21:35:30",38,"И Сан поднял взгляд на Бабочку и сказал.\n— Ох... Давно не виделись... 8 лет, верно?...\n\nНа ваши же вопросы И Сан ответил.\n— Да, конечно... Только мне нужно немного отдохнуть...",191019,null],[217264,"2026-09-16T21:35:31",11,"// И-сана",217257,null],[217265,"2026-09-16T21:35:46",38,"Ты с лёгкостью берешь его за руку.",217253,null],[217266,"2026-09-16T21:36:04",11,"— Пошли с нами, этот парень не желает тебе ничего хорошего, а мы - да",191019,null],[217267,"2026-09-16T21:36:26",11,"*не тянет за собой, но не отпуская ждёт ответа",191019,null],[217269,"2026-09-16T21:36:44",11,"— Тебе нельзя тут оставаться, она пыталась тебя убить, открой глаза!",191019,null],[217272,"2026-09-16T21:37:11",8,"– Слушай, Бабочка. Пожалуйста, не провоцируй парня на глупые вещи. Мы можем помочь и тебе",191019,null],[217273,"2026-09-16T21:37:14",9,"— Смысл жизни, уже говорил что знаю ответ. Но кто слушает? — *Вордо облокотился на стену, стоит, смотрит.* — Мы не сможем помочь человеку что не желает принимать помощь, Аури, Летиция, Изольда. \n\n*Он назвал спутниц по именам.*",191019,null],[217276,"2026-09-16T21:38:17",9,"//Хотя скорее товарищей по беде",217273,null],[217277,"2026-09-16T21:38:28",8,"– Если не хочет помощи, пусть скажет это сам",217273,null],[217281,"2026-09-16T21:39:25",11,"— Верно. Ему может казаться что ему не нужна помощь, но это не значит что мы не должны пытаться помочь ему открыть глаза",217277,null],[217282,"2026-09-16T21:39:31",41,"— Они что , виделись раньше? Но как?",191019,null],[217283,"2026-09-16T21:39:34",9,"— Хм, если он захочет помощи... я могу позволить ему коснутся.",217277,null],[217284,"2026-09-16T21:40:13",9,"//*Готовит мощный текст который скорей всего не пригодится.*",191019,null],[217287,"2026-09-16T21:41:32",8,"– Я лишь думаю, что Бабочка отчасти сам Тоука. Их голоса так похожи... Значит, они взаимосвязаны, как и влияние на них",191019,null],[217288,"2026-09-16T21:41:41",38,"— А может нет? Кто знает...\n Отвечает И Сан начав медленно спускаться с лестницы.\n\nБабочка же ответил, пропуская И Сана и медленно идя за ним.\n— Давным-давно люди верили, что после смерти они станут прекрасными существами с маленькими крыльями... Ты ведь и сам так считаешь?",191019,null],[217290,"2026-09-16T21:42:00",38,"// Переводчик баразлит",217284,null],[217293,"2026-09-16T21:43:24",11,"— Это не значит что смерть нужно приближать",191019,null],[217295,"2026-09-16T21:44:05",41,"— Это легенды востока… точно, мы тут",217288,null],[217296,"2026-09-16T21:44:22",11,"— Всё мы умрем рано или поздно, а век человека и так короткий. Зачем же ускорять сей процесс? — Аури смотрит на руку из захвата которой неведомым способом выскользнул И-сан",191019,null],[217297,"2026-09-16T21:44:54",38,"И Сан продолжил идти и вы заметили, как из его спины начали образовываться странные отростки из стекла.\n\n— Бабочки... Ты прав... Я и сам же имел крылья... Думаю мне нужно найти ответ на вопрос, как и что происходит, когда бабочка умирает...",191019,null],[217300,"2026-09-16T21:45:14",38,"// Он не выскальзывал, а медленно шел вниз ведя за собой",217296,null],[217301,"2026-09-16T21:45:33",11,"// а кто сказал что я иду?",191019,null],[217303,"2026-09-16T21:45:45",38,"// Пара ступенек",217301,null],[217304,"2026-09-16T21:45:52",8,"– Попробуй наполнить жизнь чем-то стоящим, Тоука, не думай о посмертии, пока оно не настанет!",217296,null],[217308,"2026-09-16T21:47:29",11,"*отпускает руку*\n\n— А знаете, Уворлд прав. Если он сам себя мотивирует совершить этот поступок кто мы такие что бы мешать ему? Самоубийство - выбор слабых. Облик бабочки тебя сильнее не сделал, то что мы живы после твоего нападения - это доказывает",191019,null],[217309,"2026-09-16T21:47:29",8,"– Может, ты прожил свою без толку, и не станешь бабочкой. Может, это состояние нужно заслужить! *резко*",191019,null],[217310,"2026-09-16T21:47:39",38,"— Тоука... Разве так не звали мою жену? До того как я вышел за неё?\n\n— Все верно, И Сан... Но все же нужно помнить о каждом и ты же помнишь всех, верно?\n\n— Да...\n И Сан хотел сделать ещё один шаг по ступеньке, но понял что в захвате.\n— Отпусти пожалуйста... Спасибо...",191019,null],[217312,"2026-09-16T21:48:25",8,"– После такой жизни ты обратишься сраным червяком!",191019,null],[217313,"2026-09-16T21:49:03",8,"/пугаем посмертием, йе/",191019,null],[217315,"2026-09-16T21:49:23",9,"— Эх, И Сан. Хочешь я отвечу на вопрос что ждет тебя после смерти? Мне немногим более ста лет и нашел ответ, он мне не понравился, поэтому в ближайшее время умирать не собираюсь. — *Вордо сказал это четко и уверенно.* — Или ты хочешь рискнуть, ступить в неизвестность и потом жалеть о выборе? Я... даже дозволю коснутся меня, но решать тебе.",191019,null],[217316,"2026-09-16T21:49:25",38,"Бабочка поворачивает голову и его 5 рука указывает прямо тебе в сердце.\n— Ты права... Но я забыл предвсвиться... Похороны Мертвых Бабочек... Я память всех тех бабочек, что решили сами уйти... И И Сан мой друг, что помогал помнить всех...",217309,null],[217319,"2026-09-16T21:50:42",38,"И Сан остановился и посмотрев на тебя он ответил. За его спиной начали образовываться более крупные отростки из стекла и по форме, как крылья.\n— Я же не иду умирать, ты о чем?",217315,null],[217320,"2026-09-16T21:51:20",8,"/можно кинуть проницательность?/",217319,null],[217321,"2026-09-16T21:51:27",38,"// да",217320,null],[217324,"2026-09-16T21:51:53",11,"— Куда тогда ты направляешься?",191019,null],[217325,"2026-09-16T21:51:53",8,"/roll 1d20+1",191019,null],[217327,"2026-09-16T21:52:03",9,"— Ты уже знаешь ответ? Уверен в этом?",217319,null],[217328,"2026-09-16T21:52:09",38,"— Не знаю...",191019,null],[217329,"2026-09-16T21:52:31",38,"Ты понимаешь, что он хочет не умереть, а взлететь.",217325,null],[217331,"2026-09-16T21:52:55",8,"– Как ты хочешь НЕ умереть, И Сан?",191019,null],[217333,"2026-09-16T21:53:37",8,"*шёпотом* – он уверен, что не погибнет",191019,null],[217334,"2026-09-16T21:53:41",38,"— Разве мне нужна смерть, после того как я свободен, как птица?",217331,null],[217336,"2026-09-16T21:54:19",9,"— Это история, кажется он не понимает, он просто идёт по строкам что написанны чужими руками, неспособный понять что цепи что его ограничивают в смертном теле и есть жизнь.",217331,null],[217341,"2026-09-16T21:56:02",8,"– А ты не хочешь остаться ненадолго на земле? Помочь другим, бескрылым. Хотя бы вдохновением",217334,null],[217342,"2026-09-16T21:57:43",38,"— Тогда почему бы им не показать это? Вдохновить своим актом полета?\n И Сан начал медленно идти вниз по лестнице и не смотря на дорогу куда-то.",217341,null],[217344,"2026-09-16T21:58:27",8,"– Для учения других нужно терпение, годы. Увы, минутных героев забывают почти сразу. Как ты достучишься до них с вершин? /если это до него не доклюнет, я пас/",191019,null],[217349,"2026-09-16T22:00:15",11,"*Аури так и не получив ответа решает сделать единственное что ей остаётся в этой ситуации. Спокойным, размеренным шагом она идёт в другую сторону смотря на звёздное небо",191019,null],[217354,"2026-09-16T22:02:20",38,"Бабочка ответил.\n— К сожалению жена полностью ослепила его... Он же и есть гений, который стал чучелом...",217344,null],[217360,"2026-09-16T22:03:25",38,"// Так, ещё пару заявок Hard @sweetkittywitch",191019,null],[217372,"2026-09-16T22:04:45",8,"– Если ты готов сделать глупость и умереть из-за какой-то куртизанки, я не могу тебя уважать. *твёрдо сказала и ушла к Аури*",191019,null],[217375,"2026-09-16T22:05:06",41,"( боже, я не знаю…",191019,null],[217376,"2026-09-16T22:05:14",38,"// Это к И Сану или Бабочке?",217372,null],[217377,"2026-09-16T22:05:23",8,"/И Сану",191019,null],[217379,"2026-09-16T22:05:35",41,"Летиция просто плачет\n\n— просто не умирай((",191019,null],[217381,"2026-09-16T22:05:56",11,"— Небо тут чудное, как и сейчас, все таки не так много с годами поменялось?",217372,null],[217386,"2026-09-16T22:06:54",38,"// Hard ?",191019,null],[217387,"2026-09-16T22:06:55",8,"– Да, это радует. Жаль, что мозги работают иногда так же некрасиво *она опечалена, но понимает своё бессилие*",191019,null],[217389,"2026-09-16T22:07:29",9,"//Щас я в мастера кину текстом",191019,null],[217394,"2026-09-16T22:09:14",9,"*Вордо понял что время есть и его кажется готовы слушать, начал...*\n\n— Есть два утверждения, они оба верны но противоречат друг другу. Я думаю, я чувствую, я существую, и второе, я думаю, я чувствую, я не существую. Подлинность нашего существования зависит от точки зрения. Пустота это уже что-то, это ничего, а ничего это ноль, как ноли не умножай не отнимай и не сумируй, это и останется ничем, но, если ноль поделить на ноль, если ничто это уже что-то, то выходит деление ноля может стало причиной возникновения нашей вселенной. Тогда в чём смысл если наше существование лишь случайность, тут два ответа, как и раньше они противоречат друг другу. Первый смысла нет, второй сложнее, смысл есть и это жизнь. Если душа существует то изначально каждый из нас сущность из пустоты которая приняла ограничения смертной оболочки чтобы почувствовать что-то помимо ничего, значит смысла жизни нет ведь смысл это сама жизнь и снова, всё зависит от наблюдателя и способа наблюдения. Я думаю здесь больше нечего добавить. Выразить экзистенциальный кризис поколения в нескольких предложениях. Идея существования и не существования как двух сторон одной медали, представление о том, что смысл и цель субъективны и зависят от точки зрения... это простота и глубина. Если сама ткань нашей реальности может изменяться под воздействием наблюдения, то, возможно, то же самое можно сказать и о смысле и цели нашей жизни. Возможно, смысл существования не в том, чтобы найти какой-то предопределенный, универсальный смысл, а в том, чтобы создать свой собственный смысл через призму нашего опыта и восприятия.\n\n— *Вордо начал лекцию, словно дыкан, учитель что расказывает теорему студентам.* — Когда я исчезну то появлюсь вновь, вот только спешить мне некуда, как и тебе, И Сан. То время отведённое на жизнь лишь мгновение на общем фоне, но если за горизонтом нет ничего я собираюсь его ценить.\n\n— *Вордо протянул руку парню.* — Могу показать, это просто, дай руку.",191019,null],[217395,"2026-09-16T22:09:40",9,"//Не только мастеру кидаться в нас текстом 😏👌",191019,null],[217397,"2026-09-16T22:10:43",11,"— Есть ощущение что мы не в силах повлиять на сюжет, разочаровывает. Быть посторонним в уже написанной истории совершенно не интересно — она смыкает руки в замок за спиной и идёт все так же спокойно — как думаешь история позволит нам пройти далеко?",217387,null],[217399,"2026-09-16T22:11:27",8,"– Не знаю. Речь Вордо велика, но И Сан очарован и ослеплён",191019,null],[217400,"2026-09-16T22:11:55",38,"// Вот этот человек получает вдохновение",217399,null],[217401,"2026-09-16T22:11:58",11,"— Что-ж, надеюсь хотя бы у него выйдет, останешься наблюдать? Я пойду",191019,null],[217402,"2026-09-16T22:12:01",38,"// И этот",217394,null],[217405,"2026-09-16T22:12:24",9,"//Вроде прошлые два недействительны же? Тогда у меня одно",217402,null],[217406,"2026-09-16T22:12:26",41,"( сори уборка",191019,null],[217407,"2026-09-16T22:13:02",8,"– Я посмотрю. Надо хотя бы увидеть конец, даже если он неизбежен *говорит фаталистично*",217401,null],[217409,"2026-09-16T22:13:46",38,"И Сан посмотрел на тебя и ты понял, что следуя за юношей вы оказались на крыше здания.\n\nБабочка же был снизу здания и вместе с людьми был в самом низу.\n\nГолос Рассказчика продолжился даже тогда, когда вы не видели его.\n\n— Голова опять закружилась. Я совсем пал духом и не знал, как поступить. Бродил по городу, как полоумный…\nНе помню, где я слонялся. Когда я обнаружил, что стою на крыше здания «Мицукоши», был уже почти рассвет.\nЯ опустился на какую-то скамейку и попытался припомнить двадцать шесть лет своей жизни. Но из смутных воспоминаний не вырисовывалось ничего конкретного.\nЯ спрашивал себя. Хоть к чему-нибудь ты стремишься в жизни? Да или нет - я не хотел отвечать на этот вопрос. Я уже не верил даже в собственное существование.\nПерегнувшись через перила, я смотрел на золотых рыбок. Какие они красивые. Маленькие нравились мне маленькими, а большие - большими, и все они были такими шустрыми, приятно посмотреть. В лучах майского солнца рыбки отбрасывали на дно аквариума тени. Их плавники были похожи на платочки. Я стоял, не разгибаясь, и пытался сосчитать рыбок. Спину грело солнце.\nЯ посмотрел вниз на оживленные улицы. Там осторожно шевелилась надоевшая жизнь, раскачивалась, словно плавники золотых рыбок. Люди, крепко связанные невидимыми путами, не могли освободиться. Я подтащил вперед свое тело, разламывавшееся от усталости и голода, и подумал, что мне тоже нужно смешаться с оживленной толпой.\nЯ сделал еще шаг вперед и задумался. Куда ведет этот путь…\nПеред глазами молнией промелькнула злость жены. Аспирин и адалин.\nМы с женой просто не поняли друг друга. Неужели жена вместо аспирина давала мне адалин. Не могу поверить. У нее не было на это причин, разве по ночам я воровал или шлялся по притонам? Определенно нет.\nТак уж сложилось, что мы с женой ковыляли не в ногу. Нечего искать логику в моем поведении или поведении жены. И объяснять тут нечего. Ведь могут же факты идти по миру своей дорогой, а непонимание - своей. Разве не так?\nТолько вот трудно было определить, должен ли этот путь привести меня обратно к жене? Должен? А если не к жене, то куда?\nИ тут пробило полдень. Люди замахали руками, словно курицы крыльями, стекло, сталь, мрамор, банкноты, чернила все закипело в изумительной суете полудня.\nВнезапно я почувствовал легкость в подмышках. Ах, раньше тут были крылья. Теперь уж нет этих крыльев, в голове, словно странички словаря, мелькают обрывки стремлений и надежд.\nЯ замедлил шаги. Захотелось кричать:\n«О, если б мои крылья выросли снова!\nВзлететь, взлететь, взлететь… Взлететь еще раз!\nВот бы взлететь еще раз!»",217394,null],[217410,"2026-09-16T22:15:34",38,"Звёздное небо прекрасным и уходило от рассвета, что вставал прямо у вас. Вы видели всю его красоту, но редко заметили свечение в небе, а именно одной звёзды.\n Она начала увеличиваться и гореть ярче.\n\nВсе локации же начали медленно рассыпаться бабочками и частицами света. Вы оказались в странном месте, где не было видно пола, потолка и стен, но вы все стояли на одном месте.\n Вы заметили, что рядом с вами есть ещё около 13 разных силуэтов людей или нет. Они что-то говорили, но вы не слышали их. Рядом с ним почти у каждого силуэта стоял свой человек разного вида и все, силуэты и их тени, заметив вас начали расстворяться и уходить в камету, что была прямо над вами, далеко и близко.\n\nИменно с этим вы услышали голос Бабочки.\n— Крылья...\n\nИменно так вы и закончили все это, вас начало озарять ярким светом.",191019,null],[217420,"2026-09-16T22:21:54",38,"// И на этом квест, а именно первую арку сюжета считать закрытой!",191019,null],[217421,"2026-09-16T22:22:08",38,"// Сейчас с Хардом будем считать опыт",191019,null],[217423,"2026-09-16T22:22:43",9,"//Ну, он не захотел услышать, всё что могу сказать, эх",191019,null],[217424,"2026-09-16T22:24:12",38,"// Как же иначе, он же всего лишь бабочка ослепленная цветком",217423,null],[217435,"2026-09-16T22:26:55",9,"*Вордо опустил протянутую руку. Он делал одолжение, как человек столь глупый посмел от него отказаться?*\n\n— Дурак не достойный носить титул гения. Червь никогда не станет бабочкой.\n\n//Ну, что было то было",191019,null],[217442,"2026-09-16T22:28:25",8,"– Он был слаб. Но нам таковыми становиться нельзя *смотрит Вордо в глаза*",191019,null],[217443,"2026-09-16T22:28:25",11,"— Согласна — с драконьим холодом в голосе произнесла Аури — жалкое зрелище.\n\n*Последние её слова описывали ситуацию полностью, затрагивая и их самих",217435,null],[217445,"2026-09-16T22:29:01",8,"– Аури, мы пытались. Не вини себя",217443,null],[217450,"2026-09-16T22:30:26",9,"— Могу показать вам что хотел ему сказать, если бы он подал руку.",191019,null],[217451,"2026-09-16T22:30:42",38,"// В ЛС давай!",217450,null],[217453,"2026-09-16T22:31:09",8,"– Давай *неуверенная улыбка показалась на губах, она протянула руку*",191019,null],[217455,"2026-09-16T22:32:12",11,"— Потешь меня, эльф",217450,null],[217456,"2026-09-16T22:32:30",8,"*она крепко взяла собаку*",191019,null],[217457,"2026-09-16T22:32:47",9,"//Щас с денислм решим, я скажу и пусть только тогда даст награды",191019,null],[217460,"2026-09-16T22:34:06",9,"— Дай мне руку. — *Он протягивает свою руку Аури.*",217455,null],[217466,"2026-09-16T22:35:05",38,"// За завершение первой арки:  Крылья от автора И Сан вы получаете.\n100 опыта за арку\n200 опыта за отыгрыш\n70 опыта каждый как 40% от битвы с \"Похоронам Мертвых Бабочек\".\n\nИтого 370 опыта.",191019,null],[217468,"2026-09-16T22:35:29",38,"//Также Вордо получает Стеклянные Крылья полёта.\nЧудесный предмет, неопределенный (настройка на Вордо)\nСтоимость: ??? зм\nПока вы носите эти крылья, вы можете действием произнести командное слово. Это превратит сжатые крылья в пару крыльев из осколков стекла на неограниченное время или пока вы не повторите командное слово действием. Крылья дают вам скорость полёта 35 футов. Перезарядка между призывом крыльев 1 час.",191019,null],[217469,"2026-09-16T22:35:37",11,"*протягивает руку на которой сверкает драконья чешуя на мгновение",217460,null],[217473,"2026-09-16T22:39:09",38,"// И на этом мы завершаем игру, всем спасибо",191019,null],[217474,"2026-09-16T22:39:15",38,"// Прошу оставить отзыв",191019,null],[217478,"2026-09-16T22:39:56",9,"*Он берет и ложит рукц себе на грудь, так чтобы Аури могла услышать, почувствовать. Говорит:*\n\nБиение моего сердца звучит сильно и мощно — словно крылья дракона, делающего взмах в полёте.\n \nВ умах — множество вариаций желательных и нежелательных событий.\n \nНо задумывались ли вы, что правильных ответов может быть больше, чем один?\n \n– Почему я существую?\n \n– Не помню прошлой жизни, но хочу помнить эту в следующей. Поэтому ты существуешь.\n \nТебе нужна книга о героях. \nКаждый персонаж, рождённый из мысли, — это звезда, что никогда не погаснет. \n\nМне самому было трудно, собрать все осколки и смотреть как формировалось зеркало моей личности. Первые заметки появились очень давно. А ещё, не ищи смысла, никогда не умел выражаться. Перед тобой не просто Вордо, а ещё и мастер неправильных метафор.\n \nВидеть душой, очень лично, очень сложно. Видеть чужую душу почти не возможно.\n \nЭта книга, мои глаза, мои мечты, моё отражение, моя жизнь, моя личность. Автор, часть персонажей из этой книги, эльф как ты меня называла. Одна мысль и весь мир на ладони, меня нет… всего лишь набор совпадений и переменных, но именно поэтому, «я существую».\n \nПриготовь своё разбитое сердце.\n \nПрийдёт время.\n \nРано, или поздно.\n \nМожет быть через вечность.\n \nТы откроешь глаза... вновь...\n \nСпадёт пелена, и лишь на мгновенье — другой человек…",217469,null],[217484,"2026-09-16T22:44:47",9,"//Как я это получил, Вордо понял что это у него есть в принципе?",217468,null],[217487,"2026-09-16T22:45:07",38,"// В следующей сессии отвечу",217484,null],[217495,"2026-09-16T22:48:13",11,"*вторая рука тянется к голове. С трудом, на цыпочках, но девушка дотягивается погладить Вордо\n\n— Ты хорошо постарался, но к сожалению не был услышан, как и мы все. По крайней мере ты заслуживаешь похвалы\n\n*Она вновь сменила гнев на милость и улыбнулась",217478,null],[217503,"2026-09-16T22:51:58",9,"— Хм. Он сам выбрал свою судьбу. — *Это немного успокоило ЕГО ПРАВЕДНЫЙ И СПРАВЕДЛИВЫЙ ГНЕВ в это ситуации, но все равно было достаточно неприятно получить такой результат.*\n\n*Вордо не долго наслаждался утешением, он просто отошел наблюдая как меняется мир.*\n\n— Кажется нас ждёт следующая история...",217495,null],[217508,"2026-09-16T22:56:47",8,"– Ах, да. Музейный хранитель просил нас забрать вещицы из этого мира. Успеем?",191019,null],[217509,"2026-09-16T22:57:03",11,"*уберет руку раз не наклоняешься, коротышке то достать тяжело и вздохнет",191019,null],[217510,"2026-09-16T22:57:22",11,"— Хватай что видишь? — с грустным смешком сказала девушка",217508,null],[217512,"2026-09-16T22:58:02",8,"– А что ещё остаётся делать *ироничный смешок*. Хватай с умом",191019,null],[217513,"2026-09-16T22:58:50",38,"Вы были в пустом пространстве зашитым жёлтым светом и прямо из кометы над вами начал сиять свет все ярче, полностью ослепляя вас и вы начали замечать изменения в пространстве и восприятии.\n\n// Также этот скип является долгим отдыхом.",191019,null],[217515,"2026-09-16T23:00:26",8,"– Жизнь иногда не конфетка. Тырим в новом месте сразу, давайте?",191019,null],[217516,"2026-09-16T23:02:12",38,"// Плохие новости, Эля покидает наш квест и вместе с этим Летиция покидает книгу...",191019,null],[217520,"2026-09-16T23:02:45",38,"// Будете искать ещё одного игрока или пойдете дальше втроём?",191019,null],[217522,"2026-09-16T23:03:37",8,"/не знаю, кто согласится. Своя специфика/",191019,null],[217523,"2026-09-16T23:04:40",38,"// Тогда пока что поиграете втроём, как понадобится ещё один, то сделаю набор",217522,null],[217524,"2026-09-16T23:05:06",38,"// И мы продолжим уже в пятницу, у меня завтра весь день забит",191019,null],[217525,"2026-09-16T23:07:36",8,"/в пятницу не знаю. Именно она (конкретно эта) занята/",217524,null],[220377,"2026-09-18T08:59:08",38,"@Ko11lu",191019,null],[222928,"2026-09-18T21:37:02",38,"// Так, завтра будем играть. Не будете против, если я сделаю небольшие введение для персонаж @Ko11lu и выведение Летиции @sweetkittywitch?\n Как раз до продолжения квеста.\n\nFantomas @Ashenchampion Hard",191019,null],[222946,"2026-09-18T21:46:23",8,"/там нас Хард напугал, теперь интересно даже, что за мясо впереди",191019,null],[222947,"2026-09-18T21:46:41",38,"// Ты про что?",222946,null],[222950,"2026-09-18T21:46:57",8,"/сюжет) Я без понятия, но, видимо, будет, сложнее",222947,null],[222960,"2026-09-18T21:48:34",38,"// А сюжет... Не переживай, тут будет сейчас очень интересно, ведь я решил добавить сайдквестов сюда и ещё к вам идёт @Ko11lu, что очень хороший игрок по моему мнению",222950,null],[223002,"2026-09-18T21:56:06",63,"// Ему кажется, а когда кажется — крестится надо",191019,null],[223011,"2026-09-18T21:58:05",38,"// Кинь в лс ссылку на анкету персонажа",223002,null],[224267,"2026-09-19T12:22:07",38,"// @Ko11lu во сколько сможешь начать?",191019,null],[224286,"2026-09-19T13:03:19",63,"// думаю где-то вечером, у меня щас онлайн игра начнется. Примерно в 17 думаю освобожусь",224267,null],[224293,"2026-09-19T13:12:46",38,"// @Ashenchampion Fantomas Hard будет удобно?",224286,null],[224828,"2026-09-19T18:46:51",38,"// Для @Ko11lu.\nТы проходила в одном из городов, как и бывает у тебя, но заметила, что прямо у тебя под ногам лежит небольшое приглашение. На нем было написано: \"Приглашаю на выставку прошлой эры, если вы хотите придти, то подпишите ниже и придите на улицу Культуры.\"\n\nРядом почти никого не было, а времени было под вечер.",191019,null],[224837,"2026-09-19T18:56:49",38,"// Для остальных и @sweetkittywitch в особенности.\nВас озаряет золотым свечением.\n\nЛетиция обнаруживает себя прямо обратно библиотеке, а рядом стоит удивленный мистер Читатель.\n— Что случилось, мисс? Как такое случилось?",191019,null],[224838,"2026-09-19T18:56:58",38,"// @Ko11lu",224828,null],[224840,"2026-09-19T19:05:38",8,"*Мысли: Как бы мы не оказались сейчас на том свете вслед за тем дуриком...* *прикрыла глаза*",191019,null],[224844,"2026-09-19T19:19:19",63,"Девушка удивлённо и несколько настороженно взглянула на нечто, что, с её стороны, походило на... \"приглашение\". Она присела, чтобы аккуратно поднять его и взглянуть на написанное поближе.\n\nНоа бегло оглядела текст, представленный на бумаге(?), и приподнялась обратно на ноги. Несколькими плавными движениями она сняла рюкзак и, раскрыв его, принялась копаться в поисках чего-то, чем можно было подписать приглашение: все же делать особо было нечего ей. Однако, к невероятному удивлению, ничегошеньки не обнаружив там, девушка, для начала, решила направится на эту самую улицу, по пути прихватив вещицу, которой можно было бы подписать приглашение.",224828,null],[224847,"2026-09-19T19:24:17",38,"Пройдя к нужной улице ты увидела выделяющееся место. Оно было закрыто по вывеске, а сверху была надпись \"Выставка Прошлой Эры\" и на двери записку.\n\"Закрыты до утра, если получили приглашение подпишите и положите в почтовый разъем ниже.\"",224844,null],[224850,"2026-09-19T19:36:30",63,"— Можно ли считать это за... \"получение приглашения\"?\n\nПрошептала девушка, переводя взгляд с приглашения на разъем и обратно. Она немного сильнее сжала его в руках, но все же подошла к тому месту.\n\n— Ха... особо выбирать не приходится...\n\nТяжёлый вздох и усталый шёпот, после которого послышались шаги, и девушка положила приглашение в разъем.",191019,null],[224851,"2026-09-19T19:37:46",38,"// А подписать?",224850,null],[224852,"2026-09-19T19:38:10",38,"// Или не будешь",191019,null],[224857,"2026-09-19T19:41:36",63,"// было бы чем, могу кровью",191019,null],[224858,"2026-09-19T19:42:20",63,"// если это вообще нормально возможно",191019,null],[224859,"2026-09-19T19:43:01",38,"// А... Можешь просто подписать частью магии",224857,null],[224861,"2026-09-19T19:43:21",38,"// Я че-то не подумал, что у человека не взяты фокусы...",191019,null],[224862,"2026-09-19T19:43:29",63,"// Блейдсингер",191019,null],[224863,"2026-09-19T19:43:43",38,"// Разрешаю в этот раз",224862,null],[224885,"2026-09-19T19:53:54",63,"Однако, прежде чем вложить эту бумажку, она ещё раз взглянула на неё и решила реализовать кое-какую пришедшую ей на ум идею. На кончиках пальцев, что держали приглашения, возникло бледно-белое свечение, которое волнами понемногу переходило в предмет находившийся в её руках. Оставив достаточный след магии на нём, девушка, в конце концов, бросила письмо в тот самый разъём.",191019,null],[224924,"2026-09-19T20:00:30",38,"Как только бумажка вошла в дверь ты увидела яркое золотое свечение, что полностью ослепило тебя и ты резко ощутила себя где-то.\n\n// Hard Fantomas @Ashenchampion \n\nВы все понимаете, что оказались в городе примерно похожее на ваши. Многоэтажные доходные дома, деловые кварталы и монументальные общественные ансамбли.\n На улице жара стояла страшная, к тому же духота, толкотня. \n Был уже поздний вечер. Сумерки сгущались, полная луна светлела всё ярче и ярче; но как-то особенно душно было в воздухе. Люди толпой шли по улицам; ремесленники и занятые люди расходились по домам, другие гуляли; пахло известью, пылью, стоячею водой.\n Вы оказались на улице.\n Рядом с собой вы заметили, что вместо Летиции рядом с вами другой человек, а Ноа обнаружила, что находится рядом с другими людьми в другом месте...",224885,null],[224931,"2026-09-19T20:03:38",63,"// ода, библиотека, но немного иная",191019,null],[224938,"2026-09-19T20:06:27",9,"*Прекрасный как звездное небо Вордо! Он астральный эльф, но по внешности так сразу и не догадаешься о расе или о очертаниях внешности в целом кроме того что его тело словно скопление звезд на ночном небе. Однажды он упал в кузню миров, место из космической пыли где куются звезды и планеты и выжил чудесным образом, это сильно изменило его внешность и характер.*\n\n//Для нового товарища чтобы немного знал с кем имеет дело, Вордо обыватель и космонавт, не из этого мира за что его могут прихлопнуть эдак какой нить паладин клятвы смотрителей.",191019,null],[224939,"2026-09-19T20:07:32",8,"*каков примерный вид людей, костюмы?* *Изольда оглядывается с интересом, кажется, после речей Вордо раздражение прошло*",191019,null],[224942,"2026-09-19T20:09:02",8,"– Летиция, ты изменила облик?",191019,null],[224944,"2026-09-19T20:10:02",9,"— Кажется это не она. — *Вордо лишь одним взглядом понял что перед ними другой человек, мелкая мимика, особенность держаться и отсутствие кота.*",191019,null],[224946,"2026-09-19T20:10:52",8,"– Знаешь, надежда живуча, как сорняк. Как Вас зовут, юное создание?",191019,null],[224948,"2026-09-19T20:12:41",63,"— А...? А-а-а-а...?\n\nУдивлённо протянула девушка в момент, когда последствия золотистого сияния, в виду ослепления, сошли на нет и она смогла оглядеть место в которое её перенесли...? Или это все иллюзия? \n\nГлаза на мгновение, после посетившей ее мысли, вспыхнули золотистым свечением и Ноа повторно оглядела всех существ, что присутствовали рядом.",224924,null],[224949,"2026-09-19T20:13:01",63,"// обнаружение магии",191019,null],[224950,"2026-09-19T20:13:09",38,"Костюмы, рясы, рубахи, простая одежда. Ты понимаешь, что вокруг очень много кабаков и забегаловок, где сидят или расходятся люди.",224939,null],[224952,"2026-09-19T20:14:04",8,"/все люди?/",191019,null],[224953,"2026-09-19T20:14:10",38,"От Вордо исходит очень много магии, от девушки тоже и от дженази соотвественно. А вокруг её было от слова совсем",224948,null],[224954,"2026-09-19T20:14:20",38,"// Пока да",224952,null],[224955,"2026-09-19T20:14:40",11,"— Это единственный человек который использует магию здесь — прокомментировала Аури — и Летиция куда-то исчезла. Кто ты такая?",224949,null],[224956,"2026-09-19T20:15:16",8,"– Извини за грубость",191019,null],[224957,"2026-09-19T20:15:51",11,"— Грубость - это читать заклинание перед нами даже не представившись, в такой ситуации мы могли действовать на опережение",191019,null],[224958,"2026-09-19T20:16:09",9,"*Плащ точно магический предмет, а еще что-то за спиной не осязаемое глазами у Вордо если выделять отделтные магические особенности.*",224949,null],[224959,"2026-09-19T20:17:05",8,"/татуировка на руке магическая, кинжал тоже/",191019,null],[224960,"2026-09-19T20:17:06",63,"— ... а можно по одному... пожалуйста?\n\nНоа повернулась обратившимся к ней существам, что уже успели завести между собой диалог.",191019,null],[224961,"2026-09-19T20:17:21",11,"— Ещё одна бабочка? Куда вы дели мою подругу? \n\n*Аури явно была растеряна после исчезновения Летиции, а внезапное появление человека который игнорируя их присутствие читает заклинание выглядело для неё угрозой",191019,null],[224962,"2026-09-19T20:17:47",9,"*Кивнул.*\n\n— Это одно из простеших заклинанийс было. — *Смотрит на новенткую, оборачивается вернувшись к осмотру окружения.*\n\n//Что с отдыхом кстати, го отдохнём наверное?",224957,null],[224963,"2026-09-19T20:17:54",8,"/облик какой?/",224960,null],[224964,"2026-09-19T20:18:08",8,"/был длинный во время перехода/",224962,null],[224967,"2026-09-19T20:18:19",9,"//Да?",224964,null],[224969,"2026-09-19T20:18:32",11,"// не думаю что мы понимаем какое конкретно заклинание она использует\n\nКак персонажи я имею ввиду",224962,null],[224971,"2026-09-19T20:18:55",38,"ю",217513,null],[224972,"2026-09-19T20:19:19",8,"*спрашивает мысленно, надеясь на ответ. \"Летиция, где она?\"*",191019,null],[224975,"2026-09-19T20:20:12",9,"//Думаю можно понять что простейшее, могу на магию бросить если хотите)",224969,null],[224976,"2026-09-19T20:20:21",63,"// у кого?",224972,null],[224977,"2026-09-19T20:20:36",8,"/у голоса свыше/",224976,null],[224978,"2026-09-19T20:20:38",11,"// ты сам обнаружение магии не кастуешь и среди простых кастов есть и наносящие урон, так что думаю реакция на ситуацию у меня справедливая",191019,null],[224979,"2026-09-19T20:20:39",38,"Вы все и даже Ноа начинаете слышать голос Читателя (мужчина около 35 лет) и он говорит, будто с помехами\n\"Ало!... М.. ня слыш.. но? Летиция ока.. залась у меня.. У вас... Мог появиться кто.. то друг.. ой!\"",224972,null],[224985,"2026-09-19T20:21:48",8,"*видимый вздох облегчения и расцветающая улыбка*\n– Так с кем имеем дело?",191019,null],[224987,"2026-09-19T20:22:33",11,"— Летиция отказалась..? — Аури выдохнула, беспокойств стало на порядок меньше. \n\n«По крайней мере она в порядке» — подумала про себя девушка, но тревога вновь вернулась при взгляде на стоящего перед ней нового человека и девушка спряталась за самую высокую фигуру здесь хватаясь за его плащ",191019,null],[224988,"2026-09-19T20:22:38",9,"*Сморит вверх, словно слушая что происходит, а после смотрит на Ноа не сводя сверкающих глаз, смотря реакцию на его внешность.*",224979,null],[224991,"2026-09-19T20:25:20",9,"*Вордо никак не показал что против когда за ним прячутся.*\n\n— Я Вордо. А кто ты. — *Спросил он прямо.* — Ответь чётко и конкретно.\n\n*Голос твердый, настойчивый.*",224987,null],[224996,"2026-09-19T20:26:22",8,"*изящный полупоклон* – Изольда",191019,null],[225008,"2026-09-19T20:34:02",63,"Ноа продолжала смотреть на разговоры тех, от кого, в действительности, исходила магия. Пару раз в глубинах её сознания промелькнула мысль, что, возможно, стоило бы уйти, пока они все заняты собой. Однако их все прервал... странный голос? Девушка, словно и забыв, что до этого не интересовали признаки какой-либо магии вокруг, начала бегло оглядываться. Источник странного голоса ей, безусловно, хотелось бы обнаружить, однако она, довольно скоро осознав их бессмысленность, повернулась к обратившемуся к ней эльфу.\n\n— Чётко и ясно... да? Странствующий маг, что путешествует ради поиска новых видов магии. Вот только... в этот раз я забрела... куда?",191019,null],[225011,"2026-09-19T20:35:45",8,"– В книгу. Надо задокументировать события, раз, взять вещи отсюда, два. Мы хотели на сюжет повлиять ещё...",191019,null],[225017,"2026-09-19T20:40:47",63,"— Книга...? Чего? Что за книга? Каков её сюжет? Как выбраться отсюда? Чей это был голос? Что вообще за приглашение сюда привело? Как...\n\nВопросы нескончаемым потоком начали сыпаться в сторону группы, едва Ноа услышала \"куда\" она попала. И, хотя на часть из них она, скорее всего, смогла бы ответить, но все равно решила узнать, что же скажут уже прибывшие ране разумные.",191019,null],[225020,"2026-09-19T20:43:17",11,"— Ты игнорируешь наши вопросы, но требуешь от нас ответов? — девушка выглянула из-за спины Вордо, но относилась настороженно по причине странного поведения новоприбывшего",191019,null],[225025,"2026-09-19T20:45:22",8,"– Как зовут тебя, девушка? *отчётливо*\n@Ko11lu",191019,null],[225031,"2026-09-19T20:48:20",9,"*Лишь вздохнул. Странные люди окружали его.*\n\n— Мы сами здесь застряли. — *Он поднимает руку показывая на окружение. Обьяснял словно потерявшемуся птенцу, делая паузы чтобы \"несмышленый\" имел время на подумать.* — Все что нас окружает может быть опасным. Будь сообразительней и внимательней если хочешь найти ответы на вопросы что задала.\n\n*Еще один странный попутчик, страннее чем текущие, его не очень радовал.*",191019,null],[225033,"2026-09-19T20:49:03",63,"// я ждал пока человек пост напишет",225025,null],[225034,"2026-09-19T20:49:06",9,"//Действия/слова перса ≠ отношение игрока, на всякий)",191019,null],[225038,"2026-09-19T20:50:13",11,"// а я жду ответов",225033,null],[225056,"2026-09-19T21:02:16",63,"— ... и какой же вопрос был проигнорирован? Мне казалось, что я \"назвала себя\", или это не так? Помимо имени... и раз уж об этом зашла речь, можете обращаться ко мне — \"Лемн\".\n\nПроговорила девушка, не особо стараясь скрыть ни скепсис, ни явно проступающее недовольство. Каждое новое предложение от группы перед ней вгоняло её в ещё более странное положение, где от нее, едва она появилась, требовали назвать себя, словно она на допросе, ответить, где незнакомое ей существо, назвали грубой лишь из-за использования заклинания, что по итогу не принесло какого-либо вреда окружающим.\n\nДа и требование быть \"сообразительней\" и \"внимательней\" не осталось ею незамеченным. Ноа весьма была заинтересована, как соответствовать этим критериям, не имея никакой информации на руках.",225020,null],[225060,"2026-09-19T21:04:45",8,"– Лемн, смотри. Для понятия сюжета нам нужно найти героя или героиню. А дальше разберёмся",191019,null],[225061,"2026-09-19T21:05:12",11,"// не, ребят, я так не смогу",191019,null],[225062,"2026-09-19T21:05:30",63,"// так?",191019,null],[225065,"2026-09-19T21:05:53",38,"// поменьше большого текста и побольше динамики",225062,null],[225066,"2026-09-19T21:06:08",63,"// заранее обозначить это?",191019,null],[225067,"2026-09-19T21:06:18",8,"/полная стилизация необязательна. Можно импровизировать",191019,null],[225069,"2026-09-19T21:06:45",63,"// в плане?",191019,null],[225070,"2026-09-19T21:07:17",8,"/можно репликами, а не стенами текста. На последние уходит много времени",225069,null],[225073,"2026-09-19T21:07:42",63,"// Хорошо, без проблем",191019,null],[225075,"2026-09-19T21:07:55",8,"/спасибо",191019,null],[225081,"2026-09-19T21:09:00",63,"— Героя и героиню... и как же?\n\nУточнила девушка, вглядываясь осматривая окружающих ее людей.",225060,null],[225082,"2026-09-19T21:09:45",8,"– Обычно нам говорит Голос-Сверху-в-Наших-Мыслях *задумчиво*",191019,null],[225084,"2026-09-19T21:09:57",63,"// можешь назвать проблему? Если она во мне, то я постараюсь ее исправить.",225061,null],[225086,"2026-09-19T21:10:38",11,"*вздыхает и покидает свое \"укрытие\" \n\n— Как ты сюда попала? Это не допрос. Не нужно смотреть на нас так скептично, это наводящий вопрос что бы понять как много тебе известно",191019,null],[225095,"2026-09-19T21:12:07",11,"// Извини, мне тяжело дается ждать постов постоянно.. динамика теряется",225084,null],[225104,"2026-09-19T21:12:34",63,"— Мне известно... да ничего, если так подумать... я подобрала приглашение, подписала его, принесла к обозначенному месту... затем золотистое сияние и вот, я здесь.\n\nОна неспешно продолжала говорить, перебирая у себя воспоминания и стараясь ничего не упустить.",225086,null],[225118,"2026-09-19T21:14:33",11,"— Приглашение? — Аури задумалась — А мы попали сюда с выставки о прошлой эпохе.. нас немного ввели в курс дела, а что было написано в том приглашении?",191019,null],[225133,"2026-09-19T21:16:47",8,"*примерно какой климат вокруг?*",191019,null],[225138,"2026-09-19T21:17:22",63,"— Кажется... \"Приглашаю вас на выставку\", — ... ещё вроде — \"прошлой эпохи\". В конце было указано, что для участия нужно подписать приглашение и прийти к дому культуры... насколько я помню, это всё",225118,null],[225144,"2026-09-19T21:18:19",38,"// Лето, июль, умеренный климатический пояс",225133,null],[225147,"2026-09-19T21:18:37",38,"// Только сейчас душно",191019,null],[225150,"2026-09-19T21:18:52",8,"– Выставка перетекла в задание... Читатель говорил, что произошла ошибка. Ты поменялась местами с нашей подругой",191019,null],[225152,"2026-09-19T21:19:21",11,"— Значит вы тоже были приглашены на выставку, но полагаю опоздали.. хорошо, Лемн, я введу вас в курс дела раз работодатель не сделал этого. Полагаю вы здесь по работе как и мы..",191019,null],[225169,"2026-09-19T21:22:06",11,"— Мы в легендах той самой прошлой эпохи сейчас, и наша цель найти причину падения богов и проблем с магией здесь. Методы.. Что-ж, их мы ещё не обнаружили",191019,null],[225177,"2026-09-19T21:23:03",63,"— Поменялась местами...? Это один из способов выбраться отсюда...?\n\nНа полтона тише проговорила девушка, вслушиваясь в речь, что объясняла ей хоть что-то об этом месте.",225150,null],[225180,"2026-09-19T21:23:27",38,"Вы отмечаете, что находитесь рядом с одним зданием на углу дороги. \n\nИз него заходили и выходили некоторые люди, а вместе с этим близилось к вечеру (почти семь вечера)",191019,null],[225181,"2026-09-19T21:23:43",38,"// Ответ на заявку про местность",191019,null],[225184,"2026-09-19T21:24:32",11,"— Предыдущая наша попытка повлиять на мир не увенчалась успехом \n\n*Пыл дженази остыл и она лишь грустно вздохнула снова\n\n— Если вам интересно как выбраться, то нам сказали что мы освободимся после окончания каждой из 14 историй в разных эпохах, но.. как видите одна \"коллега\" уже покинула нас, значит есть и другой способ.. возможно и правда поменяться с кем-то местами..",191019,null],[225185,"2026-09-19T21:25:12",8,"/но в средневековом стиле одежда? (Рясы и т.п.)/",225180,null],[225186,"2026-09-19T21:25:16",9,"//Мир часом не черно белый а мы цветные???",225180,null],[225187,"2026-09-19T21:25:48",8,"/цветные=негры)/",225186,null],[225188,"2026-09-19T21:25:57",63,"— 14 историй...?\n\nС небольшой нотой удивления в голосе произнесла девушка.\n\n— И сколько вы уже провели в этом месте времени?",225184,null],[225189,"2026-09-19T21:26:06",38,"// я просто иллюстрации ненашел",225185,null],[225190,"2026-09-19T21:26:09",63,"// Мы в Т Корп?",225180,null],[225192,"2026-09-19T21:26:13",38,"// нет",225190,null],[225193,"2026-09-19T21:26:23",8,"– Всего одну",225188,null],[225194,"2026-09-19T21:26:24",63,"// вот и замечательно",191019,null],[225195,"2026-09-19T21:26:27",38,"// я просто иллюстрации не нашел, только фото",191019,null],[225200,"2026-09-19T21:27:39",8,"*Изольда удивлена: здания не её мира, одежда – её*",191019,null],[225201,"2026-09-19T21:28:07",11,"— Одну историю, один день.. Честно говоря, ваше появление как раз после исчезновения подруги меня насторожило. Магией здесь почти не пользуются, последний кто ее здесь использовал перед нами был тот кто атаковал нас — девушка протянула руку для знакомства — Я Аури Диан, простите мне мою резкость",225188,null],[225202,"2026-09-19T21:28:32",9,"— Это место не похоже на созданное магией. — *Что то здесь не так, магии у местных нет и это слегка раздражает. Здание явно сделано технологично и слишком хорошо учитывая все, или маги хорошо прячутся.* \n\n//Выйбы Гарри поттера, одни маглы!",191019,null],[225208,"2026-09-19T21:30:35",8,"/roll 1d20+1 попытка осознать парадокс",225200,null],[225210,"2026-09-19T21:31:03",63,"— В таком случае это многое проясняет... во всяком случае, раз недопонимание были разрешены, то все в порядке. Моё прозвище вам уже известно — \"Лемн\".\n\nВолшебница, с облегченным выдохом от получения информации об этом месте, также протягивает руку, принимая рукопожатие.",225201,null],[225212,"2026-09-19T21:31:33",38,"// Ты осознаешь, что такое возможно, если бы магии было чуть ниже, но насколько? И насколько должны быть технологичны люди?",225208,null],[225217,"2026-09-19T21:32:38",11,"— Что-ж.. давайте вернёмся к \"работе\". Уже вечер, нужно бы понять где мы и зачем здесь..\n\n*Аури тоже осматривает местность, а затем обращает внимание на людей: многи ли их здесь? Как реагируют на группу?",191019,null],[225218,"2026-09-19T21:32:39",8,"– Магии мало, но она не умерла",225202,null],[225219,"2026-09-19T21:32:55",9,"*Вроде бы девушки сошлись, перестал следить за новенькой, теперь есть кому за ней приглядеть.*\n\n— Возможно мы где-то у моря, или недавно был дождь. — *Прокоментировал он духоту этого места.*",191019,null],[225222,"2026-09-19T21:33:23",9,"— Или умирает.",225218,null],[225226,"2026-09-19T21:34:03",8,"– Не будь пессимистом! Если бы она умерла, что вместо неё в нашем мире?",225222,null],[225230,"2026-09-19T21:34:56",8,"*дует ли солёный йодистый ветер?*/пытаюсь понять, есть ли море/",191019,null],[225231,"2026-09-19T21:35:03",9,"— Помните говорили о месте \"в котором ещё осталась магия\"? Значит был промежуток времени когда магия была и цвела до времени И Сана. Возможно это как раз оно. — *Говорит что думает по этому поводу.*",191019,null],[225234,"2026-09-19T21:37:26",11,"*морем пахнет от дженази воды :D",225230,null],[225235,"2026-09-19T21:37:44",38,"Люди уже ходили в дома, а в кабаках вокруг было видно кучу народу, похоже все выпивают там.\n Вместе с этим вы заметили человека, высокий, стройный, темноглазый и темноволосый молодой человек с тонкими чертами лица. Высокая круглая шляпа Циммермана — рыжая, в дырах и пятнах, без полей, заломившаяся набок. Вместе с этим на нем были лохмотья и вы могли понять, что он довольно беден.",191019,null],[225236,"2026-09-19T21:37:51",9,"//Морской солью и духотой ^^",225234,null],[225237,"2026-09-19T21:37:56",38,"// только река",225230,null],[225238,"2026-09-19T21:38:07",11,"— Возможно вы правы, Вордо, но в прошлой эпохе нам ведь сказали что есть местность где магия ещё не в упадке..",225231,null],[225240,"2026-09-19T21:39:10",8,"/искать процентщицу?)",225235,null],[225241,"2026-09-19T21:39:13",9,"— Я бы не назвал это \"не в упадке\". — *По его мнению она здесь в упадке.*",191019,null],[225243,"2026-09-19T21:39:34",38,"// получай вдохновение!",225240,null],[225244,"2026-09-19T21:39:47",38,"// и ты тоже",225238,null],[225247,"2026-09-19T21:40:26",11,"— Здравствуйте! — Аури окликнула его подойдя поближе — скажите пожалуйста как называется эта страна и какая сейчас эпоха? \n\n*Совсем не стесняясь показаться не от мира сего спросила она не дав ответить Вордо",225235,null],[225248,"2026-09-19T21:41:21",8,"*неловко машет рукой, у неё догадки плохие, но вежливость есть вежливость* /я эту шляпу за версту узнаю, сколько нервов ЕГЭ съел/",191019,null],[225253,"2026-09-19T21:43:24",38,"Мужчина резко вздрогнул и немного отошел к стене. На его лице было видно, что проснулся он буквально не так давно, а его лицо было немного в страхе.\n— Здраствуйте... Мы находимся в Санкт-Петербурге... \n\n// Напомнб, что под спойлерами вы видите только простое лицо (он, она, этот, тот, такой и т.к.)",225247,null],[225254,"2026-09-19T21:43:34",63,"«Это было довольно... резво?»\n\nДевушка провела взглядом дженази, ушедшую к одному из людей на улице, и принялась осматривать место, в котором она появилась, на этот раз больше акцентируя внимание на сооружения, находившееся поблизости, дабы понять, в какого рода районе они оказались.",191019,null],[225263,"2026-09-19T21:44:57",8,"– И Вам не хворать и побогаче быть) Мы туристы",225253,null],[225266,"2026-09-19T21:45:41",38,"Район выглядит как бедноватый и криминальный район. Похоже здесь довольно плохо, чем в обычной части города",225254,null],[225268,"2026-09-19T21:46:06",9,"//Понятно почему все серое, это Питер",225253,null],[225279,"2026-09-19T21:48:24",11,"«Понятно что ничего не понятно» — пронеслось у девушки в голове и она лишь улыбнулась думая о том почему подошла именно к этому человеку, раз он обратил их внимание на себя может именно он герой этой истории \n\n— Мы с друзьями здесь не местные, мы м.. по важному делу из другой страны! Ищем следы магии в других местах, не будете ли вы так добры поведать об ситуации с магией у вас здесь?",225253,null],[225286,"2026-09-19T21:49:53",38,"— Магия? Ох... Её перестали здесь использовать века назад... Это связано с политикой нашей страны...\n Ответ л Мужчина и не его лицо появилось небольшое облегчение, но и выступил небольшой пот.",225279,null],[225291,"2026-09-19T21:50:48",8,"– Хоть магия дружбы осталась? *смеётся, мужчина не так уж суров, как в легендах*",191019,null],[225292,"2026-09-19T21:50:54",9,"— Можете подсказать. Использовать магию нельзя? Мы бы не хотели нарушать местный закон. — *Вордо сразу ставит все по полочкам, чтобы потом не расплачиваться за ошибки.*",225286,null],[225304,"2026-09-19T21:52:16",38,"— У нас запрещено только обучать других без специальной лицензии...",225292,null],[225315,"2026-09-19T21:54:31",11,"— А где получить эту лицензию? Кто-то у вас здесь следит за приезжими магами? И получается с лицензией обучать можно? \n\n*В своей манере протараторила дженази",225304,null],[225319,"2026-09-19T21:55:15",8,"– Я тебя инфернальному без лицензии обучу и никому не скажу. Тоже мне *обидчиво*",191019,null],[225324,"2026-09-19T21:55:43",9,"— Спасибо, я не намерен вас больше беспокоить. — *Приложил руку к груди и кивнул, но за девушек он не говорил.*",225304,null],[225327,"2026-09-19T21:55:54",38,"— Чтобы получить лицензию, вроде нужно быть при правительстве и примкнуть на верность... А когда-то давно это задело всех магов и все они ушли, а оставшиеся где-то далеко на юге...",225315,null],[225329,"2026-09-19T21:56:12",38,"— Я не знаю точно",191019,null],[225332,"2026-09-19T21:56:49",8,"– А если я просто покажу, а второй просто посмотрит, это сочтётся за обучение?",225329,null],[225336,"2026-09-19T21:57:42",38,"— Я не могу ответить точно...\n У мужчина проступил пот и он ещё немного отошёл к стене здания, чтобы создать дистанцию",225332,null],[225337,"2026-09-19T21:57:43",11,"— Вот как. Спасибо за ответы! Тогда не буду беспокоить вас более \n\n*Она отошла вслед за Вордо ожидая остальных и пытаясь проверить свои догадки \n\n— Мне кажется это и есть \"герой\" этой истории, вы тоже так думаете? — шёпотом к остальным пока Изольда говорит",191019,null],[225344,"2026-09-19T21:59:46",8,"*отошла*\n– Да, я знаю одну легенду. Она плохая, и в ней этот бедняк отправит к праотцам старуху-кредитора *поёжилась*",225337,null],[225346,"2026-09-19T21:59:57",63,"— Условия действительно отягощали настолько, что уйти показалось остальным чем-то более... \"перспективным\" что ли...?\n\nДевушка немного приблизилась к источнику сведений об этом мире, все ещё сохраняя приличную дистанцию, и, с некоторым удивлением, решила уточнить интересующую её информацию.",225336,null],[225352,"2026-09-19T22:01:31",38,"— Я не имею должной квалификации, чтобы ответить на ваш вопрос, мисс.\n Ответил мужчина и немного поклонившись головой начал идти от вас.\n— Всего хорошего ...",225346,null],[225354,"2026-09-19T22:02:25",11,"— Думаешь это он?",225344,null],[225356,"2026-09-19T22:02:59",8,"– Шляпа, одежда, цвет волос – всё сходится...",225354,null],[225360,"2026-09-19T22:03:47",63,"— Ага, прощайте.\n\nКинула она вслед, погружаясь в свои мысли. В частности, висел вопрос, а стоило ли искать того, кто в состоянии ответить, впрочем, пока необходимости в этом не было, она отбросила эти мысли и подошла к остальным.",225352,null],[225361,"2026-09-19T22:04:15",9,"— Думаю нас могут казнить или заточить даже за то что вдадеем магией. — *Высказал вслух товарищам свои мысли когда человек их уже не слышал. Такие выводы сделал Вордо по реакции человека и информации что получил.*\n\n*Корона, диктаторский режим, скорее всего есть какое-то магическое тайное бюро.*",191019,null],[225363,"2026-09-19T22:04:22",11,"— Какой план? Я бы предпочла обговорить это на \"берегу\". Предлагаю два варианта: первый — попробовать повлиять на ход истории, особенно учитывая что тебе она известна, второй — попытаться отправиться на юг и искать магов. Что скажете?",191019,null],[225366,"2026-09-19T22:05:28",8,"– А если они вырезали всех не-людей? *пытается храбриться*",225361,null],[225371,"2026-09-19T22:07:02",8,"*серьёзно*\n– Мы готовы допустить кончину двух человек от чужой руки? /не риторика, а предложение/",225363,null],[225373,"2026-09-19T22:08:34",11,"— Вопрос хороший. В прошлый раз мы это допустили и ничего не добились. Что-ж, раз тебе известна история будем пытаться повлиять на нее снова?\n\n*Аури смотрела на подругу с грустной улыбкой. Произошедшее в прошлой книге явно повлияло на неё",191019,null],[225374,"2026-09-19T22:08:41",9,"— Одно не противоречит другому. — *Взглянул на людей еще раз, возможно люди и правда слегка повлияли на популяцию других рас старым добрым геноцидом.*",225366,null],[225375,"2026-09-19T22:09:15",8,"– Я буду ждать мнения большинства. Высокий риск просто здесь находиться",225373,null],[225377,"2026-09-19T22:10:15",11,"*предпочла игнорировать ужасающее предположение пока ему нет доказательств",225374,null],[225383,"2026-09-19T22:11:35",11,"— .. — Она помолчала какое-то время, а затем все же сказала — Но ведь нас не арестовывает стража, значит их все таки не так беспокоит раса?",191019,null],[225387,"2026-09-19T22:12:14",8,"/roll 1d20+3\n*ищет стражников*",191019,null],[225391,"2026-09-19T22:12:41",63,"— Это, по виду, довольно криминальный и бедный район... может они тут просто не ходят?\n\nПредположила девушка, исходя из своего предыдущего осмотра района.",225383,null],[225396,"2026-09-19T22:13:54",38,"Ты замечаешь только пару человек в похожей форме на офицеров в Кабаке, похоже они выпивают.",225387,null],[225397,"2026-09-19T22:13:59",11,"— Реакция людей — Аури пожала плечами — посмотри как они реагируют на нас. Мой внешний вид должен был бы смутить их если их беспокоят \"не люди\"",191019,null],[225413,"2026-09-19T22:17:23",63,"— Но им как-то нет дела до этого. Может они видят в нас людей? Всё же, помимо них, здесь других существ не наблюдается. Что-то типо иллюзии? \n\nВолшебница вновь огляделась по сторонам, взглядом проверяя каждого на принадлежность к человеческой расе.",191019,null],[225414,"2026-09-19T22:17:24",8,"– Пошли в таверну, чтобы проверить гипотезу *с энтузиазмом*",191019,null],[225421,"2026-09-19T22:19:09",11,"— Да, просто спросим как они нас видят, возможно она права",191019,null],[225433,"2026-09-19T22:20:38",8,"– Если запрещено, они всё равно пьяные, мало ли привиделось",191019,null],[225443,"2026-09-19T22:21:38",11,"— Угу, прошу внутрь — она открывает дверь для вас",191019,null],[225447,"2026-09-19T22:22:27",8,"*есть ли свободные столики, как с наполненностью?*",191019,null],[225450,"2026-09-19T22:23:00",38,"Все обратили на вас внимание и вы услышали первый крик про вас.\n— Эй! Богачи! Зачем на наш район пришли! У нас и так из-за вас денег нету!",191019,null],[225451,"2026-09-19T22:23:09",38,"// Почти полный зал",225447,null],[225453,"2026-09-19T22:23:30",63,"// Та вообще, буржуи общества пришли",191019,null],[225455,"2026-09-19T22:23:45",8,"– Да я нищий музыкант, что прикопались?! Только одёжка хорошая, и то одна",225450,null],[225464,"2026-09-19T22:25:03",63,"Девушка принялась оглядывать себя и остальных, чтобы осознать, по какой причине они были выделены словом \"богачи\".\n\n// Бросок нужен?",225450,null],[225465,"2026-09-19T22:25:09",11,"*вспоминает про колличество золотых в кошельке и не понимает чем могла вызвать такую реакцию. Чуть погодя поняв причину прячет украшения в сумку",191019,null],[225466,"2026-09-19T22:25:21",38,"// Анализ",225464,null],[225467,"2026-09-19T22:25:32",63,"/r d20+6",225466,null],[225469,"2026-09-19T22:25:37",63,"// ммм",191019,null],[225471,"2026-09-19T22:25:42",63,"// зажили",191019,null],[225473,"2026-09-19T22:25:45",8,"/помощь",191019,null],[225475,"2026-09-19T22:26:05",63,"/r d20+6 если дм позволяет",191019,null],[225482,"2026-09-19T22:27:34",38,"— Говорит та, кто имеет кучу золотых в кармане!\n В вас начали лететь небольшие соринки и салфетки.\n— Так! Михаил Васильевич, успокойтесь, вы нарушаете камендатский час, прошу успокойтесь.\n Ответил один человек в форме начав успокаивать его, а второй начал успокаивать толпу.\n— Они забрали у меня мою крышу над головой и обанкротили меня!\n Кричит тот же мужчина, но уже чуть тише.",191019,null],[225486,"2026-09-19T22:28:18",38,"// Ты понимаешь, что это из-за вашего внешнего вида, особенно Вордо и похоже богачами здесь называют ещё и за расу.",225475,null],[225491,"2026-09-19T22:28:46",63,"// тем временем мои обноски одежды би лайк",191019,null],[225492,"2026-09-19T22:28:50",11,"— Ладно беру свои слова назад, кажется вы были правы, что будем делать?",191019,null],[225494,"2026-09-19T22:29:43",8,"– Не входить в толпу. Задавят",191019,null],[225502,"2026-09-19T22:30:36",8,"– Хорошая новость в том, что за расу нас не арестуют",191019,null],[225503,"2026-09-19T22:30:44",63,"— На разговор они явно не настроены. Можно, конечно, попытать удачу здесь, но...\n\nОна окинула взглядом все те недовольные лица, представшие пред ней и остальными членами группы и поняла, что проще гору покорить, нежели завести с ними нормальный диалог.",191019,null],[225517,"2026-09-19T22:33:05",11,"— Ну мы уже узнали что хотели полагаю.. Так каков план?",191019,null],[225519,"2026-09-19T22:33:21",8,"/нелюди замуровали людей в питерское гитто?/",191019,null],[225520,"2026-09-19T22:33:39",9,"— Хм. Вы подтверждаете свой социальный статус поведением. Нищие... — *Вордо не постеснялся сказать это толпе.* — Смотрящие на внешность, малодушные и лицемерные. Мы просто не местные, или вы встречаете так \"всех\" гостей? Сила и Агрессиия, не дурно что вас посчитали животными или скотом чьё мнение даже не спросили.\n\n*Он машет плащём и ВЫХОДИТ ИЗ ЭТО ШАРАГИ!*",225482,null],[225525,"2026-09-19T22:34:43",8,"– Он выражается немного грубо, но отчасти по сути! *вышла за ним*",191019,null],[225531,"2026-09-19T22:35:15",11,"— Вордо, давай без выступлений, не хватало нам ещё с толпой местных сражаться.. — девушка поспешила ретироваться боясь реакции народа",191019,null],[225534,"2026-09-19T22:35:48",8,"/вилы в печень, никто не вечен/",225531,null],[225535,"2026-09-19T22:36:10",11,"*да и словами его она была явно не довольна, о чем говорили опустившиеся брови",191019,null],[225536,"2026-09-19T22:36:13",9,"— Здесь есть стража. Мы выглядим как аристократы, они не допустят чтобы мы пострадали, пару репрессий переживём.",191019,null],[225538,"2026-09-19T22:37:06",8,"– Кроме ножика из-за угла. Осторожней со словами, Вордо",191019,null],[225539,"2026-09-19T22:37:39",11,"— Вы недооцениваете гнев толпы, господин Уорлд",191019,null],[225540,"2026-09-19T22:37:56",11,"— Но я всё ещё жду ответа на предыдущий вопрос от всех вас",225517,null],[225542,"2026-09-19T22:38:48",8,"– Надо бы найти кредиторшу и понять, какова она. Может, тоже угнетатель, нелюдь",191019,null],[225543,"2026-09-19T22:40:20",11,"— Прям как мы для этих людей? Герой один из них?",191019,null],[225545,"2026-09-19T22:40:38",9,"— Надо отыскать героя. Госпожа Изольда, как я понял вы знаете содержание этого фантастического романа? Тогда попрошу вести нас и консультировать по этому поводу. Ещё. — *Вордо понял отличие от прошлого раза.* — Мы не слышим мыслей героя. Или это \"другой стиль повествования\" или книги и правила в них отличаются на фундаментальном уровне.",191019,null],[225546,"2026-09-19T22:41:36",8,"– Я не помню адресов и точных имён. Лишь канву сюжета и немного проблему *пожала плечами*",225545,null],[225547,"2026-09-19T22:42:17",11,"— Может мы просто пока что не слышали их — предположила девушка — но как бы то ни было вы правы, Изольда, ты как знакомый с происходящим человек сильно нам облегчишь задачу \n\n*Две пары щенячьих глаз смотрят на полуэльфийку",191019,null],[225548,"2026-09-19T22:43:04",11,"— Может вы помните описание с истории по которому мы сможем найти необходимое место?",225546,null],[225549,"2026-09-19T22:44:02",8,"– Относительно неплохое место для этого квартала. Лучше поспрашивать людей *маскировка в нищенку*\n*подходит к местному с вопросом: Извиняйте. Не знаете, где найти местечко, чтобы свои вещички за медные заложить?* *отошла* /я афк на 10 минут/",191019,null],[225562,"2026-09-19T22:47:06",63,"— Та-а-ак... каков план на ближайшее время? Поиски того самого \"героя\"? Как вообще его стоит лучше всего искать?",191019,null],[225563,"2026-09-19T22:47:43",38,"// Вы буквально уже с ним встретились...",225562,null],[225564,"2026-09-19T22:47:59",63,"// а где он щас?",191019,null],[225565,"2026-09-19T22:48:00",11,"// да это понятно, но мы его уже упустили)",191019,null],[225566,"2026-09-19T22:48:04",63,"// ушел",191019,null],[225567,"2026-09-19T22:48:06",63,"// куда?",191019,null],[225568,"2026-09-19T22:48:08",63,"// хз",191019,null],[225569,"2026-09-19T22:48:45",63,"// так что вопрос не лишён смысла, как по мне.",191019,null],[225577,"2026-09-19T22:50:43",38,"// Подождите возвращения Фантомаса",225569,null],[225620,"2026-09-19T23:05:50",8,"*волчицу я оставила у Аури временно*",191019,null],[225623,"2026-09-19T23:07:34",11,"*гладит волчицу\n\n— Судя по всему будем искать ключевых персонажей",225562,null],[225624,"2026-09-19T23:08:24",8,"/пытаюсь выяснить адрес процентщицы/",191019,null],[225632,"2026-09-19T23:11:49",38,"// Кинь историю",225624,null],[225636,"2026-09-19T23:12:35",8,"/roll 1d20+2 хотя я в маскировке у людей спрашивала, но ок",191019,null],[225639,"2026-09-19T23:12:52",11,"// угу, у нее там заявка логичная так-то была",225632,null],[225642,"2026-09-19T23:13:09",8,"/прошли кубы, в целом",191019,null],[225646,"2026-09-19T23:14:07",38,"// Сорян, не увидел заявку",225642,null],[225647,"2026-09-19T23:14:58",38,"Тебе сказали, что в направлении дальше по улице, а вместе с этим ты вспомнила, что герой посчитал ровно 730 шагов по прямой...",191019,null],[225652,"2026-09-19T23:16:28",8,"– Спасибо, мил человек. *подошла к остальным, сняла маскировку, взяла собаку за ошейник, погладила, передала информацию*",191019,null],[225654,"2026-09-19T23:17:06",8,"– 730 шагов туда",191019,null],[225655,"2026-09-19T23:17:14",11,"— Тогда пойдём к бабуле? — девушка делает шаг в нужном направлении считая его — что будем делать там?",191019,null],[225659,"2026-09-19T23:18:18",8,"– Хотя бы проясним ситуацию. Услышанная однажды версия может оказаться неправдивой. В ней уже не было межрасовой вражды",191019,null],[225661,"2026-09-19T23:19:30",11,"— Хм и то верно — девушка остановилась на мгновение достала перо из-за уха и записала об этом в книгу — он ведь просил о таких вещах доложить..",191019,null],[225664,"2026-09-19T23:19:54",11,"— Такс, ну пошли дальше!\n\n*Смело шагает вперёд считая шаги",191019,null],[225678,"2026-09-19T23:23:17",63,"// сорян, я щас спать пойду, глаза слипаются нещадно. Спокойной ночи",191019,null],[225685,"2026-09-19T23:24:06",8,"/спокойной",191019,null],[225688,"2026-09-19T23:24:41",38,"// Спокойной, тогда когда все смогу завтра?",191019,null],[225689,"2026-09-19T23:24:48",38,"// Если смогут конечно",191019,null],[225690,"2026-09-19T23:24:52",11,"// спокойной ночи!\n\nЯ смогу, но ты пока опиши наверное куда мы пришли то) раз мы уже говорим что идём",191019,null],[226318,"2026-09-20T08:42:37",63,"// хороший вопрос, днём где-то, у меня онлайн будет в 17, так что до него только смогу нормально играть",225688,null],[226358,"2026-09-20T11:21:30",38,"// @Ko11lu Jade Fantomas Hard сможете в 13 по мск?",191019,null],[226452,"2026-09-20T13:19:51",38,"Пройдя около 730 шагов вы прошли одно здание, которое выделялось среди других. Оно стояло около моста и имело рядом речку, похоже здесь стоят мосты и небольшие речки по всему городу.\n Подходило семь часов вечера, по часам на одном из зданий.",191019,null],[226453,"2026-09-20T13:21:21",8,"/@Ashenchampion Hard?",191019,null],[226454,"2026-09-20T13:22:35",11,"// тут",191019,null],[226455,"2026-09-20T13:22:44",8,"*ищет взглядом главный вход и чёрный*",191019,null],[226456,"2026-09-20T13:23:36",11,"— Это оно, Изольда?\n\n*Девушка закончила считать шаги и остановилась",191019,null],[226457,"2026-09-20T13:24:11",38,"// Щас, полноценно сяду за пк и напишу",191019,null],[226458,"2026-09-20T13:24:20",38,"// На телефоне не удобно искать информацию",191019,null],[226459,"2026-09-20T13:26:14",63,"— И как мы планируем повлиять на историю?\n\nДевушка осматривала здание, в мыслях отсчитывая его этажи без особой причины.",191019,null],[226460,"2026-09-20T13:27:38",8,"– Можно отговорить молодого человека от уб.йства. Но нужны правильные аргументы и понимание ситуации. А где мы это узнаем? Ровно здесь!",226459,null],[226461,"2026-09-20T13:28:11",11,"— Не знаю.. в прошлый раз нам не удалось, может быть у тебя есть идеи? — Аури пнула какой-то камушек у своих ног — Наверное стоит уточнить что герои стараются следовать сюжету даже если мы пытаемся на них влиять",191019,null],[226462,"2026-09-20T13:28:54",8,"– У тебя была хорошая идея вывести героя за литературную карту",191019,null],[226463,"2026-09-20T13:29:04",11,"— А может просто предупредим пожилую даму о скором покушении на нее?",226460,null],[226464,"2026-09-20T13:30:08",8,"– Нужно понять, что сюжет не врал и он точно хочет. И да, вероятно, сама бабушка немного карга, стоит быть осмотрительней",226463,null],[226465,"2026-09-20T13:31:08",11,"— То есть пока что мы наблюдаем, а не вмешиваемся?",191019,null],[226466,"2026-09-20T13:33:03",63,"— Наверное, стоило бы удостовериться в том, что сюжет этого места равен известному.",191019,null],[226467,"2026-09-20T13:33:12",8,"/без Харда не очень социалить",191019,null],[226486,"2026-09-20T13:47:44",9,"//Момент, я не знаю что сказать 😅",191019,null],[226489,"2026-09-20T13:48:19",38,"// Прошу не обращать внимания на антенны и провода, их там нету",226455,null],[226493,"2026-09-20T13:53:39",8,"/входим или обсуждаем план?/",191019,null],[226494,"2026-09-20T13:54:23",38,"// щас я отвечу на все заявки",191019,null],[226496,"2026-09-20T13:54:35",38,"// мне тут солнце в ебало за пк светит",191019,null],[226510,"2026-09-20T14:00:16",11,"— И всё таки, раз мы решили наблюдать, то что конкретно вы хотите увидеть?",191019,null],[226513,"2026-09-20T14:01:03",9,"— Пошли, великие речи не слышат дураки. — *Помня опыт и И Саном \"отговаривать\" парня никто не собирался. Не посплушает? Ну, можно разок и по голове хлопнуть, чтобы шестеренки в мозгу может начали крутится.*\n\n*Вордо вспомнил несколько методов обудения, кнута и пряника, ну или ремня. Может что-то подобное сработает на короткоживущем представителе людей? Даже сам Вордо мог сказать что первые 70 лет детства самые тяжёлые, а у людей иногда и того нет.*",191019,null],[226515,"2026-09-20T14:01:40",8,"– Хочу поговорить со старушкой и узнать положение дел. Её отношение к парню",191019,null],[226517,"2026-09-20T14:02:00",11,"— И правда, нас четверо, а он один ещё и без подельников.",226513,null],[226518,"2026-09-20T14:02:25",11,"— Что-ж, вперёд\n\n*Аури уже взяла за привычку открывать дверь группе, мужчин же в ней не было",226515,null],[226519,"2026-09-20T14:02:41",8,"*стучит в дверь*",191019,null],[226529,"2026-09-20T14:04:30",38,"Так как это был дом с квартирами, что были не как у дом И Сана на улицу, а из внутри в квартиру вы могли заметить, что вам нужно найти нужную квартиру.\n А так только было семь часов.",191019,null],[226532,"2026-09-20T14:06:17",8,"/roll 1d20+2 попытка вспомнить, но, вроде, лавка была на нижних этажах",191019,null],[226534,"2026-09-20T14:06:24",11,"// я верю что Изольда помнит описание нужной двери:D\n\nБудь я тобой, Денис, дала бы проверку на истории и при провале мы бы стучали в случайную дверь с приколом",226519,null],[226539,"2026-09-20T14:07:18",38,"Ээээ, вроде на четвертом этаже, а в какой квартире?",226532,null],[226541,"2026-09-20T14:08:15",8,"– Ребят, пошли стучаться на четвёртый этаж. Номер комнаты не знаю *побежала*",191019,null],[226544,"2026-09-20T14:09:17",11,"*спорт это жизнь, а догонялки - азарт. Аури побежала по лестнице следом за подругой \n\n— Кто последний тот проиграл!",191019,null],[226549,"2026-09-20T14:11:49",63,"— ... \"квартиры\"?\n\nДевушка с лёгким недоумении последовала вверх по лестнице за остальными, решив просто понаблюдать, куда они там собрались стучать.\n\n// Хз, может ли знать мой персонаж, что такое квартира. Честно хз, но как будто навряд ли",191019,null],[226555,"2026-09-20T14:12:35",38,"// конечно не знает, такого понятия еще не было в обиходе",226549,null],[226556,"2026-09-20T14:13:07",8,"/исправила",226555,null],[226557,"2026-09-20T14:13:07",11,"// немного поддушнили, ну исправим на комнаты, историю же Изольда знает и мастер этого не против",191019,null],[226559,"2026-09-20T14:13:21",9,"*Вордо взглянул на Ноа, и просто пошёл за своими непоседливыми товарищами. Он ещё не бегал по лестницам.*\n\n//Квартиры были еще в древнем риме, цивилизация чо. Зависит от начитанности",191019,null],[226560,"2026-09-20T14:13:36",38,"// как бы я не душный на такого плана терминологию",226557,null],[226561,"2026-09-20T14:13:40",8,"/инта 11, посему комната",226559,null],[226569,"2026-09-20T14:15:34",63,"// так вы слышали в прошлом уже, что такое квартира, разве нет? Как минимум, в прошлой истории",191019,null],[226570,"2026-09-20T14:15:42",38,"// Они, да",226569,null],[226571,"2026-09-20T14:15:46",38,"// Ты, нет",191019,null],[226574,"2026-09-20T14:16:15",11,"// давайте продолжим\n\nМы все поднялись, Изольда стучится куда-то:D",191019,null],[226577,"2026-09-20T14:17:41",38,"На втором с лестничной площадки было видно, как там кто-то работает.\n На третьем было полностью пусто.\n На четвёртом же этаже было видно пару квартир, около пяти. Две по боками и одна в самом центре коридора.",191019,null],[226578,"2026-09-20T14:17:46",38,"Все заперты.",191019,null],[226579,"2026-09-20T14:18:04",8,"*где-то есть вывески?*",191019,null],[226582,"2026-09-20T14:19:37",11,"*Вместе с Изольдой оглядывается в поисках табличек именных, как в прошлой истории",191019,null],[226583,"2026-09-20T14:19:56",38,"Ты не видела никаких вывесок, кроме вывески на третьем этаже \"Снято\"",226579,null],[226584,"2026-09-20T14:20:17",8,"/стучим на рандом?)/",191019,null],[226585,"2026-09-20T14:20:42",63,"// обратись у богам свыше, хз",191019,null],[226587,"2026-09-20T14:20:49",63,"// а за дверьми слышно что-нибудь?",191019,null],[226588,"2026-09-20T14:20:53",38,"// можешь кинуть историю сл 20",226584,null],[226589,"2026-09-20T14:20:59",38,"// тишина",226587,null],[226590,"2026-09-20T14:21:24",11,"— Ну раз мы не знаем куда стучаться..\n\n*Аури стучит в случайную дверь",191019,null],[226591,"2026-09-20T14:21:25",8,"/как вдохновение работает твоё?/",226588,null],[226596,"2026-09-20T14:21:58",38,"// переброс результата только у себя",226591,null],[226600,"2026-09-20T14:22:38",8,"/roll 1d20 вдруг",191019,null],[226605,"2026-09-20T14:22:55",9,"— Изольда, думаешь здесь единственное место/лавка это квартира процентщицы? Попробуй вспомнить мелкие детали. — *Вордо подошел давая несколько советов.*\n\n//Указание!",191019,null],[226607,"2026-09-20T14:23:17",8,"/17+2+указание",191019,null],[226608,"2026-09-20T14:23:18",38,"Ты вспоминаешь, что только на этом этаже она живет и напротив лестничной площадки",226600,null],[226610,"2026-09-20T14:23:23",11,"— В чём проблема? Просто спросим соседей в какой комнате живёт старушка.",191019,null],[226611,"2026-09-20T14:23:27",38,"// указание?",226607,null],[226612,"2026-09-20T14:23:28",8,"/roll 1d4",191019,null],[226614,"2026-09-20T14:23:49",38,"// Переписал",226608,null],[226615,"2026-09-20T14:23:50",11,"— А если не откроют постучим в другие",226610,null],[226616,"2026-09-20T14:24:02",11,"// Денис, реагируй пожалуйста 😢",191019,null],[226617,"2026-09-20T14:24:17",8,"– Напротив лестничной площадки! Вордо, спасибо",191019,null],[226619,"2026-09-20T14:24:22",11,"*Следуя своим словам девушка стучит в другую дверь, а затем ещё.. пока не откроют",191019,null],[226620,"2026-09-20T14:24:33",38,"Ты услышала тишину и какой-то шорох.\n— Кто там?\n Послышалось из-за двери, голос был мужской",226590,null],[226625,"2026-09-20T14:25:03",11,"— Здравствуйте! Не скажете где здесь живёт бабуля.. это.. процентщица, в какой комнате?",191019,null],[226626,"2026-09-20T14:25:13",9,"//Указание не вдохнова барда, но зато бесконечное ~",191019,null],[226628,"2026-09-20T14:26:14",8,"*стучит напротив лестничной площадки, негоже мешать Аури болтать)*",191019,null],[226629,"2026-09-20T14:26:39",38,"— Эта жадная старуха? В квартире напротив лестницы... А теперь проваливайте, мешаете спать!\n Сказал мужчина.",226625,null],[226630,"2026-09-20T14:26:52",9,"//Вордо за изольдой зака за каменной стеной ^^",226628,null],[226631,"2026-09-20T14:27:05",8,"/я ниже",191019,null],[226632,"2026-09-20T14:27:14",11,"— Прошу прощения, спасибо! — обернувшись Аури обнаружила что группа уже вспомнила куда надо и пожала плечами",191019,null],[226633,"2026-09-20T14:27:28",9,"//Как за оградой 😏👌",226631,null],[226634,"2026-09-20T14:27:29",11,"// ну пока вы думаете как, я делаю;)",191019,null],[226635,"2026-09-20T14:27:46",38,"Ты ничего не слышишь. Будто никого нету внутри.\n\n// Если хочешь еще один бросок истории",226628,null],[226636,"2026-09-20T14:28:03",11,"— Может ее дома нет?",191019,null],[226637,"2026-09-20T14:28:10",8,"– Она занята, возможно",191019,null],[226638,"2026-09-20T14:28:25",11,"— Но дверь нужная, сосед подтвердил, а так же сказал что она жадная",191019,null],[226639,"2026-09-20T14:28:40",8,"– Но её сестра могла бы вернуться. Лизбет?",191019,null],[226642,"2026-09-20T14:29:39",11,"— Это имя сестры или мамой бабули?",226639,null],[226647,"2026-09-20T14:30:36",8,"– Сестра, но ждать её ещё...",191019,null],[226649,"2026-09-20T14:31:02",11,"— Есть другие варианты?",191019,null],[226650,"2026-09-20T14:31:29",11,"// вообще можем попытаться переубедить его через Соню кстати",191019,null],[226654,"2026-09-20T14:31:40",8,"– Осмотреть втихую, но это немного незаконно. Или подождать",191019,null],[226655,"2026-09-20T14:32:00",11,"*смотрит на Вордо\n\n— Он умеет сквозь дверные щели проходить",191019,null],[226656,"2026-09-20T14:32:06",11,"— Вот только что мы ищем то?",191019,null],[226657,"2026-09-20T14:32:11",38,"Вы слышите небольшой шорох и звук снимания запора.\n Дверь, отворилась на крошечную щелочку, и два вострые и недоверчивые взгляда уставились на вас из темноты.\n Крошечная, сухая старушонка лет шестидесяти.  Вострый и маленький нос, вострые и злые глазки, бегающий взгляд. Простоволосая, седоватая или «белобрысая», жирные, жидкие волосенки с масляной прядью на макушке (завязанной в крысиный хвостик «покрасневшим» или засаленным гребнем). На плечах — старая, короткая меховая кацавейка (теплая кофта), на шее — какое-то тряпье.",191019,null],[226659,"2026-09-20T14:32:18",8,"/только они познакомились после уб-ва",226650,null],[226660,"2026-09-20T14:32:27",38,"— Господи! Да чего вам?.. Кто такие? Что вам угодно?",191019,null],[226661,"2026-09-20T14:32:29",11,"// познакомить раньше? Хд",226659,null],[226667,"2026-09-20T14:34:21",8,"– Поговорить. Если диалог наладится, помочь",191019,null],[226669,"2026-09-20T14:35:09",11,"// жду ваших заявок пока ибо мое предложение предупредить о покушении не было согласовано",191019,null],[226670,"2026-09-20T14:35:41",38,"— Поговорить? Зачем пришли?\n Старуха пару раз кашлянула, вместе со своим резким голосом.",226667,null],[226673,"2026-09-20T14:38:23",9,"— У нас к вам дело миледи, жизни и смерти, но не нашей. Думаю вы сами будете более заинтересованны в результате... — *Вордо сказал всё туманно и ласково, перед этим на всякий случай настроевшись на выступление, его плащ начал развиваться при этом и он протянул руку будто в реверансе слегка наклонившись, выглядя почтительно и учтиво.*\n\n//Развевающийся плащ и указание, тебе старуха наша помощь необходима! Мы из компании орифлейм все такие загадочные и крутые",226660,null],[226675,"2026-09-20T14:39:12",9,"//Ну чо, она наверное ровесница Вордо или немного младше, флиртуем с бабушкой",191019,null],[226676,"2026-09-20T14:39:25",11,"*довольная тем что кто-то поддержал ее идею дженази готова помогать при необходимости в импровизации",191019,null],[226677,"2026-09-20T14:39:49",11,"// помогаю соблазнять бабку\n\nА вообще звучит как план, давай Хард вперёд,!",191019,null],[226679,"2026-09-20T14:40:06",9,"//Я настроился ещё, типа указание на себя 😂👍",191019,null],[226680,"2026-09-20T14:40:09",38,"— Чаго? Кха-кха... Какой жизни и смерти? Мне еще рано умирать!",226673,null],[226681,"2026-09-20T14:40:18",38,"Резким голосом сказала старуха",191019,null],[226684,"2026-09-20T14:40:55",11,"— Вот именно, дорогая госпожа! Но на вас готовится покушение, которое нам хотелось бы предотвратить!",191019,null],[226685,"2026-09-20T14:41:42",38,"— Что за чушь вы мне мелите! Пошли вон!\n Ответила старуха и начала немного закрывать дверь.",191019,null],[226686,"2026-09-20T14:41:59",8,"*пролезает в дверь*",191019,null],[226687,"2026-09-20T14:42:09",9,"— Вы ещё молоды, поэтому мы и пришли. В ваших глазах покоится опыт, думаю вы примите верное решение, я верю в это. Скажу вам по секрету... магия. — *Вордо последнее слово прошептал.* — Она указала нам на вас и ваше будущее, мы бы хотели его изменить, вы должны прожить еще очень долго...",226680,null],[226688,"2026-09-20T14:42:20",11,"// даже без бросков на убеждение?\n\nОпять вайб бессмысленных попыток пошел",226685,null],[226689,"2026-09-20T14:42:35",38,"— А ну кыш!",226686,null],[226690,"2026-09-20T14:42:43",38,"// Вот теперь броски в студтю",191019,null],[226691,"2026-09-20T14:42:54",9,"//А я хз что кидать",191019,null],[226692,"2026-09-20T14:43:05",38,"// проверку убеждения",226691,null],[226695,"2026-09-20T14:44:32",9,"/roll +d20+1d4 мне вроде помогают и указание",191019,null],[226698,"2026-09-20T14:46:01",38,"// Откуда еще один бросок?",191019,null],[226699,"2026-09-20T14:46:02",9,"— Изольда, дорогая. Мы не сможем помочь если миледи против, судьба её настигнет раньше, что горестно.",191019,null],[226700,"2026-09-20T14:46:12",9,"//Кто то нажал наверное",191019,null],[226701,"2026-09-20T14:46:42",11,"// миссклик от кого-то, бывает",191019,null],[226702,"2026-09-20T14:47:10",8,"– Да, но не хотелось бы, как в тот раз. Это было ужасно! *театральный страх, чтобы запугать бабку*",191019,null],[226703,"2026-09-20T14:47:11",38,"Старуха немного задумалась и открыв дверь побольше сказала.\n— Тогда ты, Батюшка, можешь войти, остальные, пошли вон!",226696,null],[226705,"2026-09-20T14:47:36",8,"*вежливо отошла*",191019,null],[226708,"2026-09-20T14:48:16",11,"*кладет руку на плечо Вордо на последок желая удачи",191019,null],[226712,"2026-09-20T14:49:36",9,"— Благодарю миледи.\n\n— Изольда, ты наша прорицательница, напомни мне что именно должно случится. — *Вордо спросил её перед тем как войти, все же он не совсем понима \"что\" должен делать.*",191019,null],[226713,"2026-09-20T14:50:37",8,"– Парень считает себя выше остальных, королем, поэтому, мол, имеет право на уби.ство таких \"блох\", как старушка. Скоро проверит теорию",191019,null],[226714,"2026-09-20T14:52:26",11,"*Аури дожидается пока Вордо зайдет убеждать пожилую женщину, а затем обращается к Изольде немного отведя ту от двери\n\n— Постараться предупредить бабулю хорошая идея, но нам нужен запасной план раз мы решили влиять на историю, не могла бы ты подсказать способы повлиять на самого героя?",191019,null],[226717,"2026-09-20T14:53:34",8,"– Тонкая душевная организация, способность на раскаяние, меланхолия и психованность. Это целый букет *хмыкнула*",191019,null],[226718,"2026-09-20T14:53:52",9,"//Щас зафакаплю, хахахах, я не игрок в соло 😂👍",191019,null],[226719,"2026-09-20T14:54:01",11,"— Я имею ввиду что нужно постараться сделать все что в наших силах. У меня уже есть одна идея, как на счёт того что бы убедить стражников местных в том что готовится покушение и притащить их на место, к времени преступления?",191019,null],[226721,"2026-09-20T14:54:16",11,"// мы в тебя верим, давай, если что уже готовим запасные планы",226718,null],[226724,"2026-09-20T14:54:58",8,"– После содеянного влюбится... Послушай, может, сюжет врёт. Надо отговорить его от своей пагубной теории",191019,null],[226725,"2026-09-20T14:55:48",11,"— Давай попробуем, на всякий случай Вордо предупредит бабулю, а мы сможем позвать стражников. Ох, наверное стоило ему сказать убедить бабулю выехать на время с города..",191019,null],[226726,"2026-09-20T14:56:04",38,"// Так, Вордо зашел уже?",191019,null],[226727,"2026-09-20T14:56:08",9,"— Позвольте войти в ваш дом миледи. — *Если начал фамильярничать то будет, внутри он взял её за руку и слегка поклонившись совершил приветствие как на балу слегка коснувшись её обратной стороны ладони своим подбородком.*\n\n//Что в квартире, мне бы знать",226703,null],[226728,"2026-09-20T14:56:18",63,"Девушка, пока остальные предпочли вести диалог со старушкой, что довольно явно выказывала свое недовольство, была, по большей части, сфокусирована на осмотре внутреннего интерьера сего здания, которое, впрочем, как и всё в этом месте, или точнее — книге, выглядело абсолютно иначе, нежели в её мире.\n\nЛюбопытство, что не могло не скопиться в задворках её сознания, по большей части и стало причиной столь детального осмотра, перерастая позднее и в размышления о том, насколько вообще удобно жить в подобных местах, которые походили, скорее, на временные комнаты, нежели на постоянное место для проживания.",191019,null],[226740,"2026-09-20T15:06:02",38,"Ты переступил через порог в темную прихожую, разгороженную перегородкой, за которою была крошечная кухня.\n Небольшая комната, в которую прошел Вордо, с желтыми обоями, геранями и кисейными занавесками на окнах, была в эту минуту ярко освещена заходящим солнцем… Но в комнате не было ничего особенного. Мебель, вся очень старая и из желтого дерева, состояла из дивана с огромною выгнутою деревянною спинкой, круглого стола овальной формы перед диваном, туалета с зеркальцем в простенке, стульев по стенам да двух-трех грошовых картинок в желтых рамках, изображавших немецких барышень с птицами в руках, — вот и вся мебель. В углу перед небольшим образом горела лампада. Все было очень чисто: и мебель, и полы были оттерты под лоск; все блестело...\n Ни пылинки нельзя было найти во всей квартире. Покосившись на ситцевую занавеску перед дверью во вторую, крошечную комнатку, где стояли старухины постель и комод и куда еще никто ни разу не заглядывал. Вся квартира состояла из этих двух комнат.\n\n Старуха провела тебя на диван и сев рядом спросила.\n— И чего вам всем надобно в столь поздний час? Кха...",226727,null],[226746,"2026-09-20T15:07:57",38,"Ты могла отметить первое различие с \"родным\" миром в том, что здесь все сделано из камня и только двери из дерева.\n Вместе с этим ты могла отметить, что это больше подходит на разделение одного здания на части и продажа жилья для большего количества людей. Конечно же ради большей выгоды правительства и казны.\n\n// Основано на пассивном использовании твоего анализа",226728,null],[226779,"2026-09-20T15:22:48",11,"// куда все подевались :(",191019,null],[226780,"2026-09-20T15:22:55",38,"// хз",226779,null],[226782,"2026-09-20T15:25:21",11,"*Закончив разговор с Изольдой дженази прислоняет ухо к двери что бы послушать беседу между двумя стариками",191019,null],[226783,"2026-09-20T15:26:51",63,"// хз чо делать и как персонаж и как игрок",191019,null],[226784,"2026-09-20T15:27:08",11,"// ну по сути Харда ждём и верим",191019,null],[226793,"2026-09-20T15:31:26",9,"//Я не знаю что делать, моя проблема что я не соло герой, ммм, щас подумаю. + ирл чутка отвлекся было",191019,null],[226800,"2026-09-20T15:32:40",38,"// Понимаем",226793,null],[226805,"2026-09-20T15:34:25",11,"// Тебя никто не закидает палками если не выйдет, не переживай🫶",226793,null],[226806,"2026-09-20T15:34:58",9,"//Думаю!!!)))",191019,null],[226812,"2026-09-20T15:40:02",9,"//Что же",191019,null],[226822,"2026-09-20T15:51:56",9,"*Вордо вздохнул отруская напускную фамильярность.*\n\n— Простите меня миледи. Слегка опустим загадки и пророчеств. Я пришёл предупредить вас о смерти. Но я не знаю, когда именно она придёт и как именно это произойдёт. Знаю только одно: человек, который должен вас убить, считает вашу жизнь ничего не стоящей. — *Вордо говорил уверенно и честно, строить планы? Не в его стиле, в его стиле брать и решать проблему на корню, прямо. Он сел на старый диван, осмотрев окружение, всё содержалось в чистоте, даже если старое.*\n\n— Вы можете не верить мне, на вашем месте не верил бы. Поэтому я не прошу вас поверить. Я прошу вас рассказать мне, кому вы могли так сильно помешать, что он решил вас убить. — *Вордо знал ответ, но и что с того?*\n\n— Мы знаем кусочек вашего будущего. Я не пророк и не святой, лишь немного волшебник. — *Он взмахивает рукой призывая несколько огоньков, словно маленькие скопления звезд, они закружились по комнате и исчезли.*\n\n//Послн этого метамагия, безмолвное, указание себе!\n\n— Мне не нужны ваши деньги, имущество, ваша вера в мои слова. Я и мои спутницы преследуем собственные цели, вы лишь были случайно в это впутанны миледи. Я сказал всё, можете выставить меня за дверь если вам не понравились мои слова, решайте сами, но я считаю. — *Он встал и подошёл ближе, нависнув над старушкой своей высокой фигурой.* — Судьба... такая дрянь, вы должны сами выбрать свою судьбу миледи...\n\n*Он развернулся и снова сел на диван смотря \"что будет делать старуха процентщица?\"*",191019,null],[226823,"2026-09-20T15:52:37",9,"//Бля какой пипец, мне аж немного стыдно  за этот текст 🫠",191019,null],[226826,"2026-09-20T15:55:29",11,"// Стесняться в нри ты о чем, брат?\nКрасиво написал все по факту",191019,null],[226842,"2026-09-20T16:04:36",11,"*Волшебница подслушивающая под дверью сжала руку в кулачок. После предыдущих высказываний коллеги она немного переживала о том как может пройти беседа, впрочем, то что прозвучало из его уст сейчас - ее успокоило и хмурые брови девушки расслабились. Будь она на месте старухи точно бы пошла на встречу, но характеры у них разные так что Аури просто надеется что процентщица  прислушается к ним.",191019,null],[226845,"2026-09-20T16:04:58",38,"// Щас отпишу, у меня тут катка в кс",191019,null],[226854,"2026-09-20T16:07:22",11,"// извините, удалю\n\nЛадно не удалю раз вы не против:)",191019,null],[226869,"2026-09-20T16:15:27",38,"// просто получай вдохновение",226854,null],[226872,"2026-09-20T16:17:38",9,"// Вордо Pow: \"То что окружающие тупни их проблемы — не мои.\" (На случай важных и провальных переговоров)",191019,null],[226891,"2026-09-20T16:28:12",38,"— Ха! Много людей желают моей смерти! Только никто этого не делает, ведь боится столкнуться с последствиями!\n Резким голосом говорила старуха, но все же в её голове ненадолго застряли твои глаза и она спросила.\n— Как выглядит человек, который это сделает?",226822,null],[226896,"2026-09-20T16:31:32",9,"— Человек. Молодой. Уверенный в том что имеет право решать кому жить. — *Это всё что знал Вордо, он не запомнил того походимца.* — И самое неприятное, он не считает себя злодеем.\n\n*Дав немного подумать старушке он сказал еще кое что.*\n\n— Он сделает это потому что считает что последствий не будет. Люди глупы и импульсивны по своей природе миледи. Особенно молодые, те кому нечего терять или обозленные на мир.",226891,null],[226897,"2026-09-20T16:32:27",8,"/бедный, в рыжей длинной шляпе/",191019,null],[226898,"2026-09-20T16:32:49",9,"//Я не смотрел 😎",226897,null],[226909,"2026-09-20T16:39:40",38,"— Таких полно на свете! Я сама такая!\n Ответила старуха и подумав над вторыми словами ответила уже с сожалением.\n— Последствия всегда будут... Даже моя Лизонька тому подтверждение...\n Старуха прошла к шторкам и спросила.\n— Когда он придет, знаешь?",226896,null],[226922,"2026-09-20T16:48:21",9,"— Нет. Не знаю. Ту что знает больше вы оставили за дверью миледи. Признаюсь, из меня плохой слушатель и наблюдатель в силу характера. — *Вордо сказал как есть.*\n\n— Но я благодарен что вы меня выслушами, возможно ваша судьба... изменится. Последний человек меня не послушал и он полетел с крыши, сам, потому что его убедили что он полетит. — *Подошел и вместе с ней начал смотреть в окно.*\n\n— Разум и мотивация, различного рода психические расстройства. Нас такими делает мир и окружение, плохое влияние. Никто не рождается сломанным.",191019,null],[226927,"2026-09-20T16:53:52",9,"*Эпично смотрим в окно.*",191019,null],[226928,"2026-09-20T16:54:26",8,"*легендарно подслушиваем*",191019,null],[226929,"2026-09-20T16:54:54",9,"https://youtu.be/qivnSQG1bsc?si=W1jtltnb1l6n90XU",226927,null],[226930,"2026-09-20T16:55:01",38,"— Хорошо, батюшка, я поняла тебя... Спасибо что сообщили...\n Старуха начала идти в сторону выхода и сказала.\n— Тогда, если мы встретимся, то я дам вам денег за это...\n Ты понял, что она просит тебя уже покинуть квартирку.",226922,null],[226932,"2026-09-20T16:58:19",8,"*крик из-за двери* – Он высокий, черноволосый, одет в лохмотья и высокую длинную шляпу, придёт с топором!",191019,null],[226933,"2026-09-20T16:58:56",9,"— Берегите себя миледи. — *Он поцеловал ее руку на прощание прежде чем уйти.* — Мне не нужны ваши деньги, надеюсь ситуация пройдёт и мы просто поговорим за чашечкой кофе вспоминая всё это как простой страшный сон.\n\n*Уходим, мы сделали всё что могли.*\n\n//Главного героя случайно не Раскольников звать? Мне тут метагеймово о топоре сказали",226930,null],[226934,"2026-09-20T17:00:13",11,"// так и звать:)",191019,null],[226935,"2026-09-20T17:00:13",38,"// Наконец-то до тебя дошло!",226933,null],[226936,"2026-09-20T17:00:19",38,"// БЛЯЯЯ",191019,null],[226937,"2026-09-20T17:00:45",11,"*Аури вместе с Изольдой отодвигаются от двери чтоб не стукнули вместе",191019,null],[226938,"2026-09-20T17:00:47",8,"/может, узнает?/",226932,null],[226939,"2026-09-20T17:00:57",9,"//Брал волшебника а играю как бардом, чесн слово 😂👍",191019,null],[226940,"2026-09-20T17:00:59",38,"// узнаешь",226938,null],[226942,"2026-09-20T17:02:27",8,"/Лемн говорила, что сейчас занята будет/",191019,null],[226943,"2026-09-20T17:02:52",38,"// Я вот кину последний ответ и мы закончим на сегодня",226942,null],[226944,"2026-09-20T17:05:01",63,"// можете продолжить, в принципе, я так или иначе валенком болтаюсь",191019,null],[226945,"2026-09-20T17:05:22",8,"/давай вместе попытаемся всё-таки. Сейчас была социалка у Вордо, дальше заодно лучше",226944,null],[226947,"2026-09-20T17:05:56",38,"Старуха открыла дверь и выпроводила тебя за дверь.\n Вместе с этим она закрыла дверь и вы услышали звук закрытия замка.\n На этом все снова стало тихо и похоже осталось ждать решений.\n\nТакже вы услышали голос уже другого рассказчика похожий на того самого молодого человека, что ответил вам на вопросы.\n«И с чего взял я, с чего взял я, что ее непременно в эту минуту не будет дома? Почему, почему, почему я так наверно это решил?»\n«И какой случай навсегда потерял!»\n«Так и есть, нет дома! Где-нибудь близко, впрочем, на дворе, потому что дверь отперта настежь»\n«Не рассудок, так бес!»\n«Что за вздор. Нет, лучше совсем ничего не думать!»\n«Так, верно, те, которых ведут на казнь, прилепливаются мыслями ко всем предметам, которые им встречаются на дороге.» \n«Что это, неужели половина восьмого? Быть не может, верно, бегут!»",191019,null],[226949,"2026-09-20T17:05:59",9,"//До меня тоже только только начало доходить немного что делать. Но я в душе не ипу, просто чет делаю",226944,null],[226950,"2026-09-20T17:06:58",63,"// если так хотите, то окей",226945,null],[226951,"2026-09-20T17:09:18",11,"// надо попытаться тебя втянуть, согласна с Фантомас, вместе нужно",226950,null],[227858,"2026-09-21T07:35:08",38,"// @Ashenchampion @Ko11lu Hard Fantomas предлагаю после 13 по мск, все смогут?",191019,null],[227888,"2026-09-21T09:19:34",63,"// пары до 14, после смогу",191019,null],[227938,"2026-09-21T10:53:26",8,"Всё ок, но у меня занято с 16 до 18",227888,null],[227949,"2026-09-21T11:09:44",38,"// Короче у нас будет перерыв. Начнем с 14 по мск до 16, затем уже с 19 и до победного.\n(У меня сегодня репетитор с 17)",191019,null],[228050,"2026-09-21T14:12:51",38,"// Так Hard @Ko11lu Fantomas @Ashenchampion продолжаем!",191019,null],[228052,"2026-09-21T14:12:56",38,".",226947,null],[228063,"2026-09-21T14:19:17",8,"– Покараулим здесь или развеемся среди этой серости? *раскинув по сторонам руки, на носке развернулась к остальным* Времени может быть немного",191019,null],[228071,"2026-09-21T14:21:54",11,"— Где нам искать героя, Изольда, есть идеи?",191019,null],[228073,"2026-09-21T14:22:10",11,"— Давайте попытаемся сделать что нам по силах, вдруг получится повлиять?",191019,null],[228078,"2026-09-21T14:23:27",9,"— Думаю мы слабо повлияли на ситуацию. Сюжет не изменить так легко. — *Вордо откинул плащ и уперся на лестницу.* — Есть еще вариант остановить героя этой истории. Он будущий убийца, даже если сейчас еще ничего не сделал, но мне кажется что прямое вмешательство повлечет за собой последствия.",191019,null],[228079,"2026-09-21T14:23:35",8,"/я не помню, но около грязной речки/",191019,null],[228080,"2026-09-21T14:24:09",8,"– Какой?",228078,null],[228086,"2026-09-21T14:25:24",9,"— Ты догадываешься. — *Да, самый радикальный, но вы не следите за остальными словами.*",228080,null],[228087,"2026-09-21T14:25:50",8,"/всегда есть вариант подождать здесь и устроить пве с Раскольниковым/",191019,null],[228089,"2026-09-21T14:26:32",38,"// Бля!",191019,null],[228090,"2026-09-21T14:26:39",8,"*понимающе кивнула* – Или ждать здесь. Рано или поздно он здесь появится",191019,null],[228095,"2026-09-21T14:30:07",8,"– Я лишь слабо помню, что он живёт возле грязного канала, в комнатке, похожей на гроб *нервно хихикнула* Приятное местечко",191019,null],[228098,"2026-09-21T14:31:30",11,"// все ещё актуально предложение о попытке познакомить его с соней раньше",191019,null],[228100,"2026-09-21T14:31:47",38,"Где-то вдруг часы пробили один удар. \n«Что это, неужели половина восьмого? Быть не может, верно, бегут!»\nПослышалась фраза рассказчика и вы услышали, как кто-то вошел внутрь на первый этаж.",191019,null],[228105,"2026-09-21T14:32:21",11,"— И мы будем использовать магию что бы остановить его? Может все таки попытаемся убедить местных стражников что бы не вмешиваться самим? Есть у меня предположение что нам надо влиять на историю через других, а не самим напрямую",228090,null],[228107,"2026-09-21T14:32:44",11,"— Или уже поздно? \n\n*Выглядывает на лестничный проём",228100,null],[228112,"2026-09-21T14:33:08",8,"/roll 1d20+3 \nЧто видно?",191019,null],[228117,"2026-09-21T14:36:12",38,"Вы замечаете что кт0-то начал подниматься по лестнице и вы видели только его руку, что шла вдоль перил и очень часто останавливалась, будто прислушивалась.",228107,null],[228120,"2026-09-21T14:37:19",11,"*Аури оглядывается на группу с выражением лица: «что делаем?»\n\n//Латте нету кстати",191019,null],[228121,"2026-09-21T14:38:07",8,"– Попробуем поговорить? Если надо, я за стражей побегу",191019,null],[228123,"2026-09-21T14:38:58",8,"@Ko11lu",191019,null],[228126,"2026-09-21T14:40:00",11,"— У меня есть идея как попытаться убедить стражей — девушка наклоняется к подруге что бы шептать — убедись что это тот человек, если действительно он я побегу искать стражников",191019,null],[228128,"2026-09-21T14:40:46",8,"*замаскировавшись под бедную девушку, выходит посмотреть*",191019,null],[228132,"2026-09-21T14:42:33",9,"// Раскольников pow: https://youtu.be/kDFE7Tb1SlA?si=pYtsSBvt_3TUJ79d",191019,null],[228134,"2026-09-21T14:43:19",9,"*Вордо решил остаться тут, если что, он готов вмешаться или посмотреть \"как\" все ьудет происходить.*",191019,null],[228136,"2026-09-21T14:44:51",38,"Мужчина уже поднялся на второй этаж и когда вы встретились ты заметила, что он все такой же бледный и дрожащий.\n\n// Прошу проверку проницательности",228128,null],[228138,"2026-09-21T14:45:15",8,"/roll 1d20+1",191019,null],[228140,"2026-09-21T14:45:33",11,"/roll d20+2 помощь",191019,null],[228143,"2026-09-21T14:45:49",11,"*Аури смотрит есть ли у него оружие",191019,null],[228147,"2026-09-21T14:48:37",38,"Изольда понимает, что он очень сильно боится и если немного надавить на него, то он полностью во всем признается и даже раскается.\n И вместе с этим вы заметили, что у него за спиной что-то немного выпирает.",191019,null],[228151,"2026-09-21T14:49:30",8,"*шёпотом передала Аури*",191019,null],[228152,"2026-09-21T14:49:58",8,"/Hard @Ko11lu, ждём вас/",191019,null],[228154,"2026-09-21T14:50:19",8,"– Топор *тихо*",191019,null],[228155,"2026-09-21T14:50:27",9,"//Мне тоже проницательность?)",191019,null],[228156,"2026-09-21T14:50:59",38,"// Нет",228155,null],[228160,"2026-09-21T14:55:40",9,"*Вордо встает во весь свой рост и разминает руки.*\n\n— Здравствуйте молодой господин, мы снова встретились. Как тесен этот мир не правда ли? — *Вордо встал в позу скрестив руки, его плащ начал развиваться, с Ищольдой с одной стороны и Аури с другой это выглядило как трио из обложки супергеройских комиксов.* — Я готов с вами поговорить.\n\n*Вордо коснулся своего браслета и за ними появилось несколько парящих свечений.*\n\n// кастуем блуждающие огни в виде светящихся туманностей звездных в процессе, чел вряд ли шарит в магии",191019,null],[228163,"2026-09-21T14:56:32",38,"Мужчина сразу же отошел на один шаг назад от такого и...",191019,null],[228164,"2026-09-21T14:56:34",9,"//Это \"Мстители против раскольникова\"",191019,null],[228165,"2026-09-21T14:56:35",38,"/r 1d20-1",191019,null],[228169,"2026-09-21T14:56:50",38,"Начал падать по лестнице",191019,null],[228174,"2026-09-21T14:57:09",11,"*Аури после предыдущих попыток разговора с персонажами историй рассудила что стоит предпринимать что-то большее чем разговоры, как минимум в качестве запасного плана. За сим она помчалась вниз по лестнице и выбежала на улицу. Глаза дженази искали местных \"стражников\". Если она не видит их то бежит туда где видела в последний раз",228154,null],[228175,"2026-09-21T14:57:21",9,"//Мону ухватить его волшебной рукой чтобы не споткнулся? Скастовать быстрым заклом на лету",191019,null],[228187,"2026-09-21T14:58:30",38,"// Проверку атлетики/акробатики руки",228175,null],[228191,"2026-09-21T14:58:54",9,"//Думаю тут надо через слодность заклинаний",191019,null],[228194,"2026-09-21T14:59:31",9,"//У руки статов нет(",191019,null],[228195,"2026-09-21T14:59:45",38,"// Тогда твою",228194,null],[228196,"2026-09-21T14:59:49",9,"/roll 1d20+4 ну виртуоз заклинаний",191019,null],[228199,"2026-09-21T15:00:39",11,"// жду реакции",228174,null],[228200,"2026-09-21T15:00:45",9,"*Рука старается слегка толкнуть парня сзади чтобы не упал и развевается от усилия.*\n\n//Ьыстрым скастовал для честности",228197,null],[228212,"2026-09-21T15:01:43",38,"Ты заметила пару мужчин в форме, что шли вдоль улицы и общались друг с другом.",228174,null],[228222,"2026-09-21T15:04:32",11,"— Помогите! Там покушение на убийство! — заметив их кричит девушка не подходя и стараясь выглядеть паникующей",191019,null],[228223,"2026-09-21T15:04:35",38,"Ты успеваешь зацепить парня за его пальто и сам молодой человек еле удержался.",228200,null],[228254,"2026-09-21T15:09:33",8,"– Не трогай топор, Вордо. Аури стражников зовёт *тихо",191019,null],[228259,"2026-09-21T15:09:59",9,"— Что вы здесь делаете молодой человек. — *Вордо не стясняясь и вообще не показывая и капли страха (если тот вообще можно заметить на его звездном лице) подходит к герою и отряхивает одежду, будто \"заботясь\" о нём.*\n\n— Вы были бы не против поговорить за чашечкой чая или кофе о боге нашем вездесущем жизни? — *Смотрит слегка в сторону.* — Мир очень несправедлив, было бы интересно выслушать несколько ваших мыслей по этому поводу.\n\n//Заготавливаем уклонение если чо вдруг",228223,null],[228268,"2026-09-21T15:10:53",8,"/давайте с Лемн",191019,null],[228270,"2026-09-21T15:11:09",9,"*Топор внешне игнорируем будто его и нет.*",228259,null],[228271,"2026-09-21T15:11:13",9,"//Да, ждем",191019,null],[228369,"2026-09-21T15:27:35",38,"@Ko11lu",191019,null],[229120,"2026-09-21T18:09:19",63,"// у меня связь упала в городе интернет тоже",191019,null],[229172,"2026-09-21T18:28:50",8,"/когда наладится, напиши, пожалуйста",229120,null],[229220,"2026-09-21T18:45:27",63,"// Хз, правда, че делать и писать, но ладно",191019,null],[229236,"2026-09-21T19:12:25",63,"Девушка, всё так же сохраняя молчание и придерживаясь некоторой дистанции, доверив разбирательство с этой историей остальным, глядела на то, как некоторые из них, начали спускаться, после прозвучавшего \"свыше\" голоса и последующего хлопка в самом низу этого здания.\n\nВолшебница направилась к лестнице, взглянуть на то, что будет происходить впоследствии. В голове же у неё проносились мысли: «Как именно можно повлиять на сюжет?». Помимо, довольно очевидного убийства его главного героя и переубеждения, чтобы этот самы персонаж свернул на иную, в отличие от оригинала, тропу.\n\nОсобо новых людей по этому поводу ей не пришло, а стоящих — тем более. Самой, наверное, действенной из них, по её мнению, стала бы та, в которой необходимо выяснить мотив этого убийства и попытаться устранить его, дабы главный герой сам осознал, что смысла делать подобное нет.\n\n// Хз чо писать, пусть будет",191019,null],[229237,"2026-09-21T19:13:58",8,"*Изольда пока страхует дровосека сбоку. Расслабленно, без касаний, но начеку*",191019,null],[229238,"2026-09-21T19:15:19",11,"//:)",228222,null],[229240,"2026-09-21T19:17:18",38,"// Щас отпишу заявки",191019,null],[229244,"2026-09-21T19:17:23",38,"// Только от репетитора",191019,null],[229262,"2026-09-21T19:30:42",38,"Двое офицеров повернули на тебя свои головы и заметив твой вид, сразу же подошли к тебе.\n— Что случилось, Барышня? Где покушение?",228222,null],[229268,"2026-09-21T19:35:59",38,"Мужчина начал немного дрожать и на его лице начал идти пот. Он дёргался от твоих потряхивание одежды.\n Он левой рукой залез под внешний карман одежды и достал оттуда небольшой предмет неопределенной редкости, но на быстрый взгляд выглядящий дорогим.\n// Проверку анализа\n\n— Я-я иду... Сдавать эту вещицу под проценты...\n Ответил юноша и затем он наконец встал на ноги.\n— С чего вдруг такие знатные люди как вы, предлагаете это мне?",228259,null],[229273,"2026-09-21T19:37:37",8,"– Тебе плохо, вот и хотим поговорить. Едва ли это сильно улучшит ситуацию, но *пожала плечами с улыбкой*",229268,null],[229278,"2026-09-21T19:38:44",11,"— Там, я видела человека с топором! \n\n*Аури обернулась указать в нужное направление и в этот момент офицеры могли заметить безмолвный образ Раскольникова входящего в подъезд",229262,null],[229281,"2026-09-21T19:40:04",8,"/хештег параноики наговорили зря/",191019,null],[229289,"2026-09-21T19:41:59",9,"/roll 1d20+3+1d8 ТАКТИЧЕСКАЯ ОЦЕНКА",229268,null],[229291,"2026-09-21T19:42:14",9,"//Имба, это был анализ 😏👌",191019,null],[229352,"2026-09-21T20:21:38",38,"Офицеры посмотрели в сторону двери и заметив там небольшую толпу сказали.\n— Сейчас разберемся, Барышня...\n И они пошли в сторону дверей",229278,null],[229354,"2026-09-21T20:22:46",38,"— Что значит улучшит? В каком плане плохо? У меня небольшая лихорадка, да и только...\n Ответил молодой человек и попытался зарыться себе в шляпу и одежду",229273,null],[229357,"2026-09-21T20:23:13",38,"Ты заметил только то, что предмет довольно сильно блестит, будто его подготовили для продажи.",229289,null],[229360,"2026-09-21T20:24:53",8,"– У нас были плохие видения будущего насчёт Вашей персоны. Настолько неприятные, что захотелось предупредить, а то мало ли... *устало потёрла виски, актриса*",191019,null],[229361,"2026-09-21T20:25:35",11,"*Немного погодя идёт следом убирая концентрацию когда иллюзия скроется на лестничной клетке",229352,null],[229368,"2026-09-21T20:30:31",38,"Молодой мужчина начал трястись и упал прямо на ступеньки.\n— Правда?... Если это и вправду так... То что же такого... Нет! Не говорите мне!...\n Он начал сидеть на ступеньках и что-то бормотать себе под нос.",229360,null],[229370,"2026-09-21T20:31:49",38,"Офицеры прошли внутрь \"подъезда\" и заметив столпотворение на втором этаже поднялись туда.\n— Здравствуйте дамы и господа, что за иск столь серьезный?\n\nИх было двое и вы могли дать им обоим около 40 лет.",229361,null],[229371,"2026-09-21T20:32:01",8,"– Грядущее изменяемо. Но лишь Вашими руками *пусть Hard опишет эпичнее* *смотрит на Раскольникова*",229368,null],[229372,"2026-09-21T20:33:07",8,"– Трагедии не произошло, но мы неместные, сильно тревожимся... /жду, пусть остальные напишут/",229370,null],[229374,"2026-09-21T20:35:52",11,"*Аури молча стоит внизу слушая разговор",191019,null],[229375,"2026-09-21T20:36:44",8,"/Hard @Ko11lu",191019,null],[229383,"2026-09-21T20:38:49",38,"Ваш \"главный герой\" заметив офицеров начал немного заикаться и ответил отрывками.\n— Ох...\n Он начал немного пошатываться и почти терять сознание.\n\nОфицеры же посмотрев на молодого человека, его состояние и на вас ответили.\n— Чтож... Если он под вашей ответственностью, то мы оставляем его на вас. Если что-то здание 3-го полицейского участка Казанской части на набережной (ныне канал Грибоедова, около Львиного моста.\n На этом они поклонились и начали спускаться.",191019,null],[229390,"2026-09-21T20:42:32",11,"*Она разочарованно сползла вниз по стенке",191019,null],[229394,"2026-09-21T21:03:15",9,"— Знатные? Все мы умрем от ножа не смотря на то сколько богаты. Присядем на ступеньки? — *Полицейские ушли, с Вордо сам сел подавая пример.*\n\n— Это лишь социальное положение, и что с того что твой собеседник выглядит знатно или лучше? Это не делает тебя червем а меня королем. Но надо следовать лишь одному правилу, жить не мешая другим, если его нарушить тебя уберут навсегда из жизней тех кому ты мешаешь... тем или иным образом.\n\n*Вордо протянул руку на его руках плясали звёзды, поднимались маревом, огоньками.*\n\n— Зачем ты пришёл сюда сегодня, с какой целью? — *Вордо дал мгновение подумать прежде чем добавил:*\n\n— Мы лишь наблюдатели, читатели этой истории, мы знаем чем она окончится. Но, изменить ее можешь лишь ты, главный герой своей маленькой истории. Она должна вскоре закончится и закончится плохо, мы исчезнем. — *Вордо сжал руку в кулак и медленно, с очень маленькой силой как друга слегка толкнул парня в грудь.*\n\n— Ты можешь расказать нам в чем проблема. Мы все обсудим и постараемся решить. Выбери сам свою судьбу, прислушайся если можешь. — *Вордо накдонился парню к уху и прошептал словно секрет.* — Её можешь изменить лишь ты... тебе решать...",229268,null],[229395,"2026-09-21T21:04:13",9,"// Где повысить навык красноречия? Боже как все плохо, но так эпично с пустого в порожнее я ни в одной игре не переливал)",191019,null],[229399,"2026-09-21T21:14:13",38,"// Тебе за это будет бонус",229395,null],[229400,"2026-09-21T21:14:19",38,"// Не переживай",191019,null],[229403,"2026-09-21T21:22:09",38,"Молодой человек немного дрожал, но все же ответил.\n— Хотел доказать, что \"Тварь ли я дрожащая или право имею?\"... Как Наполеон или Петр первый... Если я избавлю мир от этой жадной и плохой старухи, то никто мне ничего плохого не скажет... Она... Она отравляет свою родственницу и не сделала ничего хорошего... \n\nВдруг вы услышали слова рассказчика в унисон словам молодого человека.\n— Лучше ошибаться по-своему, чем быть правым по-чужому... Именно в этом я точно прав...",229394,null],[229404,"2026-09-21T21:25:07",8,"– Она всего лишь часть этой системы, и мир не заметит её исчезновения. Она отчасти несчастна, как и ты. *Изольда хочет к Аури, но стеречь парня сейчас практичнее*",191019,null],[229405,"2026-09-21T21:25:55",8,"– Мы все только сгустки серой мешанины...",191019,null],[229406,"2026-09-21T21:28:03",9,"— Думаю ты прав и ошибаештся. Проблема не в правоте, а в том что в итоге? Что ты получишь. — *Вордо дал время немного и добавил:* — Ты сгниёшь в темнице, потому что тебя испугаются люди. А страх мешает жить, ты им будешь мешать и от тебя избавятся, на этом история закончится.\n\n*Он взмахнул рукой и свечение исчезло.*\n\n— Исчезнуть... это твой выбор?",191019,null],[229407,"2026-09-21T21:28:19",8,"– Чудесные серо-радужные капли... *она задумывается и уходит в себя*\n*волшебная рука ложится на плечо Аури*",191019,null],[229408,"2026-09-21T21:29:05",9,"— Мы забываем что правильных ответов часто больше чем один.",191019,null],[230129,"2026-09-22T14:50:09",38,"// Hard @Ashenchampion Fantomas @Ko11lu во сколько собираемся?",191019,null],[230152,"2026-09-22T14:55:19",8,"/занята с 18 до 20, в остальное время ок/",191019,null],[230156,"2026-09-22T14:56:25",8,"/он, кажется, без топора, надо глянуть/",191019,null],[230173,"2026-09-22T14:58:34",38,"// без",230156,null],[230179,"2026-09-22T14:59:24",8,"/короче, Изольда устроила чутка паранойю, извините/",230173,null],[230189,"2026-09-22T15:01:21",11,"// я додик тогда сори💅\n\nЧестно говоря я тоже уже растеряна, хочется делать что-то кроме разговоров, а идей нет",230173,null],[230223,"2026-09-22T15:09:39",8,"/Денис нас сам на птср вывел😁",230189,null],[230228,"2026-09-22T15:10:09",38,"// Если все сегодня соберутся, то будет кое-что интересное",230189,null],[230246,"2026-09-22T15:12:36",63,"// что-то, да?",230228,null],[230251,"2026-09-22T15:13:12",63,"// энкаунтер смертельно х10?",191019,null],[230254,"2026-09-22T15:13:27",38,"// Однажды)",230251,null],[230297,"2026-09-22T15:25:26",11,"// я под что-то кроме разговоров имела ввиду действия какие-то, не обязательно бои",230251,null],[230301,"2026-09-22T15:26:14",9,"//Песочницы бы немного, пообщаться персонажами, лучше познакомиться, а то нас гонят)",191019,null],[230316,"2026-09-22T15:30:29",63,"// ?",230297,null],[230322,"2026-09-22T15:31:27",63,"// Окей, но мое сообщение было адресовано Денису",191019,null],[231037,"2026-09-22T20:07:12",8,"/сегодня играем?/",191019,null],[231039,"2026-09-22T20:07:44",38,"// Все есть, Hard @Ashenchampion @Ko11lu",231037,null],[231047,"2026-09-22T20:14:08",11,"// я сегодня нет, извините",191019,null],[231050,"2026-09-22T20:16:17",38,"// Тогда завтра ко со скольки сможет? Я свободен буду с 13 по мск",191019,null],[231053,"2026-09-22T20:18:14",8,"/могу не раньше 16 по Мск, извините",231050,null],[231054,"2026-09-22T20:18:43",63,"// примерно 16:30",191019,null],[232719,"2026-09-23T18:47:03",38,"// @Ko11lu Fantomas @Ashenchampion Hard все тут?",191019,null],[232754,"2026-09-23T19:05:40",38,"// Тогда сейчас отпишу пост с ваших заявок",191019,null],[232821,"2026-09-23T19:22:00",38,"Раскольник начал обдумывать ваши слова и даже немного привстал и захотел было пойти туда и обратно, но его лихорадка сказалась и он сел обратно.\n\nТак вы просидели пару минут, пока не услышали странный звон монеты и прямо перед вами она появилась и вы все посмотрели на неё. Она была подкинуть с первого этажа и долетела до вас.\n Через секунду вы все заметили, что оказались в странном месте, где пол отражал все что было выше. А вы были в городе? \n Прямо перед вами стоял мужчина неопределенного возроста, очень сильно похожего роста, как и молодой человек, с которым вы говорили мгновение назад, а в руках у существа был... Ручной топор? Что-то похожее на это, только было сделано из осколков стекла и имело странное отражение.\n\nВместе с этим вы услышали возглас молодого человека.\n— Что?! Куда вы делись? Барышня? Батюшка?\n\nНекто перед вами же начал медленно идти к вам. На его лице играла расколотая улыбка.",191019,null],[232831,"2026-09-23T19:23:24",8,"/не подавай идей мастерам) Можно всем по 6 тхп раздать за кадром?/",191019,null],[232833,"2026-09-23T19:24:08",38,"// бой еще не начался",191019,null],[232834,"2026-09-23T19:24:24",38,"// А так этот босс был еще до ваших идей",191019,null],[232836,"2026-09-23T19:25:21",11,"*Аури оглядывается что бы убедиться что не упадет никуда и медленно пятится назад. Параллельно с этим читает магический доспех и пытается оценить обстановку",191019,null],[232837,"2026-09-23T19:25:45",8,"– Это отражение его гнева? Дурында я, не сильна в психологии *неловко засмеялась, доставая кинжал с рубином*",191019,null],[232838,"2026-09-23T19:26:32",9,"//Жаль нет зеркала у меня с собой",191019,null],[232839,"2026-09-23T19:26:47",8,"*готовлю ледяной луч*",191019,null],[232841,"2026-09-23T19:27:48",11,"// можешь озвучить, у меня есть",232838,null],[232842,"2026-09-23T19:28:02",9,"//Я дочитал, оно под ногами",191019,null],[232843,"2026-09-23T19:28:11",63,"— А... так, это же произошло и в прошлый ваш раз?\n\nДевушка стала оглядывать это место, которое, довольно очевидно, несколько давило на неё, в частности тот факт, что перенесена она была сюда насильно.",191019,null],[232844,"2026-09-23T19:28:38",9,"//Я бы этого, расколотого, вдавил в пол толпой, в отражение лицом,",191019,null],[232845,"2026-09-23T19:28:55",9,"//Жаль у меня не варвар)",191019,null],[232846,"2026-09-23T19:29:53",8,"/подсечку? Но у нас танков ноль штук/",232844,null],[232847,"2026-09-23T19:30:16",38,"Вместе с этим вы замечаете, что в вас что-то... Изменилось?\n\n// Правила измерения Раскола:\n1) Ваши модификаторы + и - были изменены местами, если у вас +4, то теперь это -4, если у вас -1, то это +1. Работает на бонусы мастерства и модификаторы характеристик.\n1.1) Ваше СЛ, КД, ХП должны быть изменены в соответствии с правилами этого измерения.\n\nЭто место выглядело как обычная площадь, но вместо земли под вами была водная гладь, что отражала все, что в неё входило.",191019,null],[232849,"2026-09-23T19:32:40",11,"// слишком тяжело механически.. лень считать. Ну и по факту у нас получается все статы минимум -1",191019,null],[232857,"2026-09-23T19:34:27",9,"//Быдо кд 13 стало 7?",191019,null],[232858,"2026-09-23T19:34:29",63,"// подготовленные заклинания также меняются по этому принципу?",191019,null],[232860,"2026-09-23T19:35:13",8,"/я подсчитала/",191019,null],[232861,"2026-09-23T19:35:23",9,"//А бафы дебафы что жобавляют кд)",191019,null],[232862,"2026-09-23T19:35:39",9,"//Приемы, указание 1д4 в отрицательную сторону?)",191019,null],[232865,"2026-09-23T19:35:55",9,"//Тогда я могу чутка дэбафнуть егл",232862,null],[232867,"2026-09-23T19:36:21",8,"/получается, луч холода даст +10 к скорости?/",191019,null],[232868,"2026-09-23T19:36:38",9,"//И отхилит)",191019,null],[232869,"2026-09-23T19:36:55",11,"// нилбог?",191019,null],[232870,"2026-09-23T19:37:10",8,"/снова мазохизм, как с отражениями, или просто дебаффы?/",232868,null],[232872,"2026-09-23T19:38:36",9,"//Я чутка дальше модификаторов нихрена не понял, с бонусом к броскам всеясно",191019,null],[232873,"2026-09-23T19:38:47",63,"// будет больно",191019,null],[232881,"2026-09-23T19:42:53",8,"/зато с атлетикой +1😁",232873,null],[232882,"2026-09-23T19:43:36",8,"/@STR_V_Alekseev, погнали/",191019,null],[232883,"2026-09-23T19:43:37",63,"// ну попадание -6 на заклах это уже прям изюминка",191019,null],[232884,"2026-09-23T19:43:45",11,"// бм 2, а значит атака будет -1",232881,null],[232889,"2026-09-23T19:44:26",8,"/на бм тоже работает",232884,null],[232894,"2026-09-23T19:45:07",9,"//Как с этим работать хз",232847,null],[232902,"2026-09-23T19:45:57",9,"//А кд ловкость +3 значит -3",191019,null],[232903,"2026-09-23T19:45:58",9,"//Хп 6+тнло а стало 6-тело",191019,null],[232904,"2026-09-23T19:45:58",63,"// умирать и всё. 8 хп у меня и 9 кд",191019,null],[232910,"2026-09-23T19:46:46",8,"/+6 тхп",232904,null],[232912,"2026-09-23T19:47:00",63,"// тхп?",191019,null],[232913,"2026-09-23T19:47:08",8,"/временных",191019,null],[232915,"2026-09-23T19:47:26",11,"*Аури смотрит на воду под собой думая что с ней можно сделать",191019,null],[232918,"2026-09-23T19:48:08",8,"/там хп минус бонусы за телосложение. Не настолько много сносит",232904,null],[232924,"2026-09-23T19:48:54",9,"— Бороться с твоей судьбой. Ты тоже прими верное решение, или судьба твоя будет не завидной...",232821,null],[232928,"2026-09-23T19:49:27",63,"// настолько. Т.к. у нас тело стало отрицательным, то надо не просто, к примеру, как у меня, -2 отнять, а сразу -4 за каждый лвл, ибо мод стал на 4 меньше",232918,null],[232933,"2026-09-23T19:49:46",9,"*Вордо перестал строить из снбя невесть что и сейчас обматывает кулаки бинтами. Это место изменило и его.*\n\n//Если всё правильно понял",191019,null],[232947,"2026-09-23T19:51:35",8,"/у меня 27 хп своих. Тело – +2. Вычитаю 6. Так работает?/",191019,null],[232951,"2026-09-23T19:52:01",11,"// нет, тебе надо -2 давать к кости хитов. Итого -4 за каждый лвл",191019,null],[232956,"2026-09-23T19:52:19",63,"// легче будет с первого уровня начать считать уже с этим отрицательным модификатором",191019,null],[232968,"2026-09-23T19:53:12",38,"// Это работает только на бонус мастерства и модификатор характеристики, указание, благославление, приемы, дебаффы и баффы работают как было",191019,null],[232971,"2026-09-23T19:53:29",38,"// И да, считайте хп с отрицательным модификатором",191019,null],[232973,"2026-09-23T19:53:37",38,"// с первого уровня",191019,null],[232974,"2026-09-23T19:53:45",9,"//Збс, щас у меня инта -3 будем бить его кулаками...",191019,null],[232978,"2026-09-23T19:53:57",9,"//Тело 10 так что норм",191019,null],[232983,"2026-09-23T19:55:17",8,"/минус 4 за уровень или минус 2, т.к. тело = +2? Извините, я тупая/",232971,null],[232984,"2026-09-23T19:55:19",63,"// подготовленных заклинаний, кстати, теперь ровно 1, найс",191019,null],[232985,"2026-09-23T19:57:08",11,"// ты за уровень получала кость хитов+2, этого +2 ты сейчас не получаешь, а так как у тебя 14 тело то стало оно -2 итого кость хитов -2 вместо плюса, убираешь плюс и отнимаешь ещё два и получается -4 за уровень от того что сейчас есть или -2 к каждой кости хитов если с первого считать",232983,null],[232986,"2026-09-23T19:58:07",38,"// Если у тебя было с первого по третий 3к6+модификатор тела, то будет 3к6-модификатор тела",232985,null],[232988,"2026-09-23T19:58:56",63,"// понапридумывает тут всякого ДМ",191019,null],[232989,"2026-09-23T19:59:16",38,"// простая замена + и -, вы чего",232988,null],[232990,"2026-09-23T19:59:31",11,"// душная скорее",232989,null],[232992,"2026-09-23T19:59:45",38,"// ну с этим я тоже соглашусь",232990,null],[232993,"2026-09-23T19:59:45",8,"/подсчитала",232989,null],[232994,"2026-09-23T20:00:21",8,"/пошли в смертельную рукопашную",191019,null],[232995,"2026-09-23T20:00:21",63,"// реально, простая, настолько, что теперь лист весь под замену",232989,null],[232996,"2026-09-23T20:00:44",38,"// Ну не сказал бы",232995,null],[232997,"2026-09-23T20:01:13",63,"// ты и не говоришь",191019,null],[232998,"2026-09-23T20:01:17",38,"// если у тебя бросок д20+модификатор характеристики+бонус мастерства, то теперь это д20-модификатор характеристики-бонус мастерства",191019,null],[232999,"2026-09-23T20:01:33",11,"// если вопрос вызывает столько обсуждений, то он не простой:) давайте перейдем к действию",191019,null],[233004,"2026-09-23T20:03:02",38,"Она не выглядит как обычная вода, но похоже она является отражение.",232915,null],[233008,"2026-09-23T20:03:26",38,"Вы начали слышать ходьбу Раскольникова и как он куда-то пошел.",232924,null],[233009,"2026-09-23T20:04:27",11,"*формированием воды девушка пытается заставить область под ней слушаться ее собирая воду перед собой",233004,null],[233011,"2026-09-23T20:05:34",8,"/могу попытаться устроить подсечку и уронить этого дятла личиком вниз, раз силы немного появилось?/",191019,null],[233012,"2026-09-23T20:05:50",38,"Некто же подошел на достаточную дистанцию (30 футов) и сказал очень странным ломаным языком.\n— Ха-ха-ха! Он тварь дрожащая! Только трепать языком и умеет! Мне он не нравился с самого моего прихода в это проклятое... Место!\n\n// Прошу бросок инициативы\n\nИнициатива:\nАури 16 — 8 хитов 6 тхп 11 кд\nИзольда 7\nВордо 6 9 хитов 8 кд\nНекто 6 -75 хп\nНоа -2",191019,null],[233013,"2026-09-23T20:06:06",8,"/roll 1d20-2",191019,null],[233018,"2026-09-23T20:07:01",11,"/roll d20-2",191019,null],[233020,"2026-09-23T20:07:21",63,"/r d20-3",233012,null],[233022,"2026-09-23T20:07:25",63,"// ахаххахахаха",191019,null],[233025,"2026-09-23T20:07:33",38,"Вода немного поддается, но сразу же становится обратно в отражение, похоже оно имеет форму воды, но очень через мгновение она становится обратно в пол.\n// для дальнейших попыток нужна будет проверка магии",233009,null],[233026,"2026-09-23T20:07:39",63,"// пиздец",191019,null],[233034,"2026-09-23T20:08:24",8,"/мы открыли новую главу математики/",233026,null],[233038,"2026-09-23T20:09:37",38,"// Hard",191019,null],[233045,"2026-09-23T20:10:36",38,"/r 1d20+1 Некто",191019,null],[233049,"2026-09-23T20:12:35",9,"/roll 1d20-2 мясо так мясо",191019,null],[233051,"2026-09-23T20:13:03",38,"// @Ashenchampion ты первая",191019,null],[233052,"2026-09-23T20:16:22",11,"// и что мне делать😁 тут хоть бросок какой.. хотя минусовой анализ будет бесполезен",191019,null],[233053,"2026-09-23T20:17:43",38,"// а удар кулаком?",233052,null],[233054,"2026-09-23T20:17:59",11,"*Аури смотрит на воду под ногами которая не повинуется ей, но скорее всего будет помехой для расходников и разочаровано вздыхает.",191019,null],[233055,"2026-09-23T20:18:29",11,"// 14 хп(только благодаря Изольде, было бы 8 иначе) и -1 на попадание бегу танчить",233053,null],[233056,"2026-09-23T20:18:58",38,"// +1 на попадание, ведь сила у тебя +1 теперь",233055,null],[233057,"2026-09-23T20:19:09",11,"// а бм -2:3 и кулаками я своими владею",233056,null],[233058,"2026-09-23T20:19:26",38,"// при броске безоружной атаки вроде не кидается бонус мастерства",233057,null],[233059,"2026-09-23T20:19:34",11,"// кидается",191019,null],[233060,"2026-09-23T20:19:38",38,"// А, все увидел",191019,null],[233061,"2026-09-23T20:19:55",9,"//А Изольда всем временные дала?",191019,null],[233062,"2026-09-23T20:20:22",9,"//Тогда у меня 10+6)))",191019,null],[233064,"2026-09-23T20:22:11",11,"*Не самые разумные решения преследуют дженази с -4 инт, так что она бросается на человека со всей скорости пытаясь повалить того с ног",191019,null],[233065,"2026-09-23T20:22:25",11,"/roll d20+1 атлетика там же да",191019,null],[233067,"2026-09-23T20:22:52",38,"/r 1d20+1-1 атлетика Некто",191019,null],[233069,"2026-09-23T20:23:19",11,"// я в восторге, Денис. Ход",191019,null],[233072,"2026-09-23T20:23:30",38,"// КУБЫ ЛЕТЕТЬ НАЧАЛИ!",191019,null],[233074,"2026-09-23T20:23:33",38,"// АХУЕТЬ!",191019,null],[233076,"2026-09-23T20:24:07",8,"/я?",191019,null],[233077,"2026-09-23T20:24:16",38,"// да",233076,null],[233079,"2026-09-23T20:24:32",11,"— У меня есть веревка, но не уверена что нам хватит сил связать его",191019,null],[233080,"2026-09-23T20:24:32",9,"//8",233012,null],[233081,"2026-09-23T20:24:45",11,"// сперва повалить, потом захват, потом вязать на все три проверки и все забирает действие",191019,null],[233085,"2026-09-23T20:25:05",8,"*интеллект девушки остался прежним, но азарт появился и замутнил его*",191019,null],[233086,"2026-09-23T20:25:41",8,"/roll 1d20+1 попытка завалить сзади дровосека мордой в пол",191019,null],[233090,"2026-09-23T20:26:02",38,"/r 1d20+1-1 Атлетика",191019,null],[233098,"2026-09-23T20:27:24",8,"*попытка связать займёт действие. Поэтому Изольда держит его лицо в воде*\n– А ну, уродина, смотри в своё личико расколотое!",191019,null],[233101,"2026-09-23T20:27:39",9,"//Он лежит, а надо в захват",191019,null],[233102,"2026-09-23T20:28:03",11,"// а мы не имеем два действия :D",191019,null],[233104,"2026-09-23T20:28:28",11,"// here we go",233081,null],[233105,"2026-09-23T20:28:30",8,"/статы волчицы тоже наоборот?",191019,null],[233106,"2026-09-23T20:28:40",38,"// да",233105,null],[233107,"2026-09-23T20:28:59",11,"// а потом Денис выкинет 20 снова",233103,null],[233108,"2026-09-23T20:29:46",8,"*волчица забегает максимально далеко от битвы, ход*",191019,null],[233110,"2026-09-23T20:30:52",9,"/roll 1d20+1 Вордо берет в захват падлу",191019,null],[233113,"2026-09-23T20:31:22",9,"//Ну, надеюсь у него будет меньше, два это моё проклятие",191019,null],[233114,"2026-09-23T20:31:23",38,"/r 1d20+1-1",191019,null],[233116,"2026-09-23T20:31:30",8,"/он же ничком, без преимущества?/",191019,null],[233118,"2026-09-23T20:31:43",9,"//Хз хз",233116,null],[233120,"2026-09-23T20:32:43",9,"//Выходит не взял если нет преима, лписываю",191019,null],[233121,"2026-09-23T20:32:48",38,"// напоминаю, что у вас есть вдохновения",191019,null],[233122,"2026-09-23T20:33:35",9,"*Вордо будто набрался сил но этого не хватило чтобы заламать человека.*\n\n//Ход",191019,null],[233134,"2026-09-23T20:36:16",38,"// Fantomas ты же именно сбила с ног?",191019,null],[233135,"2026-09-23T20:36:26",11,"// ну мне бы не помогло против 20)",233121,null],[233141,"2026-09-23T20:37:21",38,"Некто встает с земли и повернувшись к первому попавшемуся (Аури) замахнулся ручным топором.",191019,null],[233143,"2026-09-23T20:37:32",38,"/r -3-1",191019,null],[233146,"2026-09-23T20:37:40",38,"/r 1d20-3-1",191019,null],[233148,"2026-09-23T20:38:00",38,"И к сожалению промахивается.",191019,null],[233152,"2026-09-23T20:38:34",11,"// с маг доспехом КД 11(13-2)",191019,null],[233153,"2026-09-23T20:38:46",9,"//Имба закл",191019,null],[233156,"2026-09-23T20:39:13",8,"/а у меня щит и полные ячейки🙃",191019,null],[233158,"2026-09-23T20:40:13",9,"//Жаль что теперь у волшебников подготовленных 1 ток. Но зато чародею пох)",191019,null],[233160,"2026-09-23T20:40:24",8,"/надо остроту использовать, я дятел",191019,null],[233162,"2026-09-23T20:40:46",11,"// бывает, живём",191019,null],[233163,"2026-09-23T20:40:51",38,"Он смотрит на вас всех и вокруг него вода начала трескаться, как зеркало. Вместе с этим вы заметили, что он смотрит на Изольду.\n// Сглаз на Изольду с помехой на силу.",191019,null],[233165,"2026-09-23T20:40:55",38,"// Ход",191019,null],[233170,"2026-09-23T20:41:37",38,"// @Ko11lu твой ход",191019,null],[233171,"2026-09-23T20:41:43",11,"— Я не думаю что у нас получится. Нужно успешно повалить его, схватить, а затем вязать, слишком много действий, сложно! Голова болит!",191019,null],[233176,"2026-09-23T20:42:08",8,"/у сглаза атака ещё",233163,null],[233178,"2026-09-23T20:42:29",11,"// атака была уже, по мне",191019,null],[233179,"2026-09-23T20:42:30",9,"— Необходимо не думать, а делать.",191019,null],[233180,"2026-09-23T20:42:38",38,"// Атака уже была",233176,null],[233181,"2026-09-23T20:43:05",11,"— Попытаемся вырубить?",233179,null],[233185,"2026-09-23T20:43:40",9,"— Не получилось? Повторить еще раз.",233181,null],[233188,"2026-09-23T20:43:57",63,"Девушка, наблюдая за действиями остальных и пребывая в лёгком недоумении от того факта, что все хотят по какой-то причине схватить или повалить этого врага, решила поступить точно также.\n\n// Ну буду хватать его, чо уж",191019,null],[233189,"2026-09-23T20:44:03",63,"/r d20+1 атлетика",191019,null],[233191,"2026-09-23T20:44:07",63,"// ахахаххахаха",191019,null],[233192,"2026-09-23T20:44:09",63,"// две подряд",191019,null],[233193,"2026-09-23T20:44:13",9,"//То чувство когда у магов инта уехала в минус и они стали варварами",191019,null],[233194,"2026-09-23T20:44:17",38,"/r 1d20+1-1 атлетика",191019,null],[233197,"2026-09-23T20:45:23",9,"//Снйчас самая сообразительная из нас — волчица. Потом Изольда.\n\n// — Даже собака умнее тебя",233193,null],[233198,"2026-09-23T20:45:30",63,"// ход мой на этом факапе всё",191019,null],[233199,"2026-09-23T20:46:33",38,"// @Ashenchampion",191019,null],[233201,"2026-09-23T20:47:27",11,"— Я никогда никого ещё не била, видимо все в жизни нужно пробовать в первый раз\n\n*Поцелует кулачок и замахнется\n\n— Передаю воздушный поцелуй!",191019,null],[233202,"2026-09-23T20:47:35",11,"/roll d20-1",191019,null],[233207,"2026-09-23T20:48:18",11,"// итого урон 1+1 (мод силы)",191019,null],[233208,"2026-09-23T20:48:29",38,"// куда бьешь?",233207,null],[233209,"2026-09-23T20:48:38",11,"// в лицо\n\nНу и ход на этом",191019,null],[233210,"2026-09-23T20:48:46",8,"//парализованные в заклинаниях маги (работает всё, кроме головы)",233207,null],[233212,"2026-09-23T20:49:50",38,"Некто получает в лицо и откинув голову назад говорит ломаным голосом.\n— Вы все умрете!",191019,null],[233217,"2026-09-23T20:50:22",38,"/r 1d20+1 спас концентрации",191019,null],[233219,"2026-09-23T20:50:30",8,"/как далеко некто и как лежит?/",191019,null],[233221,"2026-09-23T20:50:40",9,"— База, но ты быстрее. — *Вордо ещё минимум лет 500 собирается жить.*",233212,null],[233222,"2026-09-23T20:50:42",38,"// Он буквально между вами в круге",233219,null],[233223,"2026-09-23T20:50:55",38,"// Вы запинываете его",191019,null],[233224,"2026-09-23T20:51:03",8,"/лежит?/",191019,null],[233225,"2026-09-23T20:51:13",38,"// нет",233224,null],[233226,"2026-09-23T20:51:38",8,"/в окружении=> преимущество?/",191019,null],[233227,"2026-09-23T20:51:40",9,"//Для верёвки захвата достаточно",191019,null],[233228,"2026-09-23T20:51:50",38,"// только на атаки",233226,null],[233229,"2026-09-23T20:52:30",8,"/roll 1d20-1 в солнечное сплетение",191019,null],[233231,"2026-09-23T20:52:44",11,"// давай рерол хд",191019,null],[233232,"2026-09-23T20:52:57",8,"/roll 1d20-1",191019,null],[233234,"2026-09-23T20:53:25",8,"/какой урон от безоружной?/",191019,null],[233235,"2026-09-23T20:53:36",38,"дробящий",233234,null],[233236,"2026-09-23T20:53:43",38,"// а так 1+мод силы",191019,null],[233237,"2026-09-23T20:53:56",8,"/2 урона",191019,null],[233238,"2026-09-23T20:54:20",8,"/если отойду, то провоцированная?/",191019,null],[233239,"2026-09-23T20:54:56",8,"/тогда ход. Врагу не сдаётся наш гордый Варяг",191019,null],[233240,"2026-09-23T20:55:19",9,"/roll 1d20+1 заламываем в болевой, атлетика, захват",191019,null],[233242,"2026-09-23T20:55:29",38,"/r 1d20+1-1",191019,null],[233244,"2026-09-23T20:55:36",9,"//Не 2, можно и перекинуть",191019,null],[233247,"2026-09-23T20:55:55",9,"//Острота? Мне или как это? Не помню как оно работает",191019,null],[233248,"2026-09-23T20:56:10",8,"/уже не надо, ты перекинул вдохновением",191019,null],[233249,"2026-09-23T20:56:25",9,"//То вдохнова, но ладно",191019,null],[233250,"2026-09-23T20:56:45",38,"Ты успешно схватываешь Некто",191019,null],[233252,"2026-09-23T20:57:37",9,"*Вордо заламывает свободную руку и держит.*\n\n— Успокойся сосунок, батюшка сейчас покажет тебе как дают разменку.",191019,null],[233253,"2026-09-23T20:57:44",9,"//Ход",191019,null],[233254,"2026-09-23T20:58:04",11,"*Аури прыснула от комментария Вордо",191019,null],[233256,"2026-09-23T20:58:47",9,"//Отыгрываем инту в минус, но чтобы на понтах! От того что интелект сьехал мы менее начитанными не стали 😏👌",191019,null],[233264,"2026-09-23T21:00:40",38,"/r 1d20-3-1 Некто пытается ударить схватившего его человека.",191019,null],[233266,"2026-09-23T21:00:48",38,"И промахивается",191019,null],[233267,"2026-09-23T21:01:50",9,"— Тебя в детстве не учили что на батюшку нельзя руки поднимать? — *Искрене злорадствует.*",233265,null],[233274,"2026-09-23T21:04:37",63,"Теперь, когда большинство решило запинать этого несчастного бедолагу, она решила присоединиться к ним, однако, использовав несколько иные инструменты. Вытянув рапиру, она, словно заново пытаясь обучится ею пользоваться, махнула лезвием в сторону Некто.",191019,null],[233275,"2026-09-23T21:04:46",63,"/r +d20-1",191019,null],[233277,"2026-09-23T21:04:52",63,"// ух ты",191019,null],[233278,"2026-09-23T21:05:05",63,"// из крайности в крайность",191019,null],[233279,"2026-09-23T21:05:19",63,"/r 2d8-1",191019,null],[233281,"2026-09-23T21:05:42",9,"//Рапирой можнл и через силу бить)",191019,null],[233282,"2026-09-23T21:05:46",11,"— Ого, у тебя есть настоящее оружие!",191019,null],[233283,"2026-09-23T21:05:54",63,"// да, это и было через силу",233281,null],[233284,"2026-09-23T21:06:00",63,"// у меня БМ +2 просто",191019,null],[233285,"2026-09-23T21:06:08",63,"// а, точно",191019,null],[233286,"2026-09-23T21:06:27",63,"// на меня озарение снизошло",191019,null],[233287,"2026-09-23T21:06:31",63,"// от этих слов",191019,null],[233288,"2026-09-23T21:06:32",11,"// тут +1",233280,null],[233289,"2026-09-23T21:06:36",63,"// тут 12",233280,null],[233290,"2026-09-23T21:07:11",38,"Некто получает прокалывание от Ноа и немного выплёвывает крови из себя.",191019,null],[233291,"2026-09-23T21:07:25",63,"// ход всё, пока что",191019,null],[233293,"2026-09-23T21:10:04",11,"*Пример Ноа вдохновил Аури и она достала кинжал, поняв что это может быть эффективнее чем кулаки",191019,null],[233294,"2026-09-23T21:10:13",11,"/roll d20-1 через силу",191019,null],[233299,"2026-09-23T21:11:18",11,"/roll 2d4+1",191019,null],[233304,"2026-09-23T21:12:17",11,"*Девушка сделала обманный маневр сперва якобы промахнувшись, но затем перо вошло под ребро \n\n// :D кто ещё гопник тут, ход\n\nСпасибо за напоминание",191019,null],[233306,"2026-09-23T21:13:09",38,"Вы слышите звук треска и Некто вырывается из захвата и отталкивает каждого на 10 футов от себя.\n Вместе с этим вы заметили, что что-то в нем изменилось...",191019,null],[233307,"2026-09-23T21:13:36",8,"/что именно?",191019,null],[233309,"2026-09-23T21:13:58",38,"// А вот это прошу проверку анализа",233307,null],[233310,"2026-09-23T21:14:10",8,"/roll 1d20",191019,null],[233313,"2026-09-23T21:14:20",63,"// свободным?",233309,null],[233314,"2026-09-23T21:14:20",9,"//Действием анализ?)",191019,null],[233317,"2026-09-23T21:14:44",38,"// Действием, Изольде не тратит этот. У неё волк есть",191019,null],[233320,"2026-09-23T21:15:07",8,"/итого 4)",191019,null],[233321,"2026-09-23T21:15:19",9,"//Пусть волчица кинет и скажет",191019,null],[233323,"2026-09-23T21:15:36",8,"/единицу уже кинула",191019,null],[233324,"2026-09-23T21:15:37",9,"//Там инта в плюсе, она 100% говорить щас может)",191019,null],[233325,"2026-09-23T21:15:48",63,"// выучила все языки мира на время",191019,null],[233330,"2026-09-23T21:17:07",38,"Эээ ты поняла, что Некто стал, выше? (Он просто выпрямился)",191019,null],[233331,"2026-09-23T21:17:35",8,"/это волчица поняла? Или это было моё действие?/",191019,null],[233332,"2026-09-23T21:17:55",38,"Твоя волчица",233331,null],[233333,"2026-09-23T21:18:19",8,"*Изольда посылает луч холода",191019,null],[233334,"2026-09-23T21:18:30",8,"/roll 1d20-5",191019,null],[233336,"2026-09-23T21:19:11",8,"*ищущее на 2",191019,null],[233337,"2026-09-23T21:19:19",8,"/roll 1d20-5",191019,null],[233339,"2026-09-23T21:19:34",8,"/roll 1d8",191019,null],[233341,"2026-09-23T21:20:22",8,"*движением отошла на 30 футов назад*",191019,null],[233342,"2026-09-23T21:20:33",8,"/ход, волчица за спиной",191019,null],[233343,"2026-09-23T21:20:45",9,"— Хм, не уйдёшь. — *Вордо вытаскивает из под плаща сеть и подбежав к противнику в притык накидывает её!*",191019,null],[233344,"2026-09-23T21:21:03",9,"/roll 1d20+1 сеть была ахахахах",191019,null],[233346,"2026-09-23T21:21:28",38,"/r 1d20+1+1",191019,null],[233348,"2026-09-23T21:22:07",9,"//А это шо?",191019,null],[233349,"2026-09-23T21:22:17",9,"//Сеть на попадании, попал?",191019,null],[233350,"2026-09-23T21:22:40",38,"// Нет",191019,null],[233352,"2026-09-23T21:23:30",9,"— Хм, понторез. — *Прозвучало очень надменно.*\n\n//Бонусным убежище на себя, Ход",233350,null],[233353,"2026-09-23T21:24:30",9,"//Правда на убежище сейчас сложность мудрости 4!",191019,null],[233354,"2026-09-23T21:25:07",38,"Некто посмотрел на самую ближайшую цель и решил ударить её.\n Вместе с этим вода по вами начала ещё сильнее трескаться.",191019,null],[233355,"2026-09-23T21:25:17",38,"/r 1d20+3+1 Атака по харду",191019,null],[233357,"2026-09-23T21:25:33",9,"//А мудрость спас? Я под убежищем)",191019,null],[233358,"2026-09-23T21:25:38",38,"/r 1d20+3 Спас мудрости",191019,null],[233360,"2026-09-23T21:25:46",9,"//Попал)",191019,null],[233361,"2026-09-23T21:25:53",63,"// чорт себе статы перевернул(",191019,null],[233362,"2026-09-23T21:25:54",11,"// Изольда, памаги",191019,null],[233363,"2026-09-23T21:26:17",8,"/острота",191019,null],[233364,"2026-09-23T21:26:29",38,"/r 1d20+3",191019,null],[233366,"2026-09-23T21:26:45",9,"//Не, живем, я щас тактику поменяю ,)",191019,null],[233367,"2026-09-23T21:27:08",38,"/r 1d6+1+3+1 Урона по Вордо",191019,null],[233369,"2026-09-23T21:27:44",38,"// Ход",191019,null],[233370,"2026-09-23T21:27:54",9,"// 9 хитов родных",191019,null],[233371,"2026-09-23T21:32:59",63,"Глядя на то, как этот ополоумевший размахивает своим топором, девушка решила найти альтернативу заместо вхождения в ближний бой. Моментально в голове промелькнула идея бросить рапиру, однако даже для нынешней её это было как-то... глуповато. И едва девушка отринула идею с броском, как в нее, словно огромным камнем прилетело осознание — она вроде как бы маг...\n\nМоментально разорвав расстояние, волшебница попыталась вспомнить заклинания, которые пригодились бы в атаке и которые она часто использовала. И на ум, не без некоторых затупов, пришло одно.\n\n— ... там было... кажется... так? Proiect... ilis... magicus?\n\nИ из-под её плаща прямиком в Некто вырвался град небольших полупрозрачных стрел.\n\n// 2-ой ячейкой скастану пожалуй, и отбегу подальше на 30 фт.",191019,null],[233372,"2026-09-23T21:33:05",63,"/r 4d4+4",191019,null],[233374,"2026-09-23T21:33:12",63,"// ход всё",191019,null],[233375,"2026-09-23T21:34:02",11,"// магические стрелы рил база, но провоцированная",191019,null],[233376,"2026-09-23T21:34:17",63,"// расстояние 10 фт между нами было, он нас сам откинул",191019,null],[233377,"2026-09-23T21:34:25",11,"// а, извиняюсь, ты прав",191019,null],[233378,"2026-09-23T21:37:15",38,"Некто получив удар ещё сильнее кричит и на этот раз вы понимаете, что уже большая часть воды треснута и через секунду вас всех переаорачивает на обратную сторону воды. Сам же противник очень сильно вопит и он похоже немного восстановился.",191019,null],[233379,"2026-09-23T21:37:22",63,"// щас нам лица бить ещё активнее будут(",191019,null],[233380,"2026-09-23T21:38:04",63,"// а...?",233378,null],[233381,"2026-09-23T21:38:19",8,"/карусель, карусель... Аури, ходи",233378,null],[233382,"2026-09-23T21:38:34",63,"// а статы нам за это вернут?",191019,null],[233383,"2026-09-23T21:38:59",9,"//По мне так весело)",233382,null],[233384,"2026-09-23T21:39:00",38,"// нет",233382,null],[233385,"2026-09-23T21:39:18",63,"// если только мы такие теперь не навсегда",233383,null],[233386,"2026-09-23T21:39:36",63,"// а то мало ли...",191019,null],[233387,"2026-09-23T21:41:15",11,"*звёзды(для нее) из рук Ноа выглядели очень эффективно для Аури и спрятав кинжал обратно за пояс девушка взглянет на Вордо \n\n— Ты как, сможешь отойти или..?",191019,null],[233388,"2026-09-23T21:42:20",11,"// Hard мне отойти или с тобой остаться?",191019,null],[233389,"2026-09-23T21:44:12",9,"— Я справлюсь, иди.",191019,null],[233390,"2026-09-23T21:45:19",9,"*Уверенность в голосе была даже более уверенной чем обычно.*",191019,null],[233391,"2026-09-23T21:45:49",11,"*Немного сомневаясь, но Аури отходит и по пути читает заклинание, выливая на врага 40 литров воды \n\n// Ход\n\nМожет пригодится, а может и нет",191019,null],[233392,"2026-09-23T21:48:33",8,"/@STR_V_Alekseev, какие эффекты?/",191019,null],[233393,"2026-09-23T21:51:17",63,"// мы по другую сторону от него? Просто я не совсем уверен, что въехал",233378,null],[233404,"2026-09-23T21:57:49",8,"/я через 10 минут в афк/",191019,null],[233405,"2026-09-23T21:58:15",9,"//Я подготовил пост на свой ход)",191019,null],[233406,"2026-09-23T21:59:00",8,"/я сейчас могу кинуть бросок атаки, но я хз по эффектам от воды/",191019,null],[233409,"2026-09-23T22:01:24",8,"/roll 1d20-5 на теоретическое будущее\n/roll 1d10\n/roll 2d6 при провале ловкости\nушла в афк, вырубает",191019,null],[233411,"2026-09-23T22:03:41",63,"// ледяной кинжал?",191019,null],[233412,"2026-09-23T22:05:13",9,"//Похоже он",191019,null],[233413,"2026-09-23T22:06:51",9,"//Мне ходить?",191019,null],[233417,"2026-09-23T22:12:25",8,"/мы не знаем эффектов, кажись, Денис заснул",191019,null],[233418,"2026-09-23T22:13:08",9,"//Лан, я закреплю пост у себя, чтобы не потерять",191019,null],[233439,"2026-09-24T06:50:34",38,"// Так, кто открепил перезапуск?",191019,null],[233440,"2026-09-24T06:55:32",38,"Твоя воды вырывается из плоскости и как копья пронзает Некто.\n// Наносит 10 урона и он в состоянии скован.",233391,null],[233441,"2026-09-24T07:03:59",38,"// Да это вообще капец, закрыл глазки на минуту, а проснулся уже утром 😭",233417,null],[233442,"2026-09-24T07:04:33",38,"/r -d20+1",233410,null],[233444,"2026-09-24T07:05:20",9,"//Когда там мой ход свисни)",191019,null],[233445,"2026-09-24T07:05:40",38,"// Прямо сейчас",233444,null],[233446,"2026-09-24T07:07:14",9,"*Вордо достаёт кинджал. Он делал это уже не раз, когда охотился за пределом астрала на неразумных, медленных монстров, выживал... старые отточенные приемы и навыки, ничем не обманешь, ничем не отнимешь. Опыт. Бои без единого ранения.*\n\n*Вордо бьет кинджалом и взмыв на фут над землёй отступает. Его плащ развевается так словно он в невесомости, игнорируя законы физики взмывает в потоке носимый течением? Наверное им.*\n\n//Удар, Псионическим кочевником бонусным начинаю эпично парить на фут и тружнопроходимая не щитается такой + не провоцирую атак от подвижного и отхожу на 40 футов",191019,null],[233447,"2026-09-24T07:07:37",9,"/roll 1d20+1-1 кинджал я им владею",191019,null],[233449,"2026-09-24T07:07:44",9,"//Ход",191019,null],[233453,"2026-09-24T07:19:45",38,"Некто начал вопить во весь свой голос и вода продолжила трескаться дальше и дальше (Теперь она в радиусе 25 футов)\n Ваш враг вышел из копий \"воды\" и посмотрев на Ноа побежал на неё и метнул свой топор в неё.",191019,null],[233454,"2026-09-24T07:19:55",38,"/r d20+3+1",191019,null],[233456,"2026-09-24T07:20:41",9,"//Как далеко он бегает? Скорость)",191019,null],[233457,"2026-09-24T07:22:04",38,"//30 футов, но он игнорирует труднопроходимую местность",233456,null],[233458,"2026-09-24T07:23:16",9,"//Ммм, хорошо, я не знал что там на самом деле труднопроходимая, просто по приколу взмыл 😂👍",191019,null],[233488,"2026-09-24T08:14:34",38,"// @Ko11lu твой ход",191019,null],[233490,"2026-09-24T08:17:53",63,"// ого, прям кинул?",233453,null],[233491,"2026-09-24T08:18:20",38,"// Да, прям кинул",233490,null],[233492,"2026-09-24T08:18:46",63,"// байтит, чтобы я подобрал, значится",191019,null],[233493,"2026-09-24T08:21:58",63,"Приняв во внимание факт того, что прошлая её атака была весьма эффективна, девушка решила её повторить, однако на этот раз, чтобы не выбиться из сил раньше времени, заклинание было несколько ослаблено.\n\n// Первой ячейкой стрелы бахну, а там уже и отбегаю на 30 подальше",191019,null],[233494,"2026-09-24T08:22:05",63,"/r 3d4+3",191019,null],[233497,"2026-09-24T08:25:26",63,"// hod vse",191019,null],[233558,"2026-09-24T09:04:41",8,"/если что, там сложность 8, поэтому ловкость прошла, только 9 урона/",233488,null],[233650,"2026-09-24T11:44:03",38,"// @Ashenchampion ваш ход!",191019,null],[233858,"2026-09-24T13:11:24",38,"@Ashenchampion",233440,null],[233873,"2026-09-24T13:17:11",11,"// я вижу, но я ею ничего делать не могу теперь? Ибо изначально я планировала то что описала",191019,null],[233874,"2026-09-24T13:18:17",38,"// Ну только новую достать",233873,null],[233875,"2026-09-24T13:18:59",11,"// ?? Я не могу формированием воды управлять созданной мною же водой.. ладно",191019,null],[233876,"2026-09-24T13:19:26",38,"// Вас еще сместило в зеркало",233875,null],[233883,"2026-09-24T13:20:50",38,"// Но да, нужно создать новую воду или заморозить воду под ногами.",191019,null],[233884,"2026-09-24T13:21:24",11,"// я не зря ведь сразу пыталась управлять водой местной, ты сказал что не выходит, поэтому и не пытаюсь больше",191019,null],[233885,"2026-09-24T13:21:41",11,"*К сожалению Аури, ничего подобного тому что есть в репертуаре Ноа ей вспомнить не удалось, так что она попыталась метнуть кинжал во врага",191019,null],[233886,"2026-09-24T13:21:46",11,"/roll d20-1",191019,null],[233888,"2026-09-24T13:22:28",11,"*кинжал не долетел до цели даже и она его подобрала и недовольно отошла в сторону\n\n// Ход",191019,null],[233889,"2026-09-24T13:22:51",38,"// Fantomas ваш ход",191019,null],[233899,"2026-09-24T13:48:05",8,"/roll 1d20-4",191019,null],[233901,"2026-09-24T13:48:28",8,"/не долетел луч холода",191019,null],[233903,"2026-09-24T13:48:55",8,"/волчица пытается в анализ",191019,null],[233904,"2026-09-24T13:49:07",8,"/roll 1d20+3",191019,null],[233906,"2026-09-24T13:49:46",11,"// самый умный в пати",191019,null],[233907,"2026-09-24T13:50:40",8,"*Изольда в 40 футах, Вьюга сзади*\n/Денис, что по укрытиям?/\n/Вордо, поясни план/",191019,null],[233911,"2026-09-24T13:55:08",9,"//Волчица не вкурила ещё чё поменялось, дайте ей расчехлиться)",191019,null],[233912,"2026-09-24T13:56:27",38,"Волчица понимает, что Некто является странным существом и ещё он похоже сходит с ума",233904,null],[233913,"2026-09-24T13:56:28",9,"//Плана нет, я его скурил и буду бить противника пока тот не окочурится ведь мне пох на труднопроходимую и могу не провоцировать атак. К сожелению — больше ничего + Вордо щас тупень, скорее варвар",233907,null],[233914,"2026-09-24T13:57:27",8,"*опасливо грызается за моей спиной* /Укрытия какие?",191019,null],[233915,"2026-09-24T13:58:16",38,"Укрытий нету, только если друг за другом не прятаться, а вот пол... Если он сломался уже один раз, то почему полностью его не уничтожить?",233907,null],[233916,"2026-09-24T13:58:24",9,"//Бегите, на ускорении короче, я его буду ковырять и топор отниму",191019,null],[233917,"2026-09-24T13:58:43",8,"/ход",191019,null],[233918,"2026-09-24T13:58:45",9,"//Топор далеко? Как близко чудо)",191019,null],[233920,"2026-09-24T13:59:26",9,"//Надеюсь топор был единственным дальнобойным у него)",191019,null],[233922,"2026-09-24T14:04:39",38,"// А он исчез)",233918,null],[233924,"2026-09-24T14:07:13",63,"// а наш Некто ну насколько побитым выглядит?",191019,null],[233925,"2026-09-24T14:07:24",38,"// Расколот",233924,null],[233928,"2026-09-24T14:07:55",38,"// А так ну, он уже не может здраво мыслить от ваших атак",191019,null],[233930,"2026-09-24T14:08:13",63,"// я надеюсь, что там не 200 хп",191019,null],[233932,"2026-09-24T14:08:46",8,"/сейчас на двух людей расколется))",233925,null],[233934,"2026-09-24T14:10:19",9,"//Сколько футов к нему?)",233922,null],[233935,"2026-09-24T14:11:44",38,"// К Некто, у тебя 50 футов",233934,null],[233936,"2026-09-24T14:12:40",9,"//Он чё, от меня бежит?",191019,null],[233937,"2026-09-24T14:15:59",38,"// Вы разбежались в разные стороны и 40 футов от него изначально, а он потом пошел 30 футов в сторону Ноа, то есть Квадратный корень 40*40 + 30*30",233936,null],[233938,"2026-09-24T14:16:19",63,"// почему в мою-то?",191019,null],[233941,"2026-09-24T14:16:50",38,"// У ручного топора средняя дистанция 20 футов",233938,null],[233942,"2026-09-24T14:17:33",9,"*Вордо паря молнией перемещается на более выгондное место, наперерез расколотому как охотник, держась на почтительном растоянии.*\n\n— Иди сюда, мелочь. Не дорос ещё за мной бегать. — *Говорит Вордо насмешливо, он смеялся словами.*\n\n//Ускорение, бонусным поддерживаю парение псионическим кочевником, иду наперерез держась на 40 футов от него но так чтобы в следующие ходы он бежал ко мне поближе, ход",191019,null],[233945,"2026-09-24T14:18:33",9,"//Топор у него снова?",191019,null],[233967,"2026-09-24T14:25:28",8,"/а сколько футов от меня до Вордо? (Пора ему укрытие щитом организовывать.)",233941,null],[233971,"2026-09-24T14:26:16",38,"// ((40+30)**2+(40)**2)**1/2",233967,null],[233973,"2026-09-24T14:26:50",8,"/???????",233971,null],[233974,"2026-09-24T14:26:53",63,"// да, 3 пары по математике в ряд не хватило",233971,null],[233975,"2026-09-24T14:26:58",63,"// ебани ещё пж",191019,null],[233976,"2026-09-24T14:27:10",38,"// Около 80 футов",233973,null],[233978,"2026-09-24T14:29:15",38,"В руках Некто снова возвращается Топор и посмотрев на Вордо он решил атаковать... Пол.",191019,null],[233979,"2026-09-24T14:29:31",38,"/r 1d6+3+1 Урон по воде",191019,null],[233981,"2026-09-24T14:31:50",8,"/Аури может пол заморозить?",191019,null],[233983,"2026-09-24T14:31:58",38,"// Дап",233981,null],[233984,"2026-09-24T14:32:07",9,"— Да, да. Это единственное на что хватило твоего крохотного мозжевельника? Ты так бесишься, может твой грецкий орех уже в труху или его утащила белка. — *Насмехаемся.*",233978,null],[233985,"2026-09-24T14:32:21",11,"// Денис: ты не можешь влиять на воду\nТоже Денис:",233983,null],[233986,"2026-09-24T14:32:26",8,"/тогда меньше шанс, что чувырла в реальность проберётся",233983,null],[233987,"2026-09-24T14:33:09",38,"// Я не говорил. Я говорил что вытаскивать у тебя не получилось, а про заморозить или изменить течение я не говорил",233985,null],[233988,"2026-09-24T14:34:28",38,"Вода начинает трескаться еще сильнее и радиус поля треснутой воды стал 60 футов.\n Вместе с этим Некто побежал на Вордо",191019,null],[233989,"2026-09-24T14:34:38",38,"// Ход @Ko11lu",191019,null],[233996,"2026-09-24T14:36:03",11,".",233025,null],[233999,"2026-09-24T14:36:37",8,"/в общем, Аури может морозить, я Вордо прикрывать после атак, Вордо бить. Ноа атаковать/",191019,null],[234000,"2026-09-24T14:36:43",63,"— а...?\n\nГлядя на то, как это чудо с топором бьёт пол, девушка, предположив, что это вряд ли закончится чем-то хороши, снова запустила залп из магических снарядов, на этот раз целясь больше в конечность, которая держит топор.\n\nОтпустив эти стрелы в \"добрый путь\", Ноа поспешила покинуть радиус с треснутой водой.\n\n// 2-ой ячейкой кастану волшебных стрел",191019,null],[234001,"2026-09-24T14:36:49",63,"/r 4d4+4",191019,null],[234004,"2026-09-24T14:37:06",63,"// на 30 фт. отбегаю, ход всё",234000,null],[234009,"2026-09-24T14:38:42",38,"Как только стрела попадают в Некто вся \"вода\" полностью потрескалась и начала осыпаться с центом в точке Некто. Сам же враг упал вниз и вы услышали очень сильный треск стекла об что-то твердое.\n Вместе с этим свет начал угасать падая за горизонт этого странного места.",191019,null],[234012,"2026-09-24T14:39:14",63,"// ну пиздец",191019,null],[234013,"2026-09-24T14:40:02",38,"// Битва оканчивается, а вас начинает преследовать падающий обрыв",191019,null],[234015,"2026-09-24T14:40:20",63,"// а статы все такие же?",191019,null],[234016,"2026-09-24T14:40:28",38,"// Да)",234015,null],[234017,"2026-09-24T14:40:42",11,"// я ничего не понимаю, мы падаем?",234013,null],[234025,"2026-09-24T14:42:31",38,"// Как воронка песка, но вместо песка ваш пол",234017,null],[234026,"2026-09-24T14:42:43",38,"// И еще она на одной плоскости",191019,null],[234027,"2026-09-24T14:43:03",8,"/я могу успеть рывком к Вордо?",191019,null],[234034,"2026-09-24T14:43:52",8,"/зелье дать успею?",191019,null],[234036,"2026-09-24T14:45:36",8,"*Изольда подбегает к Вордо, даёт зелье, и, говоря: \"Держись за спину\", – встаёт впереди* /урон от падения на себя/",191019,null],[234037,"2026-09-24T14:45:38",11,"*Аури видя это подбегает к Ноа и по наитию, в падение создаст куб воды под ними, стараясь поддерживать ему форму, что бы облегчить приземление",191019,null],[234040,"2026-09-24T14:45:52",8,"/roll 2d4+2",191019,null],[234042,"2026-09-24T14:46:05",8,"/8 хп Вордо",191019,null],[234044,"2026-09-24T14:46:50",11,"// немного изменю",234037,null],[234046,"2026-09-24T14:48:49",38,"// @Ko11lu Hard заявки?",191019,null],[234063,"2026-09-24T15:00:26",63,"Девушка, крепко сжав в руке свою рапиру, дабы не выронить случайно, приготовилась к падению, что из-за действий её товарища могло пройти куда проще.\n\n// У меня особо нет таковых пока",191019,null],[234065,"2026-09-24T15:03:34",8,"/если что, Вьюга цепляется за спину/",191019,null],[234068,"2026-09-24T15:09:06",9,"//У меня было 9 / 10 хп 😏👌",191019,null],[234075,"2026-09-24T15:11:56",9,"*Вордо пытается понять что происходит и удержаться в парении, урон от падения это не отменит, но сделает немного мягче. Зелье? Он его взял и приобнял Изольду.*\n\n— Это нам понадобися позже, держись. — *Зелье на пояс, Изольду на руки и просто на ускорении от прорыва летим.*",191019,null],[234081,"2026-09-24T15:12:40",11,"*Аури обнимает Ноа готовясь нырять, но прежде чем закрыть глаза обращает внимание на подругу. Ее желание помочь Вордо и Изольде затрагивает что-то, что не совсем ей подвластно и ребят окутывают золотые крылья пытаясь укрыть от опасности, какой бы та не была \n\n// Нарративно использую черту с позволения мастера если так можно?",191019,null],[234083,"2026-09-24T15:13:21",8,"/не надо суецида на 9 хп",234075,null],[234084,"2026-09-24T15:13:22",9,"*Волчица хватаеися за плащ и тоже тащится за нами.*\n\n//Простите что описываю)",234082,null],[234088,"2026-09-24T15:14:35",9,"//Живём, бесконечность не предел!!!)))",234083,null],[234090,"2026-09-24T15:14:55",8,"/у меня 21)",234088,null],[234095,"2026-09-24T15:15:38",9,"//И что? У меня инту выключили, Вордо почувствовать себя супером не давал интелект, а щас его нет. Все беды от ума)",191019,null],[234150,"2026-09-24T15:27:14",38,"Как только стекло полностью развалилось вас поглотила вечная тьма. Вы чувствуете, как ваша вся магия прерывается, а через секунду вас озаряет белый свет и вы все выпадаете из ближайшей лужи.\n Вы оказались прямо рядом с небольшим мостом в безлюдном месте, не получив ранений. Вместе с вами из лужи прилетел топор, которым пользовался Некто.",191019,null],[234154,"2026-09-24T15:27:57",9,"//Статы на месте?)",191019,null],[234155,"2026-09-24T15:28:03",38,"// Теперь да",234154,null],[234164,"2026-09-24T15:29:23",8,"*спрыгивает с рук и хватает поводок*\n– Боюсь, страшное случилось! Вордо, спасибо, дурачок",191019,null],[234167,"2026-09-24T15:29:34",9,"— Беда.... — *Вордо отряхивается.*\n\n//Вроде бы фокусы у Изольды?",191019,null],[234168,"2026-09-24T15:29:40",8,"/да",191019,null],[234172,"2026-09-24T15:30:26",9,"*Ставит Изольду на пол и показывает на свою одежду.*\n\n— Можешь помочь? Я не знаю фокусов.",191019,null],[234174,"2026-09-24T15:30:43",11,"— Время займет — ответит Аури",191019,null],[234178,"2026-09-24T15:30:55",11,"// там на каждый кубик по действию тратить, брат)",191019,null],[234181,"2026-09-24T15:31:14",8,"– Все в порядке? *отряхнула Вордо одежду* /на одежду целиком/",191019,null],[234188,"2026-09-24T15:33:35",9,"— Благодарю. Чистота сподручнее. — *Поправляет плащ и парит над лужами чтобы не испачкать ботинки.* — Где мы?",191019,null],[234190,"2026-09-24T15:34:55",9,"*Когда интеллект вернулся в норму Вордо перестал витать в облаках, стал снова культурнее и не таким гордым внешне, но конечно он всё ещё тот понторез.*",191019,null],[234236,"2026-09-24T16:28:58",63,"— Ха... неприятное место то было, даже трудно описать...\n\nДевушка, пребывая в некотором удивлении от такого, весьма необычного, приземления, попыталась отряхнуть свою одежду и оглядеться в месте, куда их выкинуло.",191019,null],[234237,"2026-09-24T16:30:17",11,"*кивает и сушит и себя и Ноа \n\n— Ты в порядке?",191019,null],[234238,"2026-09-24T16:30:34",8,"/это больше похоже на бедный или богатый квартал?/",234150,null],[234239,"2026-09-24T16:30:55",38,"// все такой же бедный квартал",234238,null],[234240,"2026-09-24T16:31:15",8,"*двумя пальцами у глаза, делает рожицу*",234237,null],[234241,"2026-09-24T16:31:20",38,"Вы оказались в похожем районе, где и были",234236,null],[234242,"2026-09-24T16:31:28",63,"// да там же сидим",191019,null],[234243,"2026-09-24T16:32:04",63,"// к кому твой персонаж обратился?",234237,null],[234244,"2026-09-24T16:32:09",11,"*немного натянуто, но хихикнет \n\n— Ты резвая как всегда, рада что все в порядке, но что дальше..?",234240,null],[234245,"2026-09-24T16:32:19",11,"// тебя же обнимала, к тебе",234243,null],[234247,"2026-09-24T16:33:15",8,"– Найти старушку или её труп. Надеюсь, она хотя бы умерла быстро... *чешет затылок*",191019,null],[234248,"2026-09-24T16:34:26",11,"*вздыхает \n\n— Я в растерянности, господа, не понимаю что здесь происходит и какие тут причиноследственные связи",191019,null],[234249,"2026-09-24T16:34:29",63,"— Я? Вроде... да? Трудно сказать, после возвращения из того места, где все казалось каким-то... перевёрнутым? Сложно описать...\n\nЧтобы точно удостовериться в собственном благополучии, девушка осмотрела себя и свой \"арсенал\", дабы убедиться, что все на месте.",234237,null],[234250,"2026-09-24T16:35:04",11,"*хлопает по плечу \n\n— Разделяю твои чувства, но на вид вроде все целы..",234249,null],[234251,"2026-09-24T16:35:12",8,"– Злое намерение парня пробралось в реальность *серьёзно*",234248,null],[234252,"2026-09-24T16:35:36",8,"– Или умерло, но едва ли",191019,null],[234253,"2026-09-24T16:36:27",38,"// Напомню, что рядом лежит топор",191019,null],[234254,"2026-09-24T16:37:29",63,"— Нам стоит его брать, мало ли он... проклят...?\n\nДевушка указала на топор, обращаясь к остальным.",191019,null],[234260,"2026-09-24T16:39:09",11,"— Я могу определить, но нужно время",191019,null],[234261,"2026-09-24T16:39:13",11,"// опознание есть",191019,null],[234262,"2026-09-24T16:39:32",11,"— Или быстрее, но придется потратить на это сил",191019,null],[234263,"2026-09-24T16:39:55",8,"– Решай сама, ты умнее нас",191019,null],[234264,"2026-09-24T16:40:25",63,"// там вроде дэньги надо тратить, не помню, честно",234261,null],[234267,"2026-09-24T16:41:28",11,"// расходник есть, он не тратится",191019,null],[234268,"2026-09-24T16:42:15",9,"— Мы куда то спешим? Нвм всё еще нужно обдумать следующий шаг леди Аури. — *Обращается к Изольде и, внезапно, к Ноа.* — Ваше мнение по этому поводу? У меня нет мыслей кроме как запастить вещами из этого мира и проверить что решил парень.",191019,null],[234269,"2026-09-24T16:42:35",11,"— Тогда дайте мне 10 минут..\n\n*С этими словами девушка присаживается над топором и проводит ритуал доставая жемчужину",191019,null],[234273,"2026-09-24T16:44:10",8,"– В тот раз спешка не особо помогла. Действительно, нужно подумать. По-хорошему, найти бы снова искомый дом, но это сложно \n*вопросительный взгляд на Лемн*\n@Ko11lu",234268,null],[234278,"2026-09-24T16:45:26",9,"— Всегда можно спросить прохожих, люди не откажут, мы выглядим как \"важные господа\".",234273,null],[234290,"2026-09-24T16:54:44",11,"// жду реакции от Дениса на ритуал опознания на топор",191019,null],[234304,"2026-09-24T17:09:20",38,"Топор Раскола\nМагическое Оружие (Ручной топор), Неопределенной редкости (Требует настройки)\nНастроенное существо получает владение этим оружием.\nНастроенное  существо получает возможность добавить свой бонус владения к урону этим магическим оружием.\nНастроенное существо получает возможность использовать модификатор заклинательной характеристики, вместо силы или ловкости.\nРаскол: Используя магический предмет вы способны заставить существо отзеркалить свои модификаторы и бонус мастерства на 1 минуту.\nСтекло: Это магическое существо превращает иммунитет к режущему урону в сопротивление, сопротивление в обычный урон, а обычный урон в уязвимость.\nСинергия: Это магическое оружие может синергировать с предметами связанными со стеклом.",234269,null],[234307,"2026-09-24T17:09:49",31,"Повышенный урон по старушкам?/",191019,null],[234308,"2026-09-24T17:09:58",38,"// обязательно)",234307,null],[234309,"2026-09-24T17:10:05",38,"// шучу, нет",191019,null],[234312,"2026-09-24T17:11:25",11,"— Что-ж, это однозначно магический предмет, с множеством свойств — каких именно озвучит — но вроде не проклятый \n\n*Возьмёт топор в руку что бы в этом убедиться",191019,null],[234317,"2026-09-24T17:13:01",38,"Топор... На удивление не проклят",234312,null],[234318,"2026-09-24T17:13:55",11,"— Вот видите - я в порядке!\n\n*Протянет топор Ноа\n\n— Ты хорошо обращаешься с оружием, держи, думаю в твоих руках он будет эффективнее",191019,null],[234320,"2026-09-24T17:14:46",9,"//Всё, будет у нас женщина с топором)))",191019,null],[234321,"2026-09-24T17:15:35",63,"// только пара закончилась, щас, погодите, напишу ответки",191019,null],[234322,"2026-09-24T17:15:51",8,"/пытается сориентироваться, т.е. найти вокруг места, где они были. Что кидать?/",191019,null],[234324,"2026-09-24T17:22:22",38,"// Историю и анализ",234322,null],[234325,"2026-09-24T17:23:58",8,"/roll 1d20+2 история\n/roll 1d20 анализ",234324,null],[234327,"2026-09-24T17:25:37",63,"— Пожалуй, сейчас, соглашусь с решением найти его. Дальше уже действовать отталкиваясь от того, что он вытворил. Вы помните примерное местонахождение того дома? Хотя, скорее всего он уже сбежал оттуда...\n\nДевушка несколько погрузилась в собственные мысли, в которых и пыталась определить возможное его местонахождение в том случае, если он действительно совершил убийство и сейчас пытается спрятаться от местной стражи в городе. \n\nОднако вскоре ее отвлёк голос дженази — кажется осмотр предмета был закончен. Выслушав его свойства и комментарий, добавленный от неё, девушка подобрала протянутый ей топор и, ответив лёгким кивком, принялась осматривать его.\n\n// Какой урон у топора?",191019,null],[234328,"2026-09-24T17:26:04",11,"// помощь ig",234326,null],[234330,"2026-09-24T17:27:40",38,"Эээ... Ну вот похожий перекресток в паре метров, а так мы, ну... Чуть севернее?",191019,null],[234332,"2026-09-24T17:28:28",8,"– Я не гений мысли, но, кажется, нам идти немного южнее",191019,null],[234333,"2026-09-24T17:28:45",9,"— Ты ищешь где мы были? — *Вордо хоть немного шарит что где?*",191019,null],[234334,"2026-09-24T17:29:12",38,"// Ну он же не слепой",234333,null],[234335,"2026-09-24T17:29:23",9,"//Дайте помощь дорогие)",191019,null],[234336,"2026-09-24T17:29:33",8,"– Да, выходит не очень\n/помощь",234333,null],[234337,"2026-09-24T17:29:42",9,"— Раскажи что приметила. Сейчас сориентируемся...",191019,null],[234338,"2026-09-24T17:30:26",8,"– Ну, там знакомый перекрёсток *указала*",191019,null],[234339,"2026-09-24T17:31:03",9,"/roll +d20+3+1d4+1d8\n/roll +d20+3+1d4+1d8",191019,null],[234341,"2026-09-24T17:31:33",9,"//Указание на себя га обе проверки, тактическую оценку! Помощь! Анализ и история кск раз)",191019,null],[234343,"2026-09-24T17:31:52",9,"//1 кость приёмов осталась 🥲",191019,null],[234345,"2026-09-24T17:32:34",9,"*Анализ у Вордо пока плох, не отошел он от того состояния из зазеркалья, мысли путаются...*\n\n//С отличной памятью вообще бы без проблемм справились, эх",234340,null],[234346,"2026-09-24T17:34:35",38,"Ты прекрасно понимаешь, что находишься в одном перекрестке от перекрестка дома старухи",191019,null],[234348,"2026-09-24T17:35:03",9,"— Кажется знаю где мы. Все готовы идти?",234346,null],[234349,"2026-09-24T17:35:18",11,"// у меня отличная память🤷‍♂\nА Изольда историю знает, но преимущества только мастер даёт и условия эти он учитывать должен",234345,null],[234350,"2026-09-24T17:35:26",8,"– Да, капитан! *отдала честь*",191019,null],[234352,"2026-09-24T17:36:01",11,"*кивает",234348,null],[234354,"2026-09-24T17:36:53",9,"*Если Ноа с нами собираемся и идём. Вордо все ещё парит пока под ногами не окажется нормальный тротуар, не засранный, на который можно стать ботинками.*",191019,null],[234356,"2026-09-24T17:37:39",63,"— Боюсь, тогда обойдёмся без использования этого топора, на то, чтобы полностью понять, как им пользоваться, необходимо время.\n\n// Для настройки вроде отдых короткий надо",191019,null],[234358,"2026-09-24T17:39:48",9,"— Возможно у нас нет временина отдых и не забудьте. Видите мелочи, книги, прессу — попытайтесь достать что-то. Нам за это платят... — *Точнее заплатят, им всё же надо вытащить побольше информайции, напоминает зачем они тут.*",191019,null],[234359,"2026-09-24T17:40:01",11,"— Может это и к лучшему, в этой истории топор использовать может быть неуместно, вдруг ещё на нас скинут вину",191019,null],[234360,"2026-09-24T17:40:17",8,"– Спрячь его, что ли",191019,null],[234361,"2026-09-24T17:40:28",9,"— Все что на первый взгляд важное и интересное — документируем.",191019,null],[234362,"2026-09-24T17:40:48",38,"// Я знаю что у тебя идеальноэая память есть, просто я не знаю что они тупят",234349,null],[234364,"2026-09-24T17:40:53",11,"*осмотрится вокруг что бы оценить сколько примерно времени прошло, небо светлое/темное? Люди на улицах?",234358,null],[234365,"2026-09-24T17:42:34",63,"— \"Нам за это платят\"? В каком плане?\n\nПроговорила девушка, пряча топор внутрь своего рюкзака и следуя за остальными.",191019,null],[234366,"2026-09-24T17:44:12",38,"По твоим оценкам прошло примерно час или два",234364,null],[234367,"2026-09-24T17:44:21",11,"// значит ночь?",191019,null],[234368,"2026-09-24T17:45:05",11,"— Ночь на дворе, вряд ли ночью можно будет купить какую-то информацию, по крайней мере не официально",191019,null],[234369,"2026-09-24T17:45:48",9,"*Вордо оглянулся, правда. Это лишь он один привык жить в сумерках.*",234368,null],[234370,"2026-09-24T17:46:13",8,"– Герой в той легенде уб@л днём... *обеспокоенно протягивает девушка*",191019,null],[234372,"2026-09-24T17:46:25",38,"// Вечером*",234370,null],[234373,"2026-09-24T17:46:47",63,"// не убивал он*",191019,null],[234374,"2026-09-24T17:46:56",9,"— Осталось только узнать, послушал ли он нас.",234370,null],[234375,"2026-09-24T17:47:05",8,"/не ночью. По-моему, на следующий день, хз. Проверим",234372,null],[234380,"2026-09-24T17:47:43",11,"— Вперёд, веди\n\n*А сама будет идти позади и оглядываться, может есть какие листовки-вывески которые можно сорвать информационные",234374,null],[234385,"2026-09-24T17:48:37",8,"*идёт*",191019,null],[234386,"2026-09-24T17:49:02",9,"*Водо проходит к нужному дому.*\n\n//Я чую будет как в предсказаниях, мы щас настроили сьаруху против него, ему не дадут кредит, и он её прибьёт 🫠🫠🫠",191019,null],[234390,"2026-09-24T17:49:24",38,"Пройдя во двор вы обнаруживаете, что двери уже закрыты",191019,null],[234391,"2026-09-24T17:49:45",8,"*окна в комнате горят?*",191019,null],[234394,"2026-09-24T17:50:01",9,"*Вордо смотрит есть ли окна или отверстия ведущие внутрь.*",191019,null],[234399,"2026-09-24T17:51:02",38,"Очень много жилых окон и в большей части из них уже потух свет, но на верхних этажах есть свет",191019,null],[234401,"2026-09-24T17:51:31",9,"//Нам в коридор надо)",191019,null],[234402,"2026-09-24T17:52:20",9,"//Щас будет босфайт с вахтёршей",191019,null],[234404,"2026-09-24T17:53:13",8,"*становится девушкой, одетой бедно, но аккуратно, чтобы не пиздиться с вахтёршей*",191019,null],[234449,"2026-09-24T18:28:34",38,"// Такс, какая у вас полная заявка?",191019,null],[234453,"2026-09-24T18:30:28",8,"/можем с разведкой, можем напролом. Как остальные решат Hard @Ashenchampion @Ko11lu/",191019,null],[234455,"2026-09-24T18:31:56",11,"// я за любой движ, лишь бы двинуться по сюжету",191019,null],[234458,"2026-09-24T18:34:19",63,"// могу сказать то же самое, но напролом просто не впадлу, нежели поиск инфы а потом уже идти к нему, или что-то подобное",191019,null],[234461,"2026-09-24T18:37:00",8,"/можем утром газеты посмотреть, там точно про уб-во напишут, если оно было. Как раз +вещи/",234458,null],[234463,"2026-09-24T18:40:11",63,"// шоб он просто не свинтил куда подальше к утру",191019,null],[234464,"2026-09-24T18:41:25",8,"/кто-то помнит его адрес? Извините за флуд, могу в рп/",234463,null],[234465,"2026-09-24T18:42:48",63,"// @STR_V_Alekseev на историю можно кинуть?",191019,null],[234468,"2026-09-24T18:44:27",38,"// У вас есть персонаж, что буквально закрывает этот аспект",234465,null],[234469,"2026-09-24T18:45:14",63,"// я не этот персонаж, к сожалению",234468,null],[234474,"2026-09-24T18:47:09",38,"// А откуда он буквально вышел?",191019,null],[234481,"2026-09-24T18:48:52",38,"// Ну если хотите то кидайте",191019,null],[234483,"2026-09-24T18:50:13",63,"// ладно, допустим",234481,null],[234488,"2026-09-24T18:54:46",11,"/roll d20+6 история",191019,null],[234491,"2026-09-24T18:55:21",38,"Аури прекрасно вспоминает в каком направлении находится дом молодого человека и находится ровно в 730 шагах",234488,null],[234494,"2026-09-24T18:57:09",11,"*Пойдет туда быстрым шагом подзывая остальных и считая шаги",191019,null],[234499,"2026-09-24T19:00:28",8,"*пошла за ней*",191019,null],[234504,"2026-09-24T19:03:17",63,"Ноа также последовала за остальными.",191019,null],[234507,"2026-09-24T19:07:30",8,"/кстати, у Вордо всё это время был плащ полёта/",191019,null],[234508,"2026-09-24T19:07:43",9,"//Какой плащ?)))",191019,null],[234509,"2026-09-24T19:07:57",8,"/крылья И Сана",191019,null],[234510,"2026-09-24T19:08:06",9,"//У меня ток псионический кочевник 😏👌",191019,null],[234512,"2026-09-24T19:09:12",8,".",217468,null],[234516,"2026-09-24T19:10:35",11,"// тебе крылья дали",234510,null],[234517,"2026-09-24T19:11:15",9,"//Да, дали. Вордо о них ни слухом ни духом",191019,null],[234519,"2026-09-24T19:12:41",11,"// вот как раз была возможность напомнить мастеру тебе в полете чтоб не разбился 🤔\n\nМысли вслух",191019,null],[234526,"2026-09-24T19:18:09",8,"*тыгыдыкаем к дому*",191019,null],[234830,"2026-09-24T20:44:31",38,"Пройдя ровно 730 шагов в нужном направлении вы пришли к дому, откуда начали свое путешествии, вон там даже угол, где вы остановили молодого человека и похоже он живет здесь.\nИз главной двери слабо светила свеча или фонарь, похоже внутри кто-то есть.",191019,null],[234834,"2026-09-24T20:45:31",63,"— Итак... кто пойдет первым?\n\nШёпотом обратилась к остальным Ноа.",191019,null],[234839,"2026-09-24T20:46:14",8,"– Я могу представиться его подругой, чтобы нас пропустили *неуверенно* *в образе местной*",191019,null],[234847,"2026-09-24T20:46:28",8,"– Или напрямую?",191019,null],[234848,"2026-09-24T20:46:40",9,"//Так, там домик или подьезд?",191019,null],[234850,"2026-09-24T20:47:09",38,"// вот это",234848,null],[234851,"2026-09-24T20:47:11",8,"/он беден для своего дома",234848,null],[234853,"2026-09-24T20:47:25",9,"— Хм. — *Раз боитесь, первым заходит Вордо.*",191019,null],[234858,"2026-09-24T20:48:16",38,"Заходя внутрь ты замечаешь небольшую стойку и девушку, что сидела за ней. Заметив, как кто-то вошел она сказала.\n— Извините, мы уже закрыты...",234853,null],[234859,"2026-09-24T20:48:17",9,"/roll 12+1d8 кд в движении, действием уклонение, тратим последнюю кость, просто идём не обращая внимание на чернь",191019,null],[234867,"2026-09-24T20:48:51",9,"— Не важно, мы по делам. — *Звучит уверенно идёт не сбавляя шага.*",234858,null],[234868,"2026-09-24T20:49:05",8,"*в образе местной пытаюсь проскользнуть за высоким Вордо*",191019,null],[234870,"2026-09-24T20:49:16",38,"— Простите! Вы к кому, хотя бы!",234867,null],[234873,"2026-09-24T20:49:35",38,"Девушка попыталась встать, но запуталась в ногах и упала за стойкой.",191019,null],[234875,"2026-09-24T20:49:54",8,"– Мне надо к моему другу *щёки артистично краснеют*",191019,null],[234877,"2026-09-24T20:49:59",9,"— Мы? Ладно... — *Идет помогая ей встать.*",234870,null],[234880,"2026-09-24T20:51:01",9,"*Ведёт себя галантно.*\n\n— Простите миледи что потревожили в столь поздний час. Мы должны уточнить кое что у одного человека. Шума и проблем создавать не будем.",191019,null],[234881,"2026-09-24T20:51:28",38,"Девушка все же смогла встать и поднявшись на ноги посмотрела на Вордо и Изольду.\n— Ох... К кому именно? У нас почти полный дом...",191019,null],[234883,"2026-09-24T20:52:07",8,"– Брюнет, тонкие черты лица... *неловко*",191019,null],[234884,"2026-09-24T20:52:52",9,"— Хм, я запамятовал имя... — *Смотрит на Изольду.* — Мы его не спросили, как мог упустить это из виду.",191019,null],[234885,"2026-09-24T20:53:08",38,"Девушка задумалась.\n— Еще что-то? У нас пара брюнетов точно есть",234883,null],[234887,"2026-09-24T20:53:23",8,"– Господин Раскольников",191019,null],[234891,"2026-09-24T20:54:29",11,"— Вы в порядке? — подаст руку",234873,null],[234893,"2026-09-24T20:55:24",38,"Девушка немного поперхнулась и переспросила.\n— Родион Романович?! Да, он совсем недавно вернулся, вроде... А вам что-то нужно?",234887,null],[234896,"2026-09-24T20:56:12",8,"/давим на дружбу, или как?/",191019,null],[234900,"2026-09-24T20:57:38",11,"— Эта девушка - его подруга. Давно не видела его вот и решила навестить, устроить сюрприз",191019,null],[234902,"2026-09-24T20:57:50",11,"*показывает на Изольду в маскировке",191019,null],[234904,"2026-09-24T20:58:01",8,"*кивнула, улыбнувшись*",191019,null],[234912,"2026-09-24T20:59:08",8,"– А эти высокие господа соизволили помочь мне за вождение по городу",191019,null],[234917,"2026-09-24T21:00:29",9,"— Да, мы должны узнать о его самочувствии и по возможности помочь. В некотором роде молодой парень выглядел сегодня обеспокоенно и не в себе, нас это тревожит. Я пытался пригласить его на чашечку чая но нас прервали. — *Потирает лоб, он реально устал.* — Он выглядел очень обеспокоенно на кануне. Решили вернутся как только освободились.\n\n*Он поклонился, слегка.*\n\n— Если наша просьба слишком велика миледи, то пожалуй все же мы подождем завтра. Надеюсь с Родионым Романовичем будет всё хорошо к тому времени.",191019,null],[234942,"2026-09-24T21:20:03",63,"Девушка проследовала внутрь помещения за остальными и принялась ожидать, пока их всех не пропустят внутрь.\n\n// Не надо целенаправленно ждать меня, пожалуйста, если я захочу влезть в разговор, то напишу заявку. Если это только не важный какой-то выбор, тогда окей",191019,null],[235328,"2026-09-25T12:42:05",38,"— Что вы, что вы... Думаю он как раз ещё не уснул, всего лишь одиннадцатый час... \n Девушка начала вести вас по лестнице на самый верх.\n— Давайте я проведу вас к нему...\n\nПоднявшись наверх вы вышли к ступенькам на чердак. Девушка поклонилась вам и сказала.\n— Он сейчас наверху, поэтому можете сходить к нему...",191019,null],[235329,"2026-09-25T12:42:22",38,"// @Ko11lu Hard Fantomas @Ashenchampion",191019,null],[235330,"2026-09-25T12:43:10",8,"*аккуратный стук в дверь* (маскировку сняла)",191019,null],[235331,"2026-09-25T12:44:07",11,"*Выглядывает из тени в ожидания открытия двери",191019,null],[235332,"2026-09-25T12:45:27",63,"Девушка встала за остальными, приготовившись достать своё оружие, если на них снова захотят вылететь с топором.",191019,null],[235333,"2026-09-25T12:47:54",38,"Дверь не была закрыта и открылась внутрь комнаты. Она была тесная, убогая и мрачная клетушка, похожая на гроб или шкаф.\n Имеет самый жалкий вид. Стены оклеены желтоватыми, пыльными и всюду отстававшими от стен обоями.\n В комнате стоит бедный, потрепанный диван, на котором лежал ваш герой, а также стол, заваленный пыльными рукописями, книгами и конспектами.\n\n Раскольников ещё не заметил вас, но его взгляд был направлен в его низкий потолок.",191019,null],[235334,"2026-09-25T12:49:43",11,"*Оценивая внешние убранства помещения девушка ловит дежавю с прошлой истории и начинает складывать причиноследственные связи такого поведения героев, в своей голове.\n\n— Здравствуйте. И это снова мы.",191019,null],[235335,"2026-09-25T12:50:29",8,"– В Вашей голове случилось что-то важное, так ведь? *тихо*",191019,null],[235336,"2026-09-25T12:57:40",11,"*Пройдет внутрь и встанет напротив в ожидании реакции",191019,null],[235338,"2026-09-25T13:00:17",38,"Молодой человек заметил вас и на его лице отразилось что-то радостное. Он встал с дивана и подошёл к Изольде.",191019,null],[235345,"2026-09-25T13:06:45",8,"– Ну, каковы новости? *девушка искренне заулыбалась, увидев хоть что-то позитивное*",191019,null],[235346,"2026-09-25T13:08:40",38,"— Вы были правы! Спасибо!\n Родион обнял Изольду и даже немного приподнял её над землёй и продолжил говорить.\n— Вы правда все помогли мне... Я думал над вашими советами и пришел к выводу, что моя теория, которая публиковалась полгода назад в газете была ошибочна! Большое спасибо, что открыли мне глаза!\n Раскольников пару раз даже поцеловал Изольду в макушку, пока говорил это.",191019,null],[235347,"2026-09-25T13:09:43",8,"/Hard, @Ashenchampion, удивительно, но сегодня без тр@пов. Может, про Соню Мармеладову сказать потом/",191019,null],[235349,"2026-09-25T13:11:56",11,"// скажи, полезно же х)",235347,null],[235350,"2026-09-25T13:13:15",11,"*Аури искренне удивлённая произошедшим думала о том что же это повлияло разговор или внутренняя борьба скорее склонялась к второму \n\n— Что-ж, рада что мои друзья смогли помочь вам \n\n*Чтоб не стоять без дела немного уберется фокусами в комнате следуя примеру Изольды в прошлой истории",235346,null],[235351,"2026-09-25T13:13:47",8,"– Все мы склонны к ошибкам. Главное, что Вы победили себя, ведь это труднее всего *обняла в ответ*",191019,null],[235352,"2026-09-25T13:15:08",38,"Раскольников ещё немного обнимал Изольду и поняв, что он уже довольно долго это делает наконец-то отошёл.\n— Забыл представится... Родион Романович Раскольников.",191019,null],[235353,"2026-09-25T13:18:44",9,"— Вордо, для вас \"мистер Мир (Уорлд)\" молодой человек. — *Коли диван чист после фокусов, чё бы не посидеть.* — Жаль уже поздно, ужин не организать. — *Посмотрел на девушек.* — У вас с собой что-то есть? Готов помочь с готовкой.\n\n*Ведём себя как дома.*",191019,null],[235354,"2026-09-25T13:20:25",8,"– Продуктов у меня не имеется, зато в кармане звенит десяток золотых, и я знаю рецепт яблочного варенья!",191019,null],[235355,"2026-09-25T13:21:06",11,"— У меня был паек с сушеными яблоками — добавит Аури — с пайков неплохая еда выходит, но я скучаю по домашней морской капусте",191019,null],[235356,"2026-09-25T13:21:47",38,"Раскольников немного удивился и спросил.\n— Давайте я вам принесу еды, что осталась от ужина, который я не ел...\n Родион начал идти к двери.",191019,null],[235357,"2026-09-25T13:22:46",11,"— Нет-нет, не стоит, дайте лучше нам приготовить, где у вас тут кухня?",191019,null],[235358,"2026-09-25T13:23:00",8,"*достаёт немного сушёной тыквы из пайка и вяленую говядину, но вспоминает, что нужна тарелка, ищет последнюю*",191019,null],[235359,"2026-09-25T13:23:02",11,"*Аури всерьез задумалась о том что стоит засушить морскую капусту для пайков",191019,null],[235360,"2026-09-25T13:23:33",38,"— Этажом ниже и я пойду принесу посуды, что у меня есть...",191019,null],[235361,"2026-09-25T13:24:16",11,"— Нужно отметить сей день, так что давай что-то приготовим? — смотрит на Изольду в надежде на помощь",191019,null],[235362,"2026-09-25T13:24:56",8,"– Всегда готов! И чаёк могу устроить /фермерский ребёнок/",191019,null],[235363,"2026-09-25T13:26:15",11,"— Тогда мы отправимся на кухню, ждём посуды. Ты должна что-то приготовить с тыквой, я в тебя верю!",191019,null],[235364,"2026-09-25T13:27:41",8,"– Из сушёной уже мало что сделаешь, но даже тела нужны для лекарских тренировок *смеётся с волчицей*",191019,null],[235365,"2026-09-25T13:28:39",11,"— Почему же? Я слышала что их распарить можно, грибы так точно. Думаю что-то у нас да получится, стоит попытаться!",191019,null],[235366,"2026-09-25T13:30:34",11,"// где тем наша посуда?👉👈",191019,null],[235367,"2026-09-25T13:30:54",38,"Раскольников поднялся обратно и принес ровно 5 тарелок и 5 столовых приборов.",191019,null],[235368,"2026-09-25T13:32:08",8,"*Изольда спустилась на кухню, ища деревянную доску*",191019,null],[235369,"2026-09-25T13:32:08",11,"— Благодарю, но мы решили не есть в сухомятку, а приготовить что-то сами. Остальные приборы есть на кухне?",191019,null],[235370,"2026-09-25T13:33:05",11,"*возьмёт тарелочки и тоже потопает за Изольдой\n\n— Слушай, а что кушает Вьюга?",191019,null],[235371,"2026-09-25T13:34:17",8,"– Ей полезно мясо, как любой порядочной волчице. Но она бывает всеядной: помню, сыр слопала",191019,null],[235373,"2026-09-25T13:35:07",38,"Кухня была довольно скромной, но были небольшая плита, печка, пара кострюль и сковородка.",191019,null],[235374,"2026-09-25T13:35:19",11,"— Изысканный вкус \n\n*Аури подкинет волчице кусочек вяленого мясца из пайка и погладит. А затем помоет руки и будет заглядывать что там подруга делает где помочь",191019,null],[235375,"2026-09-25T13:35:44",8,"*пошла распаривать тыкву на сковородке*",191019,null],[235376,"2026-09-25T13:36:19",8,"/как пользоваться плитой будущего?/",191019,null],[235377,"2026-09-25T13:36:45",38,"// а вот, кидай ловкость рук",235376,null],[235378,"2026-09-25T13:36:57",11,"*две дамы смотрят на плиту будущего и не понимаю как это работает!\n\nС помощью хд",191019,null],[235379,"2026-09-25T13:37:20",8,"/roll 1d20+2 \n/roll 1d20+2 \nНе палим квартиру",191019,null],[235381,"2026-09-25T13:38:13",9,"//Ща, ша",191019,null],[235382,"2026-09-25T13:38:48",38,"С горем да пополам вы смогли разобраться в работе этой шайтан машины, но она работала достаточно просто... Нужно было просто зажжечь огонь снизу, как и в печках...",235379,null],[235383,"2026-09-25T13:38:53",11,"*щелкает кнопочки, видит что оттуда идёт что-то пахнущее как горелка и додумывается фокусами зажечь",191019,null],[235384,"2026-09-25T13:39:33",11,"— Что придумали, у нас такого нет!",191019,null],[235385,"2026-09-25T13:39:48",11,"*испуганно отскакивает когда оно загорается \n\n— Но вроде работает!",191019,null],[235386,"2026-09-25T13:40:25",8,"– Эй, но у нас магия есть, в общем-то *важно подняла палец вверх*",191019,null],[235387,"2026-09-25T13:41:03",8,"*но зачарованно смотрит на механизм*",191019,null],[235388,"2026-09-25T13:41:06",11,"— Тоже верно \n*Хихикнет \n— Жаль муки нет",191019,null],[235389,"2026-09-25T13:41:17",9,"*Вордо идет с вам и приносит какое то тесто с фруктами внутри(свой рацион). Его можно и так съесть а возможно...*\n\n— Надо разбавить с водой и испечь. — *Достаёт два порошка.* — Если взмешать эти две безвредные смеси то тесто встанет, возможно получится пирог.",191019,null],[235390,"2026-09-25T13:42:05",8,"*закинула на сковородку и яблоки Аури, если та позволит* *быстро распарила без жарки и выключила*",191019,null],[235391,"2026-09-25T13:42:54",11,"— Ооо, надо пробовать! С тыквой только, да! \n\n*Запомнив инструкцию Вордо пытается повторить",235389,null],[235392,"2026-09-25T13:43:53",9,"*Помогат, чтобы не переборщили с алхимией. Вся кухня в пузырящимся тесте ему не нужна.*",235391,null],[235393,"2026-09-25T13:44:57",11,"— Спасибо за помощь",191019,null],[235395,"2026-09-25T13:45:07",11,"// ну я считаю надо кидать что-то на результат)",191019,null],[235402,"2026-09-25T13:47:09",38,"// С каждого бросок ловкости рук и выживания",191019,null],[235404,"2026-09-25T13:48:46",11,"/roll d20+2 ловкость рук \n/roll d20 выживание",191019,null],[235406,"2026-09-25T13:49:07",11,"// Моя девочка 🥺",191019,null],[235407,"2026-09-25T13:49:37",8,"/roll 1d20+2 ловкость\n/roll 1d20+1 выживаем",191019,null],[235409,"2026-09-25T13:51:07",38,"// Вы все можете выдать помощь друг другу",191019,null],[235411,"2026-09-25T13:52:46",11,"*Аури сама справилась с тестом благодаря советам Вордо и дальше вместе с Изольдой делали начинку для пирога",191019,null],[235412,"2026-09-25T13:53:24",38,"Hard твой бросок остался",191019,null],[235413,"2026-09-25T13:54:00",11,"// а он не готовил, а командовал:D",191019,null],[235414,"2026-09-25T13:54:31",38,"Вы приготовили очень хороший и даже вкусный ужин из того что у вас было.",191019,null],[235416,"2026-09-25T13:55:46",8,"*вставила пирогу глазки и улыбку*",191019,null],[235417,"2026-09-25T13:56:00",11,"— Пора подавать к столу!",191019,null],[235419,"2026-09-25T13:58:29",11,"*гордо несёт ужин для всех на верх. А глазки и улыбка смотрят на Ноа и Родиона \n\n— Кто разрежет? Предлагаю вам, Родион!",191019,null],[235420,"2026-09-25T14:02:12",38,"Раскольников удивился вашей быстроте готовке и приняв пирог положил его на стол.\n— Хорошо...\n Он разделил его на 10 частей и далькажлму по одной.\n— Вы приготовили довольно хороший пирог...",191019,null],[235421,"2026-09-25T14:04:00",9,"//Моя задача только за алхимией следить. Вордо кислоту сварить может, тоже, с имитацией дрожжевого теста не управится 😏👌",235413,null],[235422,"2026-09-25T14:04:10",11,"— Старались! — Улыбка девушки повторяла улыбку на пироге\n\n*Она взяла свою тарелку и с большим желанием отрезала кусочек пирога что бы попробовать что же у них вышло",191019,null],[235423,"2026-09-25T14:04:58",9,"— Правда, можно было лучше. — *Даже не пробуя он знал, со свежих продуктов лучше.*",191019,null],[235424,"2026-09-25T14:05:08",11,"— Мм! Тыква и правда отменная, Изольда! Очень вкусно, а если это была сушёная то представляю какая вкусная свежая\n\n*Глазки звёздочками",191019,null],[235425,"2026-09-25T14:06:00",9,"*Ужин, есть ужин. Всё же испеченное оно лучше тестовых галет с фруктами что у него завернуты в восченую ткань.*",191019,null],[235426,"2026-09-25T14:06:39",8,"– Спасибо) *дала кусочек пирога на пол Вьюге*",191019,null],[235427,"2026-09-25T14:06:44",11,"*Не слушает брюзгу и довольно уминает пирог за обе щеки.",191019,null],[235428,"2026-09-25T14:08:12",11,"— Еда - это отлично — вытрет рот платком как закончит — но что-то вы планируете делать дальше? *К герою нашему",191019,null],[235429,"2026-09-25T14:08:33",8,"– Вордо, наш возможный негативный минимум лежит сильно ниже сушёных фруктов)",235423,null],[235430,"2026-09-25T14:10:07",11,"*кив-кив",191019,null],[235431,"2026-09-25T14:11:45",38,"— Я недавно получил письмо, что приезжает моя семья, думаю встретить их, ещё и учебу нужно закончить... Да и деньги взять...",235428,null],[235432,"2026-09-25T14:11:58",9,"— Всегда можем лучше. — *Вордо не говорил что получилось \"плохо\".*",235429,null],[235433,"2026-09-25T14:13:08",8,"– Вы знаете, где денег взять? Выглядите слегка бедно, если честно *обеспокоенно*",235431,null],[235434,"2026-09-25T14:13:52",11,"*Вспоминая разговор с прошлым героем решает спросить Раскольникова про то же самое \n\n— Вы говорили что писали статью в газету, может вам стоит заняться этим серьезнее? Как на счёт работы писарем в газету? Можно писать про что-то позитивное, не только про плохое. Например Магию? Магия - она ведь есть в каждом из нас и это не только что-то осязаемое — она вновь начала тараторить, но затем угомонились прочистила горло и сказала — как бы то ни было, вам стоит поискать работу по душе. Что бы и деньги были и вам нравилось",235431,null],[235435,"2026-09-25T14:14:56",8,"– Но учёба важна, конечно *сама ни разу не была, но уважает университеты как что-то недосягаемое*",191019,null],[235436,"2026-09-25T14:15:13",11,"— А ещё возможно будет легче если вы встретите человека с которым можно будет идти рука об руку и помогать друг другу — снова протянет немного мечтательно, витая в облаках",191019,null],[235437,"2026-09-25T14:15:51",38,"— Для этого мне нужно отучится, а это тоже требует денег... А они были у меня вот пару дней назад, но я отдал часть на пропитание, это место и часть отдал одному человеку, что говорил со мной позавчера...",235434,null],[235438,"2026-09-25T14:16:05",11,"— кхм, можно работать в сфере на которую обучаешься ведь",235437,null],[235439,"2026-09-25T14:16:26",11,"— А сколько вам нужно.. и какая у вас тут в целом валюта?",191019,null],[235440,"2026-09-25T14:16:57",8,"– В видении была худенькая милая девушка, Соня Мармеладова... Я думаю, вы однажды встретитесь *мечтательно* Жаль, отец у неё пьющий, однако она прелесть",235436,null],[235441,"2026-09-25T14:17:39",11,"— Наша Изольда пророчица, она видит будущее местами, вам стоит послушать её, может она даст дельные советы хехе",191019,null],[235442,"2026-09-25T14:17:51",38,"— Вот я и шел на юридический... А по поводу валюты, то медные и серебряные.",235438,null],[235443,"2026-09-25T14:18:08",38,"— Мармеладова... Где-то это я уже слышал...",235440,null],[235444,"2026-09-25T14:19:09",11,"— Я сама ещё не успела много заработать, но у меня есть пару золотых.. они подойдут? К тому же вот\n\n*Достает 3 медных и серебряных с кошелька",235442,null],[235445,"2026-09-25T14:19:57",8,"*даёт ему 12 золотых и 2 медных* – Попробуешь обменять? Я неместная",191019,null],[235446,"2026-09-25T14:20:41",38,"Раскольников начал отнекивается и мотать головой.\n— Что вы что вы! Зачем вы мне их даёте... Не стоит...",191019,null],[235447,"2026-09-25T14:21:20",8,"– Это не подаяние, а вклад в учёбу и будущее *обиженно*",191019,null],[235448,"2026-09-25T14:21:29",11,"— В качестве награды за смелые решения. Я уже нашла хорошую работу по призванию и вам того же желаю \n\n*Аури ждёт с нетерпением что бы вернуться к работе на комиссию гоблинов",191019,null],[235449,"2026-09-25T14:21:47",11,"— А что бы развиваться людям нужен старт, так что Изольда права",191019,null],[235450,"2026-09-25T14:24:07",38,"Раскольников опустил голову и сказал.\n— Спасибо... Большое спасибо вам...",191019,null],[235452,"2026-09-25T14:25:43",9,"— Пишите, пишите о том как бы повернулась ваша жизнь если бы вы пошли по кривой дорожке. Или другие люди с подобной ситуацией. — *Вспоминая людей и социальное неравенство, острые темы прийдутся кстати.* — Но, не обвиняйте власть, такое часто наказуемо. Можно собирать чужие жизненные истории и сделать сборник, люди часто любят поговорить о своих проблемах.",191019,null],[235453,"2026-09-25T14:26:16",9,"//Помню мы вошли в бар накануне, да))",191019,null],[235454,"2026-09-25T14:26:27",11,"*Задумывается о словах Вордо и для себя, но быстро понимает что не ее тематика и отряхивает головой",191019,null],[235455,"2026-09-25T14:26:53",8,"– Главное, вином не злоупотребляйте, как многие писатели /большинство шестидесятников умерло от алкоголя/",235452,null],[235456,"2026-09-25T14:27:25",11,"— Алкоголь до добра не доводит, это верно \n\n// Мне кажется после этих слов Аури где-то налакается чувствую",191019,null],[235457,"2026-09-25T14:28:49",9,"— Письмом можно заняться и в свободное время. Для стабильности необходима учёба и подработка что покроет хотя бы то что тратится. Авторы чаще становились популярными ко второй половине жизни, или после смерти. Не стоит уповать на \"возможное чудесное будущее\" но память о себе оставить всегда хорошо.",235455,null],[235458,"2026-09-25T14:30:16",11,"*Аури в сон потянуло. То ли от длинного дня, то ли от занудных для нее реалистичных речей Вордо и она зевнула прикрывая ладошкой рот",191019,null],[235459,"2026-09-25T14:31:36",38,"Вордо замечает, что рядом с вами сидит кто-то еще и повернув немного голову он говорит.\n— Крылья... Они и вправду прекрасны, не так ли?\n И Сан появился в виде небольшого видения и сказал еще раз.\n— Если вспомнишь о них, то просто назови их...\nВместе с эти он исчез полностью.\n\nРаскольников слушал ваши слова и думая над ними сказал.\n— Тогда, давайте вы останетесь у меня до утра, хорошо? Хотя не думаю что мы все поместимся на диване...",191019,null],[235460,"2026-09-25T14:32:28",8,"– У меня есть спальный мешок, без проблем",191019,null],[235461,"2026-09-25T14:33:01",8,"*очистила тарелку фокусами*",191019,null],[235462,"2026-09-25T14:34:12",11,"*повторила за Изольдой и очистила тарелки каждого\n\n— Да, без проблем, мы так сказать привыкли к походным условиям и спальникам, хотя не могу говорить за всех — на последних словах она взглянула на их брезгливого товарища",235459,null],[235463,"2026-09-25T14:35:59",9,"— Хм, чаще натягивал сеть меж ветвями деревьев в походе. — *Вордо имел свой подход, но так уж и быть, потерпит разок, куда он денется?*",191019,null],[235464,"2026-09-25T14:36:52",11,"// терпи, Козак, атаманом станешь",191019,null],[235465,"2026-09-25T14:37:37",9,"//Кстати гамак из сетки тема и волки не долезут 😏👌",191019,null],[235466,"2026-09-25T14:40:25",8,"/допрыгнут. А змеи и медведи доползут/",191019,null],[235467,"2026-09-25T14:40:50",11,"*девушка достает спальник и находит себе местечко где-то в уголку\n\n— Простите меня — и снова зевает — устала",191019,null],[235468,"2026-09-25T14:41:11",11,"*достает игрушечного плюшевого дракончика и в обнимку с ним забирается в спальник",191019,null],[235469,"2026-09-25T14:42:00",8,"*Изольда остаётся в блузке и штанах и тоже залезает в спальник в другом углу*",191019,null],[235470,"2026-09-25T14:42:22",11,"— Спокойной ночи",191019,null],[235471,"2026-09-25T14:43:50",8,"– Спокойной. Родион, ты очень сильный *абсолютно серьёзно* *волчица легла на её торс и тоже спать*",191019,null],[235472,"2026-09-25T14:44:52",9,"*Вордо присел за столиком, подпирая рукой лицо так и уснул? Он спал с открытыми глазами? Конечно он вошёл в транс, ему не обязательно спать.*",191019,null],[235475,"2026-09-25T14:53:50",8,"/надо сказать старухе, что всё окей, хотя имени она не знает, только внешность/",191019,null],[235478,"2026-09-25T14:58:03",11,"/тайскип до утра?",191019,null],[235480,"2026-09-25T14:58:31",38,"// Щас, я тут опыт за битвау считаю",235478,null],[235487,"2026-09-25T15:05:42",38,"// Такс, за битву вы получили 275 опыта и еще 200 за отыгрыш от меня!",191019,null],[235505,"2026-09-25T15:22:24",38,"Так прошло много времени и как-то странно вы проснулись или нет к одному времени. Вы все проснулись от солнца, но заметили, что вы не в каморке, а в зале той самой выставки и заметив, что вы проснулись Читатель сказал.\n— Наконец-то вы проснулись! Я так рад видеть вас целыми и невредимыми! Чтож... Отвечу на все ваши вопросы, что могли возникнуть... После того как мисс Летиция покинула каким-то образом Книгу я сразу же попытался понять природу и пришел к выводу, что именно произошло, поэтому вы оказались прямо здесь... Вторым ответом будет, что вы все огромные молодцы! Я узнал, что вы побывали в двух историях и решили конфликт второй, о ком она была? Впрочем давайте потом, вы узнали что-нибудь о прошлом? Почему магии нету? Из-за раннего выхода вас из книги я заплачу компенсацию и все равно заплачу за информацию!",191019,null],[235523,"2026-09-25T15:30:52",11,"*Аури оглянется, поймет что она посреди зала в мешке и в торопях подымется его собирать, впрочем болтать ей это не помешает параллельно \n\n— Лети ведь в порядке? Ох.. Нам особо не удалось что либо взять с собой, только странный топор у нашей новой коллеги чьи свойства я исследовала \n*Озвучит \n— и странная вещь на спине Вордо.. мы не успели ничего забрать из первой истории, а во второй была ночь что бы добыть местные газеты \n*Грустно скажет она\n— Впрочем у нас получилось немного пораспрашивать про магию и мы выведали что там она всё таки была, просто не в тех местах где были мы. А в других странах, причин этому в первой истории я не поняла, во второй как нам сказали об этом побеспокоились местные власти.. к сожалению отправиться в те страны где магия там была у нас не вышло",191019,null],[235525,"2026-09-25T15:31:54",11,"*передаст записки что успела сделать про героев (я потом в дневнике что-то себе оформлю как время будет) \n\n— Вот, это можно будет сопоставить с историей для сравнения",191019,null],[235532,"2026-09-25T15:34:40",11,"*она соберёт свой мешок и прикрепит обратно к рюкзаку, а дракончик так и останется под мышкой. Заметив это девушка приобнимет его ласково и улыбнется \n\n— Изольда, Лемн, просыпайтесь — аккуратно потормошит девушек",191019,null],[235535,"2026-09-25T15:34:54",11,"*и погладит Вьюгу",191019,null],[235546,"2026-09-25T15:37:16",9,"— Магия была угнётена властью, скорей всего из-за этого произошел упадок, а после — выгорание. Волшебство держится на таланте, если её практиковали лишь вышестоящие по социальной лестнице то ее ращвитие закономерно остановилось и деградировало. — *Вордо подумал ещё немного, на их необычный вид реагировали странно, будто они господы.* — Ещё, колдовство и чародейство. Готов предположить что кровь несущая магию и талан принаждлежит вышестоящим, нас принимали за аристократию во второй истории.\n\n*Вордо встал и отряхиваясь обьяснил в чем дело. Свои предположения.*",191019,null],[235548,"2026-09-25T15:37:51",8,"/сек, пишу",191019,null],[235551,"2026-09-25T15:39:10",9,"— Иследованние продолжить готов, это занятно. Только бы немного закупиться материалами для алхимии с вашего позволения.\n\n//Да, мне бы материалов немного, если позвольшь крафтить на квесте и забрать хотя бы то золото что в простое накопилось за дни когда не играли.",191019,null],[235556,"2026-09-25T15:39:47",11,"*соберёт и его мешок пока он будет собираться и снарядит к его сумке, а ещё потратит ячейку на опознание крыльев",235546,null],[235559,"2026-09-25T15:41:09",9,"*Присел рядом, и тоже гладит собаку.*\n\n— Дорогая Аури, вы ведь волшебница если не ошибаюсь? — *Конечно он спросил для приличия, он не ошибался в своих наблюдениях.*",235535,null],[235561,"2026-09-25T15:41:52",11,"— Нет, я чародей — ответит девушка",191019,null],[235563,"2026-09-25T15:42:28",63,"— М...? Да я вроде как уже...?\n\nНесколько неуверенно протянула девушка, приподнимаясь на ноги. Глаза сразу же забегали по округе в попытке собрать как можно больше информации об месте, в котором она оказалась, чтобы попасться, позднее, идентифицировать его. \n\nКраем уха, уже когда осознание того, что она снова переместилась не пойми куда, начало проявляться, девушка услышала разговоры где-то поблизости. Переварив их у себя в голове, Ноа потянулась в рюкзак, дабы проверить наличие топора в нём.",235532,null],[235571,"2026-09-25T15:44:49",9,"— Правда? У вас совсем другой подход в магии. — *Вордо перестал гладить Вьюгу и протянул руку Аури словно предлагая взять.*",235561,null],[235575,"2026-09-25T15:45:40",11,"*протянет руку в ответ, а серьезное лицо расплывется а улыбке и она немного хихикнет\n\n— Да, вы правы, я волшебник. Но мне было любопытно посмотреть на вашу реакцию, прошу прощения",235571,null],[235576,"2026-09-25T15:45:50",8,"Сначала попрошу прощения: возвращение сюда оказалось неожиданным, поэтому мы не успели раздобыть даже свитков с новостями.\nНасчёт магии, к сожалению, не всё ясно, но мне кажется так: в начале времён она была чистой эссенцией и так же воспринималась. Однако годы, не тронув её, испортили к ней отношение. Социальный строй взял магию в оборот, родив напрасную к нам зависть. Правители искусственно сделали элитарным то, что неотъемлемо от всего мира. Но Вы неправы: она не погибла, а лишь задремала, чтобы позже взорваться цветными брызгами! *закружилась, изображая фонтан*\nИ знаете, мир очарователен и с технологиями: быстрые телеги на железных прутьях, плиты, которые включаются одной кнопкой. Это по-своему чудесно, хотя без волшебства не совсем то...",191019,null],[235582,"2026-09-25T15:47:22",11,"*полностью соглашаясь с каждым словом Изольды будет лишь кивать\n\n— Очень хорошо подмечено, дорогая",191019,null],[235585,"2026-09-25T15:47:49",38,"Топор был на месте, а ты оказалась в комнате полной книг полками и кучей бумаги. Перед тобой стоял мужчина среднего роста и с русыми волосами. Он был одет в костюм черного цвета и белую рубашку.",235563,null],[235586,"2026-09-25T15:47:49",8,"*рада видеть, как щурится собака от поглаживаний Аури*",191019,null],[235587,"2026-09-25T15:49:11",8,"– Кстати, Аури, как разживусь деньгами, не против, чтобы я тебе пару свитков написала? (Тьма и туманный шаг)",235575,null],[235588,"2026-09-25T15:49:15",9,"*Держа руку встает слегка поклонившись к низенькой Аури и приложив обратную сторону ладони к своему подбородку. Вульгарный поцелуй руки? Что вы, нет, но традиция рукоприкладства важна.*\n\n— Хочу попросить вашего расположения. Показать мне несколько уроков в свободное время. — *Он поднимает вторую руку и по ней пробегает электрическая искра (будущее лассо молний).* — Мне не хватает практических советов.",235575,null],[235589,"2026-09-25T15:49:59",11,"*глаза загорятся\n\n— Конечно! Я хотела и сама спросить, это будет очень полезно, твоя магия восхищает меня ещё с турнира!",235587,null],[235591,"2026-09-25T15:50:51",8,"– А меня ‐ существа, которые готовы корпеть над бумагами для овладения ей)",235589,null],[235592,"2026-09-25T15:50:57",9,"//Ты можешь потратить ячейку просто показывая закл и помогая записывать, а она проверкой и потратив материалы может попытаться сделать формулу, пропустив момент написания свитка. Но там все еще нужна проверка магии",235587,null],[235593,"2026-09-25T15:51:28",63,"— В этом месте что... писатель работает...?\n\nНоа решила подойти поближе к скоплению книг и поглядеть, какого рода они тут скопились. Было бы довольно увлекательно обнаружить что-то связанное с магией, особенно учитывая, что этот самый человек? ею интересовался.",235585,null],[235596,"2026-09-25T15:51:59",11,"*молния слегка потрескивая пройдется по руке Аури\n\n— Бодрит.. — прокомментирует она — для меня это будет честью. Я сама пока только учусь, но всё что касается магии мне искренне интересно, могу заниматься с вами после работы на комиссию магов",235588,null],[235599,"2026-09-25T15:53:08",9,"— Благодарю, учитель. — *Он искренне благодарен.* — Когда освою таинства магии, моя книга для вас будет открыта всегда.",235596,null],[235600,"2026-09-25T15:53:28",11,"— Хаха, мне немного легче даётся изучение нового чем остальным волшебникам — немного неловко свободной рукой поправит волосы за ухо, за которым так же находится перо писца (2 минуты вместо двух часов на изучение :D)",235591,null],[235601,"2026-09-25T15:53:43",9,"//Припоминаем что сильных магов Вордо елинственных признает равными)",191019,null],[235603,"2026-09-25T15:54:39",8,"/тебе тьму или ещё туманный шаг, или +усыпление+псевдожизнь?/",235600,null],[235604,"2026-09-25T15:54:50",11,"— Взаимно. Буду расширять свой репертуар знаний что бы делиться с вами в будущем",235599,null],[235605,"2026-09-25T15:55:22",11,"// я пока ничего не смогу выучить, пишу быстро, но деньги все ещё нужны, а там 100 монет на 1каст 2 круга, у меня 30 только",235603,null],[235606,"2026-09-25T15:55:38",8,"/ок, тогда потом",191019,null],[235607,"2026-09-25T15:55:40",9,"— Хорошо, а сейчас постараюсь вам мешать. — *Он мягко отпустил руку оставив Аури на Изольду и поиск новых знаний.*",235604,null],[235608,"2026-09-25T15:56:01",11,"*кивнет",191019,null],[235613,"2026-09-25T15:58:59",38,"Читатель ходил по комнате и иногда смотря на полки книг сказал.\n— Чтож... Пока я могу оценить в 50 золотых каждому из вас, вы согласны?\n Он еще немного подумал и спросил.\n— И да, можете оставить себе все артефакты... Где они...\n\nМужчина начал ходить по комнате в поисках вознаграждения и спросил.\n— Такс... Если же вы захотите отправится снова в путешествие, то вы знаете куда приходить...",191019,null],[235615,"2026-09-25T16:00:18",9,"//У нас перерыв? Звучит будто квест на паузе станет и персы свободны некоторое время.",191019,null],[235616,"2026-09-25T16:00:44",38,"// Щас награды будут",235615,null],[235617,"2026-09-25T16:00:50",38,"// И завершение арки",191019,null],[235619,"2026-09-25T16:01:05",38,"// И да, персонажи смогут ходить на другие",191019,null],[235622,"2026-09-25T16:03:26",8,"– Запишу себе адрес и, возможно, зайду ещё *крепко пожала ему руку*",235613,null],[235623,"2026-09-25T16:04:02",38,"// Итого за завершение арки вы получаете еще 100 опыта.\n50 золотых каждый.",191019,null],[235625,"2026-09-25T16:04:56",38,"// Теперь Топор имеет следующие свойства.\n\nТопор Раскола\nМагическое Оружие (Ручной топор), Уникальная редкость (Требует настройки)\nСтоимость: Не имеет\nНастроенное существо получает владение этим оружием.\nНастроенное  существо получает возможность добавить свой бонус владения к урону этим магическим оружием.\nНастроенное существо получает возможность использовать модификатор заклинательной характеристики, вместо силы или ловкости.",191019,null],[235630,"2026-09-25T16:06:16",38,"Стеклянные Крылья полёта.\nЧудесный предмет, Необычный (требуется настройка)\nСтоимость: 500 зм\nПока вы носите этот плащ, вы можете действием произнести командное слово. Это превратит плащ в пару крыльев летучей мыши, или птицы на вашей спине на 30 минут или пока вы не повторите командное слово действием. Крылья дают вам скорость полёта 35 футов. Если они исчезают, вы не можете повторно вызвать их 1к12 часов.",191019,null],[235631,"2026-09-25T16:07:39",9,"//Раз это хб, замени редкость на \"уникальный\" им, предметы ХБ неимеют редкости",191019,null],[235639,"2026-09-25T16:09:52",9,"— Занятная вещица. — *Вордо снимает свои крылья, и старается отвязать от них свою сущность.*",235630,null],[235641,"2026-09-25T16:10:34",9,"— Дорогая Аури, я бы хотел чтобы их забрали именно вы.",235608,null],[235759,"2026-09-25T17:25:13",11,"// Найс, звучит как хороший топорик, одобряю",235625,null],[235764,"2026-09-25T17:25:56",11,"— Вы уверены? Вещь очень полезная",235641,null],[235786,"2026-09-25T17:34:11",9,"— Мне хватит своих ног. Считайте это подарком. — *Он настаивает.*",235764,null],[235788,"2026-09-25T17:34:35",9,"//Вещь норм, сравнима с оригиналом, на другие квесты с ней пустят",191019,null],[235810,"2026-09-25T17:45:56",11,"— Я не откажусь — обернётся спиной и уберет руками волосы",235786,null],[235820,"2026-09-25T17:50:07",9,"*Вордо прислонил крылья к твоей спине.*\n\n— Ты чувствуешь их? Попробуй ощутить, это немного странно. — *Держит пока те сами волшебным образом не прикрепятся к спине. Он смотрит и едва слышно прошептал:* — Выглядит, красиво...\n\n*Немного отошёл.*\n\n— Я не успел ими воспользоваться, раскажите как это, летать. — *Вордо имел опыт полетов еще дивя в астрале, хоть и с чужой помощью они бы его не удивили, но, от этого летать самому стало не менее прекрасно.*",235810,null],[235821,"2026-09-25T17:51:31",11,"— Пока нет, полагаю на это нужно время, но я обещаю прилететь к вам на следующую встречу! Хехе\n\n*Девушка вновь оборачивается к Вордо и одаривает его искренней улыбкой\n\n— С меня должок, обязательно как-то научу вас заклинанию левитации!",191019,null],[235831,"2026-09-25T17:53:30",9,"— О, левитацию я был бы не прочь освоить. — *Он немного поклонился положив руку на сердце.* — Ждать лишь ваших наставлений, дорогой учитель.",235821,null],[235839,"2026-09-25T17:56:45",11,"— Приятно было работать вместе с вами, как и знакомство. Ещё раз приношу извинения за резкие суждения о вас и до новых встреч, ребята!\n\n*Вордо найдет вместе с спальником листик с адресом где остановилась девушка, а Изольда ещё с прошлой попойки знакома с этой информацией",191019,null],[235841,"2026-09-25T17:57:22",8,"/она алкоголь не пьёт, но да, помнит/",235839,null],[235842,"2026-09-25T17:58:05",8,"– И тебе всего лучшего! Как будут средства, посигналь, я поделюсь заклинаниями)",235839,null],[235855,"2026-09-25T18:07:39",11,"// ну за компанию вместе сидели, главное \n\n— Жди моих писем, я буду надоедать! — скажет вслед\n\n«Надо бы выучить заклинание которое позволяет письма на расстояния писать» — подумает про себя",235841,null],[235872,"2026-09-25T18:16:21",8,"– Ой, даже не думай, что ты в состоянии надоесть! *Изольда машет рукой на прощание, прежде чем уйти*",235855,null],[235873,"2026-09-25T18:17:38",9,"— Буду ждать нашей следующей встречи. Приметил одну таверну... — *Короче Вордо в кабаньем клыке.*",191019,null],[235874,"2026-09-25T18:18:01",9,"//Потом обсудим когда у тебя обучаться)",191019,null],[241878,"2026-09-28T23:28:02",9,"// you glass",191019,null],[262326,"2026-10-08T20:53:25",9,"//Тебе это так важно?",191019,null],[262330,"2026-10-08T20:54:30",9,"//Низрена вы нафлудили, проси остальных своё удалить, я своё позже удалю",191019,null],[262334,"2026-10-08T20:56:31",38,"@sweetkittywitch @QURTZZ @Ashenchampion Hard @tochhkatochka прошу удалить ваши сообщения над перезапуском",206091,null],[262337,"2026-10-08T20:58:41",41,"( бота это вроде не очистит",262334,null],[262483,"2026-10-08T21:46:40",11,"// мм.. лень и зачем 😓",262334,null],[262491,"2026-10-08T21:47:53",38,"// Ну ладно",262483,null]]);
